"use client";
import { Button, Input, Card, CardContent, CardDescription, CardHeader, CardTitle, Checkbox } from "@pec/ui";


import { useEffect, useState } from "react";
import { useAuth } from '@/features/auth/hooks/useAuth';
import {  buildApiUrl  } from "@pec/api";
import {  authClient  } from "@pec/api";

interface Permission {
  id: string;
  action: string;
  subject: string;
  conditions?: any;
}

interface Role {
  id: string;
  name: string;
  description: string | null;
  permissions: {
    permission: Permission;
  }[];
}

export default function RolesManagement() {
  const { ability } = useAuth();
  const [roles, setRoles] = useState<Role[]>([]);
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const [loading, setLoading] = useState(true);
  const [newRoleName, setNewRoleName] = useState("");

  const fetchData = async () => {
    try {
      setLoading(true);
      const token = authClient.getAccessToken();

      const [rolesRes, permsRes] = await Promise.all([
        fetch(buildApiUrl("/roles"), {
          headers: { Authorization: `Bearer ${token}` },
        }),
        fetch(buildApiUrl("/permissions"), {
          headers: { Authorization: `Bearer ${token}` },
        }),
      ]);

      if (rolesRes.ok && permsRes.ok) {
        setRoles(await rolesRes.json());
        setPermissions(await permsRes.json());
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleCreateRole = async () => {
    if (!newRoleName) return;
    const token = authClient.getAccessToken();
    await fetch(buildApiUrl("/roles"), {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ name: newRoleName, description: "Custom Role" }),
    });
    setNewRoleName("");
    fetchData();
  };

  const handleTogglePermission = async (
    roleId: string,
    permissionId: string,
    checked: boolean,
  ) => {
    const role = roles.find((r) => r.id === roleId);
    if (!role) return;

    let updatedPermIds = role.permissions.map((p) => p.permission.id);
    if (checked) {
      updatedPermIds.push(permissionId);
    } else {
      updatedPermIds = updatedPermIds.filter((id) => id !== permissionId);
    }

    const token = authClient.getAccessToken();
    await fetch(buildApiUrl(`/roles/${roleId}`), {
      method: "PATCH",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        permissions: {
          set: updatedPermIds.map((id) => ({ id })),
        },
      }),
    });

    fetchData();
  };

  if (!ability?.can("manage", "Role")) {
    return (
      <div className="flex h-[50vh] items-center justify-center text-muted-foreground">
        You do not have permission to access Role Management.
      </div>
    );
  }

  if (loading) {
    return <div className="p-8">Loading Role Matrix...</div>;
  }

  return (
    <div className="space-y-6 p-8">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Role Management</h1>
        <p className="text-muted-foreground">
          Dynamically configure Attribute-Based Access Control policies.
        </p>
      </div>

      <div className="flex items-center gap-4">
        <Input
          placeholder="New role name (e.g. TA, moderator)"
          value={newRoleName}
          onChange={(e) => setNewRoleName(e.target.value)}
          className="max-w-xs"
        />
        <Button onClick={handleCreateRole}>Create Custom Role</Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mt-6">
        {roles.map((role) => {
          const rolePermIds = role.permissions.map((p) => p.permission.id);
          return (
            <Card key={role.id}>
              <CardHeader>
                <CardTitle className="capitalize">{role.name}</CardTitle>
                <CardDescription>
                  {role.description || "Custom Role"}
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {permissions.map((perm) => (
                  <div
                    key={perm.id}
                    className="flex items-start space-x-3 space-y-0"
                  >
                    <Checkbox
                      checked={rolePermIds.includes(perm.id)}
                      onCheckedChange={(checked) =>
                        handleTogglePermission(
                          role.id,
                          perm.id,
                          checked as boolean,
                        )
                      }
                      id={`${role.id}-${perm.id}`}
                    />
                    <div className="space-y-1 leading-none">
                      <label
                        htmlFor={`${role.id}-${perm.id}`}
                        className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 cursor-pointer"
                      >
                        {perm.action} {perm.subject}
                      </label>
                      {perm.conditions && (
                        <p className="text-xs text-muted-foreground mt-1 font-mono break-all">
                          {JSON.stringify(perm.conditions)}
                        </p>
                      )}
                    </div>
                  </div>
                ))}
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { usePathname } from 'next/navigation';
import { cn } from '@/lib/utils';
import { Sidebar } from '@/components/layout/Sidebar';
import { Header } from '@/components/layout/Header';
import { BottomNav } from '@/components/layout/BottomNav';
import FloatingAIChat from '@/features/chat/FloatingAIChat';

interface ProtectedLayoutClientProps {
  children: React.ReactNode;
  user: any;
}

export function ProtectedLayoutClient({ children, user }: ProtectedLayoutClientProps) {
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [sidebarWidth, setSidebarWidth] = useState(256);
  const [isMobile, setIsMobile] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [densityMode, setDensityMode] = useState<'comfortable' | 'compact'>('comfortable');

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const savedWidth = localStorage.getItem('sidebar-width');
      if (savedWidth) {
        const parsed = parseInt(savedWidth, 10);
        if (parsed >= 200 && parsed <= 400) setSidebarWidth(parsed);
      }
    }
  }, []);

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 1024;
      setIsMobile(mobile);
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const pathname = usePathname();
  const isSpecialModule = ['/chat', '/resume-builder'].some(route => pathname?.startsWith(route));

  return (
    <div className="min-h-screen relative shadow-none overflow-x-hidden">
      <div className="mesh-gradient-bg">
        <div className="mesh-gradient-item mesh-1" />
        <div className="mesh-gradient-item mesh-2" />
        <div className="mesh-gradient-item mesh-3" />
      </div>

      <Sidebar
        role={user.role}
        collapsed={sidebarCollapsed}
        onToggle={() => setSidebarCollapsed(!sidebarCollapsed)}
        isMobile={isMobile}
        mobileMenuOpen={mobileMenuOpen}
        onMobileClose={() => setMobileMenuOpen(false)}
        width={sidebarWidth}
        onWidthChange={setSidebarWidth}
      />
      
      <Header 
        user={user} 
        sidebarCollapsed={sidebarCollapsed} 
        isMobile={isMobile}
        onMenuClick={() => setMobileMenuOpen(true)}
        densityMode={densityMode}
        onDensityModeChange={setDensityMode}
        sidebarWidth={sidebarWidth}
      />

      <main
        className={cn(
          'protected-shell pt-16 min-h-screen transition-all duration-150 relative overflow-hidden',
          isMobile && 'pl-0 pb-16'
        )}
        style={{
          paddingLeft: isMobile ? 0 : (sidebarCollapsed ? '4rem' : `${sidebarWidth}px`)
        }}
      >
        <div className="mesh-content-overlay" aria-hidden="true" />
        <div className={cn(
          "relative z-10 w-full min-h-[calc(100vh-4rem)]",
          isSpecialModule 
            ? "p-0 h-full w-full"
            : "p-4 md:p-5 lg:p-6 ui-section-gap",
        )}>
          {children}
        </div>
      </main>
      {isMobile && <BottomNav />}
      <FloatingAIChat />
    </div>
  );
}

import React, { useState } from 'react';
import {
  Button,
  Input,
  Label,
  Textarea,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@pec/ui';
import { EVENT_LABELS, CATEGORY_LABELS } from '@/features/academic-calendar/calendar-utils';
import { format } from 'date-fns';
import { CalendarEvent } from '../types';

export default function EventEditModal({
  event,
  isOpen,
  onClose,
  onSave,
}: {
  event: CalendarEvent;
  isOpen: boolean;
  onClose: () => void;
  onSave: (event: CalendarEvent) => void;
}) {
  const [formData, setFormData] = useState<CalendarEvent>(event);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-background rounded-lg border max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b">
          <h2 className="text-xl font-semibold">Edit Event</h2>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <Label htmlFor="title">Title</Label>
            <Input
              id="title"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              required
            />
          </div>

          <div>
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              rows={3}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="date">Date</Label>
              <Input
                id="date"
                type="date"
                value={formData.date ? format(new Date(formData.date), 'yyyy-MM-dd') : ''}
                onChange={(e) =>
                  setFormData({ ...formData, date: new Date(e.target.value).toISOString() })
                }
                required
              />
            </div>

            <div>
              <Label htmlFor="eventType">Event Type</Label>
              <Select
                value={formData.eventType}
                onValueChange={(value) => setFormData({ ...formData, eventType: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(EVENT_LABELS).map(([key, label]) => (
                    <SelectItem key={key} value={key}>
                      {label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="startTime">Start Time</Label>
              <Input
                id="startTime"
                type="time"
                value={formData.startTime || ''}
                onChange={(e) => setFormData({ ...formData, startTime: e.target.value })}
              />
            </div>

            <div>
              <Label htmlFor="endTime">End Time</Label>
              <Input
                id="endTime"
                type="time"
                value={formData.endTime || ''}
                onChange={(e) => setFormData({ ...formData, endTime: e.target.value })}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="category">Category</Label>
              <Select
                value={formData.category}
                onValueChange={(value) => setFormData({ ...formData, category: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(CATEGORY_LABELS).map(([key, label]) => (
                    <SelectItem key={key} value={key}>
                      {label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="importance">Importance</Label>
              <Select
                value={formData.importance}
                onValueChange={(value) => setFormData({ ...formData, importance: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="low">Low</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div>
            <Label htmlFor="location">Location</Label>
            <Input
              id="location"
              value={formData.location || ''}
              onChange={(e) => setFormData({ ...formData, location: e.target.value })}
            />
          </div>

          <div>
            <Label htmlFor="targetAudience">Target Audience</Label>
            <Input
              id="targetAudience"
              value={formData.targetAudience || ''}
              onChange={(e) => setFormData({ ...formData, targetAudience: e.target.value })}
              placeholder="e.g., all, students, faculty"
            />
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit">Save Changes</Button>
          </div>
        </form>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
