        </form>
      </div>
    </div>
  );
}

'use client';
import { Button, Badge, Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@pec/ui";


import { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import { Upload, FileText, Loader2, Eye, Save, Trash2, Plus, Edit, X } from 'lucide-react';

import { toast } from 'sonner';
import api from "@pec/api";
import { InteractiveCalendar } from '@/features/academic-calendar/InteractiveCalendar';
import { EventDetailModal } from '@/features/academic-calendar/EventDetailModal';
import {
  getEventLabel,
  CATEGORY_LABELS,
} from '@/features/academic-calendar/calendar-utils';
import { format, isValid, parseISO } from 'date-fns';
import { ParsedEvent, CalendarEvent } from './types';
import ParsedEventEditModal from './components/ParsedEventEditModal';
import EventEditModal from './components/EventEditModal';

export default function AdminAcademicCalendarPage() {
  const [view, setView] = useState<'upload' | 'preview' | 'calendar'>('upload');
  const [isUploading, setIsUploading] = useState(false);
  const [parsedEvents, setParsedEvents] = useState<ParsedEvent[]>([]);
  const [savedEvents, setSavedEvents] = useState<CalendarEvent[]>([]);
  const [selectedEvent, setSelectedEvent] = useState<CalendarEvent | null>(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [editingEvent, setEditingEvent] = useState<CalendarEvent | null>(null);
  const [editingParsedIndex, setEditingParsedIndex] = useState<number | null>(null);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isReplaceConfirmOpen, setIsReplaceConfirmOpen] = useState(false);
  const [createDate, setCreateDate] = useState<string>(format(new Date(), 'yyyy-MM-dd'));
  const [isSaving, setIsSaving] = useState(false);

  const isIsoDateValid = (value: string | null | undefined) => {
    if (!value) return false;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
    return isValid(parseISO(value));
  };

  const getEventsWithInvalidDates = (events: ParsedEvent[]) => {
    return events.filter((event) => {
      if (!isIsoDateValid(event.date)) return true;
      if (event.endDate && !isIsoDateValid(event.endDate)) return true;
      return false;
    });
  };

  const onDrop = useCallback(async (acceptedFiles: File[]) => {
    const file = acceptedFiles[0];
    if (!file || file.type !== 'application/pdf') {
      toast.error('Please upload a PDF file');
      return;
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);

      const response = await api.post('/academic-calendar/upload-pdf', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      const events = response.data.events || [];
      const invalidDateEvents = getEventsWithInvalidDates(events);

      if (invalidDateEvents.length > 0) {
        toast.error(
          `Gemini returned ${invalidDateEvents.length} event(s) with invalid date format. Please re-upload or fix the source PDF.`
        );
        setParsedEvents([]);
        setView('upload');
        return;
      }

      setParsedEvents(events);
      setView('preview');
      toast.success(
        `Parsed ${events.length} events from PDF. Review and edit before replacing calendar.`
      );
    } catch (error: any) {
      toast.error(error.message || 'Failed to parse PDF');
    } finally {
      setIsUploading(false);
    }
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: { 'application/pdf': ['.pdf'] },
    maxFiles: 1,
  });

  const handleReplaceAll = async () => {
    const invalidDateEvents = getEventsWithInvalidDates(parsedEvents);
    if (invalidDateEvents.length > 0) {
      toast.error('Please fix invalid dates before saving reviewed events.');
      return;
    }

    setIsSaving(true);
    try {
      const response = await api.post('/academic-calendar/bulk-import', {
        events: parsedEvents,
      });
      setSavedEvents(response.data.events || []);
      setIsReplaceConfirmOpen(false);
      setView('calendar');
      toast.success(`Replaced calendar with ${response.data.events?.length || 0} reviewed events`);
    } catch (error: any) {
      toast.error(error.message || 'Failed to save events');
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteEvent = async (id: string) => {
    try {
      await api.delete(`/academic-calendar/${id}`);
      setSavedEvents((prev) => prev.filter((e) => e.id !== id));
      toast.success('Event deleted');
    } catch (error: any) {
      toast.error(error.message || 'Failed to delete event');
    }
  };

  const handleDeleteParsedEvent = (index: number) => {
    setParsedEvents((prev) => prev.filter((_, i) => i !== index));
    toast.success('Parsed event removed');
  };

  const handleSaveParsedEvent = (index: number, updatedEvent: ParsedEvent) => {
    setParsedEvents((prev) => prev.map((event, i) => (i === index ? updatedEvent : event)));
    setEditingParsedIndex(null);
    toast.success('Parsed event updated');
  };

  const handleAddParsedEvent = () => {
    setParsedEvents((prev) => [
      ...prev,
      {
        title: '',
        description: '',
        date: format(new Date(), 'yyyy-MM-dd'),
        endDate: null,
        startTime: null,
        endTime: null,
        eventType: 'event',
        category: 'academic',
        location: null,
        importance: 'medium',
        targetAudience: 'all',
      },
    ]);
    setEditingParsedIndex(parsedEvents.length);
  };

  const handleUpdateEvent = async (updatedEvent: CalendarEvent) => {
    try {
      const response = await api.patch(`/academic-calendar/${updatedEvent.id}`, updatedEvent);
      setSavedEvents((prev) => prev.map((e) => (e.id === updatedEvent.id ? response.data : e)));
      toast.success('Event updated');
      setEditingEvent(null);
    } catch (error: any) {
      toast.error(error.message || 'Failed to update event');
    }
  };

  const handleEventEdit = (event: CalendarEvent) => {
    setEditingEvent({ ...event });
  };

  const loadExistingEvents = async () => {
    try {
      const response = await api.get('/academic-calendar');
      setSavedEvents(response.data);
      setView('calendar');
    } catch (error: any) {
      toast.error(error.message || 'Failed to load events');
    }
  };

  const handleOpenCreateForDate = (date: string) => {
    setCreateDate(date);
    setIsCreateModalOpen(true);
  };

  const handleCreateEvent = async (newEvent: ParsedEvent) => {
    try {
      const response = await api.post('/academic-calendar', newEvent);
      setSavedEvents((prev) => [...prev, response.data]);
      setIsCreateModalOpen(false);
      toast.success('Event created');
      await loadExistingEvents();
    } catch (error: any) {
      toast.error(error.message || 'Failed to create event');
    }
  };

  return (
    <div className="container mx-auto py-8 px-4 max-w-7xl">
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-2">Academic Calendar Management</h1>
        <p className="text-muted-foreground">
          Upload a PDF calendar, review extracted events, and manage the academic calendar
        </p>
      </div>

      <div className="flex gap-2 mb-6">
        <Button
          variant={view === 'upload' ? 'default' : 'outline'}
          onClick={() => setView('upload')}
        >
          <Upload className="w-4 h-4 mr-2" />
          Upload PDF
        </Button>
        {parsedEvents.length > 0 && (
          <Button
            variant={view === 'preview' ? 'default' : 'outline'}
            onClick={() => setView('preview')}
          >
            <Eye className="w-4 h-4 mr-2" />
            Review Events ({parsedEvents.length})
          </Button>
        )}
        <Button variant={view === 'calendar' ? 'default' : 'outline'} onClick={loadExistingEvents}>
          Calendar View
        </Button>
      </div>

      {view === 'upload' && (
        <div className="space-y-6">
          <div
            {...getRootProps()}
            className={`
              border-2 border-dashed rounded-lg p-12 text-center cursor-pointer transition-colors
              ${isDragActive ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/50'}
            `}
          >
            <input {...getInputProps()} />
            {isUploading ? (
              <div className="flex flex-col items-center gap-4">
                <Loader2 className="w-12 h-12 animate-spin text-primary" />
                <div>
                  <p className="text-lg font-medium">Analyzing PDF with AI...</p>
                  <p className="text-muted-foreground">This may take a moment</p>
                </div>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-4">
                <FileText className="w-12 h-12 text-muted-foreground" />
                <div>
                  <p className="text-lg font-medium">
                    {isDragActive ? 'Drop the PDF here' : 'Upload Academic Calendar PDF'}
                  </p>
                  <p className="text-muted-foreground">Drag and drop or click to select a file</p>
                </div>
                <p className="text-sm text-muted-foreground">Supported format: PDF only</p>
              </div>
            )}
          </div>

          <div className="bg-muted/50 rounded-lg p-6">
            <h3 className="font-semibold mb-3">How it works</h3>
            <ol className="list-decimal list-inside space-y-2 text-muted-foreground">
              <li>Upload your academic calendar PDF</li>
              <li>AI analyzes and extracts all events, holidays, and important dates</li>
              <li>Review and edit the extracted events</li>
              <li>Save to create the interactive calendar</li>
            </ol>
          </div>
        </div>
      )}

      {view === 'preview' && (
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold">Review Extracted Events</h2>
              <p className="text-muted-foreground">{parsedEvents.length} events found</p>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" onClick={handleAddParsedEvent}>
                <Plus className="w-4 h-4 mr-2" />
                Add Event
              </Button>
              <Button variant="outline" onClick={() => setView('upload')}>
                <X className="w-4 h-4 mr-2" />
                Cancel
              </Button>
              <Button
                onClick={() => setIsReplaceConfirmOpen(true)}
                disabled={isSaving || parsedEvents.length === 0}
              >
                {isSaving ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Replacing...
                  </>
                ) : (
                  <>
                    <Save className="w-4 h-4 mr-2" />
                    Replace Calendar Data
                  </>
                )}
              </Button>
            </div>
          </div>

          <div className="border rounded-lg overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Title</TableHead>
                  <TableHead>Date</TableHead>
                  <TableHead>Type</TableHead>
                  <TableHead>Category</TableHead>
                  <TableHead>Importance</TableHead>
                  <TableHead>Location</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {parsedEvents.map((event, index) => (
                  <TableRow key={index}>
                    <TableCell className="font-medium max-w-[200px] truncate">
                      {event.title}
                    </TableCell>
                    <TableCell>
                      {event.date ? format(new Date(event.date), 'MMM d, yyyy') : 'N/A'}
                      {event.endDate && (
                        <span className="text-muted-foreground">
                          {' '}
                          - {format(new Date(event.endDate), 'MMM d, yyyy')}
                        </span>
                      )}
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">{getEventLabel(event.eventType)}</Badge>
                    </TableCell>
                    <TableCell>{CATEGORY_LABELS[event.category] || event.category}</TableCell>
                    <TableCell>
                      <Badge
                        variant="outline"
                        className={
                          event.importance === 'high'
                            ? 'text-red-600'
                            : event.importance === 'medium'
                              ? 'text-yellow-600'
                              : 'text-green-600'
                        }
                      >
                        {event.importance}
                      </Badge>
                    </TableCell>
                    <TableCell className="max-w-[150px] truncate">
                      {event.location || '-'}
                    </TableCell>
                    <TableCell>
                      <div className="flex justify-end gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => setEditingParsedIndex(index)}
                        >
                          <Edit className="w-4 h-4 mr-1" />
                          Edit
                        </Button>
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() => handleDeleteParsedEvent(index)}
                        >
                          <Trash2 className="w-4 h-4 mr-1" />
                          Delete
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        </div>
      )}

      {view === 'calendar' && (
        <div className="space-y-6">
          <InteractiveCalendar
            events={savedEvents}
            isAdmin={true}
            onEventEdit={handleEventEdit}
            onEventDelete={handleDeleteEvent}
            onEventsChange={loadExistingEvents}
            onCreateEventAtDate={handleOpenCreateForDate}
          />
        </div>
      )}

      {editingParsedIndex !== null && (
        <ParsedEventEditModal
          event={parsedEvents[editingParsedIndex]}
          isOpen={true}
          onClose={() => setEditingParsedIndex(null)}
          onSave={(updatedEvent) =>
            handleSaveParsedEvent(editingParsedIndex as number, updatedEvent)
          }
        />
      )}

      {isReplaceConfirmOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-background rounded-lg border max-w-lg w-full p-6 space-y-5">
            <div className="space-y-2">
              <h2 className="text-xl font-semibold">Save reviewed calendar?</h2>
              <p className="text-sm text-muted-foreground">
                Choose one option. Replacing will remove old rows from academic calendar and insert
                the reviewed Gemini events.
              </p>
            </div>
            <div className="flex justify-end gap-3">
              <Button variant="outline" onClick={() => setIsReplaceConfirmOpen(false)}>
                Keep Older Calendar
              </Button>
              <Button onClick={handleReplaceAll} disabled={isSaving || parsedEvents.length === 0}>
                {isSaving ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Replacing...
                  </>
                ) : (
                  'Save Reviewed Edits'
                )}
              </Button>
            </div>
          </div>
        </div>
      )}

      {isCreateModalOpen && (
        <ParsedEventEditModal
          event={{
            title: '',
            description: '',
            date: createDate,
            endDate: null,
            startTime: null,
            endTime: null,
            eventType: 'event',
            category: 'academic',
            location: null,
            importance: 'medium',
            targetAudience: 'all',
          }}
          isOpen={isCreateModalOpen}
          title="Create Event"
          submitLabel="Create Event"
          onClose={() => setIsCreateModalOpen(false)}
          onSave={handleCreateEvent}
        />
      )}

      {editingEvent && (
        <EventEditModal
          event={editingEvent}
          isOpen={!!editingEvent}
          onClose={() => setEditingEvent(null)}
          onSave={handleUpdateEvent}
        />
      )}

      <EventDetailModal
        event={selectedEvent}
        isOpen={isDetailOpen}
        onClose={() => {
          setIsDetailOpen(false);
          setSelectedEvent(null);
        }}
        isAdmin={true}
        onEdit={handleEventEdit}
        onDelete={handleDeleteEvent}
      />
    </div>
  );
}

export interface ParsedEvent {
  title: string;
  description: string;
  date: string;
  endDate: string | null;
  startTime: string | null;
  endTime: string | null;
  eventType: string;
  category: string;
  location: string | null;
  importance: string;
  targetAudience: string | null;
}

export interface CalendarEvent {
  id: string;
  title: string;
  description: string;
  date: string;
  endDate: string | null;
  startTime: string | null;
  endTime: string | null;
  eventType: string;
  category: string;
  location: string | null;
  importance: string;
  targetAudience: string | null;
  rawData: any;
  isEditable: boolean;
  createdAt: string;
  updatedAt: string;
}

'use client';

import { useState, useEffect } from 'react';
import {
  Package,
  Plus,
  Clock,
  Truck,
  IndianRupee,
  MapPin,
  ShoppingBag,
  Search,
  Edit2,
  Trash2,
} from 'lucide-react';
import { toast } from 'sonner';

import {
  Button,
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  Input,
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
  Switch,
  Badge,
} from '@pec/ui';
import { AXIOS_INSTANCE } from '@pec/api';

interface CanteenItem {
  id: string;
  name: string;
  price: number;
  category: string;
  description: string;
  image: string;
  isAvailable: boolean;
  stock: number;
}

export default function CanteenManager() {
  const [items, setItems] = useState<CanteenItem[]>([]);
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'orders' | 'menu'>('orders');
  const [editingItem, setEditingItem] = useState<Partial<CanteenItem> | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState<boolean>(false);

  useEffect(() => {
    // Real-time orders
    const fetchOrders = async () => {
      try {
        const { data: raw } = await AXIOS_INSTANCE.get('/night-canteen/orders');
        setOrders(Array.isArray(raw?.data) ? raw.data : (Array.isArray(raw) ? raw : []));
      } catch (e) {
        console.error("Error fetching orders:", e);
      }
    };
    fetchOrders();
    const intervalId = setInterval(fetchOrders, 5000);
    const unsubscribeOrders = () => clearInterval(intervalId);

    // Menu items
    const fetchItems = async () => {
      try {
        const { data: raw } = await AXIOS_INSTANCE.get('/night-canteen/items');
        setItems(Array.isArray(raw?.data) ? raw.data : (Array.isArray(raw) ? raw : []));
      } catch(e) { console.error(e); }
      setLoading(false);
    };
    fetchItems();
    const unsubscribeItems = () => {};

    return () => {
      unsubscribeOrders();
      unsubscribeItems();
    };
  }, []);

  const handleSaveItem = async () => {
    if (!editingItem?.name || !editingItem?.price) {
      toast.error('Name and Price are required');
      return;
    }

    try {
      const id = editingItem.id || editingItem.name.toLowerCase().replace(/\s+/g, '_');
      if (editingItem.id) {
        await AXIOS_INSTANCE.patch('/night-canteen/items/' + id, { ...editingItem, id, isAvailable: editingItem.isAvailable ?? true, stock: editingItem.stock ?? 100 });
      } else {
        await AXIOS_INSTANCE.post('/night-canteen/items', { ...editingItem, id, isAvailable: editingItem.isAvailable ?? true, stock: editingItem.stock ?? 100 });
      }
      
      toast.success(editingItem.id ? 'Item updated' : 'Item added');
      setIsDialogOpen(false);
      setEditingItem(null);
    } catch (error) {
      toast.error('Failed to save item');
    }
  };

  const handleDeleteItem = async (id: string) => {
    if (!confirm('Are you sure you want to delete this item?')) return;
    try {
      await AXIOS_INSTANCE.delete('/night-canteen/items/' + id);
      toast.success('Item deleted');
    } catch (error) {
      toast.error('Failed to delete item');
    }
  };

  const updateOrderStatus = async (orderId: string, newStatus: string) => {
    try {
      await AXIOS_INSTANCE.patch('/night-canteen/orders/' + orderId, { status: newStatus });
      toast.success(`Order marked as ${newStatus}`);
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const canteenStats = {
    pending: orders.filter(o => o.status === 'Pending').length,
    active: orders.filter(o => o.status === 'Confirmed' || o.status === 'Out for Delivery').length,
    totalRevenue: orders
      .filter(o => o.status === 'Delivered')
      .reduce((sum, o) => sum + o.totalAmount, 0)
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-7xl">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
        <div>
          <h1 className="text-3xl font-bold text-foreground mb-2 flex items-center gap-3">
            <Package className="w-8 h-8 text-primary" />
            Canteen Dashboard
          </h1>
          <p className="text-muted-foreground">Manage your night hunger squad from here.</p>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 bg-muted p-1 rounded-lg">
            <Button 
              variant={activeTab === 'orders' ? 'secondary' : 'ghost'} 
              onClick={() => setActiveTab('orders')}
              size="sm"
            >
              Recent Orders
            </Button>
            <Button 
              variant={activeTab === 'menu' ? 'secondary' : 'ghost'} 
              onClick={() => setActiveTab('menu')}
              size="sm"
            >
              Menu Manager
            </Button>
          </div>
          
          {activeTab === 'menu' && (
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
              <DialogTrigger asChild>
                <Button variant="gradient" onClick={() => setEditingItem({})}>
                  <Plus className="w-4 h-4 mr-2" />
                  Add Item
                </Button>
              </DialogTrigger>
              <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                  <DialogTitle>{editingItem?.id ? 'Edit Item' : 'New Canteen Item'}</DialogTitle>
                </DialogHeader>
                <div className="grid gap-4 py-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Item Name</label>
                    <Input 
                      value={editingItem?.name || ''} 
                      onChange={e => setEditingItem({...editingItem, name: e.target.value})}
                      placeholder="e.g. Kurkure Masala"
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-sm font-medium">Price (₹)</label>
                      <Input 
                        type="number"
                        value={editingItem?.price || ''} 
                        onChange={e => setEditingItem({...editingItem, price: Number(e.target.value)})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-medium">Category</label>
                      <Select 
                        value={editingItem?.category || ''} 
                        onValueChange={v => setEditingItem({...editingItem, category: v})}
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="Select" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="Snacks">Snacks</SelectItem>
                          <SelectItem value="Drinks">Drinks</SelectItem>
                          <SelectItem value="Meals">Meals</SelectItem>
                          <SelectItem value="Desserts">Desserts</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Image URL</label>
                    <Input 
                      value={editingItem?.image || ''} 
                      onChange={e => setEditingItem({...editingItem, image: e.target.value})}
                      placeholder="https://..."
                    />
                  </div>
                  <div className="flex items-center justify-between pt-2">
                    <div className="space-y-0.5">
                      <label className="text-sm font-medium">Available for Order</label>
                      <p className="text-xs text-muted-foreground">Toggle to show/hide from menu</p>
                    </div>
                    <Switch 
                      checked={editingItem?.isAvailable ?? true}
                      onCheckedChange={v => setEditingItem({...editingItem, isAvailable: v})}
                    />
                  </div>
                </div>
                <DialogFooter>
                  <Button onClick={handleSaveItem} className="w-full">Save Item</Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          )}
        </div>
      </div>

      <div className="grid gap-6 md:grid-cols-3 mb-8">
        <div className="p-6 rounded-2xl border bg-card/50 flex items-center gap-4">
          <div className="p-3 rounded-xl bg-orange-500/10">
            <Clock className="w-6 h-6 text-orange-500" />
          </div>
          <div>
            <p className="text-sm text-muted-foreground">Pending Orders</p>
            <p className="text-2xl font-bold">{canteenStats.pending}</p>
          </div>
        </div>
        <div className="p-6 rounded-2xl border bg-card/50 flex items-center gap-4">
          <div className="p-3 rounded-xl bg-primary/10">
            <Truck className="w-6 h-6 text-primary" />
          </div>
          <div>
            <p className="text-sm text-muted-foreground">Active Deliveries</p>
            <p className="text-2xl font-bold">{canteenStats.active}</p>
          </div>
        </div>
        <div className="p-6 rounded-2xl border bg-card/50 flex items-center gap-4">
          <div className="p-3 rounded-xl bg-green-500/10">
            <IndianRupee className="w-6 h-6 text-green-500" />
          </div>
          <div>
            <p className="text-sm text-muted-foreground">Today&apos;s Sales</p>
            <p className="text-2xl font-bold">₹{canteenStats.totalRevenue}</p>
          </div>
        </div>
      </div>

      {activeTab === 'orders' ? (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-xl font-bold">Live Orders</h2>
            <Badge variant="secondary" className="bg-primary/5 text-primary">Auto-updates live</Badge>
          </div>

          <div className="grid gap-4">
            {orders.length > 0 ? (
              orders.map((order) => (
                <div key={order.id} className="p-6 rounded-2xl border border-border bg-card hover:border-primary/30 transition-all flex flex-col md:flex-row gap-6 md:items-center">
                  <div className="flex-1 space-y-3">
                    <div className="flex items-center gap-3">
                      <Badge className={
                        order.status === 'Pending' ? 'bg-orange-500' :
                        order.status === 'Confirmed' ? 'bg-blue-500' :
                        order.status === 'Out for Delivery' ? 'bg-indigo-500' :
                        order.status === 'Delivered' ? 'bg-green-500' :
                        'bg-red-500'
                      }>
                        {order.status}
                      </Badge>
                      <span className="text-sm font-medium text-muted-foreground">#{order.id.slice(-6).toUpperCase()}</span>
                      <span className="text-sm text-muted-foreground">• {order.timestamp?.toDate().toLocaleTimeString()}</span>
                    </div>
                    
                    <div>
                      <h3 className="text-lg font-bold">{order.studentName}</h3>
                      <p className="text-primary font-medium flex items-center gap-1">
                        <MapPin className="w-4 h-4" /> {order.hostelRoom}
                      </p>
                    </div>

                    <div className="flex flex-wrap gap-2">
                      {order.items.map((it: any, idx: number) => (
                        <div key={idx} className="px-2 py-1 rounded bg-muted text-xs font-medium">
                          {it.quantity}x {it.name}
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="flex flex-col items-end gap-4 min-w-[200px]">
                    <div className="text-right">
                      <p className="text-xs text-muted-foreground">Total Value</p>
                      <p className="text-2xl font-bold">₹{order.totalAmount}</p>
                    </div>
                    
                    <div className="flex gap-2 w-full md:w-auto">
                      {order.status === 'Pending' && (
                        <Button 
                          size="sm" 
                          onClick={() => updateOrderStatus(order.id, 'Confirmed')}
                          className="flex-1 md:flex-none bg-blue-500 hover:bg-blue-600"
                        >
                          Confirm
                        </Button>
                      )}
                      {order.status === 'Confirmed' && (
                        <Button 
                          size="sm" 
                          onClick={() => updateOrderStatus(order.id, 'Out for Delivery')}
                          className="flex-1 md:flex-none bg-indigo-500 hover:bg-indigo-600"
                        >
                          Out for Delivery
                        </Button>
                      )}
                      {(order.status === 'Out for Delivery' || order.status === 'Confirmed') && (
                        <Button 
                          size="sm" 
                          onClick={() => updateOrderStatus(order.id, 'Delivered')}
                          className="flex-1 md:flex-none bg-green-500 hover:bg-green-600"
                        >
                          Complete
                        </Button>
                      )}
                      {order.status !== 'Delivered' && order.status !== 'Cancelled' && (
                        <Button 
                          size="sm" 
                          variant="outline" 
                          onClick={() => updateOrderStatus(order.id, 'Cancelled')}
                          className="flex-1 md:flex-none text-destructive hover:bg-destructive/10"
                        >
                          Cancel
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <div className="text-center py-20 border-2 border-dashed border-muted rounded-3xl bg-card/50">
                <ShoppingBag className="w-16 h-16 text-muted-foreground/30 mx-auto mb-4" />
                <h3 className="text-xl font-bold">No orders yet</h3>
                <p className="text-muted-foreground">Wait for the hunger sirens to ring.</p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold">Menu Management</h2>
            <div className="flex items-center gap-2">
              <Search className="w-4 h-4 text-muted-foreground" />
              <Input placeholder="Search menu..." className="w-64 h-9" />
            </div>
          </div>

          <div className="overflow-hidden rounded-2xl border border-border bg-card shadow-sm">
            <table className="w-full text-left border-collapse">
              <thead className="bg-muted/50 border-b">
                <tr>
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-muted-foreground">Item</th>
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-muted-foreground">Category</th>
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-muted-foreground">Price</th>
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-muted-foreground">Status</th>
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-muted-foreground text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {items.map((item) => (
                  <tr key={item.id} className="hover:bg-muted/30 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <img src={item.image} className="w-10 h-10 rounded-lg object-cover" />
                        <div>
                          <p className="font-bold">{item.name}</p>
                          <p className="text-xs text-muted-foreground line-clamp-1">{item.description}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <Badge variant="secondary" className="font-medium">{item.category}</Badge>
                    </td>
                    <td className="px-6 py-4 font-bold text-primary">₹{item.price}</td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <Switch 
                          checked={item.isAvailable} 
                          onCheckedChange={async (v) => {
                            await AXIOS_INSTANCE.patch('/night-canteen/items/' + item.id, { isAvailable: v });
                            toast.info(`${item.name} is now ${v ? 'Available' : 'Unavailable'}`);
                          }}
                        />
                        <span className="text-sm font-medium">
                          {item.isAvailable ? 'Live' : 'Hidden'}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2">
                        <Button 
                          size="icon" 
                          variant="ghost" 
                          className="w-8 h-8 rounded-lg"
                          onClick={() => {
                            setEditingItem(item);
                            setIsDialogOpen(true);
                          }}
                        >
                          <Edit2 className="w-4 h-4" />
                        </Button>
                        <Button 
                          size="icon" 
                          variant="ghost" 
                          className="w-8 h-8 rounded-lg text-destructive hover:bg-destructive/10"
                          onClick={() => handleDeleteItem(item.id)}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';
import { Button, Input, Textarea, Card, CardContent, CardDescription, CardHeader, CardTitle } from "@pec/ui";


import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  ArrowLeft,
  Save,
  Building2,
  Mail,
  Phone,
  MapPin,
  Globe,
  Upload,
  Loader2,
  Cloud,
  Wand2,
} from 'lucide-react';

import { toast } from 'sonner';
import { usePermissions } from '@/hooks/usePermissions';
import { useRouter } from 'next/navigation';
import { uploadToCloudinary } from '@/lib/cloudinaryManager';
import { processLogoImage } from '@/lib/logoProcessor';
import { useFeatureFlagsControllerGetByKeyV1, useFeatureFlagsControllerUpsertV1 } from '@pec/api';
import type { CollegeSettings as CollegeSettingsType } from '@pec/shared';

type CollegeSettings = CollegeSettingsType;

export default function CollegeSettings() {
  const embedded = false;
  const router = useRouter();
  const { user, isAdmin, loading: authLoading } = usePermissions();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<CollegeSettings | null>(null);

  const { refetch: refetchSettings } = useFeatureFlagsControllerGetByKeyV1('college-settings', { query: { enabled: false } });
  const { mutateAsync: upsertFeatureFlag } = useFeatureFlagsControllerUpsertV1();

  // Form fields
  const [collegeName, setCollegeName] = useState('');
  const [collegeShortName, setCollegeShortName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [website, setWebsite] = useState('');
  const [tagline, setTagline] = useState('');
  const [logoUrl, setLogoUrl] = useState('');
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState('');
  const [removingBackground, setRemovingBackground] = useState(false);
  const [removeBackground, setRemoveBackground] = useState(false);
  const [attendanceRequiredPercentage, setAttendanceRequiredPercentage] = useState(75);
  
  // Logo display mode
  const [logoDisplayMode, setLogoDisplayMode] = useState<'logo-only' | 'text-only' | 'both'>('both');
  
  // Cloudinary settings (optional - college's own account)
  const [cloudinaryCloudName, setCloudinaryCloudName] = useState('');
  const [cloudinaryPreset, setCloudinaryPreset] = useState('');

  useEffect(() => {
    if (authLoading) return;
    if (!user || !isAdmin) {
      router.push('/dashboard');
      return;
    }

    fetchSettings();
  }, [authLoading, user, isAdmin, router]);

  useEffect(() => {
    if (settings) {
      setCollegeName(settings.collegeName);
      setEmail(settings.email);
      setPhone(settings.phone);
      setAddress(settings.address);
      setWebsite(settings.website);
      setTagline(settings.tagline);
      setLogoUrl(settings.logoUrl);
      setCloudinaryCloudName(settings.cloudinaryCloudName || '');
      setCloudinaryPreset(settings.cloudinaryPreset || '');
      setPreviewUrl(settings.logoUrl);
    }
  }, [settings]);

  const fetchSettings = async () => {
    try {
      setLoading(true);
      const res = await refetchSettings();
      const responseData = res.data as any;
      const featureFlag = responseData?.data || responseData;
      const parsedData = featureFlag?.payload ? JSON.parse(featureFlag.payload) : null;

      if (parsedData) {
        const data = parsedData as CollegeSettings;
        setSettings(data);
        setCollegeName(data.collegeName || '');
        setCollegeShortName(data.collegeShortName || '');
        setEmail(data.email || '');
        setPhone(data.phone || '');
        setAddress(data.address || '');
        setWebsite(data.website || '');
        setTagline(data.tagline || '');
        setLogoUrl(data.logoUrl || '');
        setLogoDisplayMode(data.logoDisplayMode || 'both');
        setCloudinaryCloudName(data.cloudinaryCloudName || '');
        setCloudinaryPreset(data.cloudinaryPreset || '');
        setAttendanceRequiredPercentage(
          typeof data.attendanceRequiredPercentage === 'number' ? data.attendanceRequiredPercentage : 75
        );
    } else {
      setSettings(null);
      setAttendanceRequiredPercentage(75);
    }
  } catch (error) {
      console.error('Error fetching college settings:', error);
      toast.error('Failed to load college settings');
    } finally {
      setLoading(false);
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processFile(file);
    }
  };

  const processFile = (file: File) => {
    if (!file.type.startsWith('image/')) {
      toast.error('Please upload an image file');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error('Image size must be less than 5MB');
      return;
    }
    setLogoFile(file);
    setRemoveBackground(false);
    const reader = new FileReader();
    reader.onloadend = () => {
      setPreviewUrl(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDragEnter = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      processFile(files[0]);
    }
  };

  const handleRemoveBackground = async () => {
    if (!logoFile) {
      toast.error('Please upload a logo first');
      return;
    }

    try {
      setRemovingBackground(true);
      toast.loading('Removing background...');
      
      const processedFile = await processLogoImage(logoFile, true);
      setLogoFile(processedFile);
      
      // Show preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
        setRemoveBackground(true);
        toast.dismiss();
        toast.success('Background removed! Logo is ready to upload.');
      };
      reader.readAsDataURL(processedFile);
    } catch (error) {
      toast.dismiss();
      console.error('Background removal error:', error);
      toast.error(
        error instanceof Error
          ? error.message
          : 'Failed to remove background. Make sure Remove.bg API key is configured.'
      );
    } finally {
      setRemovingBackground(false);
    }
  };

  const handleSave = async () => {
    if (!collegeName.trim()) {
      toast.error('Please enter college name');
      return;
    }

    try {
      setSaving(true);
      let finalLogoUrl = logoUrl;

      // If new logo file is selected, upload to Cloudinary
      if (logoFile) {
        try {
          toast.loading('Uploading logo to Cloudinary...');
          finalLogoUrl = await uploadToCloudinary(logoFile);
          toast.dismiss();
          toast.success('Logo uploaded successfully!');
        } catch (error) {
          toast.dismiss();
          console.error('Cloudinary upload error:', error);
          toast.error(
            error instanceof Error
              ? error.message
              : 'Failed to upload to Cloudinary. Make sure your environment variables are set.'
          );
          setSaving(false);
          return;
        }
      }

      await saveSettings(finalLogoUrl);
    } catch (error) {
      console.error('Error saving college settings:', error);
      toast.error('Failed to save college settings');
      setSaving(false);
    }
  };

  const saveSettings = async (logoUrl: string) => {
    try {
      const newSettings: CollegeSettings = {
        collegeName: (collegeName || '').trim(),
        collegeShortName: (collegeShortName || '').trim(),
        email: (email || '').trim(),
        phone: (phone || '').trim(),
        address: (address || '').trim(),
        website: (website || '').trim(),
        tagline: (tagline || '').trim(),
        logoUrl: logoUrl,
        logoDisplayMode: logoDisplayMode,
        cloudinaryCloudName: (cloudinaryCloudName || '').trim(),
        cloudinaryPreset: (cloudinaryPreset || '').trim(),
        attendanceRequiredPercentage: Math.max(0, Math.min(100, Math.round(attendanceRequiredPercentage || 75))),
        lastUpdated: new Date().toISOString(),
        updatedBy: user?.email || 'unknown',
      };

      await upsertFeatureFlag({
        key: 'college-settings',
        data: {
          enabled: true,
          description: 'College settings',
          payload: JSON.stringify(newSettings),
        }
      });

      setSettings(newSettings);
      setLogoFile(null);
      toast.success('College settings updated successfully!');
    } catch (error) {
      console.error('Error saving settings:', error);
      toast.error('Failed to save college settings');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="space-y-6"
    >
      {/* Back Button */}
      {!embedded && (
        <Button variant="ghost" onClick={() => router.push('/dashboard')} className="gap-2">
          <ArrowLeft className="w-4 h-4" />
          Back to Dashboard
        </Button>
      )}

      {/* Header */}
      {!embedded && (
        <div>
          <h1 className="text-3xl font-bold text-foreground">College Settings</h1>
          <p className="text-muted-foreground mt-2">
            Configure your college branding and information
          </p>
        </div>
      )}

      {/* Logo Section */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Building2 className="w-5 h-5" />
            College Logo
          </CardTitle>
          <CardDescription>
            Upload your college logo (max 5MB, recommended 200x200px)
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Upload Area */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-3">
                Logo Image
              </label>
              <div 
                onDragOver={handleDragOver}
                onDragEnter={handleDragEnter}
                onDrop={handleDrop}
                className="border-2 border-dashed border-primary/30 rounded-lg p-8 text-center cursor-pointer hover:bg-secondary/50 hover:border-primary/60 transition-all"
              >
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleLogoChange}
                  className="hidden"
                  id="logo-upload"
                />
                <label htmlFor="logo-upload" className="cursor-pointer block">
                  <Upload className="w-8 h-8 mx-auto mb-2 text-muted-foreground" />
                  <p className="text-sm font-medium text-foreground">Drag & drop or click to upload</p>
                  <p className="text-xs text-muted-foreground mt-1">PNG, JPG, GIF up to 5MB</p>
                </label>
              </div>
            </div>

            {/* Preview */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-3">
                Preview
              </label>
              <div className="border rounded-lg p-4 bg-secondary/50 flex items-center justify-center h-48">
                {previewUrl ? (
                  <div className="relative">
                    <img
                      src={previewUrl}
                      alt="Logo preview"
                      className="max-h-40 max-w-40 object-contain"
                    />
                  </div>
                ) : (
                  <p className="text-muted-foreground">No logo uploaded</p>
                )}
              </div>
              {logoFile && (
                <div className="mt-3 space-y-2">
                  <Button
                    onClick={handleRemoveBackground}
                    disabled={removingBackground || removeBackground}
                    variant="outline"
                    size="sm"
                    className="w-full gap-2"
                  >
                    {removingBackground && <Loader2 className="w-4 h-4 animate-spin" />}
                    {removeBackground ? '✓ Background Removed' : <><Wand2 className="w-4 h-4" /> Remove Background</>}
                  </Button>
                  <p className="text-xs text-muted-foreground">
                    {removeBackground ? '✓ Ready to upload' : 'Optional: Remove plain background before upload'}
                  </p>
                </div>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Logo Display Mode */}
      <Card>
        <CardHeader>
          <CardTitle>Logo Display Options</CardTitle>
          <CardDescription>Choose how to display the college branding in the interface</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* Logo Only Option */}
            <label className={`flex items-center p-4 border-2 rounded-lg cursor-pointer transition-all ${
              logoDisplayMode === 'logo-only' 
                ? 'border-primary bg-primary/5' 
                : 'border-border hover:border-primary/50'
            }`}>
              <input
                type="radio"
                name="logoDisplayMode"
                value="logo-only"
                checked={logoDisplayMode === 'logo-only'}
                onChange={(e) => setLogoDisplayMode(e.target.value as 'logo-only' | 'text-only' | 'both')}
                className="mr-3"
              />
              <div>
                <p className="font-medium text-foreground">Logo Only</p>
                <p className="text-xs text-muted-foreground">Show college logo without text</p>
                {logoUrl && (
                  <img src={logoUrl} alt="Preview" className="w-12 h-12 mt-2 object-contain" />
                )}
              </div>
            </label>

            {/* Text Only Option */}
            <label className={`flex items-center p-4 border-2 rounded-lg cursor-pointer transition-all ${
              logoDisplayMode === 'text-only' 
                ? 'border-primary bg-primary/5' 
                : 'border-border hover:border-primary/50'
            }`}>
              <input
                type="radio"
                name="logoDisplayMode"
                value="text-only"
                checked={logoDisplayMode === 'text-only'}
                onChange={(e) => setLogoDisplayMode(e.target.value as 'logo-only' | 'text-only' | 'both')}
                className="mr-3"
              />
              <div>
                <p className="font-medium text-foreground">Text Only</p>
                <p className="text-xs text-muted-foreground">Show college short name only</p>
                <p className="text-sm font-semibold mt-2">{collegeShortName || 'College'}</p>
              </div>
            </label>

            {/* Both Option */}
            <label className={`flex items-center p-4 border-2 rounded-lg cursor-pointer transition-all ${
              logoDisplayMode === 'both' 
                ? 'border-primary bg-primary/5' 
                : 'border-border hover:border-primary/50'
            }`}>
              <input
                type="radio"
                name="logoDisplayMode"
                value="both"
                checked={logoDisplayMode === 'both'}
                onChange={(e) => setLogoDisplayMode(e.target.value as 'logo-only' | 'text-only' | 'both')}
                className="mr-3"
              />
              <div>
                <p className="font-medium text-foreground">Logo + Text</p>
                <p className="text-xs text-muted-foreground">Show both logo and text</p>
                <div className="flex items-center gap-2 mt-2">
                  {logoUrl && (
                    <img src={logoUrl} alt="Preview" className="w-6 h-6 object-contain" />
                  )}
                  <p className="text-sm font-semibold">{collegeShortName || 'College'}</p>
                </div>
              </div>
            </label>
          </div>
        </CardContent>
      </Card>

      {/* Basic Information */}
      <Card>
        <CardHeader>
          <CardTitle>Basic Information</CardTitle>
          <CardDescription>College name and contact details</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              College Name *
            </label>
            <Input
              placeholder="Your College Name"
              value={collegeName}
              onChange={(e) => setCollegeName(e.target.value)}
            />
          </div>

          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              College Short Name (Optional)
            </label>
            <Input
              placeholder="e.g., IITD, DU, etc. (used in headers/badges)"
              value={collegeShortName}
              onChange={(e) => setCollegeShortName(e.target.value)}
            />
            <p className="text-xs text-muted-foreground mt-1">
              Displayed in places where space is limited (2-6 characters recommended)
            </p>
          </div>

          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              Tagline / Motto
            </label>
            <Input
              placeholder="Excellence in Education"
              value={tagline}
              onChange={(e) => setTagline(e.target.value)}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-medium text-foreground block mb-2">
                <Mail className="w-4 h-4 inline mr-1" />
                Email
              </label>
              <Input
                type="email"
                placeholder="admin@college.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>

            <div>
              <label className="text-sm font-medium text-foreground block mb-2">
                <Phone className="w-4 h-4 inline mr-1" />
                Phone
              </label>
              <Input
                placeholder="+91-XXXXXXXXXX"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
              />
            </div>
          </div>

          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              <MapPin className="w-4 h-4 inline mr-1" />
              Address
            </label>
            <Textarea
              placeholder="Street, City, State, Pin Code"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              rows={3}
            />
          </div>

          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              <Globe className="w-4 h-4 inline mr-1" />
              Website
            </label>
            <Input
              placeholder="https://college.edu"
              value={website}
              onChange={(e) => setWebsite(e.target.value)}
            />
            <p className="text-xs text-muted-foreground mt-1">
              Logo and college name will redirect to this link (if provided)
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Attendance Policy */}
      <Card>
        <CardHeader>
          <CardTitle>Attendance Policy</CardTitle>
          <CardDescription>Set the minimum required attendance percentage for students</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              Required Attendance Percentage
            </label>
            <Input
              type="number"
              min={0}
              max={100}
              value={attendanceRequiredPercentage}
              onChange={(e) => setAttendanceRequiredPercentage(Number(e.target.value))}
            />
            <p className="text-xs text-muted-foreground mt-1">
              Default is 75%. This affects student dashboards and alerts.
            </p>
