            <>
              <Save className="w-4 h-4" />
              Save Settings
            </>
          )}
        </Button>
        {!embedded && (
          <Button
            variant="outline"
            size="lg"
            onClick={() => router.push('/dashboard')}
          >
            Cancel
          </Button>
        )}
      </div>
    </motion.div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  Building2,
  AlertCircle,
  RefreshCcw,
  CheckCircle2,
  Search,
  MapPin,
  User,
  MessageSquare,
  Send,
  ShieldCheck,
} from 'lucide-react';
import { toast } from 'sonner';

import {
  Button,
  Input,
  Badge,
  Tabs,
  TabsList,
  TabsTrigger,
} from '@pec/ui';
import { cn, extractData } from '@/lib/utils';
import api from '@pec/api';

interface HostelIssue {
  id: string;
  title: string;
  description: string;
  category: string;
  priority: string;
  status: string;
  roomNumber: string;
  studentId: string;
  studentName: string;
  createdAt: any;
  updatedAt: any;
  responses?: { from: string; message: string; timestamp: any }[];
}

export default function HostelAdmin() {
  const [issues, setIssues] = useState<HostelIssue[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('all');
  const [selectedIssue, setSelectedIssue] = useState<HostelIssue | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    // Simplified query without orderBy to avoid composite index requirement
    const fetchIssues = async () => {
      try {
        const rawData = extractData<any>((await api.get('/hostelIssues', { params: { limit: 2000 } })).data);
        const data = Array.isArray(rawData) ? rawData : [];
        setIssues(data.sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()));
      } catch (err) {
        console.error("Failed to fetch issues", err);
      } finally {
        setLoading(false);
      }
    };
    fetchIssues();
    const intervalId = setInterval(fetchIssues, 5000);
    const unsubscribe = () => clearInterval(intervalId);

      return () => unsubscribe();
  }, [selectedIssue?.id]);

  const updateStatus = async (issueId: string, newStatus: string) => {
    try {
      await api.patch(`/hostelIssues/${issueId}`, { status: newStatus });
      toast.success(`Issue marked as ${newStatus}`);
    } catch (err) {
      toast.error('Failed to update status');
    }
  };

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedIssue) return;

    try {
      await api.patch(`/hostelIssues/${selectedIssue.id}`, {
        responses: {
          _op: 'arrayUnion',
          val: {
            from: 'Maintenance Team',
            message: newMessage,
            timestamp: new Date().toISOString(),
          },
        },
      });
      setNewMessage('');
      toast.success('Reply sent');
    } catch (err) {
      toast.error('Failed to send reply');
    }
  };

  const normalizeStatus = (status: string) => {
    if (status === 'open') return 'pending';
    if (status === 'in_progress') return 'assigned';
    return status;
  };

  const getStatusConfig = (status: string) => {
    switch (normalizeStatus(status)) {
      case 'pending': return { color: 'text-orange-500', bg: 'bg-orange-500/10', label: 'Pending' };
      case 'assigned': return { color: 'text-blue-500', bg: 'bg-blue-500/10', label: 'Assigned' };
      case 'resolved': return { color: 'text-green-500', bg: 'bg-green-500/10', label: 'Resolved' };
      case 'closed': return { color: 'text-muted-foreground', bg: 'bg-muted', label: 'Closed' };
      default: return { color: 'text-muted-foreground', bg: 'bg-muted', label: 'Unknown' };
    }
  };

  const filteredIssues = issues.filter(issue => {
    const matchesSearch = issue.studentName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                         issue.title.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesTab = activeTab === 'all' || normalizeStatus(issue.status) === activeTab;
    return matchesSearch && matchesTab;
  });

  const stats = {
    open: issues.filter(i => normalizeStatus(i.status) === 'pending').length,
    active: issues.filter(i => normalizeStatus(i.status) === 'assigned').length,
    resolved: issues.filter(i => normalizeStatus(i.status) === 'resolved').length
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-7xl">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
        <div>
          <h1 className="text-3xl font-bold text-foreground mb-2 flex items-center gap-3">
            <Building2 className="w-8 h-8 text-primary" />
            Hostel Maintenance Admin
          </h1>
          <p className="text-muted-foreground">Manage and resolve student hostel complaints efficiently.</p>
        </div>
      </div>

      <div className="grid gap-6 md:grid-cols-3 mb-8">
        <div className="p-6 rounded-2xl border bg-card/50 flex items-center gap-4">
          <div className="p-3 rounded-xl bg-orange-500/10">
            <AlertCircle className="w-6 h-6 text-orange-500" />
          </div>
          <div>
            <p className="text-sm text-muted-foreground">New Requests</p>
            <p className="text-2xl font-bold">{stats.open}</p>
          </div>
        </div>
        <div className="p-6 rounded-2xl border bg-card/50 flex items-center gap-4">
          <div className="p-3 rounded-xl bg-blue-500/10">
            <RefreshCcw className="w-6 h-6 text-blue-500" />
          </div>
          <div>
            <p className="text-sm text-muted-foreground">In Progress</p>
            <p className="text-2xl font-bold">{stats.active}</p>
          </div>
        </div>
        <div className="p-6 rounded-2xl border bg-card/50 flex items-center gap-4">
          <div className="p-3 rounded-xl bg-green-500/10">
            <CheckCircle2 className="w-6 h-6 text-green-500" />
          </div>
          <div>
            <p className="text-sm text-muted-foreground">Resolved Today</p>
            <p className="text-2xl font-bold">{stats.resolved}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input 
              placeholder="Search by student or title..." 
              className="pl-10"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="card-elevated overflow-hidden bg-card border border-border rounded-2xl">
            <Tabs value={activeTab} onValueChange={setActiveTab}>
              <TabsList className="w-full rounded-none border-b bg-muted/50">
                <TabsTrigger value="all" className="flex-1">All</TabsTrigger>
                <TabsTrigger value="pending" className="flex-1 text-orange-500">New</TabsTrigger>
                <TabsTrigger value="assigned" className="flex-1 text-blue-500">Active</TabsTrigger>
                <TabsTrigger value="resolved" className="flex-1 text-green-500">Fixed</TabsTrigger>
              </TabsList>
              
              <div className="divide-y max-h-[600px] overflow-y-auto custom-scrollbar">
                {filteredIssues.length > 0 ? (
                  filteredIssues.map((issue) => (
                    <div 
                      key={issue.id}
                      onClick={() => setSelectedIssue(issue)}
                      className={cn(
                        "p-4 cursor-pointer hover:bg-muted/30 transition-all",
                        selectedIssue?.id === issue.id && "bg-primary/5 border-l-4 border-primary"
                      )}
                    >
                      <div className="flex justify-between items-start mb-2">
                        <Badge variant="secondary" className={getStatusConfig(issue.status).bg + " " + getStatusConfig(issue.status).color}>
                          {getStatusConfig(issue.status).label}
                        </Badge>
                        <span className="text-[10px] uppercase font-bold text-muted-foreground">
                          {issue.createdAt ? new Date(issue.createdAt).toLocaleDateString() : 'Just now'}
                        </span>
                      </div>
                      <h3 className="font-bold text-foreground line-clamp-1">{issue.title}</h3>
                      <div className="flex items-center gap-2 mt-2 text-sm text-muted-foreground">
                        <User className="w-3 h-3" /> {issue.studentName}
                        <MapPin className="w-3 h-3 ml-2" /> {issue.roomNumber}
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="p-8 text-center text-muted-foreground">
                    No issues matching your filters.
                  </div>
                )}
              </div>
            </Tabs>
          </div>
        </div>

        <div className="lg:col-span-3">
          {selectedIssue ? (
            <motion.div 
              layout
              className="card-elevated flex flex-col h-[750px] bg-card border border-border rounded-2xl shadow-xl overflow-hidden"
            >
              <div className="p-6 border-b bg-muted/20">
                <div className="flex justify-between items-start">
                  <div>
                    <h2 className="text-xl font-bold mb-1">{selectedIssue.title}</h2>
                    <div className="flex items-center gap-4 text-sm text-muted-foreground italic">
                      <span>Reported by: <b className="text-primary">{selectedIssue.studentName}</b></span>
                      <span>Room: <b className="text-primary">{selectedIssue.roomNumber}</b></span>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    {normalizeStatus(selectedIssue.status) === 'pending' && (
                      <Button size="sm" onClick={() => updateStatus(selectedIssue.id, 'assigned')}>
                        Mark In Progress
                      </Button>
                    )}
                    {normalizeStatus(selectedIssue.status) === 'assigned' && (
                      <Button size="sm" variant="success" onClick={() => updateStatus(selectedIssue.id, 'resolved')}>
                        Mark Resolved
                      </Button>
                    )}
                  </div>
                </div>
                <div className="mt-4 p-4 rounded-xl bg-muted/30 text-sm leading-relaxed border border-border">
                  {selectedIssue.description}
                </div>
              </div>

              <div className="flex-1 p-6 overflow-y-auto space-y-4 bg-muted/5 custom-scrollbar">
                <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-muted-foreground mb-4">
                  <MessageSquare className="w-4 h-4" /> Activity Logs
                </div>
                
                {selectedIssue.responses?.map((res, idx) => (
                  <div key={idx} className={cn(
                    "flex flex-col gap-1 max-w-[85%]",
                    res.from === 'Maintenance Team' ? "ml-auto items-end" : "items-start"
                  )}>
                    <div className={cn(
                      "px-4 py-3 rounded-2xl text-sm shadow-sm",
                      res.from === 'Maintenance Team' ? "bg-primary text-primary-foreground rounded-tr-none" : "bg-card border border-border rounded-tl-none"
                    )}>
                      {res.message}
                    </div>
                    <span className="text-[10px] text-muted-foreground px-1">
                      {res.from} • {res.timestamp ? new Date(res.timestamp).toLocaleTimeString() : 'Just now'}
                    </span>
                  </div>
                ))}
              </div>

              <div className="p-4 border-t bg-card">
                <div className="flex gap-2">
                  <Input 
                    placeholder="Type a response to the student..." 
                    value={newMessage}
                    onChange={e => setNewMessage(e.target.value)}
                    onKeyPress={e => e.key === 'Enter' && handleSendMessage()}
                    className="flex-1"
                  />
                  <Button onClick={handleSendMessage} variant="gradient">
                    <Send className="w-4 h-4 mr-2" />
                    Reply
                  </Button>
                </div>
              </div>
            </motion.div>
          ) : (
            <div className="card-elevated h-full flex items-center justify-center bg-card border border-dashed border-border rounded-2xl">
              <div className="text-center">
                <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mx-auto mb-4">
                  <ShieldCheck className="w-8 h-8 text-muted-foreground" />
                </div>
                <h3 className="text-lg font-bold">Maintenance Console</h3>
                <p className="text-muted-foreground">Select an issue from the list to start resolving it.</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';
import { Button, Card, CardContent, CardHeader, CardTitle } from "@pec/ui";


import React, { useState, useEffect } from 'react';
import { Activity, Server, Database, Clock, RefreshCcw, Cpu } from 'lucide-react';

import { toast } from 'sonner';

export default function ObservabilityAdmin() {
  const [metrics, setMetrics] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(true);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  const fetchMetrics = async () => {
    setLoading(true);
    try {
      // Assuming metrics are exposed at the Next.js proxy /api/metrics or directly at the internal backend url
      const response = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/metrics`);
      if (!response.ok) {
        throw new Error('Failed to fetch metrics');
      }
      const data = await response.text();
      setMetrics(data);
      setLastUpdated(new Date());
    } catch (error) {
      console.error('Error fetching metrics:', error);
      toast.error('Failed to load observability metrics');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMetrics();
    // Refresh every 30 seconds
    const interval = setInterval(fetchMetrics, 30000);
    return () => clearInterval(interval);
  }, []);

  // Basic parsing of prometheus text format for simple display
  const processMemory = metrics.match(/process_resident_memory_bytes (\d+)/)?.[1];
  const processMemoryMB = processMemory ? (parseInt(processMemory) / 1024 / 1024).toFixed(2) : 'N/A';

  const nodejsHeapUsed = metrics.match(/nodejs_heap_space_size_used_bytes\{space="new"\} (\d+)/)?.[1];
  const nodejsHeapUsedMB = nodejsHeapUsed ? (parseInt(nodejsHeapUsed) / 1024 / 1024).toFixed(2) : 'N/A';

  return (
    <div className="container mx-auto px-4 py-8 max-w-7xl">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
        <div>
          <h1 className="text-3xl font-bold text-foreground mb-2 flex items-center gap-3">
            <Activity className="w-8 h-8 text-primary" />
            System Observability
          </h1>
          <p className="text-muted-foreground">Monitor API performance, memory usage, and database query times in real-time.</p>
        </div>
        <Button onClick={fetchMetrics} disabled={loading} className="gap-2">
          <RefreshCcw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
          Refresh Data
        </Button>
      </div>

      <div className="grid gap-6 md:grid-cols-4 mb-8">
        <Card className="bg-card/50 border-border">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground flex items-center gap-2">
              <Server className="w-4 h-4" />
              Resident Memory
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{processMemoryMB} MB</div>
          </CardContent>
        </Card>

        <Card className="bg-card/50 border-border">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground flex items-center gap-2">
              <Cpu className="w-4 h-4" />
              Heap Used (New)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{nodejsHeapUsedMB} MB</div>
          </CardContent>
        </Card>

        <Card className="bg-card/50 border-border">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground flex items-center gap-2">
              <Database className="w-4 h-4" />
              Database Health
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-500">Connected</div>
          </CardContent>
        </Card>

        <Card className="bg-card/50 border-border">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground flex items-center gap-2">
              <Clock className="w-4 h-4" />
              Last Updated
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-sm font-medium">
              {lastUpdated ? lastUpdated.toLocaleTimeString() : 'Pending...'}
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="card-elevated overflow-hidden bg-card border border-border rounded-2xl shadow-sm">
        <div className="p-4 border-b bg-muted/20 flex justify-between items-center">
          <h2 className="font-bold">Raw Prometheus Metrics</h2>
          <span className="text-xs text-muted-foreground">Scraped from /metrics</span>
        </div>
        <div className="p-4">
          {loading && !metrics ? (
            <div className="flex justify-center p-8">
              <RefreshCcw className="w-8 h-8 animate-spin text-muted-foreground" />
            </div>
          ) : (
            <pre className="text-xs bg-muted/50 p-4 rounded-lg overflow-x-auto max-h-[500px] custom-scrollbar border border-border text-foreground">
              {metrics || 'No metrics data available. Make sure the backend metrics endpoint is reachable.'}
            </pre>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';
import { Button, Input, Badge, Card, CardContent, CardDescription, CardHeader, CardTitle, RadioGroup, RadioGroupItem } from "@pec/ui";


import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  ArrowLeft,
  Save,
  AlertCircle,
  CheckCircle2,
  Copy,
  Eye,
  EyeOff,
  Loader2,
} from 'lucide-react';

import { toast } from 'sonner';
import { usePermissions } from '@/hooks/usePermissions';
import { useRouter } from 'next/navigation';
import { cn } from '@/lib/utils';
import api from "@pec/api";

type PaymentMethod = 'razorpay' | 'upi' | 'bank';

interface PaymentConfig {
  method: PaymentMethod;
  razorpay?: {
    apiKey: string;
    apiSecret: string;
  };
  upi?: {
    upiId: string;
    upiName: string;
  };
  bank?: {
    bankName: string;
    accountName: string;
    accountNumber: string;
    ifscCode: string;
    branch: string;
  };
  isActive: boolean;
  lastUpdated: any;
  updatedBy: string;
}

const extractData = <T,>(payload: any): T => {
  if (payload && typeof payload === 'object' && 'success' in payload && 'data' in payload) {
    return payload.data as T;
  }
  return payload as T;
};

export default function PaymentSettings() {
  const embedded = false;
  const router = useRouter();
  const { user, isAdmin, loading: authLoading } = usePermissions();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<PaymentConfig | null>(null);
  const [method, setMethod] = useState<PaymentMethod>('upi');
  const [showApiSecret, setShowApiSecret] = useState(false);

  // UPI fields
  const [upiId, setUpiId] = useState('');
  const [upiName, setUpiName] = useState('');

  // Bank fields
  const [bankName, setBankName] = useState('');
  const [accountName, setAccountName] = useState('');
  const [accountNumber, setAccountNumber] = useState('');
  const [ifscCode, setIfscCode] = useState('');
  const [branch, setBranch] = useState('');

  // Razorpay fields
  const [apiKey, setApiKey] = useState('');
  const [apiSecret, setApiSecret] = useState('');

  useEffect(() => {
    if (authLoading) return;
    if (!user || !isAdmin) {
      router.replace('/auth');
      return;
    }

    fetchPaymentSettings();
  }, [authLoading, user, isAdmin, router]);

  useEffect(() => {
    if (settings) {
      setMethod(settings.method);
      if (settings.method === 'razorpay' && settings.razorpay) {
        setApiKey(settings.razorpay.apiKey);
        setApiSecret(settings.razorpay.apiSecret);
      } else if (settings.method === 'upi' && settings.upi) {
        setUpiId(settings.upi.upiId);
        setUpiName(settings.upi.upiName);
      } else if (settings.method === 'bank' && settings.bank) {
        setBankName(settings.bank.bankName);
        setAccountName(settings.bank.accountName);
        setAccountNumber(settings.bank.accountNumber);
        setIfscCode(settings.bank.ifscCode);
        setBranch(settings.bank.branch);
      }
    }
  }, [settings]);

  const fetchPaymentSettings = async () => {
    try {
      setLoading(true);
      const response = await api.get('/feature-flags/payment-config');
      const flag = extractData<any>(response.data);
      const payload = flag?.payload ? JSON.parse(flag.payload) : null;
      if (payload) {
        setSettings(payload as PaymentConfig);
      } else {
        setSettings(null);
        setMethod('upi');
      }
    } catch (error) {
      console.error('Error fetching payment settings:', error);
      toast.error('Failed to load payment settings');
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (method === 'upi') {
      if (!upiId.trim() || !upiName.trim()) {
        toast.error('Please fill in UPI ID and Name');
        return;
      }
      if (!upiId.includes('@')) {
        toast.error('Invalid UPI ID format (should be like 9876543210@ybl)');
        return;
      }
    } else if (method === 'bank') {
      if (!bankName.trim() || !accountName.trim() || !accountNumber.trim() || !ifscCode.trim()) {
        toast.error('Please fill in all bank details');
        return;
      }
    } else if (method === 'razorpay') {
      if (!apiKey.trim() || !apiSecret.trim()) {
        toast.error('Please fill in API Key and Secret');
        return;
      }
    }

    try {
      setSaving(true);
      const newConfig: PaymentConfig = {
        method,
        isActive: true,
        lastUpdated: new Date().toISOString(),
        updatedBy: user?.email || 'unknown',
      };

      if (method === 'upi') {
        newConfig.upi = {
          upiId: upiId.trim(),
          upiName: upiName.trim(),
        };
      } else if (method === 'bank') {
        newConfig.bank = {
          bankName: bankName.trim(),
          accountName: accountName.trim(),
          accountNumber: accountNumber.trim(),
          ifscCode: ifscCode.trim(),
          branch: branch.trim(),
        };
      } else if (method === 'razorpay') {
        newConfig.razorpay = {
          apiKey: apiKey.trim(),
          apiSecret: apiSecret.trim(),
        };
      }

      await api.post('/feature-flags/payment-config', {
        enabled: true,
        description: 'Campus payment gateway configuration',
        payload: JSON.stringify(newConfig),
      });

      setSettings(newConfig);
      toast.success(`Payment method updated to ${method.toUpperCase()}`);
    } catch (error) {
      console.error('Error saving payment settings:', error);
      toast.error('Failed to save payment settings');
    } finally {
      setSaving(false);
    }
  };

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    toast.success(`${label} copied!`);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="space-y-6"
    >
      {/* Back Button */}
      {!embedded && (
        <Button variant="ghost" onClick={() => router.push('/finance' as any)} className="gap-2">
          <ArrowLeft className="w-4 h-4" />
          Back to Finance
        </Button>
      )}

      {/* Header */}
      {!embedded && (
        <div>
          <h1 className="text-3xl font-bold text-foreground">Payment Settings</h1>
          <p className="text-muted-foreground mt-2">
            Configure how students will pay fees
          </p>
        </div>
      )}

      {/* Current Status */}
      {settings && (
        <Card className="border-success/30 bg-success/5">
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <CheckCircle2 className="w-5 h-5 text-success" />
              <div>
                <p className="font-medium text-foreground capitalize">
                  Current: {settings.method} Payment
                </p>
                <p className="text-sm text-muted-foreground">
                  Last updated: {settings.lastUpdated ? new Date(settings.lastUpdated).toLocaleDateString() : 'Never'}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Payment Method Selection */}
      <Card>
        <CardHeader>
          <CardTitle>Choose Payment Method</CardTitle>
          <CardDescription>
            Select which payment method your students will use
          </CardDescription>
        </CardHeader>
        <CardContent>
          <RadioGroup value={method} onValueChange={(val) => setMethod(val as PaymentMethod)}>
            <div className="space-y-4">
              {/* UPI Option */}
              <div className={cn(
                'p-4 rounded-lg border-2 cursor-pointer transition-all',
                method === 'upi'
                  ? 'border-primary bg-primary/5'
                  : 'border-border hover:border-border/80'
              )}>
                <div className="flex items-start gap-3">
                  <RadioGroupItem value="upi" id="upi-radio" className="mt-1" />
                  <div className="flex-1">
                    <label htmlFor="upi-radio" className="font-semibold text-foreground cursor-pointer">
                      UPI Payment ⚡
                    </label>
                    <p className="text-sm text-muted-foreground mt-1">
                      Simple & Direct - Students scan QR or click button to pay via UPI app
                    </p>
                    <Badge variant="outline" className="mt-2">
                      0% Commission
                    </Badge>
                  </div>
                </div>
              </div>

              {/* Bank Option */}
              <div className={cn(
                'p-4 rounded-lg border-2 cursor-pointer transition-all',
                method === 'bank'
                  ? 'border-primary bg-primary/5'
                  : 'border-border hover:border-border/80'
              )}>
                <div className="flex items-start gap-3">
                  <RadioGroupItem value="bank" id="bank-radio" className="mt-1" />
                  <div className="flex-1">
                    <label htmlFor="bank-radio" className="font-semibold text-foreground cursor-pointer">
                      Bank Transfer 🏦
                    </label>
                    <p className="text-sm text-muted-foreground mt-1">
                      Manual - Students transfer to your bank account and upload proof for verification
                    </p>
                    <Badge variant="outline" className="mt-2">
                      0% Commission | Manual Verification
                    </Badge>
                  </div>
                </div>
              </div>

              {/* Razorpay Option */}
              <div className={cn(
                'p-4 rounded-lg border-2 cursor-pointer transition-all',
                method === 'razorpay'
                  ? 'border-primary bg-primary/5'
                  : 'border-border hover:border-border/80'
              )}>
                <div className="flex items-start gap-3">
                  <RadioGroupItem value="razorpay" id="razorpay-radio" className="mt-1" />
                  <div className="flex-1">
                    <label htmlFor="razorpay-radio" className="font-semibold text-foreground cursor-pointer">
                      Razorpay Payment 💳
                    </label>
                    <p className="text-sm text-muted-foreground mt-1">
                      Professional - Cards, UPI, NetBanking, Wallets. Auto-verified payments.
                    </p>
                    <Badge variant="outline" className="mt-2">
                      0% for UPI | 0.5-2% for others
                    </Badge>
                  </div>
                </div>
              </div>
            </div>
          </RadioGroup>
        </CardContent>
      </Card>

      {/* Configuration Forms */}
      <Card>
        <CardHeader>
          <CardTitle>
            {method === 'upi' ? 'UPI Configuration' : method === 'bank' ? 'Bank Details Configuration' : 'Razorpay Configuration'}
          </CardTitle>
          <CardDescription>
            {method === 'upi'
              ? 'Your UPI ID for receiving payments'
              : method === 'bank'
              ? 'Your bank account details for student transfers'
              : 'Your Razorpay API credentials (get from https://razorpay.com)'}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {method === 'upi' ? (
            <>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  UPI ID *
                </label>
                <Input
                  placeholder="9876543210@ybl"
                  value={upiId}
                  onChange={(e) => setUpiId(e.target.value)}
                  className="font-mono text-sm"
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Format: phone@bankname (e.g., 9876543210@ybl, 9876543210@okhdfcbank)
                </p>
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Your Name *
                </label>
                <Input
                  placeholder="Ananay Dubey"
                  value={upiName}
                  onChange={(e) => setUpiName(e.target.value)}
                />
                <p className="text-xs text-muted-foreground mt-1">
                  How your name appears in payment apps
                </p>
              </div>

              {/* Preview */}
              {upiId && upiName && (
                <div className="p-3 bg-secondary/50 rounded-lg border border-border">
                  <p className="text-xs font-medium text-muted-foreground mb-2">Preview:</p>
                  <div className="space-y-1">
                    <p className="text-sm">
                      <span className="font-medium">Name:</span> {upiName}
                    </p>
                    <p className="text-sm font-mono">
                      <span className="font-medium">UPI:</span> {upiId}
                    </p>
                  </div>
                </div>
              )}
            </>
          ) : method === 'bank' ? (
            <>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Bank Name *
                </label>
                <Input
                  placeholder="State Bank of India"
                  value={bankName}
                  onChange={(e) => setBankName(e.target.value)}
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Account Holder Name *
                </label>
                <Input
                  placeholder="Your Name"
                  value={accountName}
                  onChange={(e) => setAccountName(e.target.value)}
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Account Number *
                </label>
                <Input
                  placeholder="1234567890123456"
                  value={accountNumber}
                  onChange={(e) => setAccountNumber(e.target.value)}
                  className="font-mono"
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  IFSC Code *
                </label>
                <Input
                  placeholder="SBIN0001234"
                  value={ifscCode}
                  onChange={(e) => setIfscCode(e.target.value)}
                  className="font-mono"
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Branch
                </label>
                <Input
                  placeholder="University Campus Branch"
                  value={branch}
                  onChange={(e) => setBranch(e.target.value)}
                />
              </div>

              {/* Preview */}
              {bankName && accountNumber && (
                <div className="p-3 bg-secondary/50 rounded-lg border border-border">
                  <p className="text-xs font-medium text-muted-foreground mb-2">Preview:</p>
                  <div className="space-y-1 text-sm">
                    <p><span className="font-medium">Bank:</span> {bankName}</p>
                    <p><span className="font-medium">Account:</span> {accountName}</p>
                    <p className="font-mono"><span className="font-medium">Number:</span> {accountNumber}</p>
                    <p className="font-mono"><span className="font-medium">IFSC:</span> {ifscCode}</p>
                  </div>
                </div>
              )}
            </>
          ) : (
            <>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Razorpay API Key *
                </label>
                <div className="flex gap-2">
                  <Input
                    placeholder="rzp_live_xxxxxxxxxxxxx"
                    value={apiKey}
                    onChange={(e) => setApiKey(e.target.value)}
                    className="font-mono text-sm"
                  />
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => copyToClipboard(apiKey, 'API Key')}
                    disabled={!apiKey}
                  >
                    <Copy className="w-4 h-4" />
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground mt-1">
                  Get from Razorpay Dashboard → Settings → API Keys
                </p>
              </div>

              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Razorpay API Secret *
                </label>
                <div className="flex gap-2">
                  <Input
                    placeholder="xxxxxxxxxxxxxxxxxxxxxxxx"
                    type={showApiSecret ? 'text' : 'password'}
                    value={apiSecret}
                    onChange={(e) => setApiSecret(e.target.value)}
                    className="font-mono text-sm"
                  />
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => setShowApiSecret(!showApiSecret)}
                  >
                    {showApiSecret ? (
                      <EyeOff className="w-4 h-4" />
                    ) : (
                      <Eye className="w-4 h-4" />
                    )}
                  </Button>
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => copyToClipboard(apiSecret, 'API Secret')}
                    disabled={!apiSecret}
                  >
                    <Copy className="w-4 h-4" />
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground mt-1">
                  Keep this secret! Never share publicly
                </p>
              </div>

              {/* Info Box */}
              <div className="p-3 bg-blue-50/50 dark:bg-blue-950/20 rounded-lg border border-blue-200/50 dark:border-blue-800/50">
                <div className="flex gap-2">
                  <AlertCircle className="w-4 h-4 text-blue-600 dark:text-blue-400 flex-shrink-0 mt-0.5" />
                  <div className="text-sm text-blue-900 dark:text-blue-200">
                    <p className="font-medium">Get Razorpay credentials:</p>
                    <ol className="list-decimal list-inside mt-1 space-y-1">
                      <li>Visit <a href="https://razorpay.com" target="_blank" rel="noopener noreferrer" className="underline font-medium">razorpay.com</a></li>
                      <li>Sign up (free account)</li>
                      <li>Go to Settings → API Keys</li>
                      <li>Copy Key ID and Key Secret</li>
                    </ol>
                  </div>
                </div>
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {/* Warning Box */}
      <Card className="border-yellow-200/50 bg-yellow-50/50 dark:border-yellow-800/50 dark:bg-yellow-950/20">
        <CardContent className="pt-6">
          <div className="flex gap-3">
            <AlertCircle className="w-5 h-5 text-yellow-600 dark:text-yellow-500 flex-shrink-0" />
            <div className="text-sm text-yellow-900 dark:text-yellow-200">
              <p className="font-medium">Important:</p>
              <ul className="list-disc list-inside mt-2 space-y-1">
                <li>Changing payment method will affect future payments</li>
                <li>Students will see the configured method on payment page</li>
                <li>Keep your credentials secure</li>
                {method === 'razorpay' && <li>Razorpay will verify payments automatically</li>}
                {method === 'upi' && <li>You&apos;ll need to verify UPI payments in your bank</li>}
              </ul>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex gap-3">
        <Button
          size="lg"
          onClick={handleSave}
          disabled={saving}
          className="gap-2"
        >
          {saving ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save className="w-4 h-4" />
              Save Configuration
            </>
          )}
        </Button>
        {!embedded && (
          <Button
            variant="outline"
            size="lg"
            onClick={() => router.push('/finance' as any)}
          >
            Cancel
          </Button>
        )}
      </div>
    </motion.div>
  );
}

'use client';
import { Button, Input, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Badge, Dialog, DialogContent } from "@pec/ui";


import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  CheckCircle,
  XCircle,
  Clock,
  Upload,
} from 'lucide-react';

import { toast } from 'sonner';
import api from "@pec/api";
import { extractData } from '@/lib/utils';
import { LoadingGrid } from '@/components/common/AsyncState';
import PDFExportButton from '@/components/common/PDFExportButton';
import BulkUpload from '@/components/BulkUpload';

interface CourseAttendance {
  courseId: string;
  courseName: string;
  courseCode: string;
  present: number;
  absent: number;
  late: number;
  total: number;
  percentage: number;
}

interface AttendanceClientProps {
  session: any;
  initialData?: any;
}

export default function AttendanceClient({ session, initialData }: AttendanceClientProps) {
  const isAdmin = session.role === 'college_admin';
  const isFaculty = session.role === 'faculty';

  if (isAdmin || isFaculty) {
    return <AttendanceManager userId={session.uid} userRole={session.role} initialData={initialData} />;
  }

  return <StudentAttendanceView userId={session.uid} initialData={initialData} />;
}

function AttendanceManager({ userId, userRole, initialData }: { userId: string; userRole: string; initialData?: any }) {
  const [courses, setCourses] = useState<any[]>(initialData?.courses || []);
  const [selectedCourse, setSelectedCourse] = useState('');
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [students, setStudents] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [showBulkUpload, setShowBulkUpload] = useState(false);

  const isAdmin = userRole === 'college_admin';

  useEffect(() => {
    if (!initialData?.courses || initialData.courses.length === 0) {
       fetchCourses();
    }
  }, [userId, userRole, initialData]);

  useEffect(() => {
    if (selectedCourse && selectedDate) {
      fetchStudentAttendance();
    } else {
      setStudents([]);
    }
  }, [selectedCourse, selectedDate]);

  const fetchCourses = async () => {
    try {
      let data: any[] = [];
      if (isAdmin) {
        const response = await api.get<any>('/courses', {
          params: { limit: 200, offset: 0 },
        });
        data = extractData<any[]>(response) || [];
      } else {
        const response = await api.get<any>('/courses', {
          params: { facultyId: userId, limit: 200, offset: 0 },
        });
        data = extractData<any[]>(response) || [];
        if (!data.length) {
          const fallback = await api.get<any>('/courses', {
            params: { limit: 200, offset: 0 },
          });
          const allCourses = extractData<any[]>(fallback) || [];
          data = allCourses.filter((course: any) =>
            course.facultyId === userId || course.instructorId === userId
          );
        }
      }
      
      setCourses(data);
    } catch (error) {
      console.error('Error fetching courses:', error);
    }
  };

  const fetchStudentAttendance = async () => {
    setLoading(true);
    try {
      const [enrollmentsRes, attendanceRes] = await Promise.all([
        api.get<any>('/enrollments', {
          params: { courseId: selectedCourse, status: 'active', limit: 100, offset: 0 },
        }),
        api.get<any>('/attendance', {
          params: { subject: selectedCourse, date: selectedDate },
        })
      ]);

      const enrolledStudents = (extractData<any[]>(enrollmentsRes) || []);
      const attendanceRows = extractData<any[]>(attendanceRes) || [];

      const existingRecords = attendanceRows.reduce((acc: any, record: any) => {
        acc[record.studentId] = record;
        return acc;
      }, {});

      const merged = (enrolledStudents || []).map(en => {
        const student = en.student || null;
        return {
          id: en.studentId,
          name: student?.name || student?.fullName || 'Unknown',
          email: student?.email || '',
          recordId: existingRecords[en.studentId]?.id,
          status: existingRecords[en.studentId]?.status || null
        };
      });

      setStudents(merged);
    } catch (error) {
      console.error('Error fetching students:', error);
      toast.error('Failed to load student list');
    } finally {
      setLoading(false);
    }
  };

  const handleMark = (studentId: string, status: string) => {
    setStudents(prev => prev.map(s => s.id === studentId ? { ...s, status } : s));
  };

  const handleSave = async () => {
    try {
      const batchPromises = students.map(async (student) => {
        if (!student.status) return;

        const data = {
          studentId: student.id,
          subject: selectedCourse,
          date: selectedDate,
          status: student.status,
        };

        if (student.recordId) {
           await api.patch(`/attendance/${student.recordId}`, data);
        } else {
           await api.post('/attendance', data);
        }
      });
      await Promise.all(batchPromises);
      toast.success('Attendance records synchronized successfully');
      fetchStudentAttendance();
    } catch (error) {
      toast.error('Failed to synchronize records');
    }
  };

  const handleBulkImport = async (data: any[]) => {
    return { success: data.length, failed: 0, errors: [] };
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-foreground uppercase tracking-widest">Attendance Management</h1>
          <p className="text-muted-foreground mt-1 font-medium italic">Protocol-level session verification and ledger control</p>
        </div>
        <div className="flex gap-2">
            <PDFExportButton
              onExport={async () => {
                if (!selectedCourse) {
                  toast.error('Please select a course first');
                  return;
                }
                const { exportAttendanceReport } = await import('@/lib/pdfExport');
                const course = courses.find(c => c.id === selectedCourse);
                const attendanceData = students.map(s => ({
                  studentName: s.name,
                  enrollmentNumber: s.email,
                  present: s.status === 'present' ? 1 : 0,
                  absent: s.status === 'absent' ? 1 : 0,
                  total: s.status ? 1 : 0,
                  percentage: s.status === 'present' ? 100 : s.status === 'absent' ? 0 : 50
                }));
                exportAttendanceReport(
                  course?.name || 'Course',
                  attendanceData,
                  { start: selectedDate, end: selectedDate }
                );
              }}
              label="EXCEL LEDGER"
            />
            <Button variant="outline" onClick={() => setShowBulkUpload(true)} className="h-10 px-4 font-black uppercase tracking-widest text-[10px]">
              <Upload className="w-3 h-3 mr-2" /> DATA SYNC
            </Button>
        </div>
      </div>

      <div className="card-elevated p-6 space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
          <div className="md:col-span-8">
            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground mb-2 block">Instructional Course</label>
            <Select value={selectedCourse} onValueChange={setSelectedCourse}>
              <SelectTrigger className="h-12 text-sm font-bold bg-muted/20 border-border/60">
                <SelectValue placeholder="Select high-priority course..." />
              </SelectTrigger>
              <SelectContent>
                {courses.map(c => (
                  <SelectItem key={c.id} value={c.id} className="font-bold py-3 text-sm">
                    <span className="text-primary mr-2">[{c.code}]</span> {c.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="md:col-span-4">
            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground mb-2 block">Sync Date</label>
            <Input 
              type="date" 
              className="h-12 bg-muted/20 border-border/60 font-mono font-bold"
              value={selectedDate} 
              onChange={(e) => setSelectedDate(e.target.value)} 
            />
          </div>
        </div>

        {selectedCourse && (
          <div className="pt-8 border-t border-border/60 space-y-6">
             {loading ? <LoadingGrid count={5} /> : (
               <>
                 <div className="border border-border/60 rounded-xl overflow-hidden bg-card shadow-xl">
                    <table className="w-full border-collapse">
                      <thead>
                        <tr className="bg-muted border-b border-border/60">
                          <th className="py-4 px-6 text-left font-black uppercase text-[10px] tracking-widest text-primary border-r border-border/60">Registry Student</th>
                          <th className="py-4 px-6 text-center font-black uppercase text-[10px] tracking-widest">Verification Status</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-border/60">
                        {students.map(s => (
                          <tr key={s.id} className="group hover:bg-muted/30 transition-colors">
                            <td className="py-4 px-6 border-r border-border/60">
                              <div className="flex flex-col">
                                <span className="font-black text-foreground group-hover:text-primary transition-colors tracking-tight">{s.name}</span>
                                <span className="text-[10px] text-muted-foreground font-mono uppercase tracking-tighter">{s.email}</span>
                              </div>
                            </td>
                            <td className="py-4 px-6">
                               <div className="flex justify-center gap-2">
                                  {['present', 'absent', 'late'].map(status => (
                                    <Button
                                      key={status}
                                      size="sm"
                                      variant={s.status === status ? 'default' : 'outline'}
                                      className={`text-[9px] font-black uppercase tracking-widest px-4 h-9 transition-all
                                        ${s.status === status 
                                          ? (status === 'present' ? 'bg-success hover:bg-success/90' : status === 'absent' ? 'bg-destructive hover:bg-destructive/90' : 'bg-warning hover:bg-warning/90')
                                          : 'hover:border-primary/50'
                                        }`}
                                      onClick={() => handleMark(s.id, status)}
                                    >
                                      {status === 'present' ? 'PRESENT' : status === 'absent' ? 'ABSENT' : 'LATE'}
                                    </Button>
                                  ))}
                               </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                 </div>
                 <div className="flex justify-end pt-4">
                    <Button 
                      onClick={handleSave} 
                      className="bg-primary text-primary-foreground font-black tracking-[0.2em] uppercase text-[11px] h-12 px-10 shadow-lg shadow-primary/20 hover:scale-[1.02] active:scale-[0.98] transition-all"
                    >
                       COMMIT RECORDS TO LEDGER
                    </Button>
                 </div>
               </>
             )}
          </div>
        )}
      </div>

      <Dialog open={showBulkUpload} onOpenChange={setShowBulkUpload}>
        <DialogContent className="max-w-4xl bg-card border-border/60">
           <div className="flex flex-col space-y-4">
             <div className="space-y-1">
                <h2 className="text-xl font-black uppercase tracking-widest">Bulk Sync Protocol</h2>
                <p className="text-sm text-muted-foreground font-medium italic">Import external session data via standard CSV/Excel format</p>
             </div>
             <BulkUpload 
               entityType="attendance" 
               onImport={handleBulkImport} 
               templateColumns={['studentEmail', 'courseCode', 'date', 'status']} 
               sampleData={[{ studentEmail: 'test@pec.edu', courseCode: 'CS101', date: '2024-03-30', status: 'present' }]} 
             />
           </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function StudentAttendanceView({ userId, initialData }: { userId: string; initialData?: any }) {
  const [loading, setLoading] = useState(!initialData?.summary);
  const [attendanceRecords, setAttendanceRecords] = useState<any[]>(initialData?.records || []);
  const [courseAttendance, setCourseAttendance] = useState<CourseAttendance[]>(initialData?.summary?.courses || []);
  const [overallPercentage, setOverallPercentage] = useState(initialData?.summary?.totalSummary?.percentage || 0);

  useEffect(() => {
    if (!initialData?.summary) {
      fetchData();
    }
  }, [userId, initialData]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [summaryRes, recordsRes] = await Promise.all([
        api.get<any>('/attendance/summary'),
        api.get<any>('/attendance', { params: { studentId: userId, limit: 100 } })
      ]);
      const summary = extractData<any>(summaryRes);
      if (summary) {
        setCourseAttendance(summary.courses || []);
        setOverallPercentage(summary.totalSummary?.percentage || 0);
      }
      setAttendanceRecords(extractData<any[]>(recordsRes) || []);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (percentage: number) => {
    if (percentage >= 75) return 'text-success';
    if (percentage >= 65) return 'text-warning';
    return 'text-destructive';
  };

  const getProgressColor = (percentage: number) => {
    if (percentage >= 75) return 'bg-success';
    if (percentage >= 65) return 'bg-warning';
    return 'bg-destructive';
  };

  if (loading) {
    return <LoadingGrid count={4} className="grid gap-6 md:grid-cols-2" itemClassName="h-32" />;
  }

  return (
    <div className="space-y-8 pb-20">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-foreground uppercase tracking-widest">Attendance Overview</h1>
          <p className="text-muted-foreground mt-1 font-medium italic">Detailed session analytics and eligibility tracking</p>
        </div>
        <div className="flex items-center gap-3">
          <Badge variant="outline" className="h-10 px-4 font-black uppercase tracking-widest text-[10px] bg-card">
            System Status: Active
          </Badge>
          <Badge className={`h-10 px-6 font-black tracking-widest uppercase text-[10px] ${overallPercentage >= 75 ? 'bg-success/20 text-success border-success/30' : 'bg-destructive/10 text-destructive border-destructive/20'}`}>
            {overallPercentage >= 75 ? 'ELIGIBLE' : 'SHORTAGE'}
          </Badge>
        </div>
      </div>

      <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="grid md:grid-cols-12 gap-6 items-stretch">
        <div className="md:col-span-5 card-elevated p-8 flex flex-col items-center justify-center relative overflow-hidden group">
           <div className="absolute inset-0 bg-primary/5 opacity-0 group-hover:opacity-100 transition-opacity" />
           <div className="relative w-48 h-48">
              <svg className="w-full h-full -rotate-90">
                <circle cx="96" cy="96" r="88" stroke="currentColor" strokeWidth="12" fill="none" className="text-muted/20" />
                <motion.circle 
                  cx="96" cy="96" r="88" stroke="currentColor" strokeWidth="12" fill="none" 
                  strokeDasharray={`${2 * Math.PI * 88}`} 
                  initial={{ strokeDashoffset: 2 * Math.PI * 88 }}
                  animate={{ strokeDashoffset: 2 * Math.PI * 88 * (1 - overallPercentage / 100) }}
                  transition={{ duration: 1.5, ease: "easeOut" }}
                  className={getStatusColor(overallPercentage)} strokeLinecap="square" 
                />
              </svg>
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className={`text-5xl font-black tracking-tighter ${getStatusColor(overallPercentage)}`}>{Math.round(overallPercentage)}%</span>
                <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mt-1">Aggregate</span>
              </div>
           </div>
        </div>

        <div className="md:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4">
           <div className="card-elevated p-6 flex flex-col justify-between border-l-4 border-success">
              <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Classes Attended</p>
              <div className="flex items-baseline gap-2">
                <span className="text-5xl font-black text-foreground">{(courseAttendance || []).reduce((s,c)=>s+c.present,0)}</span>
                <span className="text-muted-foreground font-bold text-sm">Sessions</span>
              </div>
              <div className="mt-4 flex items-center gap-2 text-success font-bold text-[10px] uppercase tracking-widest">
                <CheckCircle className="w-3 h-3" /> Growth: +2.4%
              </div>
           </div>
           <div className="card-elevated p-6 flex flex-col justify-between border-l-4 border-destructive">
              <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Classes Missed</p>
              <div className="flex items-baseline gap-2">
                <span className="text-5xl font-black text-foreground">{(courseAttendance || []).reduce((s,c)=>s+c.absent,0)}</span>
                <span className="text-muted-foreground font-bold text-sm">Sessions</span>
              </div>
              <div className="mt-4 flex items-center gap-2 text-destructive font-bold text-[10px] uppercase tracking-widest">
                <XCircle className="w-3 h-3" /> Risk Factor: High
              </div>
           </div>
        </div>
      </motion.div>

      <div className="space-y-4">
        <div className="flex items-center gap-2">
           <div className="h-px flex-1 bg-border/60" />
           <span className="text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground px-4">Course Specific Metrics</span>
           <div className="h-px flex-1 bg-border/60" />
        </div>
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
           {(courseAttendance || []).map(c => (
             <motion.div 
               key={c.courseId} 
               whileHover={{ y: -4 }}
               className={`card-elevated p-6 border group transition-all ${c.percentage < 75 ? 'border-destructive/30 hover:border-destructive/60' : 'border-border hover:border-primary/40'}`}
             >
                <div className="flex justify-between items-start mb-6">
                  <div className="space-y-1">
                    <Badge variant="secondary" className="font-mono text-[9px] h-5 tracking-tight px-2 bg-muted/50">{c.courseCode}</Badge>
                    <h3 className="font-black text-foreground uppercase tracking-tight text-sm line-clamp-1">{c.courseName}</h3>
                  </div>
                  <div className={`text-2xl font-black tracking-tighter ${getStatusColor(c.percentage)}`}>{Math.round(c.percentage)}%</div>
                </div>

                <div className="space-y-3">
                   <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden border border-border/10">
                     <motion.div 
                      initial={{ width: 0 }}
                      animate={{ width: `${c.percentage}%` }}
                      className={`h-full ${getProgressColor(c.percentage)}`}
                     />
                   </div>
                   <div className="flex justify-between text-[10px] font-black uppercase tracking-tighter">
                      <span className="text-success flex items-center gap-1 group-hover:gap-2 transition-all">ATTENDED: {c.present}</span>
                      <span className="text-destructive">MISSED: {c.absent}</span>
                   </div>
                </div>
             </motion.div>
           ))}
        </div>
      </div>

      <div className="space-y-4">
         <div className="flex items-center justify-between">
           <h2 className="font-black uppercase tracking-widest text-sm flex items-center gap-2">
             <Clock className="w-4 h-4 text-primary" /> Session History Log
           </h2>
           <div className="text-[10px] font-bold text-muted-foreground uppercase opacity-60">Showing last 100 interactions</div>
         </div>
         
         <div className="border border-border/60 rounded-xl overflow-hidden bg-card shadow-2xl">
            <table className="w-full border-collapse">
              <thead>
                <tr className="bg-muted border-b border-border/60">
                  <th className="py-4 px-6 text-left font-black uppercase text-[10px] tracking-widest text-primary border-r border-border/60">Verification</th>
                  <th className="py-4 px-6 text-left font-black uppercase text-[10px] tracking-widest border-r border-border/60">Subject & Instructor</th>
                  <th className="py-4 px-6 text-left font-black uppercase text-[10px] tracking-widest border-r border-border/60">Timestamp</th>
                  <th className="py-4 px-6 text-right font-black uppercase text-[10px] tracking-widest">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/60">
                {!Array.isArray(attendanceRecords) || attendanceRecords.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="py-20 text-center text-muted-foreground font-medium italic">No attendance data logged yet.</td>
                  </tr>
                ) : (
                  attendanceRecords.map(r => {
                    const course = (courseAttendance || []).find(c => c.courseId === r.subject);
                    const isPresent = r.status === 'present';
                    return (
                      <tr key={r.id} className="group hover:bg-muted/30 transition-colors">
                        <td className="py-4 px-6 border-r border-border/60">
                          <div className={`w-10 h-10 rounded-lg flex items-center justify-center border ${isPresent ? 'bg-success/10 text-success border-success/20' : 'bg-destructive/10 text-destructive border-destructive/20'}`}>
                            {isPresent ? <CheckCircle className="w-5 h-5" /> : <XCircle className="w-5 h-5" />}
                          </div>
                        </td>
                        <td className="py-4 px-6 border-r border-border/60">
                          <div className="flex flex-col">
                            <span className="text-base font-bold text-foreground group-hover:text-primary transition-colors">{course?.courseCode || 'GEN-CORE'}</span>
                            <span className="text-[11px] text-muted-foreground font-medium line-clamp-1">{course?.courseName || 'Unspecified Academic Session'}</span>
                          </div>
                        </td>
                        <td className="py-4 px-6 border-r border-border/60">
                           <div className="flex flex-col">
                             <span className="text-sm font-bold text-foreground">{new Date(r.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</span>
                             <span className="text-[10px] font-bold text-muted-foreground uppercase">{new Intl.DateTimeFormat('en-US', { weekday: 'long' }).format(new Date(r.date))}</span>
                           </div>
                        </td>
                        <td className="py-4 px-6 text-right">
                          <Badge variant={isPresent ? 'default' : 'destructive'} className="text-[9px] font-black uppercase tracking-widest px-3">
                            {isPresent ? 'AUTHENTICATED' : 'MISSED'}
                          </Badge>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
         </div>
      </div>
    </div>
  );
}

'use client';
import { Button, Input, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@pec/ui";


import { useState, useEffect } from 'react';
import { 
  Upload, 
  Database, 
  ShieldCheck, 
  Loader2, 
  Users, 
  Calendar as CalendarIcon,
  CheckCircle2,
  XCircle,
  FileSpreadsheet,
  Settings2,
  Filter,
  Activity
} from 'lucide-react';

import { toast } from 'sonner';
import { useAction } from 'next-safe-action/hooks';
import api from "@pec/api";
import { extractData, cn } from '@/lib/utils';
import { LoadingGrid } from '@/components/common/AsyncState';
import PDFExportButton from '@/components/common/PDFExportButton';
import BulkUpload from '@/components/BulkUpload';
import { markBulkAttendanceAction } from './actions';
import { motion, AnimatePresence } from 'framer-motion';

export default function AttendanceManager({ userId, userRole, initialData }: any) {
  const [courses, setCourses] = useState<any[]>(initialData?.courses || []);
  const [selectedCourse, setSelectedCourse] = useState('');
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [students, setStudents] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [showBulkUpload, setShowBulkUpload] = useState(false);

  const isAdmin = ['college_admin', 'super_admin'].includes(userRole);

  const asArray = <T,>(value: unknown): T[] => (Array.isArray(value) ? (value as T[]) : []);

  const { execute: executeBulk, isPending: isSaving } = useAction(markBulkAttendanceAction, {
    onSuccess: () => {
      toast.success('Attendance records updated successfully.');
      fetchStudentAttendance();
    },
    onError: ({ error }) => toast.error(error.serverError || 'Failed to update records.'),
  });

  useEffect(() => {
    if (!initialData?.courses || initialData.courses.length === 0) fetchCourses();
  }, [userId, userRole]);

  useEffect(() => {
    if (selectedCourse && selectedDate) fetchStudentAttendance();
    else setStudents([]);
  }, [selectedCourse, selectedDate]);

  const fetchCourses = async () => {
    let data: any[] = [];
    if (isAdmin) {
      const response = await api.get<any>('/courses', { params: { limit: 200 } });
      data = asArray<any>(extractData<any>(response.data));
    } else {
      const response = await api.get<any>('/courses', { params: { facultyId: userId, limit: 200 } });
      data = asArray<any>(extractData<any>(response.data));
      if (!data.length) {
        let facultyName = '';
        try {
          const profileRes = await api.get<any>('/auth/profile');
          facultyName = profileRes?.data?.data?.fullName || profileRes?.data?.data?.name || profileRes?.data?.fullName || profileRes?.data?.name || '';
        } catch {
          facultyName = '';
        }
        const fallback = await api.get<any>('/courses', { params: { limit: 200 } });
        const allCourses = asArray<any>(extractData<any>(fallback.data));
        const name = facultyName.toLowerCase();
        data = allCourses.filter((c: any) => {
          if (c.facultyId === userId || c.instructorId === userId) return true;
          if (!name) return false;
          const instructor = String(c.instructor || c.facultyName || c.instructorName || '').toLowerCase();
          return instructor.includes(name);
        });
      }
    }
    setCourses(data);
  };

  const fetchStudentAttendance = async () => {
    setLoading(true);
    try {
      const course = courses.find((c) => c.id === selectedCourse);
      const subjectId = course?.id || selectedCourse;

      const [enrollRes, attRes] = await Promise.all([
        api.get<any>('/enrollments', { params: { courseId: selectedCourse, status: 'active', limit: 200 } }),
        api.get<any>('/attendance', { params: { subject: subjectId, date: selectedDate } })
      ]);

      const enrolled = asArray<any>(extractData<any>(enrollRes.data));
      const records = asArray<any>(extractData<any>(attRes.data));
      
      const recordMap = new Map(records.map((r: any) => [r.studentId, r]));

      setStudents(enrolled.map(en => {
        const student = en.student || null;
        const r = recordMap.get(en.studentId);
        return {
          id: en.studentId,
          name: student?.name || student?.fullName || 'Unknown Student',
          email: student?.email || '',
          recordId: r?.id,
          status: r?.status || null
        };
      }));
    } catch (e) {
      toast.error('Failed to load student data.');
    } finally {
      setLoading(false);
    }
  };

  const handleMark = (id: string, status: any) => {
    setStudents(prev => prev.map(s => s.id === id ? { ...s, status } : s));
  };

  const handleBulkMark = (status: 'present' | 'absent') => {
    setStudents(prev => prev.map(s => ({ ...s, status })));
    toast.success(`Marked all students as ${status}`);
  };

  const handleSave = () => {
    const records = students
      .filter(s => s.status)
      .map(s => ({
        id: s.recordId,
        studentId: s.id,
        subject: selectedCourse,
        date: selectedDate,
        status: s.status as 'present' | 'absent' | 'late'
      }));
    
    if (records.length === 0) return toast.info('No changes to save.');
    executeBulk({ records });
  };

  const stats = {
    total: students.length,
    present: students.filter(s => s.status === 'present').length,
    absent: students.filter(s => s.status === 'absent').length,
    pending: students.filter(s => !s.status).length,
    participationRate: students.length > 0 ? (students.filter(s => s.status === 'present').length / students.length) * 100 : 0
  };

  return (
    <div className="space-y-8 pb-12 animate-in fade-in duration-500">
      {/* Professional Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-border/40">
        <div className="flex items-center gap-5">
           <div className="p-3.5 bg-primary/10 rounded-2xl border border-primary/20 shadow-sm relative overflow-hidden group">
             <div className="absolute inset-0 bg-primary/20 opacity-0 group-hover:opacity-100 transition-opacity blur-xl" />
             <Settings2 className="w-8 h-8 text-primary shadow-glow relative z-10" />
           </div>
           <div>
             <h1 className="text-3xl font-bold tracking-tight text-foreground">Attendance Management</h1>
             <p className="text-sm text-muted-foreground font-medium italic mt-1 font-display">Mark and verify student attendance records</p>
           </div>
        </div>
        <div className="flex items-center gap-3">
          <PDFExportButton 
            onExport={async () => {
              if (!selectedCourse) {
                toast.error('Select a course to export.');
                return;
              }
              const { exportAttendanceReport } = await import('@/lib/pdfExport');
              const course = courses.find(c => c.id === selectedCourse);
              exportAttendanceReport(course?.name || 'Attendance_Report', students, { start: selectedDate, end: selectedDate });
            }} 
            label="Export Report"
          />
          <Button 
            variant="outline" 
            onClick={() => setShowBulkUpload(true)} 
            className="h-11 rounded-xl px-5 border-border/60 font-bold text-[10px] uppercase tracking-widest gap-2 bg-background hover:bg-muted/40 transition-all border-2"
          >
            <FileSpreadsheet className="w-4 h-4" /> Bulk Upload
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-3 space-y-8">
          {/* Selection Area */}
          <div className="card-elevated p-8 bg-card/60 backdrop-blur-sm border-primary/10 relative overflow-hidden">
             <div className="absolute top-0 right-0 p-8 opacity-5">
               <Database className="w-24 h-24 text-primary" />
             </div>
             <div className="grid grid-cols-1 md:grid-cols-12 gap-8 relative z-10">
               <div className="md:col-span-8 space-y-3">
                 <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-muted-foreground/60 flex items-center gap-2">
                   <Filter className="w-3 h-3 text-primary" /> Course Selection
                 </label>
                 <Select value={selectedCourse} onValueChange={setSelectedCourse}>
                   <SelectTrigger className="h-14 font-bold text-lg bg-background border-border/60 rounded-xl px-6 focus:ring-primary/20">
                     <SelectValue placeholder="Select course..." />
                   </SelectTrigger>
                   <SelectContent className="max-h-[400px]">
                     {courses.map(c => (
                       <SelectItem key={c.id} value={c.id} className="font-bold py-3 text-sm">
                         <span className="font-bold text-primary mr-3 opacity-60">[{c.code}]</span> {c.name}
                       </SelectItem>
                     ))}
                   </SelectContent>
                 </Select>
               </div>
               <div className="md:col-span-4 space-y-3">
                 <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-muted-foreground/60 flex items-center gap-2">
                   <CalendarIcon className="w-3 h-3 text-primary" /> Session Date
                 </label>
                 <Input 
                   type="date" 
                   className="h-14 bg-background border-border/60 font-mono font-bold text-center text-lg rounded-xl focus:ring-primary/20"
                   value={selectedDate} 
                   onChange={(e) => setSelectedDate(e.target.value)} 
                 />
               </div>
             </div>
          </div>

          <AnimatePresence mode="wait">
            {selectedCourse ? (
              <motion.div 
                initial={{ opacity: 0, y: 20 }} 
                animate={{ opacity: 1, y: 0 }} 
                className="space-y-6"
              >
                {/* Stats Bar */}
                <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                   {[
                     { label: 'Total Enrolled', value: stats.total, icon: Users, color: 'text-primary', bg: 'bg-primary/5' },
                     { label: 'Present', value: stats.present, icon: CheckCircle2, color: 'text-success', bg: 'bg-success/5' },
                     { label: 'Absent', value: stats.absent, icon: XCircle, color: 'text-destructive', bg: 'bg-destructive/5' },
                     { label: 'Participation', value: `${Math.round(stats.participationRate)}%`, icon: Activity, color: 'text-indigo-500', bg: 'bg-indigo-500/5' },
                   ].map((item, idx) => (
                     <div key={idx} className={cn(
                       "relative overflow-hidden p-5 rounded-2xl border border-border/40 bg-card/40 backdrop-blur-md flex flex-col gap-4 group transition-all duration-300 hover:border-primary/30 hover:translate-y-[-2px]",
                       item.bg
                     )}>
                        <div className="absolute top-0 right-0 p-4 opacity-[0.03] group-hover:opacity-[0.07] transition-opacity">
                          <item.icon className="w-16 h-16" />
                        </div>
                        <div className={cn("w-10 h-10 rounded-xl flex items-center justify-center border border-border/40 bg-background", item.color)}>
                          <item.icon className="w-5 h-5 shadow-glow" />
                        </div>
                        <div>
                          <p className="text-[10px] font-bold uppercase tracking-[0.15em] text-muted-foreground opacity-60 mb-1">{item.label}</p>
                          <p className="text-2xl font-bold font-display tracking-tight">
                            {item.value}
                          </p>
                        </div>
                     </div>
                   ))}
                </div>

                {/* List Container */}
                <div className="card-elevated overflow-hidden bg-card/60 backdrop-blur-sm shadow-2xl">
                  <div className="bg-muted/30 border-b border-border/40 px-8 py-5 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="w-2 h-8 bg-primary rounded-full hidden sm:block" />
                      <span className="text-sm font-bold uppercase tracking-widest text-foreground/80">Student Enrollment List</span>
                    </div>
                    <div className="flex items-center gap-3">
                       <Button 
                         variant="outline" 
                         size="sm"
                         onClick={() => handleBulkMark('present')}
                         className="h-9 px-5 rounded-xl font-bold text-[10px] uppercase tracking-[0.1em] border-success/30 text-success hover:bg-success/10 transition-all"
                       >
                         Mark All Present
                       </Button>
                       <Button 
                         variant="outline" 
                         size="sm"
                         onClick={() => handleBulkMark('absent')}
                         className="h-9 px-5 rounded-xl font-bold text-[10px] uppercase tracking-[0.1em] border-destructive/30 text-destructive hover:bg-destructive/10 transition-all"
                       >
                         Mark All Absent
                       </Button>
                    </div>
                  </div>

                  {loading ? <div className="p-20"><LoadingGrid count={5} /></div> : (
                    <div className="divide-y divide-border/20">
                      {students.map(s => (
                        <div key={s.id} className="flex items-center justify-between py-6 px-8 hover:bg-primary/[0.02] transition-colors group">
                           <div className="flex items-center gap-6">
                              <div className="w-12 h-12 rounded-2xl bg-muted/40 flex items-center justify-center border border-border/20 font-bold text-primary text-xs shrink-0 group-hover:scale-110 transition-transform">
                                {s.name.substring(0, 2).toUpperCase()}
                              </div>
                              <div className="flex flex-col">
                                <span className="text-base font-bold text-foreground group-hover:text-primary transition-colors">{s.name}</span>
                                <span className="text-xs font-mono text-muted-foreground opacity-60">{s.email}</span>
                              </div>
                           </div>

                           <div className="flex items-center p-1 bg-muted/40 rounded-2xl border border-border/40 shadow-inner overflow-hidden">
                             {[
                               { id: 'present', label: 'Present', icon: CheckCircle2, activeClass: 'bg-success text-white shadow-xl shadow-success/30 border-success/50' },
                               { id: 'absent', label: 'Absent', icon: XCircle, activeClass: 'bg-destructive text-white shadow-xl shadow-destructive/30 border-destructive/50' }
                             ].map((status) => (
                               <button
                                 key={status.id}
                                 onClick={() => handleMark(s.id, status.id)}
                                 className={cn(
                                   "flex items-center justify-center gap-2 px-8 py-3 rounded-xl font-bold text-[10px] uppercase tracking-wider transition-all duration-200 border-2 border-transparent",
                                   s.status === status.id 
                                     ? status.activeClass 
                                     : "text-muted-foreground font-medium grayscale hover:grayscale-0 hover:bg-background/80"
                                 )}
                               >
                                 <status.icon className={cn("w-4 h-4", s.status === status.id ? "animate-pulse" : "")} />
                                 {status.label}
                               </button>
                             ))}
                           </div>
                        </div>
                      ))}
                    </div>
                  )}

                  <div className="p-8 border-t border-border/40 bg-muted/10 flex justify-end">
                    <Button 
                      onClick={handleSave} 
                      disabled={isSaving || !selectedCourse}
                      className="bg-primary text-primary-foreground font-bold tracking-widest uppercase text-xs h-14 px-16 rounded-2xl shadow-glow hover:scale-[1.02] transition-all"
                    >
                       {isSaving ? <Loader2 className="w-5 h-5 animate-spin mr-3" /> : <CheckCircle2 className="w-5 h-5 mr-3 shadow-glow" />}
                       Update Attendance
                    </Button>
                  </div>
                </div>
              </motion.div>
            ) : (
              <div className="py-32 text-center border-2 border-dashed border-primary/10 rounded-3xl bg-primary/[0.01] flex flex-col items-center gap-6">
                <div className="w-20 h-20 rounded-full bg-primary/5 flex items-center justify-center border border-primary/10">
                  <Database className="w-8 h-8 text-primary/40" />
                </div>
                <div className="space-y-1">
                  <h3 className="text-xl font-bold tracking-tight text-foreground/80">Select Parameters</h3>
                  <p className="text-sm text-center text-muted-foreground font-medium italic max-w-sm">Please select a course and date to begin marking attendance.</p>
                </div>
              </div>
            )}
          </AnimatePresence>
        </div>

        {/* Sidebar Info */}
        <div className="space-y-8">
           <div className="card-elevated p-8 bg-primary/5 border-primary/20 space-y-6 relative overflow-hidden">
              <div className="absolute inset-0 bg-grid-pattern opacity-[0.03] -z-10" />
              <div className="w-12 h-12 bg-primary/10 rounded-xl flex items-center justify-center border border-primary/20 shadow-sm transition-transform hover:rotate-12">
                <ShieldCheck className="w-6 h-6 text-primary" />
              </div>
              <div className="space-y-2">
                <h3 className="text-xl font-bold tracking-tight font-display">Instructions</h3>
                <p className="text-xs text-muted-foreground leading-relaxed font-bold opacity-80">
                  Ensure accurate verification of student presence. Attendance records are permanent academic logs.
                </p>
              </div>
              <ul className="space-y-3 pt-2">
                {[
                  'Verify student identity',
                  'Select correct date/course',
                  'Confirm and update records',
                ].map((rule, idx) => (
                  <li key={idx} className="flex items-center gap-3 text-[10px] font-bold uppercase tracking-widest text-primary/70">
                    <div className="w-1 h-1 bg-primary rounded-full shrink-0" />
                    {rule}
                  </li>
                ))}
              </ul>
           </div>
        </div>
      </div>

      <Dialog open={showBulkUpload} onOpenChange={setShowBulkUpload}>
        <DialogContent className="max-w-4xl bg-card border-border/60 rounded-3xl p-0 overflow-hidden backdrop-blur-xl shadow-2xl">
           <DialogHeader className="bg-primary p-12 text-white">
              <div className="flex items-center justify-between">
                <div className="space-y-2">
                  <DialogTitle className="text-3xl font-black uppercase tracking-tight">Institutional Bulk Intake</DialogTitle>
                  <DialogDescription className="opacity-70 font-bold uppercase tracking-widest text-[11px] italic">Attendance Registry Parity System — CSV/Excel Protocol</DialogDescription>
                </div>
                <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center border border-white/20">
                   <Upload className="w-8 h-8 text-white shadow-glow" />
                </div>
              </div>
           </DialogHeader>
           <div className="p-10">
             <BulkUpload 
               entityType="attendance" 
               onImport={null as any} 
               templateColumns={['studentEmail', 'courseCode', 'date', 'status']} 
               sampleData={[{ studentEmail: 'student@college.edu', courseCode: 'CS101', date: '2024-03-31', status: 'present' }]} 
             />
           </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { Suspense } from 'react';
import dynamic from 'next/dynamic';
import { AttendanceManagerSkeleton, StudentAttendanceSkeleton } from '@/components/common/ContentSkeletons';

// Lazy load the sub-views for performance
const AttendanceManager = dynamic<any>(() => import('./AttendanceManager'), {
    loading: () => <AttendanceManagerSkeleton />
});
const StudentAttendance = dynamic<any>(() => import('./StudentAttendance'), {
    loading: () => <StudentAttendanceSkeleton />
});


interface AttendanceViewProps {
  session: any;
  initialData?: any;
}

/**
 * Domain-Driven Attendance Logic Root
 * Professional Routing between Role-Specific Interfaces
 */
export default function AttendanceView({ session, initialData }: AttendanceViewProps) {
  const isAdmin = ['college_admin', 'super_admin'].includes(session.role);
  const isFaculty = session.role === 'faculty';

  return (
    <Suspense fallback={<AttendanceManagerSkeleton />}>
        { (isAdmin || isFaculty) ? (
            <AttendanceManager 
                userId={session.uid} 
                userRole={session.role} 
                initialData={initialData} 
            />
        ) : (
            <StudentAttendance 
                userId={session.uid} 
                initialData={initialData} 
            />
        )}
    </Suspense>
  );
}

'use client';
import { Badge, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, Input, Textarea, Button } from "@pec/ui";


import { useState, useEffect, useRef } from 'react';
import { 
  Calendar, 
  BookOpen, 
  TrendingUp, 
  Activity, 
  ShieldCheck, 
  ShieldAlert,
  ArrowRight,
  Loader2,
  Paperclip,
  CheckCircle2
} from 'lucide-react';

import api, {  isAuthError  } from "@pec/api";
import { extractData, cn } from '@/lib/utils';
import { LoadingGrid } from '@/components/common/AsyncState';
import { useAuth } from '@/features/auth/hooks/useAuth';
import { toast } from 'sonner';

import { 
  RadialBarChart, 
  RadialBar, 
  ResponsiveContainer, 
  PolarAngleAxis 
} from 'recharts';

type WaiverRequest = {
  id: string;
  courseId?: string | null;
  courseCode?: string | null;
  courseName?: string | null;
  fromDate: string;
  toDate: string;
  reason: string;
  status: 'pending' | 'approved' | 'rejected' | string;
  reviewerNote?: string | null;
  createdAt: string;
};

export default function StudentAttendance({ userId, initialData }: any) {
  const { isAuthenticated, isLoading: authLoading } = useAuth();
  const hasFetchedRef = useRef(false);
  const waiverFileInputRef = useRef<HTMLInputElement>(null);
  const [loading, setLoading] = useState(!initialData?.summary);
  const [attendanceRecords, setAttendanceRecords] = useState<any[]>(initialData?.records || []);
  const [courseAttendance, setCourseAttendance] = useState<any[]>(initialData?.summary?.courses || []);
  const [overallPercentage, setOverallPercentage] = useState(initialData?.summary?.totalSummary?.percentage || 0);
  const [isWaiverDialogOpen, setIsWaiverDialogOpen] = useState(false);
  const [isSubmittingWaiver, setIsSubmittingWaiver] = useState(false);
  const [isUploadingWaiverDoc, setIsUploadingWaiverDoc] = useState(false);
  const [uploadedWaiverFileName, setUploadedWaiverFileName] = useState('');
  const [waiverRequests, setWaiverRequests] = useState<WaiverRequest[]>([]);
  const [waiverForm, setWaiverForm] = useState({
    courseId: '',
    fromDate: '',
    toDate: '',
    reason: '',
    supportingDocUrl: '',
  });

  const asArray = <T,>(value: unknown): T[] => (Array.isArray(value) ? (value as T[]) : []);

  useEffect(() => {
    if (initialData?.summary) return;
    if (!userId) return;
    if (authLoading) return;
    if (!isAuthenticated) return;
    if (hasFetchedRef.current) return;
    hasFetchedRef.current = true;
    void fetchData();
  }, [userId, initialData?.summary, authLoading, isAuthenticated]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [sumRes, recRes] = await Promise.all([
        api.get<any>('/attendance/summary'),
        api.get<any>('/attendance', { params: { studentId: userId, limit: 100 } })
      ]);
      const summary = extractData<any>(sumRes.data);
      if (summary) {
        setCourseAttendance(asArray<any>(summary.courses));
        setOverallPercentage(summary.totalSummary?.percentage || 0);
      }
      setAttendanceRecords(asArray<any>(extractData<any>(recRes.data)));
    } catch (e) {
      if (!isAuthError(e)) {
        console.error(e);
      }
    } finally {
      setLoading(false);
    }
  };

  const fetchWaiverRequests = async () => {
    try {
      const response = await api.get<any>('/attendance/waivers/my');
      const payload = extractData<any>(response);
      const list = extractData<WaiverRequest[]>(payload);
      setWaiverRequests(Array.isArray(list) ? list : []);
    } catch (error) {
      if (!isAuthError(error)) {
        toast.error('Unable to fetch waiver requests');
      }
    }
  };

  useEffect(() => {
    if (!isWaiverDialogOpen || authLoading || !isAuthenticated) return;
    void fetchWaiverRequests();
  }, [isWaiverDialogOpen, authLoading, isAuthenticated]);

  const handleWaiverSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isSubmittingWaiver) return;

    if (!waiverForm.fromDate || !waiverForm.toDate || waiverForm.reason.trim().length < 10) {
      toast.error('Fill all required fields and provide a detailed reason (10+ chars).');
      return;
    }

    const selectedCourse = courseAttendance.find((course) => course.courseId === waiverForm.courseId);

    setIsSubmittingWaiver(true);
    try {
      await api.post('/attendance/waivers', {
        courseId: selectedCourse?.courseId || undefined,
        courseCode: selectedCourse?.courseCode || undefined,
        courseName: selectedCourse?.courseName || undefined,
        fromDate: waiverForm.fromDate,
        toDate: waiverForm.toDate,
        reason: waiverForm.reason.trim(),
        supportingDocUrl: waiverForm.supportingDocUrl.trim() || undefined,
      });

      toast.success('Waiver request submitted successfully.');
      setWaiverForm({
        courseId: waiverForm.courseId,
        fromDate: '',
        toDate: '',
        reason: '',
        supportingDocUrl: '',
      });
      await fetchWaiverRequests();
    } catch (error: any) {
      const message = String(error?.message || 'Failed to submit waiver request');
      toast.error(message);
    } finally {
      setIsSubmittingWaiver(false);
    }
  };

  const handleWaiverDocumentUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const maxBytes = 5 * 1024 * 1024;
    if (file.size > maxBytes) {
      toast.error('File size should be 5 MB or less.');
      event.target.value = '';
      return;
    }

    const allowed = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
    if (!allowed.includes(file.type)) {
      toast.error('Only PDF, JPG, PNG or WEBP files are allowed.');
      event.target.value = '';
      return;
    }

    const formData = new FormData();
    formData.append('file', file);

    setIsUploadingWaiverDoc(true);
    try {
      const response = await api.post<any>('/attendance/waivers/upload', formData);
      const uploaded = extractData<any>(response);
      const uploadedData = extractData<any>(uploaded);
      const docUrl = String(uploadedData?.url || '').trim();
      if (!docUrl) {
        throw new Error('Upload succeeded but no document URL was returned.');
      }

      setWaiverForm((prev) => ({ ...prev, supportingDocUrl: docUrl }));
      setUploadedWaiverFileName(String(uploadedData?.originalName || file.name));
      toast.success('Document attached successfully.');
    } catch (error: any) {
      toast.error(String(error?.message || 'Failed to upload document'));
    } finally {
      setIsUploadingWaiverDoc(false);
      event.target.value = '';
    }
  };

  const isEligible = overallPercentage >= 75;
  const totalPresent = courseAttendance.reduce((sum, course) => sum + (Number(course.present) || 0), 0);
  const totalAbsent = courseAttendance.reduce((sum, course) => sum + (Number(course.absent) || 0), 0);
  const totalSessions = totalPresent + totalAbsent;
  const leavesLeft =
    totalSessions > 0 ? Math.max(0, Math.floor(totalPresent / 0.75 - totalSessions)) : 0;
  const sessionsNeededForEligibility =
    totalSessions > 0 && !isEligible
      ? Math.max(0, Math.ceil((0.75 * totalSessions - totalPresent) / 0.25))
      : 0;

  const chartData = [
    {
      name: 'Attendance',
      value: overallPercentage,
      fill: 'url(#attendanceGradient)',
    },
  ];

  if (loading) return <LoadingGrid count={4} className="grid md:grid-cols-2 gap-8" />;

  return (
    <div className="space-y-10 pb-12 animate-in fade-in duration-500">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-border/40">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
            <Activity className="w-8 h-8 text-primary shadow-glow" />
            Attendance
          </h1>
          <p className="text-sm text-muted-foreground font-medium italic mt-1">View your attendance summary and eligibility status</p>
        </div>
        <div className="flex items-center gap-4">
          <Badge 
            className={cn(
              "h-10 px-6 rounded-xl font-bold text-[10px] uppercase tracking-wider border-2",
              isEligible 
                ? "bg-success/10 text-success border-success/30" 
                : "bg-destructive/10 text-destructive border-destructive/30"
            )}
          >
            {isEligible ? (
              <span className="flex items-center gap-2"><ShieldCheck className="w-3.5 h-3.5" /> Eligible</span>
            ) : (
              <span className="flex items-center gap-2"><ShieldAlert className="w-3.5 h-3.5" /> At Risk</span>
            )}
          </Badge>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Analytics Card */}
        <div className="lg:col-span-2 card-elevated p-8 bg-card/60 backdrop-blur-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
            <TrendingUp className="w-32 h-32 text-primary" />
          </div>
          
          <div className="flex flex-col md:flex-row items-center gap-10 relative z-10">
            <div className="w-56 h-56 shrink-0 relative">
              <ResponsiveContainer width="100%" height="100%">
                <RadialBarChart 
                  innerRadius="80%" 
                  outerRadius="100%" 
                  data={chartData} 
                  startAngle={90} 
                  endAngle={450}
                >
                  <defs>
                    <linearGradient id="attendanceGradient" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="hsl(var(--primary))" stopOpacity={1}/>
                      <stop offset="95%" stopColor="hsl(var(--primary))" stopOpacity={0.6}/>
                    </linearGradient>
                  </defs>
                  <PolarAngleAxis
                    type="number"
                    domain={[0, 100]}
                    angleAxisId={0}
                    tick={false}
                  />
                  <RadialBar
                    background
                    dataKey="value"
                    cornerRadius={15}
                    angleAxisId={0}
                  />
                </RadialBarChart>
              </ResponsiveContainer>
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-4xl font-bold font-display tracking-tight text-primary">
                  {Math.round(overallPercentage)}%
                </span>
                <span className="text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground opacity-60">Cumulative</span>
              </div>
            </div>

            <div className="space-y-6 flex-1">
              <div>
                <h3 className="text-2xl font-bold tracking-tight mb-2">Overall Attendance</h3>
                <p className="text-sm text-muted-foreground leading-relaxed">
                  Your cumulative presence is <span className="font-bold text-foreground">{Math.round(overallPercentage)}%</span>. 
                  Maintenance of a 75% threshold is mandatory for examination clearance.
                </p>
                <p className="text-xs font-semibold mt-3 text-primary/90">
                  {isEligible
                    ? `Leaves left (considering 75% attendance): ${leavesLeft} session${leavesLeft === 1 ? '' : 's'}.`
                    : `Leaves left (considering 75% attendance): 0. Attend ${sessionsNeededForEligibility} more session${sessionsNeededForEligibility === 1 ? '' : 's'} to recover eligibility.`}
                </p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="p-4 rounded-xl bg-success/5 border border-success/20 space-y-1">
                  <p className="text-[9px] font-bold uppercase tracking-widest text-success">Attended</p>
                  <p className="text-xl font-bold font-display">{totalPresent}<span className="text-xs text-muted-foreground ml-1">Sessions</span></p>
                </div>
                <div className="p-4 rounded-xl bg-destructive/5 border border-destructive/20 space-y-1">
                  <p className="text-[9px] font-bold uppercase tracking-widest text-destructive">Missed</p>
                  <p className="text-xl font-bold font-display">{totalAbsent}<span className="text-xs text-muted-foreground ml-1">Sessions</span></p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Secondary Info Card - Eligibility Protocol */}
        <div className="card-elevated p-8 bg-primary/5 border-primary/20 flex flex-col justify-between relative overflow-hidden">
          <div className="absolute inset-0 bg-grid-pattern opacity-[0.03] -z-10" />
          <div className="space-y-4">
            <div className="w-12 h-12 bg-primary/10 rounded-xl flex items-center justify-center border border-primary/20 shadow-sm">
              <ShieldCheck className="w-6 h-6 text-primary" />
            </div>
            <h3 className="text-xl font-bold tracking-tight">Eligibility Guidelines</h3>
            <p className="text-sm text-muted-foreground leading-relaxed">
              Maintain academic compliance by tracking your course-wise attendance. Medical leave and waivers require official documentation.
            </p>
          </div>
          <div className="pt-6">
            <button
              onClick={() => setIsWaiverDialogOpen(true)}
              className="w-full h-10 rounded-xl bg-white/5 border border-white/10 text-white font-bold text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-white/10 transition-all"
            >
              Request Waiver <ArrowRight className="w-3 h-3" />
            </button>
          </div>
        </div>
      </div>

      <Dialog open={isWaiverDialogOpen} onOpenChange={setIsWaiverDialogOpen}>
        <DialogContent className="max-w-2xl border-border/60 bg-card/95 backdrop-blur-xl">
          <DialogHeader>
            <DialogTitle className="text-xl font-bold">Request Attendance Waiver</DialogTitle>
            <DialogDescription>
              Submit your request with reason and date range. Faculty/admin will review it.
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleWaiverSubmit} className="space-y-4">
            <div className="grid md:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Course (optional)</label>
                <select
                  value={waiverForm.courseId}
                  onChange={(e) => setWaiverForm((prev) => ({ ...prev, courseId: e.target.value }))}
                  className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
                >
                  <option value="">General Waiver (All Courses)</option>
                  {courseAttendance.map((course) => (
                    <option key={course.courseId} value={course.courseId}>
                      {course.courseCode} - {course.courseName}
                    </option>
                  ))}
                </select>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Supporting Document URL (optional)</label>
                <div className="space-y-2">
                  <div className="flex gap-2">
                    <Input
                      placeholder="https://..."
                      value={waiverForm.supportingDocUrl}
                      onChange={(e) => {
                        setWaiverForm((prev) => ({ ...prev, supportingDocUrl: e.target.value }));
                        if (!e.target.value.trim()) {
                          setUploadedWaiverFileName('');
                        }
                      }}
                    />
                    <Button
                      type="button"
                      variant="secondary"
                      onClick={() => waiverFileInputRef.current?.click()}
                      disabled={isUploadingWaiverDoc}
                      className="shrink-0"
                    >
                      {isUploadingWaiverDoc ? (
                        <span className="inline-flex items-center gap-2">
                          <Loader2 className="w-4 h-4 animate-spin" /> Uploading
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-2">
                          <Paperclip className="w-4 h-4" /> Attach Document
                        </span>
                      )}
                    </Button>
                    <input
                      ref={waiverFileInputRef}
                      type="file"
                      accept=".pdf,image/jpeg,image/png,image/webp"
                      className="hidden"
                      onChange={handleWaiverDocumentUpload}
                    />
                  </div>
                  {uploadedWaiverFileName ? (
                    <p className="text-xs text-success inline-flex items-center gap-1">
                      <CheckCircle2 className="w-3.5 h-3.5" /> Attached: {uploadedWaiverFileName}
                    </p>
                  ) : null}
                </div>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">From Date</label>
                <Input
                  type="date"
                  value={waiverForm.fromDate}
                  onChange={(e) => setWaiverForm((prev) => ({ ...prev, fromDate: e.target.value }))}
                  required
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">To Date</label>
                <Input
