          <div className="flex-1" />
          <Button variant="outline" size="sm" onClick={() => setEditingRegion(null)}>
            Cancel
          </Button>
          <Button size="sm" onClick={onSave} className="gap-1">
            <Save className="w-4 h-4" />
            Save
          </Button>
        </div>
      </div>
    </div>
  );
}

'use client';
import { useState, useRef, useEffect, useCallback, Suspense } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  MapPin,
  Save,
  Edit3,
  X,
  ZoomIn,
  ZoomOut,
  Route,
  Square,
  RotateCcw,
  Box,
  Map,
  Loader2,
} from 'lucide-react';
import { Button } from '@pec/ui';
import { Badge } from '@pec/ui';
import { cn } from '@/lib/utils';
import { AXIOS_INSTANCE } from '@pec/api';
import { useAuth } from '@/features/auth/hooks/useAuth';
import { toast } from 'sonner';
import dynamic from 'next/dynamic';

// Shared config and types
import {
  MapRegion,
  MapRoad,
  defaultRegions,
  defaultRoads,
  categories,
} from './components/mapConfig';

// Subcomponents
import EditRegionModal from './components/EditRegionModal';

const CampusMap3D = dynamic(
  () => import('@/features/campus-map/CampusMap3D').then((mod) => mod.default),
  {
    ssr: false,
    loading: () => (
      <div className="w-full h-[600px] flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    ),
  }
);

type DrawMode = 'none' | 'building' | 'road';
type ResizeHandle = 'nw' | 'ne' | 'sw' | 'se' | null;

export default function CampusMap() {
  const { user } = useAuth();
  const isAdmin = user?.role === 'college_admin';

  const [regions, setRegions] = useState<MapRegion[]>([]);
  const [roads, setRoads] = useState<MapRoad[]>([]);
  const [selectedRegion, setSelectedRegion] = useState<MapRegion | null>(null);
  const [editMode, setEditMode] = useState(false);
  const [drawMode, setDrawMode] = useState<DrawMode>('none');
  const [drawStart, setDrawStart] = useState<{ x: number; y: number } | null>(null);
  const [newRegion, setNewRegion] = useState<Partial<MapRegion> | null>(null);
  const [newRoad, setNewRoad] = useState<Partial<MapRoad> | null>(null);
  const [zoom, setZoom] = useState(1);
  const [viewMode, setViewMode] = useState<'2d' | '3d'>('2d');

  // Resize and drag state
  const [resizing, setResizing] = useState<{ region: MapRegion; handle: ResizeHandle } | null>(
    null
  );
  const [dragging, setDragging] = useState<{
    region: MapRegion;
    offsetX: number;
    offsetY: number;
  } | null>(null);

  // Track unsaved changes
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInnerRef = useRef<HTMLDivElement>(null);
  const [editingRegion, setEditingRegion] = useState<MapRegion | null>(null);

  // Fetch data
  useEffect(() => {
    const fetchData = async () => {
      try {
        const orgId = user?.organizationId;

        let regionsSnap: any = { empty: true, docs: [] };
        try {
          const { data: raw } = await AXIOS_INSTANCE.get('/api/v1/campus-map' + (orgId ? '?organizationId=' + orgId : ''));
          const arr = Array.isArray(raw?.data) ? raw.data : (Array.isArray(raw) ? raw : []);
          regionsSnap = { empty: arr.length === 0, docs: arr.map((d: any) => ({ id: d.id, data: () => d })) };
        } catch(e) { console.error('regions fetch err', e); }
        
        // Fetch roads
        let roadsSnap: any = { empty: true, docs: [] };
        try {
          const { data: raw } = await AXIOS_INSTANCE.get('/api/v1/campus-map-roads' + (orgId ? '?organizationId=' + orgId : ''));
          const arr = Array.isArray(raw?.data) ? raw.data : (Array.isArray(raw) ? raw : []);
          roadsSnap = { empty: arr.length === 0, docs: arr.map((d: any) => ({ id: d.id, data: () => d })) };
        } catch(e) { console.error('roads fetch err', e); }
        if (regionsSnap.empty) {
          setRegions(
            defaultRegions.map((r, i) => ({
              ...r,
              id: `default-${i}`,
              organizationId: orgId || '',
            }))
          );
        } else {
          setRegions(regionsSnap.docs.map((doc) => ({ id: doc.id, ...doc.data() }) as MapRegion));
        }

        if (roadsSnap.empty) {
          setRoads(
            defaultRoads.map((r, i) => ({ ...r, id: `road-${i}`, organizationId: orgId || '' }))
          );
        } else {
          setRoads(roadsSnap.docs.map((doc) => ({ id: doc.id, ...doc.data() }) as MapRoad));
        }
      } catch (error) {
        console.error('Error fetching data:', error);
        setRegions(
          defaultRegions.map((r, i) => ({ ...r, id: `default-${i}`, organizationId: '' }))
        );
        setRoads(defaultRoads.map((r, i) => ({ ...r, id: `road-${i}`, organizationId: '' })));
      }
    };
    fetchData();
  }, [user?.organizationId]);

  // Grid size (2% = 50 cells)
  const GRID_SIZE = 2;

  // Snap value to grid
  const snapToGrid = (val: number) => Math.round(val / GRID_SIZE) * GRID_SIZE;

  // Get mouse position as percentage (snapped to grid)
  const getMousePos = useCallback((e: React.MouseEvent, snap = true) => {
    const rect = mapInnerRef.current?.getBoundingClientRect();
    if (!rect) return { x: 0, y: 0 };
    let x = ((e.clientX - rect.left) / rect.width) * 100;
    let y = ((e.clientY - rect.top) / rect.height) * 100;
    if (snap) {
      x = snapToGrid(x);
      y = snapToGrid(y);
    }
    return { x, y };
  }, []);

  // Mouse down handlers
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      if (!editMode) return;

      const pos = getMousePos(e);

      if (drawMode === 'building') {
        setDrawStart(pos);
        setNewRegion({
          x: pos.x,
          y: pos.y,
          width: 0,
          height: 0,
          name: '',
          description: '',
          category: 'academic',
        });
      } else if (drawMode === 'road') {
        // For polyline roads: start with first point
        if (!newRoad || !newRoad.points || newRoad.points.length === 0) {
          setDrawStart(pos);
          setNewRoad({ points: [pos], width: 2 });
        } else {
          // Add new waypoint to existing road being drawn
          const lastPoint = newRoad.points[newRoad.points.length - 1];
          const dx = Math.abs(pos.x - lastPoint.x);
          const dy = Math.abs(pos.y - lastPoint.y);
          // Snap to horizontal or vertical from last point
          const newPoint = dx >= dy ? { x: pos.x, y: lastPoint.y } : { x: lastPoint.x, y: pos.y };
          setNewRoad((prev) => ({ ...prev, points: [...(prev?.points || []), newPoint] }));
        }
      }
    },
    [editMode, drawMode, getMousePos, newRoad]
  );

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      const pos = getMousePos(e);

      if (drawStart && drawMode === 'building' && newRegion) {
        const width = snapToGrid(Math.abs(pos.x - drawStart.x));
        const height = snapToGrid(Math.abs(pos.y - drawStart.y));
        const x = Math.min(pos.x, drawStart.x);
        const y = Math.min(pos.y, drawStart.y);
        setNewRegion((prev) => ({ ...prev, x, y, width, height }));
      } else if (
        drawStart &&
        drawMode === 'road' &&
        newRoad &&
        newRoad.points &&
        newRoad.points.length > 0
      ) {
        // Preview next segment from last point
        const lastPoint = newRoad.points[newRoad.points.length - 1];
        const dx = Math.abs(pos.x - lastPoint.x);
        const dy = Math.abs(pos.y - lastPoint.y);
        // Show preview line snapped to horizontal or vertical
        const previewPoint = dx >= dy ? { x: pos.x, y: lastPoint.y } : { x: lastPoint.x, y: pos.y };
        setNewRoad((prev) => ({ ...prev, previewPoint }));
      } else if (resizing) {
        // Handle resize
        const { region, handle } = resizing;
        let newX = region.x,
          newY = region.y,
          newW = region.width,
          newH = region.height;

        if (handle === 'se') {
          newW = snapToGrid(Math.max(4, pos.x - region.x));
          newH = snapToGrid(Math.max(4, pos.y - region.y));
        } else if (handle === 'sw') {
          newW = snapToGrid(Math.max(4, region.x + region.width - pos.x));
          newX = snapToGrid(Math.min(pos.x, region.x + region.width - 4));
          newH = snapToGrid(Math.max(4, pos.y - region.y));
        } else if (handle === 'ne') {
          newW = snapToGrid(Math.max(4, pos.x - region.x));
          newH = snapToGrid(Math.max(4, region.y + region.height - pos.y));
          newY = snapToGrid(Math.min(pos.y, region.y + region.height - 4));
        } else if (handle === 'nw') {
          newW = snapToGrid(Math.max(4, region.x + region.width - pos.x));
          newX = snapToGrid(Math.min(pos.x, region.x + region.width - 4));
          newH = snapToGrid(Math.max(4, region.y + region.height - pos.y));
          newY = snapToGrid(Math.min(pos.y, region.y + region.height - 4));
        }

        setRegions((prev) =>
          prev.map((r) =>
            r.id === region.id ? { ...r, x: newX, y: newY, width: newW, height: newH } : r
          )
        );
      } else if (dragging) {
        // Handle drag/move building
        const { region, offsetX, offsetY } = dragging;
        const newX = snapToGrid(Math.max(0, Math.min(100 - region.width, pos.x - offsetX)));
        const newY = snapToGrid(Math.max(0, Math.min(100 - region.height, pos.y - offsetY)));

        setRegions((prev) =>
          prev.map((r) => (r.id === region.id ? { ...r, x: newX, y: newY } : r))
        );
      }
    },
    [drawStart, drawMode, newRegion, newRoad, resizing, dragging, getMousePos]
  );

  const handleMouseUp = useCallback(async () => {
    if (
      newRegion &&
      newRegion.width &&
      newRegion.height &&
      newRegion.width > 2 &&
      newRegion.height > 2
    ) {
      setEditingRegion({
        id: '',
        name: '',
        description: '',
        category: 'academic',
        x: newRegion.x || 0,
        y: newRegion.y || 0,
        width: newRegion.width || 5,
        height: newRegion.height || 5,
      });
    }

    // Don't auto-save road on mouseUp - wait for double-click to finish road

    // Mark as having unsaved changes if something was moved/resized
    if (resizing || dragging) {
      setHasUnsavedChanges(true);
    }

    setDrawStart(null);
    setNewRegion(null);
    setNewRoad(null);
    setResizing(null);
    setDragging(null);
    if (!newRoad || !newRoad.points || newRoad.points.length < 2) {
      setDrawMode('none');
    }
  }, [newRegion, newRoad, drawStart, resizing, dragging]);

  // Save region
  const saveRegion = async () => {
    if (!editingRegion || !editingRegion.name) {
      toast.error('Please enter a name');
      return;
    }

    try {
      const regionData = { ...editingRegion, organizationId: user?.organizationId || '' };

      if (editingRegion.id && !editingRegion.id.startsWith('default-')) {
        // Update existing region record
        await AXIOS_INSTANCE.patch('/api/v1/campus-map/' + editingRegion.id, regionData);
        setRegions(prev => prev.map(r => r.id === editingRegion.id ? { ...regionData, id: editingRegion.id } : r));
        toast.success('Region updated!');
      } else {
        // Create new region (replace only THIS default region, keep others)
        const { data: docRef } = await AXIOS_INSTANCE.post('/api/v1/campus-map', regionData);
        setRegions(prev => [
          ...prev.filter(r => r.id !== editingRegion.id), // Remove only the one being saved
          { ...regionData, id: (docRef?.id || docRef?.data?.id || "new-" + Date.now()) }
        ]);
        toast.success('Region added!');
      }
      setEditingRegion(null);
    } catch (error) {
      console.error('Error saving region:', error);
      toast.error('Failed to save');
    }
  };

  // Finish and save polyline road
  const finishRoad = () => {
    if (!newRoad || !newRoad.points || newRoad.points.length < 2) {
      toast.error('Need at least 2 points to create a road');
      return;
    }

    // Create new road with clean data - ensure points are simple {x, y} objects
    const cleanPoints = newRoad.points.map((p) => ({ x: Number(p.x), y: Number(p.y) }));
    const roadData: MapRoad = {
      id: `road-new-${Date.now()}`,
      points: cleanPoints,
      width: newRoad.width || 2,
      organizationId: user?.organizationId || '',
    };

    // Add to state
    setRoads((prevRoads) => {
      const newRoads = [...prevRoads, roadData];

      return newRoads;
    });

    // Mark as needing save and reset drawing state
    setHasUnsavedChanges(true);
    setNewRoad(null);
    setDrawStart(null);
    setDrawMode('none');
    toast.success('Road created! Click Save to persist.');
  };

  // Save all changes to backend
  const saveAllChanges = async () => {
    if (!user?.organizationId) {
      toast.error('No organization ID');
      return;
    }

    try {
      const orgId = user.organizationId;

      // First, delete all existing regions and roads for this org
      const { data: existingRegionsRaw } = await AXIOS_INSTANCE.get('/api/v1/campus-map?organizationId=' + orgId);
      const existingRegions = { docs: (Array.isArray(existingRegionsRaw?.data) ? existingRegionsRaw.data : existingRegionsRaw || []).map((d: any) => ({ id: d.id })) };
      const { data: existingRoadsRaw } = await AXIOS_INSTANCE.get('/api/v1/campus-map-roads?organizationId=' + orgId);
      const existingRoads = { docs: (Array.isArray(existingRoadsRaw?.data) ? existingRoadsRaw.data : existingRoadsRaw || []).map((d: any) => ({ id: d.id })) };
      for (const docSnap of existingRegions.docs) {
        await AXIOS_INSTANCE.delete('/api/v1/campus-map/' + docSnap.id);
      }
      for (const docSnap of existingRoads.docs) {
        await AXIOS_INSTANCE.delete('/api/v1/campus-map-roads/' + docSnap.id);
      }

      // Now save all current regions
      const savedRegions: MapRegion[] = [];
      for (const region of regions) {
        const { id, ...data } = region;
        const { data: newDoc } = await AXIOS_INSTANCE.post('/api/v1/campus-map', { ...data, organizationId: orgId });
        savedRegions.push({ ...data, id: (newDoc?.id || newDoc?.data?.id || "new-" + Date.now()), organizationId: orgId });
      }

      // Save all current roads
      const savedRoads: MapRoad[] = [];
      for (const road of roads) {
        if (!road.points || road.points.length < 2) continue;
        const { id, ...data } = road;
        const { data: newDoc } = await AXIOS_INSTANCE.post('/api/v1/campus-map-roads', { ...data, organizationId: orgId });
        savedRoads.push({ ...data, id: (newDoc?.id || newDoc?.data?.id || "new-" + Date.now()), organizationId: orgId });
      }

      // Update local state with new IDs
      setRegions(savedRegions);
      setRoads(savedRoads);
      setHasUnsavedChanges(false);
      toast.success('All changes saved!');
    } catch (error) {
      console.error('Error saving all changes:', error);
      toast.error('Failed to save changes');
    }
  };

  // Delete road
  const deleteRoad = async (id: string) => {
    try {
      if (!id.startsWith('road-')) {
        await AXIOS_INSTANCE.delete('/api/v1/campus-map-roads/' + id);
      }
      setRoads((prev) => prev.filter((r) => r.id !== id));
      toast.success('Road deleted');
    } catch (error) {
      toast.error('Failed to delete road');
    }
  };

  // Delete region
  const deleteRegion = async (id: string) => {
    try {
      if (!id.startsWith('default-')) {
        await AXIOS_INSTANCE.delete('/api/v1/campus-map/' + id);
      }
      setRegions((prev) => prev.filter((r) => r.id !== id));
      setSelectedRegion(null);
      toast.success('Region deleted');
    } catch (error) {
      toast.error('Failed to delete');
    }
  };

  const getCategoryStyles = (cat: string) => {
    return (
      categories.find((c) => c.id === cat) || {
        regionVars: 'bg-gray-100 dark:bg-gray-800 border-gray-300 dark:border-gray-600',
        badgeVars: 'bg-gray-600',
      }
    );
  };

  return (
    <div className="container max-w-7xl animate-in fade-in duration-500">
      {/* Institutional Header */}
      <div className="pt-2 md:pt-6 mb-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6">
          <div className="flex items-center gap-5">
            <div className="p-3.5 bg-primary/10 rounded-2xl border border-primary/20 shadow-sm relative overflow-hidden group">
              <div className="absolute inset-0 bg-primary/20 opacity-0 group-hover:opacity-100 transition-opacity blur-xl" />
              <MapPin className="w-8 h-8 text-primary relative z-10" />
            </div>
            <div>
              <h1 className="text-3xl font-bold tracking-tight text-foreground">Campus Map</h1>
              <p className="text-sm text-muted-foreground font-medium italic mt-1 font-display">
                Interactive campus layout
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {/* View Mode Toggle */}
            <div className="flex items-center gap-1 border border-border rounded-lg p-1 bg-card">
              <Button
                variant={viewMode === '2d' ? 'default' : 'ghost'}
                size="sm"
                onClick={() => setViewMode('2d')}
                className="gap-1 h-7 px-2 text-xs"
              >
                <Map className="w-3.5 h-3.5" /> 2D
              </Button>
              <Button
                variant={viewMode === '3d' ? 'default' : 'ghost'}
                size="sm"
                onClick={() => setViewMode('3d')}
                className="gap-1 h-7 px-2 text-xs"
              >
                <Box className="w-3.5 h-3.5" /> 3D
              </Button>
            </div>

            {/* Zoom */}
            <div className="flex items-center gap-1 border border-border rounded-lg p-1 bg-card">
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={() => setZoom((z) => Math.max(0.5, z - 0.25))}
              >
                <ZoomOut className="w-4 h-4" />
              </Button>
              <span className="text-xs w-10 text-center">{Math.round(zoom * 100)}%</span>
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={() => setZoom((z) => Math.min(2, z + 0.25))}
              >
                <ZoomIn className="w-4 h-4" />
              </Button>
            </div>

            {/* Admin Tools */}
            {isAdmin && (
              <>
                {editMode ? (
                  <div className="flex items-center gap-2">
                    <Button
                      variant={drawMode === 'building' ? 'default' : 'outline'}
                      size="sm"
                      onClick={() => setDrawMode(drawMode === 'building' ? 'none' : 'building')}
                      className="gap-1"
                    >
                      <Square className="w-4 h-4" />
                      Building
                    </Button>
                    <Button
                      variant={drawMode === 'road' ? 'default' : 'outline'}
                      size="sm"
                      onClick={() => setDrawMode(drawMode === 'road' ? 'none' : 'road')}
                      className="gap-1"
                    >
                      <Route className="w-4 h-4" />
                      Road
                    </Button>
                    {/* Finish Road button - shown when actively drawing a road */}
                    {newRoad && newRoad.points && newRoad.points.length >= 2 && (
                      <Button
                        variant="default"
                        size="sm"
                        onClick={finishRoad}
                        className="gap-1 bg-green-600 hover:bg-green-700"
                      >
                        <Save className="w-4 h-4" />
                        Finish Road
                      </Button>
                    )}
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => {
                        // Reset to defaults
                        const orgId = user?.organizationId || '';
                        setRegions(
                          defaultRegions.map((r, i) => ({
                            ...r,
                            id: `default-${i}`,
                            organizationId: orgId,
                          }))
                        );
                        setRoads(
                          defaultRoads.map((r, i) => ({
                            ...r,
                            id: `road-${i}`,
                            organizationId: orgId,
                          }))
                        );
                        setHasUnsavedChanges(true); // Mark as needing save
                        toast.success('Map reset to defaults! Click Save to persist.');
                      }}
                      className="gap-1 text-orange-600 border-orange-300 hover:bg-orange-50 dark:hover:bg-orange-950"
                    >
                      <RotateCcw className="w-4 h-4" />
                      Reset
                    </Button>
                    {/* Save Changes button - shown when there are unsaved changes */}
                    {hasUnsavedChanges && (
                      <Button
                        variant="default"
                        size="sm"
                        onClick={saveAllChanges}
                        className="gap-1 bg-green-600 hover:bg-green-700"
                      >
                        <Save className="w-4 h-4" />
                        Save Changes
                      </Button>
                    )}
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => {
                        setEditMode(false);
                        setDrawMode('none');
                        setNewRoad(null);
                        setDrawStart(null);
                      }}
                    >
                      Done
                    </Button>
                  </div>
                ) : (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setEditMode(true)}
                    className="gap-1"
                  >
                    <Edit3 className="w-4 h-4" />
                    Edit Map
                  </Button>
                )}
              </>
            )}
          </div>
        </div>
      </div>

      {/* Legend */}
      <div className="mb-4">
        <div className="flex flex-wrap gap-4">
          {categories.map((cat) => (
            <div key={cat.id} className="flex items-center gap-1.5">
              <span className={cn('w-3 h-3 rounded-full', cat.badgeVars)} />
              <span className="text-xs text-muted-foreground">{cat.label}</span>
            </div>
          ))}
          <div className="flex items-center gap-1.5">
            <span className="w-6 h-2 rounded bg-zinc-700 dark:bg-zinc-300" />
            <span className="text-xs text-muted-foreground">Roads</span>
          </div>
        </div>
      </div>

      {/* Map */}
      <div>
        {viewMode === '3d' ? (
          <Suspense
            fallback={
              <div className="w-full h-[600px] flex items-center justify-center">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
              </div>
            }
          >
            <CampusMap3D
              regions={regions}
              roads={roads}
              selectedRegion={selectedRegion}
              onSelectRegion={setSelectedRegion}
            />
          </Suspense>
        ) : (
          <div
            ref={mapContainerRef}
            className={cn(
              'relative rounded-xl border border-border overflow-auto bg-card',
              drawMode !== 'none' && 'cursor-crosshair'
            )}
            style={{ maxHeight: '75vh' }}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={() => {
              if (drawStart || resizing) handleMouseUp();
            }}
          >
            <div
              ref={mapInnerRef}
              className="relative bg-green-100 dark:bg-zinc-900 w-full h-[700px]"
              style={{
                transform: `scale(${zoom})`,
                transformOrigin: 'top left',
                width: zoom > 1 ? `${100 / zoom}%` : '100%',
              }}
            >
              {/* Grass texture */}
              <div
                className="absolute inset-0 opacity-10 dark:opacity-5"
                style={{
                  backgroundImage:
                    'radial-gradient(circle at 2px 2px, currentColor 1px, transparent 0)',
                  backgroundSize: '16px 16px',
                }}
              />

              {/* Grid overlay - visible in edit mode */}
              {editMode && (
                <svg
                  className="absolute inset-0 w-full h-full pointer-events-none opacity-30"
                  viewBox="0 0 100 100"
                  preserveAspectRatio="none"
                >
                  {/* Vertical grid lines */}
                  {Array.from({ length: 51 }, (_, i) => i * 2).map((x) => (
                    <line
                      key={`v-${x}`}
                      x1={x}
                      y1={0}
                      x2={x}
                      y2={100}
                      stroke="currentColor"
                      strokeWidth="0.1"
                    />
                  ))}
                  {/* Horizontal grid lines */}
                  {Array.from({ length: 51 }, (_, i) => i * 2).map((y) => (
                    <line
                      key={`h-${y}`}
                      x1={0}
                      y1={y}
                      x2={100}
                      y2={y}
                      stroke="currentColor"
                      strokeWidth="0.1"
                    />
                  ))}
                </svg>
              )}

              {/* Roads - Dark asphalt with white lane markings */}
              <svg
                className="absolute inset-0 w-full h-full pointer-events-none"
                viewBox="0 0 100 100"
                preserveAspectRatio="none"
              >
                {roads.map((road) => {
                  // Skip roads without valid points array (legacy format)
                  if (!road.points || !Array.isArray(road.points) || road.points.length < 2) {
                    return null;
                  }
                  // Convert points array to SVG polyline points string
                  const pointsStr = road.points.map((p) => `${p.x},${p.y}`).join(' ');
                  return (
                    <g key={road.id}>
                      {/* Road base (dark asphalt) */}
                      <polyline
                        points={pointsStr}
                        fill="none"
                        stroke="#374151"
                        className="dark:stroke-zinc-500"
                        strokeWidth={`${road.width}%`}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                      {/* White dashed center line */}
                      <polyline
                        points={pointsStr}
                        fill="none"
                        stroke="white"
                        strokeWidth="0.3%"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeDasharray="2 1"
                        className="opacity-70"
                      />
                    </g>
                  );
                })}

                {/* Drawing preview for road polyline */}
                {newRoad && newRoad.points && newRoad.points.length > 0 && (
                  <g>
                    {/* Drawn segments */}
                    <polyline
                      points={newRoad.points.map((p) => `${p.x},${p.y}`).join(' ')}
                      fill="none"
                      stroke="#3b82f6"
                      strokeWidth="2%"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                    {/* Preview segment to cursor */}
                    {(newRoad as any).previewPoint && (
                      <line
                        x1={newRoad.points[newRoad.points.length - 1].x}
                        y1={newRoad.points[newRoad.points.length - 1].y}
                        x2={(newRoad as any).previewPoint.x}
                        y2={(newRoad as any).previewPoint.y}
                        stroke="#3b82f6"
                        strokeWidth="2%"
                        strokeLinecap="round"
                        strokeDasharray="1 1"
                        opacity="0.5"
                      />
                    )}
                    {/* Point markers */}
                    {newRoad.points.map((p, i) => (
                      <circle key={i} cx={p.x} cy={p.y} r="0.8" fill="#3b82f6" />
                    ))}
                  </g>
                )}
              </svg>

              {/* Regions */}
              {regions.map((region) => {
                const styles = getCategoryStyles(region.category);

                return (
                  <div
                    key={region.id}
                    onMouseDown={(e) => {
                      if (editMode && !resizing && drawMode === 'none') {
                        e.stopPropagation();
                        // Calculate offset from click to region corner
                        const rect = mapInnerRef.current?.getBoundingClientRect();
                        if (rect) {
                          const clickX = ((e.clientX - rect.left) / rect.width) * 100;
                          const clickY = ((e.clientY - rect.top) / rect.height) * 100;
                          setDragging({
                            region,
                            offsetX: clickX - region.x,
                            offsetY: clickY - region.y,
                          });
                        }
                      }
                    }}
                    onClick={() => {
                      if (editMode && !resizing && !dragging) {
                        setEditingRegion(region);
                      } else if (!editMode) {
                        setSelectedRegion(region);
                      }
                    }}
                    className={cn(
                      'absolute rounded border-2 shadow-sm transition-all duration-200 flex items-center justify-center p-1 text-center overflow-hidden',
                      drawMode !== 'none'
                        ? 'pointer-events-none'
                        : editMode
                          ? 'cursor-move'
                          : 'cursor-pointer',
                      'hover:shadow-lg',
                      styles.regionVars,
                      selectedRegion?.id === region.id &&
                        'ring-2 ring-primary ring-offset-2 z-20 scale-105',
                      editMode && drawMode === 'none' && 'ring-1 ring-dashed ring-primary/50',
                      dragging?.region.id === region.id && 'z-50 opacity-90'
                    )}
                    style={{
                      left: `${region.x}%`,
                      top: `${region.y}%`,
                      width: `${region.width}%`,
                      height: `${region.height}%`,
                    }}
                  >
                    <span className="text-[8px] md:text-[10px] font-semibold leading-tight text-foreground/80 pointer-events-none select-none">
                      {region.name}
                    </span>

                    {/* Resize handles - only shown in edit mode */}
                    {editMode && (
                      <>
                        {(['nw', 'ne', 'sw', 'se'] as const).map((handle) => (
                          <div
                            key={handle}
                            onMouseDown={(e) => {
                              e.stopPropagation();
                              setResizing({ region, handle });
                            }}
                            className={cn(
                              'absolute w-4 h-4 bg-primary border-2 border-white rounded-full cursor-nwse-resize z-30 shadow-lg',
                              handle === 'nw' && 'top-0 left-0 -translate-x-1/2 -translate-y-1/2',
                              handle === 'ne' &&
                                'top-0 right-0 translate-x-1/2 -translate-y-1/2 cursor-nesw-resize',
                              handle === 'sw' &&
                                'bottom-0 left-0 -translate-x-1/2 translate-y-1/2 cursor-nesw-resize',
                              handle === 'se' && 'bottom-0 right-0 translate-x-1/2 translate-y-1/2'
                            )}
                          />
                        ))}
                      </>
                    )}
                  </div>
                );
              })}

              {/* New region preview */}
              {newRegion && newRegion.width && newRegion.height && (
                <div
                  className="absolute border-2 border-dashed border-primary bg-primary/20 rounded pointer-events-none"
                  style={{
                    left: `${newRegion.x}%`,
                    top: `${newRegion.y}%`,
                    width: `${newRegion.width}%`,
                    height: `${newRegion.height}%`,
                  }}
                />
              )}

              {/* Road delete markers in edit mode - one per segment */}
              {editMode &&
                roads.map((road) => {
                  // Skip roads without valid points
                  if (!road.points || !Array.isArray(road.points) || road.points.length < 2) {
                    return null;
                  }
                  // Create a delete button for EACH segment of the road
                  return road.points.slice(0, -1).map((point, segmentIndex) => {
                    const nextPoint = road.points[segmentIndex + 1];
                    const midX = (point.x + nextPoint.x) / 2;
                    const midY = (point.y + nextPoint.y) / 2;
                    return (
                      <button
                        key={`del-${road.id}-seg-${segmentIndex}`}
                        onClick={(e) => {
                          e.stopPropagation();
                          deleteRoad(road.id);
                        }}
                        className="absolute w-5 h-5 bg-destructive text-destructive-foreground rounded-full flex items-center justify-center text-xs z-30 hover:scale-110 transition-transform"
                        style={{
                          left: `${midX}%`,
                          top: `${midY}%`,
                          transform: 'translate(-50%, -50%)',
                        }}
                        title={`Delete road (segment ${segmentIndex + 1})`}
                      >
                        <X className="w-3 h-3" />
                      </button>
                    );
                  });
                })}
            </div>
          </div>
        )}
      </div>

      {/* Selected Region Info */}
      <AnimatePresence>
        {selectedRegion && !editMode && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 20 }}
            className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 w-full max-w-md px-4"
          >
            <div className="bg-card rounded-xl border border-border shadow-2xl p-4">
              <div className="flex items-start justify-between mb-2">
                <div>
                  <h3 className="font-bold text-lg text-foreground">{selectedRegion.name}</h3>
                  <Badge variant="secondary" className="text-xs capitalize">
                    {selectedRegion.category}
                  </Badge>
                </div>
                <Button variant="ghost" size="icon" onClick={() => setSelectedRegion(null)}>
                  <X className="w-4 h-4" />
                </Button>
              </div>
              <p className="text-sm text-muted-foreground">{selectedRegion.description}</p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Edit Region Modal */}
      <EditRegionModal
        editingRegion={editingRegion}
        setEditingRegion={setEditingRegion}
        onSave={saveRegion}
        onDelete={deleteRegion}
        categories={categories}
      />

      {/* Edit Mode Hint */}
      {editMode && (
        <div className="fixed bottom-4 right-4 bg-card border border-border rounded-lg p-3 shadow-lg max-w-xs">
          <p className="text-sm text-muted-foreground">
            <strong className="text-foreground">Edit Mode</strong>
            <br />
            {drawMode === 'building' && 'Click & drag to draw a building'}
            {drawMode === 'road' && 'Click & drag to draw a road'}
            {drawMode === 'none' &&
              'Select Building or Road tool, or click a region to edit. Drag corners to resize.'}
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
  UtensilsCrossed,
  Search,
  Plus,
  ShoppingBag,
  MapPin,
  Loader2,
  Clock,
  Trash2,
  Minus,
} from "lucide-react";
import { toast } from "sonner";

import { Badge, Button, Input, Skeleton } from "@pec/ui";
import { AXIOS_INSTANCE } from "@pec/api";
import { usePermissions } from "@/hooks/usePermissions";

interface CanteenItem {
  id: string;
  name: string;
  price: number;
  category: string;
  description: string;
  image: string;
  isAvailable: boolean;
  stock: number;
}

interface CartItem extends CanteenItem {
  quantity: number;
}

export default function NightCanteen() {
  const { user } = usePermissions();
  const [items, setItems] = useState<CanteenItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [hostelRoom, setHostelRoom] = useState("");
  const [isPlacingOrder, setIsPlacingOrder] = useState(false);
  const [view, setView] = useState<"menu" | "orders">("menu");
  const [myOrders, setMyOrders] = useState<any[]>([]);

  const categories = ["All", "Snacks", "Drinks", "Meals", "Desserts"];

  useEffect(() => {
    const fetchItems = async () => {
      try {
        const { data: raw } = await AXIOS_INSTANCE.get('/night-canteen/items');
        const fetchedItems = Array.isArray(raw?.data) ? raw.data : (Array.isArray(raw) ? raw : []);
        // Idempotent state update to prevent duplicates from strict mode or bridge polling
        setItems((prev) => {
          const combined = [...prev, ...fetchedItems];
          const uniqueMap = new Map(combined.map((item) => [item.id, item]));
          return Array.from(uniqueMap.values());
        });
      } catch (error) {
        console.error("Error fetching canteen items:", error);
        toast.error("Failed to load menu");
      } finally {
        setLoading(false);
      }
    };

    fetchItems();
  }, []);

  useEffect(() => {
    if (view === "orders" && user) {
      const fetchOrders = async () => {
        try {
          const { data: raw } = await AXIOS_INSTANCE.get('/night-canteen/orders');
          const ordersArr = Array.isArray(raw?.data) ? raw.data : (Array.isArray(raw) ? raw : []);
          setMyOrders(ordersArr.sort((a: any, b: any) => new Date(b.timestamp || b.createdAt).getTime() - new Date(a.timestamp || a.createdAt).getTime()));
        } catch (e) { console.error(e); }
      };
      fetchOrders();
      const interval = setInterval(fetchOrders, 10000);
      return () => clearInterval(interval);
    }
  }, [view, user]);

  const addToCart = (item: CanteenItem) => {
    setCart((prev) => {
      const existing = prev.find((i) => i.id === item.id);
      if (existing) {
        return prev.map((i) =>
          i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i,
        );
      }
      return [...prev, { ...item, quantity: 1 }];
    });
    toast.success(`${item.name} added to cart`);
  };

  const removeFromCart = (itemId: string) => {
    setCart((prev) => prev.filter((i) => i.id !== itemId));
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart((prev) =>
      prev.map((i) => {
        if (i.id === itemId) {
          const newQty = Math.max(1, i.quantity + delta);
          return { ...i, quantity: newQty };
        }
        return i;
      }),
    );
  };

  const cartTotal = cart.reduce(
    (sum, item) => sum + item.price * item.quantity,
    0,
  );

  const placeOrder = async () => {
    if (!hostelRoom.trim()) {
      toast.error("Please enter your hostel and room number");
      return;
    }

    if (cart.length === 0) {
      toast.error("Your cart is empty");
      return;
    }

    setIsPlacingOrder(true);
    try {
      const orderData = {
        studentId: user?.uid,
        studentName: user?.fullName || user?.name || user?.email?.split("@")[0],
        hostelRoom,
        items: cart.map((i) => ({
          itemId: i.id,
          quantity: i.quantity,
        })),
        totalAmount: cartTotal,
        status: "Pending",
        timestamp: new Date().toISOString(),
      };

      await AXIOS_INSTANCE.post('/night-canteen/orders', orderData);
      setCart([]);
      setHostelRoom("");
      toast.success("Order placed successfully!");
      setView("orders");
    } catch (error) {
      console.error("Error placing order:", error);
      toast.error("Failed to place order");
    } finally {
      setIsPlacingOrder(false);
    }
  };

  const filteredItems = items.filter((item) => {
    const matchesSearch = item.name
      .toLowerCase()
      .includes(searchQuery.toLowerCase());
    const matchesCategory =
      selectedCategory === "All" || item.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="container mx-auto px-4 py-8 max-w-7xl">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
        <div>
          <h1 className="text-3xl font-bold text-foreground mb-2 flex items-center gap-3">
            <UtensilsCrossed className="w-8 h-8 text-primary" />
            Night Canteen
          </h1>
          <p className="text-muted-foreground">
            Late night cravings sorted! Ordered straight to your room.
          </p>
        </div>

        <div className="flex items-center gap-2 bg-muted p-1 rounded-lg self-start">
          <Button
            variant={view === "menu" ? "secondary" : "ghost"}
            onClick={() => setView("menu")}
            className="rounded-md"
          >
            Menu
          </Button>
          <Button
            variant={view === "orders" ? "secondary" : "ghost"}
            onClick={() => setView("orders")}
            className="rounded-md"
          >
            My Orders
          </Button>
        </div>
      </div>

      {view === "menu" ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Menu Section */}
          <div className="lg:col-span-2 space-y-6">
            <div className="flex flex-col sm:flex-row gap-4">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input
                  placeholder="Search for items..."
                  className="pl-10"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                {categories.map((cat) => (
                  <Button
                    key={cat}
                    variant={selectedCategory === cat ? "default" : "outline"}
                    size="sm"
                    onClick={() => setSelectedCategory(cat)}
                    className="whitespace-nowrap"
                  >
                    {cat}
                  </Button>
                ))}
              </div>
            </div>

            {loading ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {[1, 2, 3, 4].map((i) => (
                  <div
                    key={i}
                    className="rounded-2xl border border-border bg-card overflow-hidden"
                  >
                    <Skeleton className="h-48 w-full" />
                    <div className="p-4 space-y-3">
                      <div className="flex justify-between">
                        <Skeleton className="h-6 w-3/4" />
                        <Skeleton className="h-6 w-12" />
                      </div>
                      <Skeleton className="h-4 w-full" />
                      <Skeleton className="h-10 w-full rounded-md" />
                    </div>
                  </div>
                ))}
              </div>
            ) : filteredItems.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {filteredItems.map((item) => (
                  <motion.div
                    layout
                    key={item.id}
                    className="group relative overflow-hidden rounded-2xl border border-border bg-card hover:border-primary/50 transition-all card-shadow"
                  >
                    <div className="aspect-[16/9] overflow-hidden bg-muted relative">
                      <img
                        src={item.image}
                        alt={item.name}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                      />
                      <div className="absolute inset-0 bg-gradient-to-t from-background/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                    </div>
                    <div className="p-4">
                      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start gap-2 mb-2">
                        <h3 className="font-semibold text-lg">{item.name}</h3>
                        <span className="text-primary font-bold whitespace-nowrap">
                          ₹{item.price}
                        </span>
                      </div>
                      <p className="text-sm text-muted-foreground mb-4 line-clamp-2">
                        {item.description}
                      </p>
                      <Button
                        onClick={() => addToCart(item)}
                        className="w-full group-hover:bg-primary group-hover:text-primary-foreground transition-all duration-300 shadow-sm"
                        variant="secondary"
                      >
                        <Plus className="w-4 h-4 mr-2" />
                        Add to Cart
                      </Button>
                    </div>
                  </motion.div>
                ))}
              </div>
            ) : (
              <div className="text-center py-12 border-2 border-dashed rounded-2xl border-muted">
                <Search className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
                <h3 className="text-lg font-medium">No items found</h3>
                <p className="text-muted-foreground">
                  Try a different search or category
                </p>
              </div>
            )}
          </div>

          {/* Cart Section */}
          <div className="lg:col-span-1">
            <div className="sticky top-6 rounded-2xl border border-border bg-card p-6 shadow-xl overflow-hidden">
              <div className="absolute top-0 left-0 w-full h-1 bg-primary" />
              <div className="flex items-center gap-2 mb-6">
                <ShoppingBag className="w-5 h-5 text-primary" />
                <h2 className="text-xl font-bold">Your Cart</h2>
                {cart.length > 0 && (
                  <Badge variant="secondary" className="ml-auto rounded-full">
                    {cart.length}
                  </Badge>
                )}
              </div>

              {cart.length > 0 ? (
                <>
                  <div className="space-y-4 mb-8 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
                    {cart.map((item) => (
                      <div key={item.id} className="flex gap-3">
                        <div className="w-16 h-16 rounded-lg overflow-hidden shrink-0 border border-border">
                          <img
                            src={item.image}
                            alt={item.name}
                            className="w-full h-full object-cover"
                          />
                        </div>
                        <div className="flex-1">
                          <h4 className="font-medium text-sm">{item.name}</h4>
                          <p className="text-primary text-sm">₹{item.price}</p>
                          <div className="flex items-center gap-2 mt-2">
                            <button
                              onClick={() => updateQuantity(item.id, -1)}
                              className="p-1 rounded-md hover:bg-muted"
                            >
                              <Minus className="w-3 h-3" />
                            </button>
                            <span className="text-sm font-medium w-4 text-center">
                              {item.quantity}
                            </span>
                            <button
                              onClick={() => updateQuantity(item.id, 1)}
                              className="p-1 rounded-md hover:bg-muted"
                            >
                              <Plus className="w-3 h-3" />
                            </button>
                            <button
                              onClick={() => removeFromCart(item.id)}
                              className="ml-auto text-muted-foreground hover:text-destructive transition-colors"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>

                  <div className="space-y-4 pt-4 border-t border-border">
                    <div className="space-y-2">
                      <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground flex items-center gap-2">
                        <MapPin className="w-3 h-3" /> Delivery Address
                      </label>
                      <Input
                        placeholder="Hostel Name & Room No (e.g. H4, 302)"
                        value={hostelRoom}
                        onChange={(e) => setHostelRoom(e.target.value)}
                        className="bg-muted/50"
                      />
                    </div>

                    <div className="flex justify-between items-center py-2">
                      <span className="text-muted-foreground">
                        Total Amount
                      </span>
                      <span className="text-2xl font-bold">₹{cartTotal}</span>
                    </div>

                    <Button
                      onClick={placeOrder}
                      className="w-full h-12 text-lg font-bold"
                      disabled={isPlacingOrder}
                      variant="gradient"
                    >
                      {isPlacingOrder ? (
                        <>
                          <Loader2 className="w-5 h-5 mr-2 animate-spin" />
                          Placing Order...
                        </>
                      ) : (
                        "Confirm Order"
                      )}
                    </Button>
                    <p className="text-[10px] text-center text-muted-foreground uppercase tracking-widest">
                      Cash on Delivery Only
                    </p>
                  </div>
                </>
              ) : (
                <div className="text-center py-12 flex flex-col items-center gap-4">
                  <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center">
                    <ShoppingBag className="w-8 h-8 text-muted-foreground/50" />
                  </div>
                  <div className="space-y-1">
                    <h3 className="font-semibold">Hungry?</h3>
                    <p className="text-sm text-muted-foreground">
                      Your cart is as empty as your stomach!
                    </p>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-6">
          <h2 className="text-2xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6 text-primary" />
            Order History
          </h2>

          {myOrders.length > 0 ? (
            <div className="grid gap-4 lg:grid-cols-2">
              {myOrders.map((order) => (
                <div
                  key={order.id}
                  className="p-6 rounded-2xl border border-border bg-card card-shadow relative overflow-hidden hover:border-primary/30 transition-all"
                >
                  <div className="absolute top-0 right-0 p-4">
                    <Badge
                      className={
                        order.status === "Pending"
                          ? "bg-orange-500/10 text-orange-500"
                          : order.status === "Delivered"
                            ? "bg-green-500/10 text-green-500"
                            : order.status === "Cancelled"
                              ? "bg-red-500/10 text-red-500"
                              : "bg-primary/10 text-primary"
                      }
                    >
                      {order.status}
                    </Badge>
                  </div>

                  <div className="space-y-4">
                    <div>
                      <p className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1">
                        Order #{order.id.slice(-6).toUpperCase()}
                      </p>
                      <p className="text-sm flex items-center gap-1 text-muted-foreground">
                        <Clock className="w-3 h-3" />{" "}
                        {order.timestamp?.toLocaleString() || "Processsing..."}
                      </p>
                    </div>

                    <div className="flex flex-wrap gap-2">
                      {order.items.map((item: any, idx: number) => (
                        <Badge key={idx} variant="secondary">
                          {item.quantity}x {item.name}
                        </Badge>
                      ))}
                    </div>

                    <div className="flex justify-between items-end pt-2 border-t border-border mt-4">
                      <div>
                        <p className="text-xs text-muted-foreground">
                          Delivery to
                        </p>
                        <p className="font-bold">{order.hostelRoom}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-xs text-muted-foreground">
                          Total Paid
                        </p>
                        <p className="text-xl font-bold text-primary">
                          ₹{order.totalAmount}
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-20 border-2 border-dashed border-muted rounded-3xl">
              <Clock className="w-16 h-16 text-muted-foreground/30 mx-auto mb-4" />
              <h3 className="text-xl font-bold">No orders yet</h3>
              <p className="text-muted-foreground mt-2">
                Hunger is a choice. Make the right one.
              </p>
              <Button onClick={() => setView("menu")} className="mt-6">
                Browse Menu
              </Button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

"use client";
import { Button } from "@pec/ui";


import { useState, useRef, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import { ArrowLeft } from "lucide-react";

import { ChatSidebar } from "@/features/chat/ChatSidebar";
import { ChatMessage } from "@/features/chat/ChatMessage";
import { ChatInput } from "@/features/chat/ChatInput";
import { ChatInfoDialog } from "@/features/chat/ChatInfoDialog";

import { EmptyState, StatePanel } from "@/components/common/AsyncState";

import { useChatRooms } from "@/hooks/use-chat-rooms";
import { useChatMessages } from "@/hooks/useChatMessages";

interface ChatViewProps {
  user: any;
  initialRooms: any[];
}

export function ChatView({ user, initialRooms }: ChatViewProps) {
  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);
  const [showChatOnMobile, setShowChatOnMobile] = useState(false);
  const [isInfoDialogOpen, setIsInfoDialogOpen] = useState(false);

  const searchParams = useSearchParams();
  const roomFromUrl = searchParams.get('room');

  const { rooms, loading: roomsLoading } = useChatRooms(user, initialRooms);
  
  const [selectedRoomId, setSelectedRoomId] = useState<string | null>(roomFromUrl || (rooms.length > 0 ? rooms[0].id : null));
  const [replyingTo, setReplyingTo] = useState<{ id: string; text: string; senderName: string } | null>(null);

  useEffect(() => {
    if (roomFromUrl) {
      setSelectedRoomId(roomFromUrl);
      setShowChatOnMobile(true);
      return;
    }

    if (!selectedRoomId && rooms.length > 0) {
      setSelectedRoomId(rooms[0].id);
    }
  }, [roomFromUrl, rooms, selectedRoomId]);

  const {
    messages,
    loading: messagesLoading,
    sendMessage,
    loadMore,
    hasMore,
  } = useChatMessages(selectedRoomId);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messageRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);

  useEffect(() => {
    const behavior = messagesLoading ? "auto" : "smooth";
    if (!isAutoScrolling) {
      messagesEndRef.current?.scrollIntoView({ behavior, block: "end" });
    }
  }, [messages, messagesLoading, isAutoScrolling]);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const { scrollTop } = e.currentTarget;
    if (scrollTop === 0 && hasMore && !messagesLoading) {
      setIsAutoScrolling(true);
      loadMore();
    } else {
      setIsAutoScrolling(false);
    }
  };

  if (!user) return null;

  const selectedRoom = rooms.find((room) => room.id === selectedRoomId);

  const handleRoomSelect = (roomId: string) => {
    setSelectedRoomId(roomId);
    setShowChatOnMobile(true);
  };

  return (
    <div className="flex h-[calc(100vh-4rem)] bg-background overflow-hidden w-full">
      <div className={`${showChatOnMobile ? 'hidden lg:block' : 'block'} lg:block w-full lg:w-auto`}>
        <ChatSidebar
          rooms={rooms}
          selectedRoom={selectedRoomId ?? ""}
          onRoomChange={handleRoomSelect}
          userRole={(user.role as any) || 'student'}
          userId={user.uid}
          loading={roomsLoading}
          isMobileOpen={isMobileSidebarOpen}
          onMobileClose={() => setIsMobileSidebarOpen(false)}
        />
      </div>

      <div className={`${showChatOnMobile ? 'flex' : 'hidden lg:flex'} flex-1 flex-col chat-main`}>
        <div className="chat-navbar px-4 py-3 border-b flex items-center justify-between">
          <div className="flex items-center gap-3 flex-1 overflow-hidden">
            <Button
              variant="ghost"
              size="icon"
              className="lg:hidden"
              onClick={() => setShowChatOnMobile(false)}
            >
              <ArrowLeft className="w-5 h-5" />
            </Button>

            {selectedRoom && (
              <button
                onClick={() => setIsInfoDialogOpen(true)}
                className="flex items-center gap-2 hover:bg-secondary/50 px-3 py-1.5 rounded-lg transition-colors overflow-hidden max-w-full text-left"
              >
                <div className="flex-1 overflow-hidden">
                  <h2 className="text-base font-semibold truncate">{selectedRoom.title}</h2>
                  <span className="text-xs text-muted-foreground hidden sm:inline">
                      {selectedRoom.type} Chat
                  </span>
                </div>
              </button>
            )}
          </div>
        </div>

        <div className="chat-messages flex-1 overflow-y-auto bg-background/50" onScroll={handleScroll}>
          {messagesLoading && messages.length === 0 ? (
            <div className="h-full flex items-center justify-center p-4">
              <StatePanel title="Loading messages" description="Fetching history…" />
            </div>
          ) : messages.length === 0 ? (
            <div className="h-full flex items-center justify-center p-4">
               <EmptyState title="No messages" description="Start a conversation!" />
            </div>
          ) : (
            <div className="py-4">
              {messages.map((msg) => (
                <div key={msg.id} ref={(el) => { messageRefs.current[msg.id] = el; }}>
                  <ChatMessage
                    message={{
                        id: msg.id,
                        content: msg.text,
                        senderId: msg.senderId,
                        senderName: msg.senderId === user.uid ? "You" : (msg.senderName || "Unknown"),
                        timestamp: msg.createdAt?.toDate?.() ?? new Date(),
                        isOwn: msg.senderId === user.uid,
                    }}
                    onReply={() => {}}
                    onReplyClick={() => {}}
                  />
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {selectedRoomId && (
          <div className="p-4 border-t bg-background">
            <ChatInput
              onSend={(text, metadata) => sendMessage(selectedRoomId, text, metadata)}
              placeholder={`Message #${selectedRoom?.title ?? "chat"}...`}
              roomId={selectedRoomId}
              replyingTo={replyingTo}
              onCancelReply={() => setReplyingTo(null)}
            />
          </div>
        )}
      </div>

      <ChatInfoDialog
        open={isInfoDialogOpen}
        onOpenChange={setIsInfoDialogOpen}
        room={selectedRoom || null}
        onRoomSelect={handleRoomSelect}
      />
    </div>
  );
}

import { Loader } from "@pec/ui";


export default function Loading() {
  return <Loader fullScreen={false} />;
}

'use client';
import { Button, Input, Textarea, Badge } from "@pec/ui";


import { useEffect, useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import { Loader2, Plus, Send, MessageSquare, Users, FileText } from 'lucide-react';
import { toast } from 'sonner';

import { useAuth } from '@/features/auth/hooks/useAuth';
import api from "@pec/api";
import { ClubProposalDialog } from '@/features/clubs/ClubProposalDialog';
import { ClubRequestsReview } from '@/features/clubs/ClubRequestsReview';

type Club = {
  id: string;
  name: string;
  memberCount: number;
  joined: boolean;
  requestStatus?: 'none' | 'pending' | 'approved' | 'rejected';
  pendingRequestCount?: number;
};

const adminRoles = ['college_admin'];

export default function ClubsPage() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();
  const [loading, setLoading] = useState(true);
  const [clubs, setClubs] = useState<Club[]>([]);
  const [newClubName, setNewClubName] = useState('');
  const [postingByClub, setPostingByClub] = useState<Record<string, string>>({});
  const [selectedClubForProposal, setSelectedClubForProposal] = useState<{
    id: string;
    name: string;
  } | null>(null);

  const isAdmin = useMemo(
    () => adminRoles.includes(user?.role || ''),
    [user?.role],
  );

  const studentClubStats = useMemo(() => {
    if (isAdmin) return null;
    const total = clubs.length;
    const joined = clubs.filter((club) => club.joined).length;
    const pending = clubs.filter((club) => !club.joined && club.requestStatus === 'pending').length;
    const rejected = clubs.filter((club) => !club.joined && club.requestStatus === 'rejected').length;
    const available = Math.max(0, total - joined - pending - rejected);
    return { total, joined, pending, rejected, available };
  }, [clubs, isAdmin]);

  const loadClubs = async () => {
    try {
      setLoading(true);
      const res = await api.get('/chat/clubs');
      const rawClubs = (res.data?.data || []) as Club[];
      const uniqueClubs = rawClubs.filter(
        (club, index, arr) => arr.findIndex((c) => c.id === club.id) === index,
      );
      setClubs(uniqueClubs);
    } catch (error) {
      console.error(error);
      toast.error('Failed to load clubs');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (authLoading) return;
    if (!user) {
      router.replace('/auth');
      return;
    }
    if (user.role === 'faculty') {
      toast.error('Clubs are not available for faculty');
      router.replace('/dashboard');
      return;
    }
    void loadClubs();
  }, [authLoading, user, router]);

  const createClub = async () => {
    const name = newClubName.trim();
    if (!name) return;
    try {
      await api.post('/chat/clubs', { name });
      toast.success('Club created');
      setNewClubName('');
      await loadClubs();
      window.dispatchEvent(new Event('chat-rooms-updated'));
    } catch (error: any) {
      console.error(error);
      toast.error(error?.response?.data?.error?.message || 'Failed to create club');
    }
  };

  const postToClub = async (clubId: string) => {
    const content = (postingByClub[clubId] || '').trim();
    if (!content) return;
    try {
      await api.post(`/chat/clubs/${clubId}/post`, { content });
      toast.success('Posted to club chat');
      setPostingByClub((prev) => ({ ...prev, [clubId]: '' }));
      router.push(`/chat?room=${clubId}`);
    } catch (error: any) {
      console.error(error);
      toast.error(error?.response?.data?.error?.message || 'Failed to post');
    }
  };

  if (authLoading || loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!user) return null;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-foreground">Clubs</h1>
        <p className="text-muted-foreground">
          {isAdmin
            ? 'Create and manage clubs, post club-wise updates, and monitor club chats.'
            : 'Join clubs and participate in club-specific discussions.'}
        </p>
      </div>

      {!isAdmin && studentClubStats && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          <div className="card-elevated ui-card-pad">
            <p className="text-[10px] uppercase tracking-widest text-muted-foreground">Total Clubs</p>
            <p className="text-2xl font-bold text-foreground">{studentClubStats.total}</p>
          </div>
          <div className="card-elevated ui-card-pad">
            <p className="text-[10px] uppercase tracking-widest text-muted-foreground">Accepted</p>
            <p className="text-2xl font-bold text-foreground">{studentClubStats.joined}</p>
          </div>
          <div className="card-elevated ui-card-pad">
            <p className="text-[10px] uppercase tracking-widest text-muted-foreground">Pending</p>
            <p className="text-2xl font-bold text-foreground">{studentClubStats.pending}</p>
          </div>
          <div className="card-elevated ui-card-pad">
            <p className="text-[10px] uppercase tracking-widest text-muted-foreground">Rejected</p>
            <p className="text-2xl font-bold text-foreground">{studentClubStats.rejected}</p>
          </div>
          <div className="card-elevated ui-card-pad">
            <p className="text-[10px] uppercase tracking-widest text-muted-foreground">Available</p>
            <p className="text-2xl font-bold text-foreground">{studentClubStats.available}</p>
          </div>
        </div>
      )}

      {isAdmin && (
        <div className="card-elevated ui-card-pad space-y-3">
          <h2 className="text-lg font-semibold text-foreground">Create New Club</h2>
          <div className="flex gap-2">
            <Input
              placeholder="Enter club name (e.g. Robotics Club)"
              value={newClubName}
              onChange={(e) => setNewClubName(e.target.value)}
            />
            <Button onClick={createClub}>
              <Plus className="w-4 h-4 mr-2" />
              Create
            </Button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {clubs.map((club) => (
          <div key={club.id} className="card-elevated ui-card-pad space-y-3">
            <div className="flex items-start justify-between gap-3">
              <div>
                <h3 className="text-lg font-semibold text-foreground">{club.name}</h3>
                <p className="text-sm text-muted-foreground flex items-center gap-2">
                  <Users className="w-4 h-4" />
                  {club.memberCount} members
                </p>
              </div>
              <Badge variant={club.joined ? 'default' : 'secondary'}>
                {club.joined ? 'Joined' : 'Not Joined'}
              </Badge>
            </div>

            {!isAdmin && !club.joined && club.requestStatus === 'pending' && (
              <p className="text-xs text-amber-600 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded px-2 py-1">
                Join request pending admin approval
              </p>
            )}

            {!isAdmin && !club.joined && club.requestStatus === 'rejected' && (
              <p className="text-xs text-red-600 bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800 rounded px-2 py-1">
                Last request was rejected. You can submit a new proposal.
              </p>
            )}

            {isAdmin && (club.pendingRequestCount || 0) > 0 && (
              <p className="text-xs text-primary bg-primary/10 border border-primary/20 rounded px-2 py-1">
                {club.pendingRequestCount} pending request
                {(club.pendingRequestCount || 0) > 1 ? 's' : ''}
              </p>
            )}

            <div className="flex flex-wrap gap-2">
              {!club.joined && !isAdmin && (
                <Button onClick={() => setSelectedClubForProposal({ id: club.id, name: club.name })}>
                  <FileText className="w-4 h-4 mr-2" />
                  {club.requestStatus === 'pending' ? 'Update Proposal' : 'Submit Proposal'}
                </Button>
              )}
              {(club.joined || isAdmin) && (
                <Button
                  variant="outline"
                  onClick={() => router.push(`/chat?room=${club.id}`)}
                >
                  <MessageSquare className="w-4 h-4 mr-2" />
                  Open Club Chat
                </Button>
              )}
            </div>

            {isAdmin && (
              <div className="space-y-2 border-t border-border pt-3">
                <p className="text-sm font-medium text-foreground">
                  Post Club-wise Update
                </p>
                <Textarea
                  rows={3}
                  placeholder="Write update / task for this club..."
                  value={postingByClub[club.id] || ''}
                  onChange={(e) =>
                    setPostingByClub((prev) => ({
                      ...prev,
                      [club.id]: e.target.value,
                    }))
                  }
                />
                <Button onClick={() => postToClub(club.id)}>
                  <Send className="w-4 h-4 mr-2" />
                  Post to Club
                </Button>
              </div>
            )}
          </div>
        ))}
      </div>

      {clubs.length === 0 && (
        <p className="text-sm text-muted-foreground">No clubs created yet.</p>
      )}

      {isAdmin && (
        <div className="border-t border-border pt-6">
          <ClubRequestsReview />
        </div>
      )}

      <ClubProposalDialog
        clubId={selectedClubForProposal?.id || ''}
        clubName={selectedClubForProposal?.name || ''}
        isOpen={!!selectedClubForProposal}
        onClose={() => setSelectedClubForProposal(null)}
        onSubmitSuccess={() => loadClubs()}
      />
    </div>
  );
}

'use client';
import { extractData } from "@/lib/utils";
import api from "@pec/api";
import { Button, Badge, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, Input, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@pec/ui";


import { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import {
  FileText,
  Upload,
  Download,
  Trash2,
  Plus,
  Loader2,
  BookOpen,
  Video,
  File,
  ClipboardList,
} from 'lucide-react';

import { toast } from 'sonner';
import { useRouter } from 'next/navigation';
import { usePermissions } from '@/hooks/usePermissions';
import BulkUpload from '@/components/BulkUpload';

import useSWR from 'swr';



interface CourseMaterial {
  id: string;
  courseId: string;
  courseName: string;
  courseCode: string;
  title: string;
  description: string;
  fileURL: string;
  type: 'lecture-notes' | 'reference' | 'assignment' | 'video' | 'other';
  uploadedBy: string;
  uploadedAt: any;
}

const formatUploadedDate = (uploadedAt: unknown) => {
  if (!uploadedAt) return 'N/A';
  if (typeof uploadedAt === 'object' && 'toDate' in uploadedAt) {
    const timestampObj = uploadedAt as { toDate?: () => Date };
    const converted = timestampObj.toDate?.();
    return converted ? converted.toLocaleDateString() : 'N/A';
  }
  const parsed = new Date(uploadedAt as string | number | Date);
  return Number.isNaN(parsed.getTime()) ? 'N/A' : parsed.toLocaleDateString();
};

export default function CourseMaterials() {
  const router = useRouter();
  const { isAdmin, isFaculty, user, loading: authLoading } = usePermissions();
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (authLoading) return; // Wait for auth to load
    
    if (!user) {
      router.replace('/auth');
      return;
    }
    setLoading(false);
  }, [authLoading, user, router]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (isAdmin || isFaculty) {
    return <MaterialsManager userId={user.uid} userRole={user.role} />;
  }

  return <StudentMaterialsView userId={user.uid} />;
}

function MaterialsManager({ userId, userRole }: { userId: string; userRole: string }) {
  const [selectedCourse, setSelectedCourse] = useState('');
  const [showUploadDialog, setShowUploadDialog] = useState(false);
  const [showBulkUpload, setShowBulkUpload] = useState(false);
  const [uploading, setUploading] = useState(false);
  const hasWarnedMissingMaterialsApi = useRef(false);

  const [materialForm, setMaterialForm] = useState({
    courseId: '',
    title: '',
    description: '',
    type: 'lecture-notes' as CourseMaterial['type'],
  });
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  const isAdmin = userRole.includes('admin');

  const fetcher = async () => {
    let coursesData = [];
    if (isAdmin) {
      coursesData = extractData<any>((await api.get('/courses', { params: { limit: 2000 } })).data);
    } else {
      const facultyCourses = extractData<any>((await api.get('/courses', { params: { ...{ facultyId: userId }, limit: 2000 } })).data);
      if (facultyCourses.length > 0) {
        coursesData = facultyCourses;
      } else {
        const allCourses = extractData<any>((await api.get('/courses', { params: { limit: 2000 } })).data);
        coursesData = allCourses.filter(
          (course: any) => course.facultyId === userId || course.instructorId === userId
        );
      }
    }

    const courseIds = coursesData.map(c => c.id);
    let materialsData: CourseMaterial[] = [];
    let materialsApiAvailable = true;

    if (courseIds.length > 0) {
      try {
        materialsData = (extractData<any>((await api.get('/course-materials', { params: { limit: 2000 } })).data))
          .filter((m: CourseMaterial) => courseIds.includes(m.courseId));
      } catch (error: any) {
        if (error?.response?.status === 404) {
          materialsApiAvailable = false;
          if (!hasWarnedMissingMaterialsApi.current) {
            toast.info('Course materials API is not available yet.');
            hasWarnedMissingMaterialsApi.current = true;
          }
        } else {
          throw error;
        }
      }
    }

    return { coursesData, materialsData, materialsApiAvailable };
  };

  const { data, error, isLoading, mutate } = useSWR(`manager-materials-${userId}`, fetcher, {
    revalidateOnFocus: false,
    dedupingInterval: 60000,
  });

  const courses = data?.coursesData || [];
  const materials = data?.materialsData || [];
  const materialsApiAvailable = data?.materialsApiAvailable ?? true;

  const handleUpload = async () => {
    if (!materialForm.title || !materialForm.courseId || !selectedFile) {
      toast.error('Please fill all required fields and select a file');
      return;
    }

    setUploading(true);
    try {
      const course = courses.find(c => c.id === materialForm.courseId);
      
      const formData = new FormData();
      formData.append('courseId', materialForm.courseId);
      formData.append('courseName', course?.name || '');
      formData.append('courseCode', course?.code || '');
      formData.append('title', materialForm.title);
      formData.append('description', materialForm.description);
      formData.append('type', materialForm.type);
      formData.append('uploadedBy', userId);
      formData.append('file', selectedFile);

      await api.post('/course-materials', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      
      toast.success('Material uploaded successfully');
      setShowUploadDialog(false);
      resetForm();
      mutate();
    } catch (error) {
      console.error('Error uploading material:', error);
      toast.error('Failed to upload material');
    } finally {
      setUploading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this material?')) return;
    
    try {
      await api.delete(`/course-materials/${id}`);
      toast.success('Material deleted');
      mutate();
    } catch (error) {
      console.error('Error deleting:', error);
      toast.error('Failed to delete');
    }
  };

  const handleBulkImport = async (data: any[]) => {
    let success = 0;
    let failed = 0;
    const errors: string[] = [];

    for (const row of data) {
      try {
        const course = courses.find(c => c.code === row.courseCode);
        if (!course) throw new Error(`Course ${row.courseCode} not found`);

        await api.post('/course-materials', {
          courseId: course.id,
          courseName: course.name,
          courseCode: course.code,
          title: row.title,
          description: row.description || '',
          fileURL: row.fileURL,
          type: row.type || 'other',
          uploadedBy: userId,
        });
        success++;
      } catch (err) {
        failed++;
        errors.push((err as Error).message);
      }
    }
    
    mutate();
    return { success, failed, errors };
  };

  const resetForm = () => {
    setMaterialForm({
      courseId: '',
      title: '',
      description: '',
      type: 'lecture-notes',
    });
    setSelectedFile(null);
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'lecture-notes': return <BookOpen className="w-6 h-6" />;
      case 'reference': return <FileText className="w-6 h-6" />;
      case 'assignment': return <ClipboardList className="w-6 h-6" />;
      case 'video': return <Video className="w-6 h-6" />;
      default: return <File className="w-6 h-6" />;
    }
  };

  const filteredMaterials = selectedCourse && selectedCourse !== 'all'
    ? materials.filter(m => m.courseId === selectedCourse)
    : materials;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">Course Materials</h1>
          <p className="text-muted-foreground">Upload and manage course materials</p>
        </div>
        <div className="button-group">
          <Button variant="outline" onClick={() => setShowBulkUpload(true)}>
            <Upload className="w-4 h-4 mr-2" /> Bulk Upload
          </Button>
          <Button onClick={() => { resetForm(); setShowUploadDialog(true); }}>
            <Plus className="w-4 h-4 mr-2" /> Upload Material
          </Button>
        </div>
      </div>

      <div className="card-elevated p-4">
        <Select value={selectedCourse || 'all'} onValueChange={(val) => setSelectedCourse(val === 'all' ? '' : val)}>
          <SelectTrigger>
            <SelectValue placeholder="All courses" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Courses</SelectItem>
            {courses.map(c => (
              <SelectItem key={c.id} value={c.id}>{c.code} - {c.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="space-y-4">
        {!materialsApiAvailable && (
          <div className="card-elevated p-4 text-sm text-muted-foreground">
            Course materials backend is not configured yet.
          </div>
        )}
        {filteredMaterials.length === 0 ? (
          <div className="card-elevated p-12 text-center">
            <FileText className="w-12 h-12 mx-auto mb-4 opacity-20" />
            <p className="text-muted-foreground">No materials uploaded yet</p>
          </div>
        ) : (
          filteredMaterials.map((material, idx) => (
            <motion.div
              key={material.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
              className="card-elevated p-6"
            >
              <div className="flex items-start justify-between">
                <div className="flex gap-4 flex-1">
                  <div className="p-3 rounded-lg bg-primary/10 text-primary">
                    {getTypeIcon(material.type)}
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-2">
                      <h3 className="font-semibold">{material.title}</h3>
                      <Badge variant="outline">{material.courseCode}</Badge>
                      <Badge variant="secondary">{material.type.replace('-', ' ')}</Badge>
                    </div>
                    <p className="text-sm text-muted-foreground mb-2">{material.description}</p>
                    <p className="text-xs text-muted-foreground">
                      Uploaded: {formatUploadedDate(material.uploadedAt)}
                    </p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <Button size="sm" variant="outline" asChild>
                    <a href={material.fileURL} target="_blank" rel="noopener noreferrer">
                      <Download className="w-4 h-4 mr-2" /> Download
                    </a>
                  </Button>
                  <Button size="sm" variant="ghost" onClick={() => handleDelete(material.id)}>
                    <Trash2 className="w-4 h-4 text-destructive" />
                  </Button>
                </div>
              </div>
            </motion.div>
          ))
        )}
      </div>

      {/* Upload Dialog */}
      <Dialog open={showUploadDialog} onOpenChange={setShowUploadDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Upload Course Material</DialogTitle>
            <DialogDescription>Add a new material for your course</DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium">Course</label>
              <Select value={materialForm.courseId} onValueChange={val => setMaterialForm({...materialForm, courseId: val})}>
                <SelectTrigger className="mt-1">
                  <SelectValue placeholder="Select course" />
                </SelectTrigger>
                <SelectContent>
                  {courses.map(c => <SelectItem key={c.id} value={c.id}>{c.code} - {c.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium">Title</label>
              <Input value={materialForm.title} onChange={e => setMaterialForm({...materialForm, title: e.target.value})} className="mt-1" placeholder="Lecture 1 - Introduction" />
            </div>
            <div>
              <label className="text-sm font-medium">Description</label>
              <textarea value={materialForm.description} onChange={e => setMaterialForm({...materialForm, description: e.target.value})} className="mt-1 w-full min-h-[80px] p-2 rounded border bg-background" placeholder="Brief description..." />
            </div>
            <div>
              <label className="text-sm font-medium">Type</label>
              <Select value={materialForm.type} onValueChange={(val: any) => setMaterialForm({...materialForm, type: val})}>
                <SelectTrigger className="mt-1">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="lecture-notes">Lecture Notes</SelectItem>
                  <SelectItem value="reference">Reference Material</SelectItem>
                  <SelectItem value="assignment">Assignment</SelectItem>
                  <SelectItem value="video">Video</SelectItem>
                  <SelectItem value="other">Other</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium">File</label>
              <Input 
                type="file" 
                onChange={e => setSelectedFile(e.target.files?.[0] || null)} 
                className="mt-1 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary/10 file:text-primary hover:file:bg-primary/20 cursor-pointer" 
              />
              <p className="text-xs text-muted-foreground mt-1">Select a file (PDF, DOCX, ZIP) - Max 50MB</p>
            </div>
            <Button onClick={handleUpload} disabled={uploading} className="w-full">
              {uploading ? <><Loader2 className="w-4 h-4 animate-spin mr-2" /> Uploading...</> : <><Upload className="w-4 h-4 mr-2" /> Upload Material</>}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Bulk Upload */}
      <Dialog open={showBulkUpload} onOpenChange={setShowBulkUpload}>
        <DialogContent className="max-w-4xl">
          <DialogHeader>
            <DialogTitle>Bulk Upload Materials</DialogTitle>
            <DialogDescription>Columns: courseCode, title, description, type, fileURL</DialogDescription>
          </DialogHeader>
          <BulkUpload 
            entityType="materials" 
            onImport={handleBulkImport} 
            templateColumns={['courseCode', 'title', 'description', 'type', 'fileURL']}
            sampleData={[{ courseCode: 'CS101', title: 'Lecture 1', description: 'Intro', type: 'lecture-notes', fileURL: 'https://...' }]}
          />
        </DialogContent>
      </Dialog>
    </div>
  );
}

function StudentMaterialsView({ userId }: { userId: string }) {
  const [filterType, setFilterType] = useState('all');
  const [filterCourse, setFilterCourse] = useState('all');
  const hasWarnedMissingMaterialsApi = useRef(false);

  const fetcher = async () => {
    let enrollmentsResponse;
    try {
      const scopedEnrollments = extractData<any>((await api.get('/enrollments', { params: { ...{
        studentId: userId,
        status: 'active',
      }, limit: 2000 } })).data);
      enrollmentsResponse = { data: scopedEnrollments };
    } catch {
      const allEnrollments = extractData<any>((await api.get('/enrollments', { params: { limit: 2000 } })).data);
      enrollmentsResponse = { data: allEnrollments };
    }
    const enrolledCourseIds = (Array.isArray(enrollmentsResponse.data) ? enrollmentsResponse.data : [])
      .filter((enrollment: any) => enrollment.studentId === userId && (enrollment.status ?? 'active') === 'active')
      .map((enrollment: any) => enrollment.courseId);

    if (enrolledCourseIds.length === 0) {
      return { coursesData: [], materialsData: [] };
    }

    const coursesData = (extractData<any>((await api.get('/courses', { params: { limit: 2000 } })).data))
      .filter((course: any) => enrolledCourseIds.includes(course.id));

    try {
      const materialsData = (extractData<any>((await api.get('/course-materials', { params: { limit: 2000 } })).data))
        .filter((m: CourseMaterial) => enrolledCourseIds.includes(m.courseId));
      
      return { coursesData, materialsData, materialsApiAvailable: true };
    } catch (error: any) {
      if (error?.response?.status === 404) {
        if (!hasWarnedMissingMaterialsApi.current) {
          toast.info('Course materials API is not available yet.');
          hasWarnedMissingMaterialsApi.current = true;
        }
        return { coursesData, materialsData: [], materialsApiAvailable: false };
      } else {
        throw error;
      }
    }
  };

  const { data, error, isLoading } = useSWR(`student-materials-${userId}`, fetcher, {
    revalidateOnFocus: false,
    dedupingInterval: 60000,
  });

  const courses = data?.coursesData || [];
  const materials = data?.materialsData || [];
  const materialsApiAvailable = data?.materialsApiAvailable ?? true;
  const loading = isLoading;

  if (error) {
    toast.error('Failed to load materials');
  }

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'lecture-notes': return <BookOpen className="w-6 h-6" />;
      case 'reference': return <FileText className="w-6 h-6" />;
      case 'assignment': return <ClipboardList className="w-6 h-6" />;
      case 'video': return <Video className="w-6 h-6" />;
      default: return <File className="w-6 h-6" />;
    }
  };

  const filteredMaterials = materials.filter(m => {
    const matchesType = filterType === 'all' || m.type === filterType;
    const matchesCourse = filterCourse === 'all' || m.courseId === filterCourse;
    return matchesType && matchesCourse;
  });

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold">Course Materials</h1>
        <p className="text-muted-foreground">Access learning resources for your courses</p>
      </div>

      <div className="card-elevated p-4">
        <div className="flex flex-col sm:flex-row gap-4">
          <Select value={filterCourse} onValueChange={setFilterCourse}>
            <SelectTrigger className="flex-1">
              <SelectValue placeholder="All courses" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Courses</SelectItem>
              {courses.map(c => (
                <SelectItem key={c.id} value={c.id}>{c.code} - {c.name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={filterType} onValueChange={setFilterType}>
            <SelectTrigger className="w-full sm:w-48">
              <SelectValue placeholder="All types" />
            </SelectTrigger>
            <SelectContent>
