);

'use client';
import { Tabs, TabsContent, TabsList, TabsTrigger, Badge, ImageWithBlur, Input, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, Button } from "@pec/ui";


import { useState, useTransition, useOptimistic } from 'react';
import { 
  Search, 
  BookOpen,
  Filter,
  Layers
} from 'lucide-react';

import { CourseCard } from './CourseCard';
import { toast } from 'sonner';
import { enrollInCourseAction, dropCourseAction } from '../actions';
import { Course } from '@pec/shared';
import { motion, AnimatePresence } from 'framer-motion';

interface CourseDirectoryProps {
  initialCourses: Course[];
  initialEnrolledIds: string[];
  initialEnrolledCourses?: Course[];
  user: any;
  studentProfile?: any;
}

export function CourseDirectory({ initialCourses, initialEnrolledIds, initialEnrolledCourses = [], user, studentProfile }: CourseDirectoryProps) {
  const [courses, setCourses] = useState(initialCourses);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState(Array.from(new Set(initialEnrolledIds)));
  
  const [optimisticEnrolledIds, setOptimisticEnrolledIds] = useOptimistic(
    enrolledCourseIds,
    (state: string[], { action, id }: { action: 'add' | 'remove', id: string }) => {
      if (action === 'add') return [...state, id];
      return state.filter(cid => cid !== id);
    }
  );

  const [searchTerm, setSearchTerm] = useState('');
  const [departmentFilter, setDepartmentFilter] = useState(studentProfile?.department || 'all');
  const [semesterFilter, setSemesterFilter] = useState(studentProfile?.semester?.toString() || 'all');
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [showDetailsDialog, setShowDetailsDialog] = useState(false);
  const [loadingSchedule, setLoadingSchedule] = useState(false);
  const [isPending, startTransition] = useTransition();

  const handleEnroll = async (course: Course) => {
    startTransition(async () => {
      setOptimisticEnrolledIds({ action: 'add', id: course.id });
      
      const formData = new FormData();
      formData.append('courseId', course.id);
      formData.append('courseCode', course.code);
      formData.append('courseName', course.name);
      formData.append('semester', String(course.semester));

      const result = await enrollInCourseAction(null, formData);
      if (result.success) {
        setEnrolledCourseIds(prev => [...prev, course.id]);
        toast.success(`Registered for ${course.code}`);
      } else {
        toast.error(result.error || 'Failed to register');
      }
    });
  };

  const handleDrop = async (courseId: string) => {
    if (!confirm('Are you sure you want to drop this course?')) return;
    startTransition(async () => {
      setOptimisticEnrolledIds({ action: 'remove', id: courseId });
      
      const result = await dropCourseAction(courseId);
      if (result.success) {
        setEnrolledCourseIds(prev => prev.filter(id => id !== courseId));
        toast.success('Course dropped successfully');
      } else {
        toast.error(result.error || 'Failed to drop course');
      }
    });
  };

  const fetchCourseSchedule = async (courseId: string) => {
     setLoadingSchedule(true);
     setTimeout(() => setLoadingSchedule(false), 500);
  };

  const departments = [...new Set(courses.map(c => c.department))];

  const getCourseImage = (dept: string, name: string) => {
    const deptImages: Record<string, string> = {
      'Computer Science': 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?w=800&q=80',
      'Electronics': 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&q=80',
      'Mechanical': 'https://images.unsplash.com/photo-1537462715879-360eeb61a0ad?w=800&q=80',
      'Civil': 'https://images.unsplash.com/photo-1503387762-592deb58ef4e?w=800&q=80',
      'Electrical': 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800&q=80',
    };
    return deptImages[dept] || 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&q=80';
  };

  const filtered = courses.filter(course => {
    const matchesSearch = course.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         course.code?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesDept = departmentFilter === 'all' || course.department === departmentFilter;
    const matchesSem = semesterFilter === 'all' || course.semester.toString() === semesterFilter;
    return matchesSearch && matchesDept && matchesSem;
  });

  const available = filtered.filter(c => {
    const isEnrolled = optimisticEnrolledIds.includes(c.id);
    if (isEnrolled) return false;
    
    if (user.role === 'student' && studentProfile) {
       const sameDept = c.department === studentProfile.department;
       const sameSem = c.semester === studentProfile.semester;
       return sameDept && sameSem;
    }
    
    return true;
  });
  
  const enrolledCourseMap = new Map<string, Course>();
  for (const course of initialEnrolledCourses) {
    if (course?.id) enrolledCourseMap.set(course.id, course);
  }
  for (const course of courses) {
    if (course?.id) enrolledCourseMap.set(course.id, course);
  }

  const enrolled = optimisticEnrolledIds
    .map((id) => enrolledCourseMap.get(id))
    .filter((course): course is Course => Boolean(course));

  return (
    <div className="space-y-8 pb-10">
      <Tabs defaultValue="enrolled" className="space-y-10 group/tabs">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
          <TabsList className="h-14 p-1.5 bg-muted/20 backdrop-blur-md rounded-2xl border border-border/20 gap-1 relative overflow-hidden">
            <TabsTrigger 
              value="enrolled" 
              className="rounded-xl px-8 h-full font-bold text-[10px] uppercase tracking-widest data-[state=active]:bg-primary/10 data-[state=active]:text-primary data-[state=active]:shadow-inner transition-all duration-300"
            >
              My Curriculum ({enrolled.length})
            </TabsTrigger>
            <TabsTrigger 
              value="available" 
              className="rounded-xl px-8 h-full font-bold text-[10px] uppercase tracking-widest data-[state=active]:bg-primary/10 data-[state=active]:text-primary data-[state=active]:shadow-inner transition-all duration-300"
            >
              Open Enrollment ({available.length})
            </TabsTrigger>
          </TabsList>
          
          <div className="flex items-center gap-3">
             <div className="relative group/search flex-1 md:w-64">
               <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/60 transition-colors group-focus-within/search:text-primary" />
               <Input 
                placeholder="Search catalog..." 
                className="h-14 pl-11 rounded-2xl bg-white/5 border-border/20 focus:bg-white/10 hover:bg-white/10 transition-all font-bold placeholder:font-normal placeholder:text-muted-foreground/60 shadow-inner"
                value={searchTerm} 
                onChange={e => setSearchTerm(e.target.value)} 
               />
             </div>
             
             <Select value={departmentFilter} onValueChange={setDepartmentFilter}>
               <SelectTrigger className="h-14 w-[180px] rounded-2xl bg-white/5 border-border/20 hover:bg-white/10 font-bold transition-all shadow-inner">
                 <div className="flex items-center gap-2"><Filter className="w-3.5 h-3.5 text-muted-foreground/80" /><SelectValue placeholder="Org" /></div>
               </SelectTrigger>
               <SelectContent className="rounded-2xl border-border/20 shadow-2xl bg-card/95 backdrop-blur-xl">
                  <SelectItem value="all" className="font-bold text-[10px] uppercase tracking-widest py-3">All Departments</SelectItem>
                  {departments.map(d => <SelectItem key={d} value={d} className="font-bold text-[10px] uppercase tracking-widest py-3">{d}</SelectItem>)}
               </SelectContent>
             </Select>
          </div>
        </div>

        <TabsContent value="available" className="mt-0 focus-visible:outline-none">
          <AnimatePresence mode="wait">
            <motion.div 
               initial={{ opacity: 0 }}
               animate={{ opacity: 1 }}
               className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
            >
              {available.map(course => (
                <CourseCard 
                  key={course.id} 
                  course={course} 
                  enrolled={false} 
                  image={getCourseImage(course.department, course.name)}
                  onView={c => { setSelectedCourse(c); fetchCourseSchedule(c.id); setShowDetailsDialog(true); }}
                  onEnroll={handleEnroll}
                />
              ))}
            </motion.div>
          </AnimatePresence>
          {available.length === 0 && (
            <div className="py-32 text-center rounded-3xl border-2 border-dashed border-border/40 bg-muted/5 flex flex-col items-center gap-6">
               <div className="p-6 bg-background rounded-full border border-border/40 shadow-sm"><Layers className="w-8 h-8 text-muted-foreground/40" /></div>
               <p className="text-sm font-medium text-muted-foreground italic">No matching elective courses identified in the catalog.</p>
            </div>
          )}
        </TabsContent>

        <TabsContent value="enrolled" className="mt-0 focus-visible:outline-none">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {enrolled.map(course => (
              <CourseCard 
                key={course.id} 
                course={course} 
                enrolled={true} 
                image={getCourseImage(course.department, course.name)}
                onView={c => { setSelectedCourse(c); fetchCourseSchedule(c.id); setShowDetailsDialog(true); }}
                onDrop={handleDrop}
              />
            ))}
          </div>
          {enrolled.length === 0 && (
            <div className="py-32 text-center rounded-3xl border-2 border-dashed border-border/40 bg-muted/5 flex flex-col items-center gap-6">
               <div className="p-6 bg-background rounded-full border border-border/40 shadow-sm"><BookOpen className="w-8 h-8 text-muted-foreground/40" /></div>
               <p className="text-sm font-medium text-muted-foreground italic">You are not currently enrolled in any courses for the active semester.</p>
               <Button variant="outline" className="h-12 rounded-xl px-8 font-bold text-[10px] uppercase tracking-widest border-primary/20 text-primary shadow-sm" onClick={() => (document.querySelector('[value="available"]') as any)?.click()}>Explore Electives</Button>
            </div>
          )}
        </TabsContent>
      </Tabs>

      <Dialog open={showDetailsDialog} onOpenChange={setShowDetailsDialog}>
        <DialogContent className="max-w-2xl p-0 overflow-hidden rounded-3xl border-border/20 bg-card/95 backdrop-blur-2xl shadow-2xl">
           <DialogHeader className="sr-only">
             <DialogTitle>{selectedCourse?.name || 'Course Details'}</DialogTitle>
             <DialogDescription>View course catalog information and syllabus details</DialogDescription>
           </DialogHeader>
           {selectedCourse && (
             <div className="space-y-0">
                <div className="relative h-40 w-full">
                   <ImageWithBlur src={getCourseImage(selectedCourse.department, selectedCourse.name)} alt={selectedCourse.name} className="w-full h-full object-cover" />
                   <div className="absolute inset-0 bg-gradient-to-t from-card via-card/50 to-transparent opacity-90" />
                   <div className="absolute bottom-5 left-6 right-6 flex items-end justify-between">
                      <div className="space-y-1.5">
                        <Badge className="bg-primary/20 text-primary border-primary/30 backdrop-blur-md px-2.5 py-0.5 font-bold text-[9px] tracking-widest uppercase shadow-glow">{selectedCourse.code}</Badge>
                        <h2 className="text-2xl font-bold tracking-tight text-foreground drop-shadow-md">{selectedCourse.name}</h2>
                      </div>
                   </div>
                </div>
                
                <div className="p-6 space-y-6">
                   <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                      <div className="bg-white/5 border border-white/5 rounded-xl p-3 flex flex-col gap-1 transition-colors hover:bg-white/10">
                         <span className="text-[9px] font-bold uppercase tracking-widest text-muted-foreground">Faculty Lead</span>
                         <p className="text-xs font-semibold text-foreground/90">{selectedCourse.facultyName.replace(/\b[A-Z]+\b/g, m => m.charAt(0) + m.slice(1).toLowerCase())}</p>
                      </div>
                      <div className="bg-white/5 border border-white/5 rounded-xl p-3 flex flex-col gap-1 transition-colors hover:bg-white/10">
                         <span className="text-[9px] font-bold uppercase tracking-widest text-muted-foreground">Academic Units</span>
                         <p className="text-xs font-semibold text-foreground/90">{selectedCourse.credits} Credits</p>
                      </div>
                      <div className="bg-white/5 border border-white/5 rounded-xl p-3 flex flex-col gap-1 transition-colors hover:bg-white/10">
                         <span className="text-[9px] font-bold uppercase tracking-widest text-muted-foreground">Level</span>
                         <p className="text-xs font-semibold text-foreground/90">Semester {selectedCourse.semester}</p>
                      </div>
                   </div>

                   <div className="space-y-2 px-1">
                      <h4 className="text-[9px] font-bold uppercase tracking-widest text-primary">Catalog Description</h4>
                      <p className="text-sm text-foreground/80 leading-relaxed font-medium">
                        {selectedCourse.description || "Comprehensive curriculum details for this institutional module will be provided during the orientation session."}
                      </p>
                   </div>
                   
                   <div className="flex gap-3 pt-4 mt-4 border-t border-border/10">
                      <Button className="flex-1 h-11 rounded-xl bg-primary text-primary-foreground font-bold text-[10px] uppercase tracking-widest shadow-glow hover:scale-[1.02] transition-all" onClick={() => setShowDetailsDialog(false)}>
                         Go to Course Materials
                      </Button>
                      <Button variant="outline" className="h-11 rounded-xl px-8 font-bold text-[10px] uppercase tracking-widest border-border/20 hover:bg-white/5" onClick={() => setShowDetailsDialog(false)}>Close</Button>
                   </div>
                </div>
             </div>
           )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { Loader } from "@pec/ui";


export default function Loading() {
  return <Loader fullScreen={false} />;
}

import { getServerSession } from '@/lib/server-auth';
import { redirect } from 'next/navigation';
import { CourseDirectory } from './components/CourseDirectory';
import { CourseManagement } from './components/CourseManagement';
import { serverFetch } from '@/lib/server-data';
import { BookOpen, Settings } from 'lucide-react';

export const metadata = {
  title: 'Academic Catalog | PEC APP',
  description: 'Institutional course directory and enrollment management services.',
};

export default async function CoursesPage() {
  const session = await getServerSession();
  if (!session) redirect('/auth');

  // Fetch role-specific initial data on server.
  const profile = await serverFetch('/auth/profile');

  let courses: any[] = [];
  if (session.role === 'faculty') {
    const scoped = await serverFetch(`/courses?facultyId=${session.uid}&limit=200`);
    courses = Array.isArray(scoped) ? scoped : [];

    if (!courses.length) {
      const allCourses = await serverFetch('/courses?limit=200');
      const facultyName = String(
        profile?.fullName || profile?.name || session.fullName || ''
      ).toLowerCase();
      const safeAllCourses = Array.isArray(allCourses) ? allCourses : [];
      courses = safeAllCourses.filter((course: any) => {
        if (course.facultyId === session.uid || course.instructorId === session.uid) {
          return true;
        }
        if (!facultyName) return false;
        const instructor = String(
          course.instructor || course.facultyName || course.instructorName || ''
        ).toLowerCase();
        return instructor.includes(facultyName);
      });
    }
  } else {
    const fetched = await serverFetch('/courses?limit=100');
    courses = Array.isArray(fetched) ? fetched : [];
  }

  const enrollments =
    session.role === 'student'
      ? await serverFetch(`/enrollments?studentId=${session.uid}&status=active`)
      : [];

  const sanitizedCourses = (courses || []).map((c: any) => ({
    ...c,
    facultyName: c.instructor || c.facultyName || 'TBA',
    maxStudents: Number(c.maxStudents || 60),
    enrolledStudents: Number(c._count?.enrollments ?? c.enrolledStudents ?? 0),
    description: c.description || '',
  }));

  const sanitizedEnrollments = Array.isArray(enrollments) ? enrollments : [];
  const sanitizedEnrolledIds = sanitizedEnrollments.map((e: any) => e.courseId);
  const initialEnrolledCourses = sanitizedEnrollments
    .map((e: any) => {
      const c = e?.course;
      if (!c) return null;
      return {
        id: c.id,
        code: c.code || 'COURSE',
        name: c.name || 'Course',
        department: c.department || 'General',
        semester: Number(c.semester || 0),
        credits: Number(c.credits || 0),
        facultyName: c.instructor || 'TBA',
        instructor: c.instructor || 'TBA',
        maxStudents: 0,
        enrolledStudents: 0,
        description: '',
        type: 'Core',
      };
    })
    .filter(Boolean);

  return (
    <div className="container py-8 px-6 max-w-7xl animate-in fade-in duration-500 min-h-screen relative">
      {/* Decorative Atmosphere Layer */}
      <div className="absolute inset-0 pointer-events-none -z-10 overflow-hidden">
        <div className="absolute inset-0 bg-grid-pattern opacity-[0.03]" />
        <div className="absolute top-[-5%] right-[-5%] w-[40%] h-[40%] bg-[radial-gradient(circle_at_center,rgba(var(--primary-rgb),0.05)_0%,transparent_70%)] blur-[80px]" />
      </div>

      {session.role === 'student' ? (
        <div className="space-y-10 pb-20">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-border/40">
            <div className="flex items-center gap-5">
              <div className="p-3.5 bg-primary/10 rounded-2xl border border-primary/20 shadow-sm shadow-primary/5">
                <BookOpen className="w-8 h-8 text-primary shadow-glow" />
              </div>
              <div>
                <h1 className="text-3xl font-bold tracking-tight text-foreground">Course Directory</h1>
                <p className="text-sm text-muted-foreground font-medium italic mt-1 font-display">Explore and enroll in the institutional academic catalog</p>
              </div>
            </div>
          </div>
          
          <CourseDirectory 
            initialCourses={sanitizedCourses} 
            initialEnrolledIds={sanitizedEnrolledIds} 
            initialEnrolledCourses={initialEnrolledCourses as any}
            user={session}
            studentProfile={profile}
          />
        </div>
      ) : (
        <div className="space-y-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-border/40">
            <div className="flex items-center gap-5">
              <div className="p-3.5 bg-primary/10 rounded-2xl border border-primary/20 shadow-sm shadow-primary/5">
                <Settings className="w-8 h-8 text-primary shadow-glow" />
              </div>
              <div>
                <h1 className="text-3xl font-bold tracking-tight text-foreground">Course Management</h1>
                <p className="text-sm text-muted-foreground font-medium italic mt-1 font-display">Manage institutional academic offerings and infrastructure</p>
              </div>
            </div>
          </div>
          
          <CourseManagement 
            initialCourses={sanitizedCourses} 
            user={session}
          />
        </div>
      )}
    </div>
  );
}

'use client';
import { Button, Tabs, TabsContent, TabsList, TabsTrigger } from "@pec/ui";

import { useState, useEffect } from 'react';

import dynamic from 'next/dynamic';
import { Settings, Loader2, BookOpen, Users, BarChart3 } from 'lucide-react';
import { useRouter } from 'next/navigation';

import { useAdminDashboard } from '@/hooks/useAdminDashboard';

// Types
import { AdminDashboardData } from '@pec/shared';

// Components
import { AdminStatsCards } from './components/AdminStatsCards';
import { CoursesTable } from './components/CoursesTable';
import { UsersTable } from './components/UsersTable';
import { CourseDialog } from './components/CourseDialog';
import { UserDialog } from './components/UserDialog';

const AdminAnalyticsCharts = dynamic(
  () => import('./components/AdminAnalyticsCharts').then((mod) => mod.AdminAnalyticsCharts),
  {
    ssr: false,
    loading: () => (
      <div className="grid gap-4 md:grid-cols-2">
        <div className="card-elevated p-6 h-[320px] bg-muted/40 animate-pulse" />
        <div className="card-elevated p-6 h-[320px] bg-muted/40 animate-pulse" />
      </div>
    ),
  }
);

export interface AdminDashboardProps {
  initialData?: AdminDashboardData;
}

export function AdminDashboard({ initialData }: AdminDashboardProps = {}) {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState('courses');
  const [timePeriod, setTimePeriod] = useState<string>('');

  useEffect(() => {
    const hour = new Date().getHours();
    if (hour < 12) setTimePeriod('Good Morning');
    else if (hour < 17) setTimePeriod('Good Afternoon');
    else setTimePeriod('Good Evening');
  }, []);

  const {
    loading,
    courses,
    users,
    stats,
    courseSearchQuery,
    setCourseSearchQuery,
    userSearchQuery,
    setUserSearchQuery,
    showCourseDialog,
    setShowCourseDialog,
    editingCourse,
    courseForm,
    setCourseForm,
    showUserDialog,
    setShowUserDialog,
    editingUser,
    userForm,
    setUserForm,
    handleCreateCourse,
    handleUpdateCourse,
    handleDeleteCourse,
    handleCreateUser,
    handleUpdateUser,
    handleDeleteUser,
    openEditCourseDialog,
    openEditUserDialog,
    resetCourseForm,
    resetUserForm,
    setEditingCourse,
    setEditingUser,
  } = useAdminDashboard(initialData);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <Loader2 className="w-8 h-8 animate-spin mx-auto mb-4 text-primary" />
          <p className="text-muted-foreground">Loading admin dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="relative overflow-hidden p-8 rounded-2xl bg-card/60 backdrop-blur-md border border-border flex flex-col md:flex-row md:items-center md:justify-between gap-6 shadow-xl glass-premium">
        <div className="z-10">
          <div className="inline-flex items-center px-2 py-0.5 rounded-full bg-primary/10 text-primary text-[10px] font-bold tracking-wider mb-2">
            System Administration
          </div>
          <h1 className="text-3xl font-bold text-foreground">
            {timePeriod ? `${timePeriod}, Admin` : 'Welcome, Admin'}
          </h1>
          <p className="text-muted-foreground mt-1">Complete control over your institutional ERP system</p>
        </div>
        <div className="flex gap-2">
          <Button 
            variant="outline" 
            size="sm"
            onClick={() => router.push('/admin/college-settings' as any)}
            className="gap-2"
          >
            <Settings className="w-4 h-4" />
            College Settings
          </Button>
        </div>
      </div>

      <AdminStatsCards stats={stats} onTabChange={setActiveTab} />

      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-4">
        <TabsList className="w-full justify-start overflow-x-auto overflow-y-hidden flex-nowrap tabs-list-scroll">
          <TabsTrigger value="courses"><BookOpen className="w-4 h-4 mr-2" />Courses</TabsTrigger>
          <TabsTrigger value="users"><Users className="w-4 h-4 mr-2" />Users</TabsTrigger>
          <TabsTrigger value="analytics"><BarChart3 className="w-4 h-4 mr-2" />Analytics</TabsTrigger>
        </TabsList>

        <TabsContent value="courses" className="space-y-4">
          <CoursesTable 
            courses={courses}
            searchQuery={courseSearchQuery}
            onSearchChange={setCourseSearchQuery}
            onAddCourse={() => { resetCourseForm(); setEditingCourse(null); setShowCourseDialog(true); }}
            onEditCourse={openEditCourseDialog}
            onDeleteCourse={handleDeleteCourse}
          />
        </TabsContent>

        <TabsContent value="users" className="space-y-4">
          <UsersTable 
            users={users}
            searchQuery={userSearchQuery}
            onSearchChange={setUserSearchQuery}
            onAddUser={() => { resetUserForm(); setEditingUser(null); setShowUserDialog(true); }}
            onEditUser={openEditUserDialog}
            onDeleteUser={handleDeleteUser}
          />
        </TabsContent>

        <TabsContent value="analytics" className="space-y-4">
          <AdminAnalyticsCharts
            totalStudents={stats.totalStudents}
            totalFaculty={stats.totalFaculty}
            adminCount={users.filter((u: any) => u.role === 'college_admin' || u.role === 'super_admin').length}
          />
        </TabsContent>
      </Tabs>

      <CourseDialog 
        open={showCourseDialog}
        onOpenChange={setShowCourseDialog}
        editingCourse={editingCourse}
        courseForm={courseForm}
        setCourseForm={setCourseForm}
        onSubmit={editingCourse ? handleUpdateCourse : handleCreateCourse}
        onCancel={() => { setShowCourseDialog(false); setEditingCourse(null); resetCourseForm(); }}
      />

      <UserDialog 
        open={showUserDialog}
        onOpenChange={setShowUserDialog}
        editingUser={editingUser}
        userForm={userForm}
        setUserForm={setUserForm}
        onSubmit={editingUser ? handleUpdateUser : handleCreateUser}
        onCancel={() => { setShowUserDialog(false); setEditingUser(null); resetUserForm(); }}
      />
    </div>
  );
}

'use client';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@pec/ui";


import { motion } from 'framer-motion';
import { Loader2 } from 'lucide-react';

import QRAttendanceGenerator from '@/features/attendance/QRAttendanceGenerator';
import FacultyScheduleManager from '@/features/timetable/FacultyScheduleManager';
import { useFacultyDashboard } from '@/hooks/useFacultyDashboard';

// Components
import { FacultyHeader } from './components/FacultyHeader';
import { FacultyStatsGrid } from './components/FacultyStatsGrid';
import { FacultyTodaySchedule } from './components/FacultyTodaySchedule';
import { FacultyCoursesGrid } from './components/FacultyCoursesGrid';
import { LowAttendanceAlert } from './components/LowAttendanceAlert';
import { FacultyQuickActions } from './components/FacultyQuickActions';
import { NoticeboardCard } from './components/NoticeboardCard';

const container = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: { staggerChildren: 0.1 }
  }
};

export interface FacultyDashboardProps {
  initialData?: any;
  user?: any;
}

export function FacultyDashboard({ initialData, user: serverUser }: FacultyDashboardProps = {}) {
  const {
    loading,
    courses,
    notices,
    courseCards,
    todaySchedule,
    stats,
    selectedCourse,
    setSelectedCourse,
    showQRModal,
    setShowQRModal,
    showScheduleManager,
    setShowScheduleManager,
    handleGenerateQR,
    router,
  } = useFacultyDashboard(initialData, serverUser);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <motion.div
      variants={container}
      initial="hidden"
      animate="show"
      className="space-y-6"
    >
      <FacultyHeader 
        courses={courses}
        selectedCourse={selectedCourse}
        onSelectCourse={setSelectedCourse}
        onShowScheduleManager={() => setShowScheduleManager(true)}
        onGenerateQR={handleGenerateQR}
      />

      <FacultyStatsGrid stats={stats} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          <FacultyTodaySchedule
              schedule={todaySchedule}
              onViewFull={() => router.push('/timetable')}
              onGenerateQR={handleGenerateQR}
            />
          <FacultyCoursesGrid courses={courseCards} onManage={() => router.push('/courses')} />
        </div>

        <div className="space-y-6">
          <LowAttendanceAlert
            lowAttendanceCount={stats.lowAttendanceCount}
            onViewStudents={() => router.push('/attendance')}
          />
          <FacultyQuickActions onAction={(path) => router.push(path as any)} />
          <NoticeboardCard 
            notices={notices} 
            onViewAll={() => router.push('/noticeboard')} 
          />
        </div>
      </div>

      {/* QR Attendance Modal */}
      <Dialog open={showQRModal} onOpenChange={setShowQRModal}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>QR Attendance</DialogTitle>
          </DialogHeader>
          {selectedCourse && (
            <QRAttendanceGenerator
              courseId={selectedCourse.id}
              courseName={`${selectedCourse.code} - ${selectedCourse.name}`}
              onClose={() => setShowQRModal(false)}
            />
          )}
        </DialogContent>
      </Dialog>

      {/* Schedule Manager Modal */}
      <Dialog open={showScheduleManager} onOpenChange={setShowScheduleManager}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Manage Schedule</DialogTitle>
          </DialogHeader>
          <FacultyScheduleManager
            courses={courses}
            onScheduleAdded={() => setShowScheduleManager(false)}
          />
        </DialogContent>
      </Dialog>
    </motion.div>
  );
}

export default FacultyDashboard;

'use client';

import { useEffect, useRef, useState } from 'react';
import { motion } from 'framer-motion';
import { ErrorState, LoadingGrid } from '@/components/common/AsyncState';
import { useStudentDashboard } from '@/hooks/useStudentDashboard';

// Components
import { StudentWelcomeHeader } from './components/StudentWelcomeHeader';
import { StudentStatsCards } from './components/StudentStatsCards';
import { EnrolledCoursesCard } from './components/EnrolledCoursesCard';
import { TodayScheduleCard } from './components/TodayScheduleCard';
import { AttendanceOverviewCard } from './components/AttendanceOverviewCard';
import { NoticeboardCard } from './components/NoticeboardCard';
import { FinanceSummaryCard } from './components/FinanceSummaryCard';
import { MarketplaceCard } from './components/MarketplaceCard';

const item = {
  hidden: { opacity: 0, y: 12 },
  show: { opacity: 1, y: 0 }
};

interface StudentDashboardProps {
  initialData?: any;
  user?: any;
}

export function StudentDashboard({ initialData, user: initialUser }: StudentDashboardProps) {
  const enrolledCardRef = useRef<HTMLDivElement | null>(null);
  const [scheduleCardHeight, setScheduleCardHeight] = useState<number | null>(null);
  const {
    loading,
    firstName,
    profileData,
    stats,
    todayClasses,
    todayEvents,
    scheduleDay,
    enrolledCoursesList,
    noticeboardItems,
    requiredAttendancePercentage,
    loadError,
    setLoading,
    fetchStudentStats,
    orgSlug,
  } = useStudentDashboard(initialData, initialUser);

  const getFullUrl = (path: string) => orgSlug ? `/${orgSlug}${path}` : path;

  useEffect(() => {
    const node = enrolledCardRef.current;
    if (!node) return;

    const updateHeight = () => {
      const nextHeight = node.offsetHeight;
      if (nextHeight > 0) setScheduleCardHeight(nextHeight);
    };

    updateHeight();

    if (typeof ResizeObserver === 'undefined') {
      window.addEventListener('resize', updateHeight);
      return () => window.removeEventListener('resize', updateHeight);
    }

    const observer = new ResizeObserver(updateHeight);
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  if (loading) {
    return (
       <div className="space-y-6 md:space-y-8">
          <div className="flex justify-between items-center">
             <div className="space-y-2">
                <div className="h-8 w-64 bg-muted animate-pulse rounded-md" />
                <div className="h-4 w-48 bg-muted animate-pulse rounded-md" />
             </div>
             <div className="h-10 w-32 bg-muted animate-pulse rounded-md" />
          </div>
          <LoadingGrid count={3} className="grid gap-4 md:grid-cols-2 xl:grid-cols-3" itemClassName="h-24 rounded-md" />
          <div className="grid gap-5 md:gap-6 xl:grid-cols-3">
             <div className="lg:col-span-2 h-64 bg-muted animate-pulse rounded-xl" />
             <div className="h-64 bg-muted animate-pulse rounded-xl" />
          </div>
       </div>
    );
  }

  if (loadError) {
    return (
      <ErrorState
        title="Dashboard unavailable"
        description={loadError}
        actionLabel="Try again"
        onAction={() => {
          setLoading(true);
          void fetchStudentStats().finally(() => setLoading(false));
        }}
      />
    );
  }

  return (
    <div className="space-y-6 md:space-y-8">
      <StudentWelcomeHeader 
        firstName={firstName} 
        profileData={profileData} 
      />

      <StudentStatsCards 
        stats={stats} 
        onStatClick={(type) => {
          if (type === 'attendance') window.location.href = getFullUrl('/attendance');
          if (type === 'courses') window.location.href = getFullUrl('/courses');
          if (type === 'scores') window.location.href = getFullUrl('/score-sheet');
        }}
      />

      <div className="grid items-start gap-5 md:gap-6 xl:grid-cols-3">
        <EnrolledCoursesCard 
          containerRef={enrolledCardRef}
          className="self-start"
          enrolledCoursesList={enrolledCoursesList} 
          onViewAll={() => window.location.href = getFullUrl('/courses')}
          onCourseClick={(id) => window.location.href = getFullUrl(`/courses/${id}`)}
        />

        <TodayScheduleCard 
          scheduleDay={scheduleDay} 
          todayClasses={todayClasses} 
          todayEvents={todayEvents}
          onViewFull={() => window.location.href = getFullUrl('/timetable')}
          containerHeight={scheduleCardHeight}
        />
      </div>

      <motion.div
        variants={item}
        initial="hidden"
        animate="show"
        className="grid gap-6 lg:grid-cols-3"
      >
        <AttendanceOverviewCard
          className="lg:col-span-1"
          attendancePercentage={stats.attendancePercentage}
          onClick={() => window.location.href = getFullUrl('/attendance')}
          targetPercentage={requiredAttendancePercentage}
        />
        <NoticeboardCard
          className="lg:col-span-2"
          notices={noticeboardItems}
          onViewAll={() => window.location.href = getFullUrl('/noticeboard')}
        />
      </motion.div>

      <motion.div
        variants={item}
        initial="hidden"
        animate="show"
        className="grid gap-6"
      >
        <div className="grid gap-6 lg:grid-cols-2">
          <FinanceSummaryCard
            onViewAll={() => window.location.href = getFullUrl('/finance')}
          />
          <MarketplaceCard 
            onViewAll={() => window.location.href = getFullUrl('/marketplace')}
            onCreateListing={() => window.location.href = getFullUrl('/marketplace/sell')}
          />
        </div>
      </motion.div>

    </div>
  );
}

