        <Button 
          variant="gradient" 
          size="sm"
          onClick={onGenerateQR}
          disabled={!selectedCourse}
          className="h-9 px-4 font-semibold tracking-tight shadow-lg shadow-primary/10"
        >
          <QrCode className="w-4 h-4 mr-2" />
          QR Attendance
        </Button>
      </div>
    </div>
  );
}

