}

'use client';
import { Button, Input, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@pec/ui";


import { useState, useTransition, useEffect, useOptimistic } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { departmentSchema, DepartmentInput } from '@pec/shared';
import { useRouter } from 'next/navigation';
import { motion } from 'framer-motion';
import {
 Building2, Users, GraduationCap,
 Plus, Edit, Trash2, Upload, Download, Loader2, Search
} from 'lucide-react';

import { toast } from 'sonner';
import BulkUpload from '@/components/BulkUpload';
import { useAction } from 'next-safe-action/hooks';
import {
 createDepartmentAction, 
 updateDepartmentAction, 
 deleteDepartmentAction,
} from './actions';

interface DepartmentsViewProps {
 initialDepartments: any[];
 isAdmin: boolean;
}

const emptyForm = { name: '', code: '', hod: '', description: '' };

export function DepartmentsView({ initialDepartments, isAdmin }: DepartmentsViewProps) {
 const router = useRouter();
 const [isPending, startTransition] = useTransition();

 const [departments, setDepartments] = useState<any[]>(initialDepartments);
 const [searchTerm, setSearchTerm] = useState('');
 const [showDialog, setShowDialog] = useState(false);
 const [showBulkUpload, setShowBulkUpload] = useState(false);
 const [editingDept, setEditingDept] = useState<any>(null);
 
 const {
  register,
  handleSubmit: formSubmit,
  reset,
  formState: { errors }
 } = useForm<DepartmentInput>({
  resolver: zodResolver(departmentSchema),
  defaultValues: emptyForm,
 });

 const { execute: executeCreate } = useAction(createDepartmentAction, {
  onSuccess: () => {
   toast.success('Department created successfully!');
   setShowDialog(false);
   reset();
   router.refresh();
  },
  onError: ({ error }) => {
    toast.error(error.serverError || 'Failed to create department.');
  }
 });

 const { execute: executeUpdate } = useAction(updateDepartmentAction, {
  onSuccess: () => {
   toast.success('Department updated!');
   setShowDialog(false);
   setEditingDept(null);
   reset();
   router.refresh();
  },
  onError: ({ error }) => {
    toast.error(error.serverError || 'Failed to update department.');
  }
 });

 const { execute: executeDelete, isPending: isDeleting } = useAction(deleteDepartmentAction, {
  onSuccess: () => {
   toast.success('Department deleted!');
   router.refresh();
  },
  onError: ({ error }) => {
    toast.error(error.serverError || 'Failed to delete department.');
  }
 });

 useEffect(() => {
  setDepartments(initialDepartments);
 }, [initialDepartments]);

 const [optimisticDepts, addOptimisticDept] = useOptimistic(
  departments,
  (state, { type, payload }: { type: 'create' | 'update' | 'delete', payload: any }) => {
   switch (type) {
    case 'create':
     return [...state, { ...payload, id: 'temp-' + Date.now(), status: 'active' }];
    case 'update':
     return state.map(d => d.id === payload.id ? { ...d, ...payload } : d);
    case 'delete':
     return state.filter(d => d.id !== payload.id);
    default:
     return state;
   }
  }
 );

 const resetForm = () => { reset(emptyForm); };

 const openEditDialog = (dept: any) => {
  setEditingDept(dept);
  reset({ name: dept.name, code: dept.code, hod: dept.hod || '', description: dept.description || '' });
  setShowDialog(true);
 };

 const onSubmit = (data: DepartmentInput) => {
  startTransition(() => {
   if (editingDept) {
    addOptimisticDept({ type: 'update', payload: { ...data, id: editingDept.id } });
    executeUpdate({ ...data, id: editingDept.id });
   } else {
    addOptimisticDept({ type: 'create', payload: data });
    executeCreate(data);
   }
  });
 };

 const handleDelete = (deptId: string) => {
  if (!confirm('Are you sure you want to delete this department?')) return;
  startTransition(() => {
   addOptimisticDept({ type: 'delete', payload: { id: deptId } });
   executeDelete({ id: deptId });
  });
 };

 const exportDepartments = async () => {
  const ExcelJS = await import('exceljs');
  const fileSaver = await import('file-saver');
  
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet('Departments');
  
  worksheet.columns = [
   { header: 'Name', key: 'name', width: 30 },
   { header: 'Code', key: 'code', width: 15 },
   { header: 'Head of Department', key: 'hod', width: 30 },
   { header: 'Description', key: 'description', width: 40 },
  ];
  
  departments.forEach(d => {
   worksheet.addRow({
    name: d.name, code: d.code, hod: d.hod || '', description: d.description || '',
   });
  });
  
  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  fileSaver.saveAs(blob, `departments_export_${new Date().toISOString().split('T')[0]}.xlsx`);
  toast.success('Exported!');
 };

 const handleBulkImport = async (data: any[]) => {
  let successCount = 0, failCount = 0;
  const errors: string[] = [];

  for (const row of data) {
   const result = await createDepartmentAction({
    name: row.name,
    code: row.code,
    hod: row.hod || '',
    description: row.description || '',
   });
   
   if (result?.validationErrors || result?.serverError) {
    failCount++;
    errors.push(`${row.name}: Error`);
   } else {
    successCount++;
   }
  }

  router.refresh();
  return { success: successCount, failed: failCount, errors };
 };

 const filtered = optimisticDepts.filter(d =>
  d.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
  d.code?.toLowerCase().includes(searchTerm.toLowerCase())
 );

 return (
  <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-10">
   <div className="flex items-center justify-between">
    <div>
     <h1 className="text-3xl font-bold tracking-tight">Departments</h1>
     <p className="text-muted-foreground mt-1 font-medium italic text-[11px]">Manage and track institutional academic departments</p>
    </div>
    <div className="flex gap-3">
     <Button variant="outline" onClick={exportDepartments} className="h-11 rounded-sm border-2 font-bold px-6">
      <Download className="w-4 h-4 mr-2" /> Export
     </Button>
     <Button variant="outline" onClick={() => setShowBulkUpload(true)} className="h-11 rounded-sm border-2 font-bold px-6">
      <Upload className="w-4 h-4 mr-2" /> Bulk Upload
     </Button>
     {isAdmin && (
      <Button onClick={() => { resetForm(); setEditingDept(null); setShowDialog(true); }} className="h-11 rounded-sm bg-primary text-white font-bold uppercase tracking-widest text-[10px] px-6">
       <Plus className="w-4 h-4 mr-2" /> Add Department
      </Button>
     )}
    </div>
   </div>

   <div className="grid gap-6 md:grid-cols-3">
    {[
     { icon: Building2, label: 'Departments', value: optimisticDepts.length, color: 'primary' },
     { icon: GraduationCap, label: 'Active', value: optimisticDepts.filter(d => d.status !== 'inactive').length, color: 'success' },
     { icon: Users, label: 'HODs Assigned', value: optimisticDepts.filter(d => d.hod).length, color: 'warning' },
    ].map(({ icon: Icon, label, value, color }) => (
     <div key={label} className="card-elevated p-6 border-b-4 border-r-4 border-primary/10">
      <div className="flex items-center gap-4">
       <div className={`p-3 rounded-sm bg-${color}/10 border border-${color}/20`}><Icon className={`w-6 h-6 text-${color}`} /></div>
       <div>
        <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground/60">{label}</p>
        <p className="text-4xl font-bold mt-1">{value}</p>
       </div>
      </div>
     </div>
    ))}
   </div>

   <div className="relative">
    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
    <Input placeholder="Search departments..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="h-14 pl-12 border-2 rounded-sm bg-background/50 font-bold" />
   </div>

   <div className="card-elevated overflow-hidden border-2 rounded-sm shadow-[12px_12px_0px_rgba(0,0,0,0.03)]">
    <div className="overflow-x-auto">
     <table className="w-full">
      <thead className="bg-muted/50 border-b-2 border-border">
       <tr>
        {['Code', 'Name', 'Head of Department', 'Actions'].map((h, i) => (
         <th key={h} className={`p-5 text-[10px] font-bold uppercase tracking-widest text-muted-foreground/60 ${i === 3 ? 'text-right' : 'text-left'}`}>{h}</th>
        ))}
       </tr>
      </thead>
      <tbody className="divide-y divide-border">
       {filtered.length === 0 ? (
        <tr><td colSpan={4} className="p-12 text-center text-muted-foreground font-medium italic">No departments found.</td></tr>
       ) : filtered.map(dept => (
        <tr key={dept.id} className="hover:bg-muted/30 cursor-pointer transition-all border-l-4 border-transparent hover:border-primary" onClick={() => router.push(`/departments/${dept.id}`)}>
         <td className="p-5 font-bold font-mono text-primary text-sm tracking-tight">{dept.code}</td>
         <td className="p-5 font-bold text-foreground text-base tracking-tight">{dept.name}</td>
         <td className="p-5 text-muted-foreground font-mono text-xs uppercase opacity-70">{dept.hodName || dept.hod || '---'}</td>
         <td className="p-5">
          <div className="flex items-center justify-end gap-3" onClick={e => e.stopPropagation()}>
           {isAdmin && (
            <>
             <Button variant="ghost" size="sm" onClick={() => openEditDialog(dept)} className="hover:bg-primary/10 hover:text-primary rounded-sm h-9 w-9 p-0">
              <Edit className="w-4 h-4" />
             </Button>
             <Button variant="ghost" size="sm" onClick={() => handleDelete(dept.id)} disabled={isDeleting} className="hover:bg-destructive/10 hover:text-destructive rounded-sm h-9 w-9 p-0">
              {isDeleting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
             </Button>
            </>
           )}
          </div>
         </td>
        </tr>
       ))}
      </tbody>
     </table>
    </div>
   </div>

   <Dialog open={showDialog} onOpenChange={setShowDialog}>
    <DialogContent className="max-w-xl rounded-sm border-2 border-primary shadow-[20px_20px_0px_rgba(0,0,0,0.05)]">
     <DialogHeader className="space-y-4">
      <DialogTitle className="text-3xl font-bold">{editingDept ? 'Edit Department' : 'Add New Department'}</DialogTitle>
      <DialogDescription className="font-bold text-[11px] uppercase tracking-widest text-muted-foreground bg-muted p-2 rounded-sm italic opacity-60">Institutional Department Details</DialogDescription>
     </DialogHeader>
     <div className="space-y-6 pt-4">
      <div className="grid grid-cols-2 gap-6">
       <div className="space-y-2">
        <label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Department Code *</label>
        <Input {...register('code')} placeholder="e.g. CS" className={`mt-1 h-12 border-2 rounded-sm font-bold font-mono ${errors.code ? 'border-destructive' : ''}`} />
        {errors.code && <p className="text-[10px] font-bold text-destructive uppercase">{errors.code.message}</p>}
       </div>
       <div className="space-y-2">
        <label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Department Name *</label>
        <Input {...register('name')} placeholder="e.g. Computer Science" className={`mt-1 h-12 border-2 rounded-sm font-bold ${errors.name ? 'border-destructive' : ''}`} />
        {errors.name && <p className="text-[10px] font-bold text-destructive uppercase">{errors.name.message}</p>}
       </div>
      </div>
      <div className="space-y-2">
       <label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Head of Department (HOD)</label>
       <Input {...register('hod')} placeholder="e.g. Dr. John Doe" className="mt-1 h-12 border-2 rounded-sm font-bold" />
      </div>
      <div className="space-y-2">
       <label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Description</label>
       <textarea {...register('description')} placeholder="Describe the department's focus..." className="mt-1 w-full min-h-[100px] p-4 rounded-sm border-2 border-border bg-background/50 font-medium focus:border-primary transition-all" />
      </div>
      <div className="flex gap-4 pt-6">
       <Button onClick={formSubmit(onSubmit)} className="flex-1 h-14 bg-primary text-white font-bold uppercase tracking-widest text-xs shadow-lg hover:brightness-110 active:scale-[0.98] transition-all">
        {isPending ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
        {editingDept ? 'Save Changes' : 'Create Department'}
       </Button>
       <Button variant="outline" onClick={() => { setShowDialog(false); setEditingDept(null); resetForm(); }} className="h-14 border-2 font-bold px-8 uppercase tracking-widest text-[10px] rounded-sm">Cancel</Button>
      </div>
     </div>
    </DialogContent>
   </Dialog>

   <Dialog open={showBulkUpload} onOpenChange={setShowBulkUpload}>
    <DialogContent className="max-w-4xl border-2 border-primary rounded-sm overflow-hidden p-0">
     <DialogHeader className="bg-primary text-white p-10">
      <DialogTitle className="text-3xl font-bold">Bulk Upload Departments</DialogTitle>
      <DialogDescription className="text-white/70 font-bold uppercase tracking-widest text-[11px] mt-2 italic">Standardized CSV/Excel data upload</DialogDescription>
     </DialogHeader>
     <div className="p-10">
      <BulkUpload entityType="departments" onImport={handleBulkImport} templateColumns={['name', 'code', 'hod', 'description']} sampleData={[{ name: 'Computer Science', code: 'CS', hod: 'Dr. John Smith', description: 'CSE Dept' }]} />
     </div>
    </DialogContent>
   </Dialog>
  </motion.div>
 );
}

'use client';
import { Button, Badge } from "@pec/ui";


import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import {
  ArrowLeft,
  Users,
  GraduationCap,
  BookOpen,
  Mail,
  Phone,
  Building2,
  Calendar,
  Search,
  Loader2,
  ChevronRight,
} from 'lucide-react';
import { AXIOS_INSTANCE } from "@pec/api";

import { toast } from 'sonner';

export default function DepartmentDetail() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [department, setDepartment] = useState<any>(null);
  const [faculty, setFaculty] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);

  const [timetable, setTimetable] = useState<any[]>([]);

  const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const TIME_SLOTS_DATA = [
    { id: '08:00-09:00', label: '08:00 AM' },
    { id: '09:00-10:00', label: '09:00 AM' },
    { id: '10:00-11:00', label: '10:00 AM' },
    { id: '11:00-12:00', label: '11:00 AM' },
    { id: '12:00-13:00', label: '12:00 PM' },
    { id: '13:00-14:00', label: '01:00 PM' }, // LUNCH
    { id: '14:00-15:00', label: '02:00 PM' },
    { id: '15:00-16:00', label: '03:00 PM' },
    { id: '16:00-17:00', label: '04:00 PM' },
  ];

  useEffect(() => {
    const fetchData = async () => {
      if (!id) return;
      try {
        setLoading(true);

        // Fetch department details via NestJS REST API
        const deptRes = await AXIOS_INSTANCE.get(`/api/v1/departments/${id}`);
        const deptData = deptRes.data?.data ?? deptRes.data;
        if (!deptData) {
          toast.error('Department not found');
          router.push('/departments');
          return;
        }
        setDepartment(deptData);

        const departmentName = encodeURIComponent(deptData.name);

        // Fetch faculty, students, courses, timetable in parallel
        const [facultyRes, studentsRes, coursesRes, timetableRes] = await Promise.all([
          AXIOS_INSTANCE.get(`/api/v1/users?role=faculty&department=${departmentName}&limit=200`),
          AXIOS_INSTANCE.get(`/api/v1/users?role=student&department=${departmentName}&limit=500`),
          AXIOS_INSTANCE.get(`/api/v1/courses?department=${departmentName}&limit=200`),
          AXIOS_INSTANCE.get(`/api/v1/timetable?department=${departmentName}&limit=500`),
        ]);

        const toArray = (res: any) =>
          Array.isArray(res.data) ? res.data
          : Array.isArray(res.data?.data) ? res.data.data
          : [];

        setFaculty(toArray(facultyRes));
        setStudents(toArray(studentsRes));
        setCourses(toArray(coursesRes));
        setTimetable(toArray(timetableRes));

      } catch (error) {
        console.error('Error fetching department details:', error);
        toast.error('Failed to load department statistics');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [id, router]);

  const getSlotsContent = (day: string, timeId: string) => {
    return timetable.filter(s => s.day === day && s.timeSlot === timeId);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!department) return null;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="space-y-6 pb-12"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link href="/departments">
            <Button variant="ghost" size="icon">
              <ArrowLeft className="w-5 h-5" />
            </Button>
          </Link>
          <div>
            <div className="flex items-center gap-2">
              <Badge variant="outline" className="font-mono">
                {department.code}
              </Badge>
              <h1 className="text-3xl font-bold text-foreground">{department.name}</h1>
            </div>
            <p className="text-muted-foreground mt-1 max-w-2xl">{department.description}</p>
          </div>
        </div>
      </div>

      {/* Stats Overview */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="card-elevated p-6 flex items-center gap-4 hover:scale-[1.02] transition-transform cursor-default">
          <div className="p-3 rounded-xl bg-primary/10">
            <GraduationCap className="w-8 h-8 text-primary" />
          </div>
          <div>
            <p className="text-3xl font-bold text-foreground">{students.length}</p>
            <p className="text-sm text-muted-foreground font-medium">Active Students</p>
          </div>
        </div>
        <div className="card-elevated p-6 flex items-center gap-4 hover:scale-[1.02] transition-transform cursor-default">
          <div className="p-3 rounded-xl bg-accent/10">
            <Users className="w-8 h-8 text-accent" />
          </div>
          <div>
            <p className="text-3xl font-bold text-foreground">{faculty.length}</p>
            <p className="text-sm text-muted-foreground font-medium">Faculty Members</p>
          </div>
        </div>
        <div className="card-elevated p-6 flex items-center gap-4 hover:scale-[1.02] transition-transform cursor-default">
          <div className="p-3 rounded-xl bg-success/10">
            <BookOpen className="w-8 h-8 text-success" />
          </div>
          <div>
            <p className="text-3xl font-bold text-foreground">{courses.length}</p>
            <p className="text-sm text-muted-foreground font-medium">Total Courses</p>
          </div>
        </div>
      </div>

      {/* Dynamic Timetable Section */}
      <div className="card-elevated p-6">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
            <Calendar className="w-5 h-5 text-primary" />
            Departmental Schedule
          </h2>
          <Link href="/timetable">
            <Button variant="outline" size="sm">Manage Full Timetable</Button>
          </Link>
        </div>
        
        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr>
                <th className="p-3 bg-muted/30 border border-border text-sm font-semibold text-muted-foreground w-32">Time / Day</th>
                {DAYS.map(day => (
                  <th key={day} className="p-3 bg-muted/30 border border-border text-sm font-semibold text-muted-foreground px-4 text-center">
                    {day}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {TIME_SLOTS_DATA.map(timeObj => (
                <tr key={timeObj.id}>
                  <td className="p-3 bg-muted/10 border border-border text-xs font-bold text-center text-primary">
                    {timeObj.label}
                  </td>
                  {DAYS.map(day => {
                    const isLunch = timeObj.id === '13:00-14:00';
                    const slots = getSlotsContent(day, timeObj.id);

                    if (isLunch) {
                      return (
                        <td key={`${day}-${timeObj.id}`} className="p-2 border border-border bg-muted/20 text-center align-middle">
                          {day === 'Wednesday' && (
                            <span className="text-[9px] font-bold tracking-widest uppercase text-muted-foreground/40 font-mono">Lunch Break</span>
                          )}
                        </td>
                      );
                    }

                    return (
                      <td key={`${day}-${timeObj.id}`} className="p-2 border border-border min-h-[100px] align-top">
                        <div className="space-y-1.5">
                          {slots.length > 0 ? (
                            slots.map((slot, idx) => (
                              <div 
                                key={idx}
                                className="p-2 rounded-lg bg-primary/5 border border-primary/10 hover:bg-primary/10 transition-colors cursor-pointer group shadow-sm"
                                onClick={() => router.push(`/courses/${slot.courseId}`)}
                              >
                                <div className="flex items-center justify-between gap-1">
                                  <p className="text-[10px] font-bold text-primary truncate group-hover:underline">
                                    {slot.courseCode}
                                  </p>
                                  <Badge variant="outline" className="px-1 py-0 text-[8px] h-3.5 font-mono border-primary/20 text-primary/60">
                                    S{slot.semester}
                                  </Badge>
                                </div>
                                <p className="text-[10px] font-medium text-foreground line-clamp-1 mt-0.5">
                                  {slot.courseName}
                                </p>
                                <div className="flex items-center justify-between mt-1 text-[9px] text-muted-foreground font-medium">
                                  <span className="truncate max-w-[60px]">{slot.facultyName}</span>
                                  <span className="font-mono text-primary/70">{slot.room}</span>
                                </div>
                              </div>
                            ))
                          ) : (
                            <div className="h-full min-h-[60px] flex items-center justify-center opacity-20">
                              <span className="text-[10px] text-muted-foreground font-medium tracking-tighter">---</span>
                            </div>
                          )}
                        </div>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Leadership Section */}
        <div className="card-elevated p-6">
          <h2 className="text-xl font-bold text-foreground mb-4 flex items-center gap-2">
            <Building2 className="w-5 h-5 text-accent" />
            Leadership
          </h2>
          <div className="p-5 border border-border rounded-2xl bg-gradient-to-br from-primary/5 to-transparent">
            <div className="flex items-center gap-5">
              <div className="w-20 h-20 rounded-2xl bg-primary/10 flex items-center justify-center border border-primary/20">
                <span className="text-2xl font-bold text-primary">
                  {department.hod?.split(' ').map((n: string) => n[0]).join('') || 'H'}
                </span>
              </div>
              <div>
                <p className="font-extrabold text-xl text-foreground tracking-tight">{department.hod || 'Acting HOD'}</p>
                <div className="flex items-center gap-2 mt-1">
                  <Badge variant="secondary" className="px-2 py-0">Head of Department</Badge>
                  <p className="text-xs text-muted-foreground font-medium">Joined 2021</p>
                </div>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3 mt-5">
               <Button variant="secondary" size="sm" className="w-full gap-2">
                 <Mail className="w-3.5 h-3.5" /> Contact
               </Button>
               <Button variant="outline" size="sm" className="w-full gap-2">
                 <Phone className="w-3.5 h-3.5" /> Schedule Call
               </Button>
            </div>
          </div>
        </div>

        {/* Courses List Section */}
        <div className="card-elevated p-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
              <BookOpen className="w-5 h-5 text-success" />
              Academic Courses
            </h2>
            <Link href="/courses">
              <Button variant="ghost" size="sm" className="text-xs font-bold text-primary">Browse All</Button>
            </Link>
          </div>
          <div className="space-y-3 max-h-[320px] overflow-y-auto pr-2 custom-scrollbar">
            {courses.length > 0 ? (
              courses.map((course) => (
                <div 
                  key={course.id} 
                  className="flex items-center justify-between p-4 rounded-xl border border-border/50 hover:border-primary/30 hover:bg-primary/5 cursor-pointer transition-all duration-300 group shadow-sm bg-card"
                  onClick={() => router.push(`/courses/${course.id}`)}
                >
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-lg bg-success/10 flex items-center justify-center font-bold text-success text-xs border border-success/20">
                      {course.code.slice(-3)}
                    </div>
                    <div>
                      <p className="font-bold text-sm text-foreground group-hover:text-primary transition-colors">{course.code}</p>
                      <p className="text-xs text-muted-foreground font-medium mt-0.5">{course.name}</p>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <Badge variant="outline" className="text-[10px] font-mono px-2">{course.credits} Cr</Badge>
                  </div>
                </div>
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-10 text-muted-foreground bg-muted/10 rounded-xl">
                 <Search className="w-8 h-8 opacity-20 mb-2" />
                 <p className="text-sm font-medium">No courses found</p>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Faculty Roster */}
        <div className="card-elevated p-6">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
              <Users className="w-5 h-5 text-accent" />
              Faculty Members
            </h2>
            <Link href="/faculty">
              <Button variant="ghost" size="sm" className="text-xs font-bold text-accent">Full Directory</Button>
            </Link>
          </div>
          <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
            {faculty.length > 0 ? (
              faculty.map((member) => (
                <div 
                  key={member.id} 
                  className="flex items-center gap-4 p-4 rounded-xl bg-card border border-border/50 hover:bg-accent/5 hover:border-accent/30 cursor-pointer transition-all shadow-sm"
                  onClick={() => router.push(`/users/${member.id}`)}
                >
                  <div className="w-12 h-12 rounded-full bg-accent/10 flex items-center justify-center border border-accent/20">
                    <span className="text-sm font-black text-accent">
                      {member.fullName?.split(' ').map((n: string) => n[0]).join('')}
                    </span>
                  </div>
                  <div className="flex-1">
                    <p className="font-bold text-base text-foreground transition-colors group-hover:text-accent">{member.fullName}</p>
                    <div className="flex items-center gap-2 mt-0.5">
                      <p className="text-xs text-muted-foreground font-medium">{member.designation || member.role}</p>
                      <span className="w-1 h-1 rounded-full bg-muted-foreground/30"></span>
                      <p className="text-[10px] text-muted-foreground uppercase tracking-wider">{member.employeeId || 'ID Pending'}</p>
                    </div>
                  </div>
                  <ChevronRight className="w-4 h-4 text-muted-foreground/30" />
                </div>
              ))
            ) : (
              <p className="text-center text-muted-foreground py-10 bg-muted/10 rounded-xl font-medium">No faculty specialized in this area</p>
            )}
          </div>
        </div>

        {/* Student Enrollment */}
        <div className="card-elevated p-6">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
              <GraduationCap className="w-5 h-5 text-primary" />
              Student Base
            </h2>
          </div>
          <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
            {students.length > 0 ? (
              students.map((student) => (
                <div 
                  key={student.id} 
                  className="flex items-center justify-between p-4 rounded-xl bg-card border border-border/50 hover:bg-primary/5 hover:border-primary/30 cursor-pointer transition-all shadow-sm"
                  onClick={() => router.push(`/users/${student.id}`)}
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-primary/10 flex items-center justify-center border border-primary/20">
                      <span className="text-sm font-black text-primary">
                        {student.fullName?.split(' ').map((n: string) => n[0]).join('')}
                      </span>
                    </div>
                    <div>
                      <p className="font-bold text-base text-foreground">{student.fullName}</p>
                      <p className="text-xs text-muted-foreground font-mono mt-0.5">{student.enrollmentNumber || student.email}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <Badge variant="secondary" className="px-2 py-0 text-[10px] uppercase font-black bg-primary/20 text-primary border-none">Sem {student.semester || 'N/A'}</Badge>
                    <p className="text-[9px] text-muted-foreground mt-1 font-bold">BATCH 2025</p>
                  </div>
                </div>
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-12 text-muted-foreground bg-muted/10 rounded-2xl">
                 <Search className="w-10 h-10 opacity-10 mb-3" />
                 <p className="text-sm font-bold">No active enrollments for this session</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </motion.div>
  );
}

'use client';

import { Button } from "@pec/ui";

import { useEffect } from 'react';
import { AlertCircle, RotateCcw } from 'lucide-react';

export default function ProtectedError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error('Segment Error:', error);
  }, [error]);

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-6 px-4">
      <div className="card-elevated p-8 max-w-md w-full border-t-4 border-t-destructive shadow-2xl animate-in zoom-in-95 duration-200">
        <div className="flex items-center gap-4 mb-4">
           <div className="h-10 w-10 bg-destructive/10 rounded-full flex items-center justify-center">
              <AlertCircle className="w-6 h-6 text-destructive" />
           </div>
           <h2 className="text-xl font-bold text-foreground">Something went wrong!</h2>
        </div>
        
        <div className="bg-muted/50 p-4 rounded-lg mb-6 text-sm font-mono border border-border/50 text-muted-foreground break-words overflow-auto max-h-32">
           {error.message || "An unexpected error occurred while loading this segment."}
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <Button 
            variant="default" 
            onClick={() => reset()} 
            className="flex-1 gap-2 shadow-lg shadow-primary/20"
          >
            <RotateCcw className="w-4 h-4" /> Try again
          </Button>
          <Button 
            variant="outline" 
            onClick={() => window.location.href = '/dashboard'}
            className="flex-1"
          >
            Go to Home
          </Button>
        </div>
      </div>
      <p className="text-xs text-muted-foreground opacity-50">Error UID: {error.digest || 'no-digest'}</p>
    </div>
  );
}

