export default function FacultyDetail() {
  const { id } = useParams<{ id: string }>();
  const [member, setMember] = useState<any | null>(null);
  const [courses, setCourses] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    const load = async () => {
      setLoading(true);
      try {
        const [facultyBioRes, coursesRes] = await Promise.all([
          api.get(`/faculty-bio/${id}`),
          api.get('/courses', { params: { facultyId: id, limit: 200, offset: 0 } }),
        ]);

        const bioData = facultyBioRes.data;
        setMember(bioData || null);
        setCourses(extractData<any[]>(coursesRes) || []);
      } catch (error) {
        console.error('Error loading faculty profile:', error);
        setMember(null);
        setCourses([]);
      } finally {
        setLoading(false);
      }
    };

    void load();
  }, [id]);

  const initials = useMemo(() => {
    const name = member?.fullName || member?.name || '';
    return name
      .split(' ')
      .slice(1)
      .map((n: string) => n[0])
      .join('');
  }, [member]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[320px]">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!member) {
    return (
      <EmptyState
        title="Faculty not found"
        description="We couldn't locate this faculty profile."
      />
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
