                <p className="text-sm text-muted-foreground">Courses</p>
              </div>
            </div>
          </div>
        </div>

        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6">
          {/* Bio */}
          <div className="card-elevated p-6">
            <h3 className="text-lg font-semibold text-foreground mb-3">About</h3>
