}

'use client';
import { Button, Input, Tabs, TabsContent, TabsList, TabsTrigger, Badge, SearchResultsSkeleton } from "@pec/ui";


import { motion } from 'framer-motion';
import { 
  Users as UsersIcon, 
  Search as SearchIcon,
  LayoutDashboard,
  BookOpen
} from 'lucide-react';

import { useSearchPage } from '@/hooks/useSearchPage';

// Components
import { 
