                </TabsTrigger>
              </TabsList>

              <TabsContent value="all" className="space-y-8">
                {/* Pages Section */}
                {results.pages.length > 0 && (
                  <section>
                    <h2 className="flex items-center gap-2 text-lg font-semibold mb-4">
                      <LayoutDashboard className="w-5 h-5" /> Pages
