                )}

                {/* Users Section */}
                {results.users.length > 0 && (
                  <section>
                    <h2 className="flex items-center gap-2 text-lg font-semibold mb-4">
                      <UsersIcon className="w-5 h-5" /> People
                    </h2>
                    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                      {results.users.slice(0, 6).map(user => (
                        <UserCard key={user.id} user={user} />
                      ))}
                    </div>
                  </section>
                )}
              </TabsContent>

              <TabsContent value="people">
                <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                  {results.users.map(user => (
                    <UserCard key={user.id} user={user} />
                  ))}
                </div>
              </TabsContent>

              <TabsContent value="pages">
                <div className="grid gap-4 md:grid-cols-3">
                  {results.pages.map(page => (
                     <PageCard key={page.path} page={page} />
                  ))}
                </div>
              </TabsContent>
              <TabsContent value="subjects">
                <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
                  {results.subjects.map(sub => (
                     <SubjectCard key={sub.id} subject={sub} />
                  ))}
                </div>
              </TabsContent>
            </Tabs>
          )}
        </motion.div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Button } from '@pec/ui';
import { Lock, Smartphone, Monitor, Globe, LogOut, Loader2 } from 'lucide-react';
import { authClient, buildApiUrl } from '@pec/api';
import { toast } from 'sonner';

interface Session {
  id: string;
  ipAddress: string | null;
  userAgent: string | null;
  createdAt: string;
  expiresAt: string;
  isCurrent?: boolean;
}

export function SecuritySettings() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchSessions = async () => {
    try {
      const token = authClient.getAccessToken();
      const res = await fetch(buildApiUrl('/auth/sessions'), {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) throw new Error('Failed to fetch sessions');
      const data = await res.json();
      setSessions(data.sessions || []);
    } catch (err) {
      toast.error('Could not load active sessions.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSessions();
  }, []);

  const handleRevoke = async (id: string) => {
    try {
      const token = authClient.getAccessToken();
      const res = await fetch(buildApiUrl(`/auth/sessions/${id}`), {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) throw new Error('Failed to revoke session');
      toast.success('Session revoked successfully.');
      setSessions((prev) => prev.filter((s) => s.id !== id));
    } catch (err) {
      toast.error('Failed to revoke session.');
    }
  };

  const getDeviceIcon = (ua: string | null) => {
    if (!ua) return <Globe className="w-5 h-5 text-muted-foreground" />;
    if (ua.toLowerCase().includes('mobile') || ua.toLowerCase().includes('android') || ua.toLowerCase().includes('iphone')) {
      return <Smartphone className="w-5 h-5 text-muted-foreground" />;
    }
    return <Monitor className="w-5 h-5 text-muted-foreground" />;
  };

  const getDeviceName = (ua: string | null) => {
    if (!ua) return 'Unknown Device';
    if (ua.includes('Windows')) return 'Windows PC';
    if (ua.includes('Mac OS')) return 'Mac';
    if (ua.includes('Linux')) return 'Linux PC';
    if (ua.includes('iPhone')) return 'iPhone';
    if (ua.includes('Android')) return 'Android Device';
    return 'Unknown Device';
  };

  return (
    <div className="card-elevated p-8 bg-card/60 backdrop-blur-sm space-y-8 animate-in fade-in duration-500">
      <div className="flex items-center gap-3 pb-4 border-b border-border/40">
        <Lock className="w-5 h-5 text-primary" />
        <h2 className="text-xl font-bold tracking-tight">Security & Device Management</h2>
      </div>

      <div className="space-y-6">
        <div>
          <h3 className="text-[11px] font-bold uppercase tracking-widest text-muted-foreground opacity-60 mb-1">Active Sessions</h3>
          <p className="text-[10px] text-muted-foreground italic font-medium mb-4">Manage the devices that are currently logged into your account</p>
        </div>

        {loading ? (
          <div className="flex justify-center p-8">
            <Loader2 className="w-6 h-6 animate-spin text-primary" />
          </div>
        ) : sessions.length === 0 ? (
          <div className="text-center p-8 text-sm text-muted-foreground italic bg-background/40 rounded-xl border border-border/20">
            No active sessions found.
          </div>
        ) : (
          <div className="space-y-3">
            {sessions.map((session, i) => (
              <div key={session.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-5 rounded-2xl border border-border/40 bg-background/40 hover:border-primary/20 transition-all gap-4">
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-muted/30 rounded-xl">
                    {getDeviceIcon(session.userAgent)}
                  </div>
                  <div>
                    <h4 className="font-bold text-sm text-foreground flex items-center gap-2">
                      {getDeviceName(session.userAgent)}
                      {i === 0 && (
                         <span className="text-[9px] uppercase tracking-wider font-bold bg-primary/10 text-primary px-2 py-0.5 rounded-full">Current Device</span>
                      )}
                    </h4>
                    <p className="text-xs text-muted-foreground mt-1">
                      {session.ipAddress || 'Unknown IP'} • Started {new Date(session.createdAt).toLocaleDateString()}
                    </p>
                  </div>
                </div>
                {i !== 0 && (
                  <Button 
                    variant="outline" 
                    size="sm" 
                    onClick={() => handleRevoke(session.id)}
                    className="shrink-0 h-9 rounded-lg border-destructive/20 text-destructive hover:bg-destructive/5 font-bold text-xs"
                  >
                    <LogOut className="w-3.5 h-3.5 mr-2" /> Revoke
                  </Button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { Button, Input, Textarea, Card, CardContent, CardDescription, CardHeader, CardTitle } from "@pec/ui";
import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  ArrowLeft,
  Save,
  Building2,
  Mail,
  Phone,
  MapPin,
  Globe,
  Upload,
  Loader2,
  Cloud,
  Wand2,
} from 'lucide-react';

import { toast } from 'sonner';
import { usePermissions } from '@/hooks/usePermissions';
import { useRouter } from 'next/navigation';
import { uploadToCloudinary } from '@/lib/cloudinaryManager';
import { processLogoImage } from '@/lib/logoProcessor';
import { AXIOS_INSTANCE } from "@pec/api";
import type { CollegeSettings as CollegeSettingsType } from '@pec/shared';

type CollegeSettings = CollegeSettingsType;

export default function CollegeSettings() {
  const embedded = false;
  const router = useRouter();
  const { user, isAdmin, loading: authLoading } = usePermissions();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<CollegeSettings | null>(null);

  // Form fields
  const [collegeName, setCollegeName] = useState('');
  const [collegeShortName, setCollegeShortName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [website, setWebsite] = useState('');
  const [tagline, setTagline] = useState('');
  const [logoUrl, setLogoUrl] = useState('');
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState('');
  const [removingBackground, setRemovingBackground] = useState(false);
  const [removeBackground, setRemoveBackground] = useState(false);
  const [attendanceRequiredPercentage, setAttendanceRequiredPercentage] = useState(75);
  
  // Logo display mode
  const [logoDisplayMode, setLogoDisplayMode] = useState<'logo-only' | 'text-only' | 'both'>('both');
  
  // Cloudinary settings (optional - college's own account)
  const [cloudinaryCloudName, setCloudinaryCloudName] = useState('');
  const [cloudinaryPreset, setCloudinaryPreset] = useState('');

  useEffect(() => {
    if (authLoading) return;
    if (!user || !isAdmin) {
      router.push('/dashboard');
      return;
    }

    fetchSettings();
  }, [authLoading, user, isAdmin, router]);

  useEffect(() => {
    if (settings) {
      setCollegeName(settings.collegeName);
      setEmail(settings.email);
      setPhone(settings.phone);
      setAddress(settings.address);
      setWebsite(settings.website);
      setTagline(settings.tagline);
      setLogoUrl(settings.logoUrl);
      setCloudinaryCloudName(settings.cloudinaryCloudName || '');
      setCloudinaryPreset(settings.cloudinaryPreset || '');
      setPreviewUrl(settings.logoUrl);
    }
  }, [settings]);

  const fetchSettings = async () => {
    try {
      setLoading(true);
      const { data: settingsRes } = await AXIOS_INSTANCE.get('/api/v1/college-settings/main');
      const settingsSnap = { exists: () => !!settingsRes?.data || !!settingsRes, data: () => settingsRes?.data || settingsRes };

      if (settingsSnap.exists()) {
        const data = settingsSnap.data() as CollegeSettings;
        setSettings(data);
        setCollegeName(data.collegeName || '');
        setCollegeShortName(data.collegeShortName || '');
        setEmail(data.email || '');
        setPhone(data.phone || '');
        setAddress(data.address || '');
        setWebsite(data.website || '');
        setTagline(data.tagline || '');
        setLogoUrl(data.logoUrl || '');
        setLogoDisplayMode(data.logoDisplayMode || 'both');
        setCloudinaryCloudName(data.cloudinaryCloudName || '');
        setCloudinaryPreset(data.cloudinaryPreset || '');
        setAttendanceRequiredPercentage(
          typeof data.attendanceRequiredPercentage === 'number' ? data.attendanceRequiredPercentage : 75
        );
    } else {
      setSettings(null);
      setAttendanceRequiredPercentage(75);
    }
  } catch (error) {
      console.error('Error fetching college settings:', error);
      toast.error('Failed to load college settings');
    } finally {
      setLoading(false);
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processFile(file);
    }
  };

  const processFile = (file: File) => {
    if (!file.type.startsWith('image/')) {
      toast.error('Please upload an image file');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error('Image size must be less than 5MB');
      return;
    }
    setLogoFile(file);
    setRemoveBackground(false);
    const reader = new FileReader();
    reader.onloadend = () => {
      setPreviewUrl(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDragEnter = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      processFile(files[0]);
    }
  };

  const handleRemoveBackground = async () => {
    if (!logoFile) {
      toast.error('Please upload a logo first');
      return;
    }

    try {
      setRemovingBackground(true);
      toast.loading('Removing background...');
      
      const processedFile = await processLogoImage(logoFile, true);
      setLogoFile(processedFile);
      
      // Show preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
        setRemoveBackground(true);
        toast.dismiss();
        toast.success('Background removed! Logo is ready to upload.');
      };
      reader.readAsDataURL(processedFile);
    } catch (error) {
      toast.dismiss();
      console.error('Background removal error:', error);
      toast.error(
        error instanceof Error
          ? error.message
          : 'Failed to remove background. Make sure Remove.bg API key is configured.'
      );
    } finally {
      setRemovingBackground(false);
    }
  };

  const handleSave = async () => {
    if (!collegeName.trim()) {
      toast.error('Please enter college name');
      return;
    }

    try {
      setSaving(true);
      let finalLogoUrl = logoUrl;

      // If new logo file is selected, upload to Cloudinary
      if (logoFile) {
        try {
          toast.loading('Uploading logo to Cloudinary...');
          finalLogoUrl = await uploadToCloudinary(logoFile);
          toast.dismiss();
          toast.success('Logo uploaded successfully!');
        } catch (error) {
          toast.dismiss();
          console.error('Cloudinary upload error:', error);
          toast.error(
            error instanceof Error
              ? error.message
              : 'Failed to upload to Cloudinary. Make sure your environment variables are set.'
          );
          setSaving(false);
          return;
        }
      }

      await saveSettings(finalLogoUrl);
    } catch (error) {
      console.error('Error saving college settings:', error);
      toast.error('Failed to save college settings');
      setSaving(false);
    }
  };

  const saveSettings = async (logoUrl: string) => {
    try {
      const newSettings: CollegeSettings = {
        collegeName: (collegeName || '').trim(),
        collegeShortName: (collegeShortName || '').trim(),
        email: (email || '').trim(),
        phone: (phone || '').trim(),
        address: (address || '').trim(),
        website: (website || '').trim(),
        tagline: (tagline || '').trim(),
        logoUrl: logoUrl,
        logoDisplayMode: logoDisplayMode,
        cloudinaryCloudName: (cloudinaryCloudName || '').trim(),
        cloudinaryPreset: (cloudinaryPreset || '').trim(),
        attendanceRequiredPercentage: Math.max(0, Math.min(100, Math.round(attendanceRequiredPercentage || 75))),
        lastUpdated: new Date().toISOString(),
        updatedBy: user?.email || 'unknown',
      };

      await AXIOS_INSTANCE.put('/api/v1/college-settings/main', newSettings);

      setSettings(newSettings);
      setLogoFile(null);
      toast.success('College settings updated successfully!');
    } catch (error) {
      console.error('Error saving settings:', error);
      toast.error('Failed to save college settings');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="space-y-6"
    >
      {/* Back Button */}
      {!embedded && (
        <Button variant="ghost" onClick={() => router.push('/dashboard')} className="gap-2">
          <ArrowLeft className="w-4 h-4" />
          Back to Dashboard
        </Button>
      )}

      {/* Header */}
      {!embedded && (
        <div>
          <h1 className="text-3xl font-bold text-foreground">College Settings</h1>
          <p className="text-muted-foreground mt-2">
            Configure your college branding and information
          </p>
        </div>
      )}

      {/* Logo Section */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Building2 className="w-5 h-5" />
            College Logo
          </CardTitle>
          <CardDescription>
            Upload your college logo (max 5MB, recommended 200x200px)
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Upload Area */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-3">
                Logo Image
              </label>
              <div 
                onDragOver={handleDragOver}
                onDragEnter={handleDragEnter}
                onDrop={handleDrop}
                className="border-2 border-dashed border-primary/30 rounded-lg p-8 text-center cursor-pointer hover:bg-secondary/50 hover:border-primary/60 transition-all"
              >
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleLogoChange}
                  className="hidden"
                  id="logo-upload"
                />
                <label htmlFor="logo-upload" className="cursor-pointer block">
                  <Upload className="w-8 h-8 mx-auto mb-2 text-muted-foreground" />
                  <p className="text-sm font-medium text-foreground">Drag & drop or click to upload</p>
                  <p className="text-xs text-muted-foreground mt-1">PNG, JPG, GIF up to 5MB</p>
                </label>
              </div>
            </div>

            {/* Preview */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-3">
                Preview
              </label>
              <div className="border rounded-lg p-4 bg-secondary/50 flex items-center justify-center h-48">
                {previewUrl ? (
                  <div className="relative">
                    <img
                      src={previewUrl}
                      alt="Logo preview"
                      className="max-h-40 max-w-40 object-contain"
                    />
                  </div>
                ) : (
                  <p className="text-muted-foreground">No logo uploaded</p>
                )}
              </div>
              {logoFile && (
                <div className="mt-3 space-y-2">
                  <Button
                    onClick={handleRemoveBackground}
                    disabled={removingBackground || removeBackground}
                    variant="outline"
                    size="sm"
                    className="w-full gap-2"
                  >
                    {removingBackground && <Loader2 className="w-4 h-4 animate-spin" />}
                    {removeBackground ? '✓ Background Removed' : <><Wand2 className="w-4 h-4" /> Remove Background</>}
                  </Button>
                  <p className="text-xs text-muted-foreground">
                    {removeBackground ? '✓ Ready to upload' : 'Optional: Remove plain background before upload'}
                  </p>
                </div>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Logo Display Mode */}
      <Card>
        <CardHeader>
          <CardTitle>Logo Display Options</CardTitle>
          <CardDescription>Choose how to display the college branding in the interface</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* Logo Only Option */}
            <label className={`flex items-center p-4 border-2 rounded-lg cursor-pointer transition-all ${
              logoDisplayMode === 'logo-only' 
                ? 'border-primary bg-primary/5' 
                : 'border-border hover:border-primary/50'
            }`}>
              <input
                type="radio"
                name="logoDisplayMode"
                value="logo-only"
                checked={logoDisplayMode === 'logo-only'}
                onChange={(e) => setLogoDisplayMode(e.target.value as 'logo-only' | 'text-only' | 'both')}
                className="mr-3"
              />
              <div>
                <p className="font-medium text-foreground">Logo Only</p>
                <p className="text-xs text-muted-foreground">Show college logo without text</p>
                {logoUrl && (
                  <img src={logoUrl} alt="Preview" className="w-12 h-12 mt-2 object-contain" />
                )}
              </div>
            </label>

            {/* Text Only Option */}
            <label className={`flex items-center p-4 border-2 rounded-lg cursor-pointer transition-all ${
              logoDisplayMode === 'text-only' 
                ? 'border-primary bg-primary/5' 
                : 'border-border hover:border-primary/50'
            }`}>
              <input
                type="radio"
                name="logoDisplayMode"
                value="text-only"
                checked={logoDisplayMode === 'text-only'}
                onChange={(e) => setLogoDisplayMode(e.target.value as 'logo-only' | 'text-only' | 'both')}
                className="mr-3"
              />
              <div>
                <p className="font-medium text-foreground">Text Only</p>
                <p className="text-xs text-muted-foreground">Show college short name only</p>
                <p className="text-sm font-semibold mt-2">{collegeShortName || 'College'}</p>
              </div>
            </label>

            {/* Both Option */}
            <label className={`flex items-center p-4 border-2 rounded-lg cursor-pointer transition-all ${
              logoDisplayMode === 'both' 
                ? 'border-primary bg-primary/5' 
                : 'border-border hover:border-primary/50'
            }`}>
              <input
                type="radio"
                name="logoDisplayMode"
                value="both"
                checked={logoDisplayMode === 'both'}
                onChange={(e) => setLogoDisplayMode(e.target.value as 'logo-only' | 'text-only' | 'both')}
                className="mr-3"
              />
              <div>
                <p className="font-medium text-foreground">Logo + Text</p>
                <p className="text-xs text-muted-foreground">Show both logo and text</p>
                <div className="flex items-center gap-2 mt-2">
                  {logoUrl && (
                    <img src={logoUrl} alt="Preview" className="w-6 h-6 object-contain" />
                  )}
                  <p className="text-sm font-semibold">{collegeShortName || 'College'}</p>
                </div>
              </div>
            </label>
          </div>
        </CardContent>
      </Card>

      {/* Basic Information */}
      <Card>
        <CardHeader>
          <CardTitle>Basic Information</CardTitle>
          <CardDescription>College name and contact details</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              College Name *
            </label>
            <Input
              placeholder="Your College Name"
              value={collegeName}
              onChange={(e) => setCollegeName(e.target.value)}
            />
          </div>

          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              College Short Name (Optional)
            </label>
            <Input
              placeholder="e.g., IITD, DU, etc. (used in headers/badges)"
              value={collegeShortName}
              onChange={(e) => setCollegeShortName(e.target.value)}
            />
            <p className="text-xs text-muted-foreground mt-1">
              Displayed in places where space is limited (2-6 characters recommended)
            </p>
          </div>

          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              Tagline / Motto
            </label>
            <Input
              placeholder="Excellence in Education"
              value={tagline}
              onChange={(e) => setTagline(e.target.value)}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-medium text-foreground block mb-2">
                <Mail className="w-4 h-4 inline mr-1" />
                Email
              </label>
              <Input
                type="email"
                placeholder="admin@college.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>

            <div>
              <label className="text-sm font-medium text-foreground block mb-2">
                <Phone className="w-4 h-4 inline mr-1" />
                Phone
              </label>
              <Input
                placeholder="+91-XXXXXXXXXX"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
              />
            </div>
          </div>

          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              <MapPin className="w-4 h-4 inline mr-1" />
              Address
            </label>
            <Textarea
              placeholder="Street, City, State, Pin Code"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              rows={3}
            />
          </div>

          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              <Globe className="w-4 h-4 inline mr-1" />
              Website
            </label>
            <Input
              placeholder="https://college.edu"
              value={website}
              onChange={(e) => setWebsite(e.target.value)}
            />
            <p className="text-xs text-muted-foreground mt-1">
              Logo and college name will redirect to this link (if provided)
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Attendance Policy */}
      <Card>
        <CardHeader>
          <CardTitle>Attendance Policy</CardTitle>
          <CardDescription>Set the minimum required attendance percentage for students</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <label className="text-sm font-medium text-foreground block mb-2">
              Required Attendance Percentage
            </label>
            <Input
              type="number"
              min={0}
              max={100}
              value={attendanceRequiredPercentage}
              onChange={(e) => setAttendanceRequiredPercentage(Number(e.target.value))}
            />
            <p className="text-xs text-muted-foreground mt-1">
              Default is 75%. This affects student dashboards and alerts.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Branding Colors */}
      {/* Info Box */}
      <Card className="border-blue-200 dark:border-blue-800 bg-blue-50 dark:bg-blue-950/20">
        <CardContent className="pt-6">
          <p className="text-sm text-blue-900 dark:text-blue-200">
            ℹ️ <strong>Note:</strong> These settings will be displayed across the PEC platform including invoices, 
            certificates, and public-facing pages. Keep your information up-to-date.
          </p>
        </CardContent>
      </Card>

      {/* Cloudinary Settings (Optional) */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Cloud className="w-5 h-5" />
            Cloudinary Settings (Optional)
          </CardTitle>
          <CardDescription>Use your own Cloudinary account to store college logo privately</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <p className="text-sm text-muted-foreground">
            Leave blank to use default PEC cloud storage. Or enter your own Cloudinary credentials to keep logos on your account.
          </p>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-medium text-foreground block mb-2">
                Cloud Name
              </label>
              <Input
                placeholder="e.g., dxtvdf6x"
                value={cloudinaryCloudName}
                onChange={(e) => setCloudinaryCloudName(e.target.value)}
              />
              <p className="text-xs text-muted-foreground mt-1">Get from Cloudinary Dashboard</p>
            </div>

            <div>
              <label className="text-sm font-medium text-foreground block mb-2">
                Upload Preset
              </label>
              <Input
                placeholder="e.g., unsigned_preset"
                value={cloudinaryPreset}
                onChange={(e) => setCloudinaryPreset(e.target.value)}
              />
              <p className="text-xs text-muted-foreground mt-1">Unsigned preset from Cloudinary</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex gap-3">
        <Button
          size="lg"
          onClick={handleSave}
          disabled={saving}
          className="gap-2"
        >
          {saving ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save className="w-4 h-4" />
              Save Settings
            </>
          )}
        </Button>
        {!embedded && (
          <Button
            variant="outline"
            size="lg"
            onClick={() => router.push('/dashboard')}
          >
            Cancel
          </Button>
        )}
      </div>
    </motion.div>
  );
}

import { Button, Input, Badge, Card, CardContent, CardDescription, CardHeader, CardTitle, RadioGroup, RadioGroupItem } from "@pec/ui";
import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  ArrowLeft,
  Save,
  AlertCircle,
  CheckCircle2,
  Copy,
  Eye,
  EyeOff,
  Loader2,
} from 'lucide-react';

import { toast } from 'sonner';
import { usePermissions } from '@/hooks/usePermissions';
import { useRouter } from 'next/navigation';
import { cn } from '@/lib/utils';
import api from "@pec/api";

import { PaymentMethod, PaymentConfig } from './types';

const extractData = <T,>(payload: any): T => {
  if (payload && typeof payload === 'object' && 'success' in payload && 'data' in payload) {
    return payload.data as T;
  }
  return payload as T;
};

export default function PaymentSettings() {
  const embedded = false;
  const router = useRouter();
  const { user, isAdmin, loading: authLoading } = usePermissions();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<PaymentConfig | null>(null);
  const [method, setMethod] = useState<PaymentMethod>('upi');
  const [showApiSecret, setShowApiSecret] = useState(false);

  // UPI fields
  const [upiId, setUpiId] = useState('');
  const [upiName, setUpiName] = useState('');

  // Bank fields
  const [bankName, setBankName] = useState('');
  const [accountName, setAccountName] = useState('');
  const [accountNumber, setAccountNumber] = useState('');
  const [ifscCode, setIfscCode] = useState('');
  const [branch, setBranch] = useState('');

  // Razorpay fields
  const [apiKey, setApiKey] = useState('');
  const [apiSecret, setApiSecret] = useState('');

  useEffect(() => {
    if (authLoading) return;
    if (!user || !isAdmin) {
      router.replace('/auth');
      return;
    }

    fetchPaymentSettings();
  }, [authLoading, user, isAdmin, router]);

  useEffect(() => {
    if (settings) {
      setMethod(settings.method);
      if (settings.method === 'razorpay' && settings.razorpay) {
        setApiKey(settings.razorpay.apiKey);
        setApiSecret(settings.razorpay.apiSecret);
      } else if (settings.method === 'upi' && settings.upi) {
        setUpiId(settings.upi.upiId);
        setUpiName(settings.upi.upiName);
      } else if (settings.method === 'bank' && settings.bank) {
        setBankName(settings.bank.bankName);
        setAccountName(settings.bank.accountName);
        setAccountNumber(settings.bank.accountNumber);
        setIfscCode(settings.bank.ifscCode);
        setBranch(settings.bank.branch);
      }
    }
  }, [settings]);

  const fetchPaymentSettings = async () => {
    try {
      setLoading(true);
      const response = await api.get('/feature-flags/payment-config');
      const flag = extractData<any>(response.data);
      const payload = flag?.payload ? JSON.parse(flag.payload) : null;
      if (payload) {
        setSettings(payload as PaymentConfig);
      } else {
        setSettings(null);
        setMethod('upi');
      }
    } catch (error) {
      console.error('Error fetching payment settings:', error);
      toast.error('Failed to load payment settings');
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (method === 'upi') {
      if (!(upiId || '').trim() || !(upiName || '').trim()) {
        toast.error('Please fill in UPI ID and Name');
        return;
      }
      if (!upiId.includes('@')) {
        toast.error('Invalid UPI ID format (should be like 9876543210@ybl)');
        return;
      }
    } else if (method === 'bank') {
      if (
        !(bankName || '').trim() ||
        !(accountName || '').trim() ||
        !(accountNumber || '').trim() ||
        !(ifscCode || '').trim()
      ) {
        toast.error('Please fill in all bank details');
        return;
      }
    } else if (method === 'razorpay') {
      if (!(apiKey || '').trim() || !(apiSecret || '').trim()) {
        toast.error('Please fill in API Key and Secret');
        return;
      }
    }

    try {
      setSaving(true);
      const newConfig: PaymentConfig = {
        method,
        isActive: true,
        lastUpdated: new Date().toISOString(),
        updatedBy: user?.email || 'unknown',
      };

      if (method === 'upi') {
        newConfig.upi = {
          upiId: (upiId || '').trim(),
          upiName: (upiName || '').trim(),
        };
      } else if (method === 'bank') {
        newConfig.bank = {
          bankName: (bankName || '').trim(),
          accountName: (accountName || '').trim(),
          accountNumber: (accountNumber || '').trim(),
          ifscCode: (ifscCode || '').trim(),
          branch: (branch || '').trim(),
        };
      } else if (method === 'razorpay') {
        newConfig.razorpay = {
          apiKey: (apiKey || '').trim(),
          apiSecret: (apiSecret || '').trim(),
        };
      }

      await api.post('/feature-flags/payment-config', {
        enabled: true,
        description: 'Campus payment gateway configuration',
        payload: JSON.stringify(newConfig),
      });

      setSettings(newConfig);
      toast.success(`Payment method updated to ${method.toUpperCase()}`);
    } catch (error) {
      console.error('Error saving payment settings:', error);
      toast.error('Failed to save payment settings');
    } finally {
      setSaving(false);
    }
  };

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    toast.success(`${label} copied!`);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="space-y-6"
    >
      {/* Back Button */}
      {!embedded && (
        <Button variant="ghost" onClick={() => router.push('/finance' as any)} className="gap-2">
          <ArrowLeft className="w-4 h-4" />
          Back to Finance
        </Button>
      )}

      {/* Header */}
      {!embedded && (
        <div>
          <h1 className="text-3xl font-bold text-foreground">Payment Settings</h1>
          <p className="text-muted-foreground mt-2">Configure how students will pay fees</p>
        </div>
      )}

      {/* Current Status */}
      {settings && (
        <Card className="border-success/30 bg-success/5">
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <CheckCircle2 className="w-5 h-5 text-success" />
              <div>
                <p className="font-medium text-foreground capitalize">
                  Current: {settings.method} Payment
                </p>
                <p className="text-sm text-muted-foreground">
                  Last updated:{' '}
                  {settings.lastUpdated
                    ? new Date(settings.lastUpdated).toLocaleDateString()
                    : 'Never'}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Payment Method Selection */}
      <Card>
        <CardHeader>
          <CardTitle>Choose Payment Method</CardTitle>
          <CardDescription>Select which payment method your students will use</CardDescription>
        </CardHeader>
        <CardContent>
          <RadioGroup value={method} onValueChange={(val) => setMethod(val as PaymentMethod)}>
            <div className="space-y-4">
              {/* UPI Option */}
              <div
                className={cn(
                  'p-4 rounded-lg border-2 cursor-pointer transition-all',
                  method === 'upi'
                    ? 'border-primary bg-primary/5'
                    : 'border-border hover:border-border/80'
                )}
              >
                <div className="flex items-start gap-3">
                  <RadioGroupItem value="upi" id="upi-radio" className="mt-1" />
                  <div className="flex-1">
                    <label
                      htmlFor="upi-radio"
                      className="font-semibold text-foreground cursor-pointer"
                    >
                      UPI Payment ⚡
                    </label>
                    <p className="text-sm text-muted-foreground mt-1">
                      Simple & Direct - Students scan QR or click button to pay via UPI app
                    </p>
                    <Badge variant="outline" className="mt-2">
                      0% Commission
                    </Badge>
                  </div>
                </div>
              </div>

              {/* Bank Option */}
              <div
                className={cn(
                  'p-4 rounded-lg border-2 cursor-pointer transition-all',
                  method === 'bank'
                    ? 'border-primary bg-primary/5'
                    : 'border-border hover:border-border/80'
                )}
              >
                <div className="flex items-start gap-3">
                  <RadioGroupItem value="bank" id="bank-radio" className="mt-1" />
                  <div className="flex-1">
                    <label
                      htmlFor="bank-radio"
                      className="font-semibold text-foreground cursor-pointer"
                    >
                      Bank Transfer 🏦
                    </label>
                    <p className="text-sm text-muted-foreground mt-1">
                      Manual - Students transfer to your bank account and upload proof for
                      verification
                    </p>
                    <Badge variant="outline" className="mt-2">
                      0% Commission | Manual Verification
                    </Badge>
                  </div>
                </div>
              </div>

              {/* Razorpay Option */}
              <div
                className={cn(
                  'p-4 rounded-lg border-2 cursor-pointer transition-all',
                  method === 'razorpay'
                    ? 'border-primary bg-primary/5'
                    : 'border-border hover:border-border/80'
                )}
              >
                <div className="flex items-start gap-3">
                  <RadioGroupItem value="razorpay" id="razorpay-radio" className="mt-1" />
                  <div className="flex-1">
                    <label
                      htmlFor="razorpay-radio"
                      className="font-semibold text-foreground cursor-pointer"
                    >
                      Razorpay Payment 💳
                    </label>
                    <p className="text-sm text-muted-foreground mt-1">
                      Professional - Cards, UPI, NetBanking, Wallets. Auto-verified payments.
                    </p>
                    <Badge variant="outline" className="mt-2">
                      0% for UPI | 0.5-2% for others
                    </Badge>
                  </div>
                </div>
              </div>
            </div>
          </RadioGroup>
        </CardContent>
      </Card>

      {/* Configuration Forms */}
      <Card>
        <CardHeader>
          <CardTitle>
            {method === 'upi'
              ? 'UPI Configuration'
              : method === 'bank'
                ? 'Bank Details Configuration'
                : 'Razorpay Configuration'}
          </CardTitle>
          <CardDescription>
            {method === 'upi'
              ? 'Your UPI ID for receiving payments'
              : method === 'bank'
                ? 'Your bank account details for student transfers'
                : 'Your Razorpay API credentials (get from https://razorpay.com)'}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {method === 'upi' ? (
            <>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">UPI ID *</label>
                <Input
                  placeholder="9876543210@ybl"
                  value={upiId}
                  onChange={(e) => setUpiId(e.target.value)}
                  className="font-mono text-sm"
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Format: phone@bankname (e.g., 9876543210@ybl, 9876543210@okhdfcbank)
                </p>
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Your Name *
                </label>
                <Input
                  placeholder="Ananay Dubey"
                  value={upiName}
                  onChange={(e) => setUpiName(e.target.value)}
                />
                <p className="text-xs text-muted-foreground mt-1">
                  How your name appears in payment apps
                </p>
              </div>

              {/* Preview */}
              {upiId && upiName && (
                <div className="p-3 bg-secondary/50 rounded-lg border border-border">
                  <p className="text-xs font-medium text-muted-foreground mb-2">Preview:</p>
                  <div className="space-y-1">
                    <p className="text-sm">
                      <span className="font-medium">Name:</span> {upiName}
                    </p>
                    <p className="text-sm font-mono">
                      <span className="font-medium">UPI:</span> {upiId}
                    </p>
                  </div>
                </div>
              )}
            </>
          ) : method === 'bank' ? (
            <>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Bank Name *
                </label>
                <Input
                  placeholder="State Bank of India"
                  value={bankName}
                  onChange={(e) => setBankName(e.target.value)}
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Account Holder Name *
                </label>
                <Input
                  placeholder="Your Name"
                  value={accountName}
                  onChange={(e) => setAccountName(e.target.value)}
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Account Number *
                </label>
                <Input
                  placeholder="1234567890123456"
                  value={accountNumber}
                  onChange={(e) => setAccountNumber(e.target.value)}
                  className="font-mono"
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  IFSC Code *
                </label>
                <Input
                  placeholder="SBIN0001234"
                  value={ifscCode}
                  onChange={(e) => setIfscCode(e.target.value)}
                  className="font-mono"
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">Branch</label>
                <Input
                  placeholder="University Campus Branch"
                  value={branch}
                  onChange={(e) => setBranch(e.target.value)}
                />
              </div>

              {/* Preview */}
              {bankName && accountNumber && (
                <div className="p-3 bg-secondary/50 rounded-lg border border-border">
                  <p className="text-xs font-medium text-muted-foreground mb-2">Preview:</p>
                  <div className="space-y-1 text-sm">
                    <p>
                      <span className="font-medium">Bank:</span> {bankName}
                    </p>
                    <p>
                      <span className="font-medium">Account:</span> {accountName}
                    </p>
                    <p className="font-mono">
                      <span className="font-medium">Number:</span> {accountNumber}
                    </p>
                    <p className="font-mono">
                      <span className="font-medium">IFSC:</span> {ifscCode}
                    </p>
                  </div>
                </div>
              )}
            </>
          ) : (
            <>
              <div>
                <label className="text-sm font-medium text-foreground block mb-2">
                  Razorpay API Key *
                </label>
                <div className="flex gap-2">
                  <Input
                    placeholder="rzp_live_xxxxxxxxxxxxx"
                    value={apiKey}
