            </>
          ) : (
            <>
              <Save className="w-4 h-4" />
              Save Configuration
            </>
          )}
        </Button>
        {!embedded && (
          <Button variant="outline" size="lg" onClick={() => router.push('/finance' as any)}>
            Cancel
          </Button>
        )}
      </div>
    </motion.div>
  );
}

