                      { id: 'amethyst', name: 'Amethyst', color: 'bg-purple-500' },
                      { id: 'pec-gold', name: 'PEC Gold', color: 'bg-yellow-500' }
                    ].map(acc => {
                      const isActive = document.documentElement.classList.contains(`accent-${acc.id}`) || 
                                     (acc.id === 'emerald' && !document.documentElement.className.includes('accent-'));
                      return (
                        <div 
                          key={acc.id}
                          onClick={() => {
                            const root = document.documentElement;
                            root.classList.remove('accent-emerald', 'accent-sapphire', 'accent-amethyst', 'accent-pec-gold');
                            root.classList.add(`accent-${acc.id}`);
                            localStorage.setItem('accent-color', acc.id);
                            document.cookie = `accent-color=${acc.id}; path=/; max-age=31536000`;
                            toast.success(`${acc.name} theme applied`);
                          }}
                          className={cn(
                            "p-4 rounded-xl border cursor-pointer transition-all",
                            isActive ? "border-primary bg-primary/10" : "border-border/40 hover:bg-muted/50"
                          )}
                        >
                          <div className={cn("w-full h-8 rounded-lg", acc.color)} />
                          <p className="text-[10px] font-bold mt-2 text-center uppercase tracking-wider">{acc.name}</p>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            </TabsContent>

            <TabsContent value="notifications" className="mt-0">
               <NotificationSettings />
            </TabsContent>

            <TabsContent value="privacy" className="mt-0">
               <PrivacySettings />
            </TabsContent>

            <TabsContent value="connected" className="mt-0">
               <NetworkSettings />
            </TabsContent>

            <TabsContent value="security" className="mt-0">
               <SecuritySettings />
            </TabsContent>
      </Tabs>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { api } from "@pec/api";
import { Monitor, Smartphone, Globe, Shield, Trash2, Loader2 } from "lucide-react";
import { formatDistanceToNow } from "date-fns";

interface Session {
  id: string;
  ipAddress: string | null;
  userAgent: string | null;
  createdAt: string;
  expiresAt: string;
}

function parseUA(ua: string | null) {
  if (!ua) return { browser: "Unknown Device", icon: Globe };
  const isMobile = /Mobile|Android|iP(hone|od|ad)/i.test(ua);

  let browser = "Unknown Browser";
  if (ua.includes("Edge") || ua.includes("Edg/")) browser = "Edge";
  else if (ua.includes("Chrome")) browser = "Chrome";
  else if (ua.includes("Safari") && !ua.includes("Chrome")) browser = "Safari";
  else if (ua.includes("Firefox")) browser = "Firefox";

  let os = "Unknown OS";
  if (ua.includes("Windows")) os = "Windows";
  else if (ua.includes("Mac OS")) os = "macOS";
  else if (ua.includes("Linux")) os = "Linux";
  else if (ua.includes("Android")) os = "Android";
  else if (ua.includes("iPhone") || ua.includes("iPad")) os = "iOS";

  return {
    browser: `${browser} on ${os}`,
    icon: isMobile ? Smartphone : Monitor,
  };
}

export default function SecuritySettingsPage() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [revoking, setRevoking] = useState<string | null>(null);

  const fetchSessions = async () => {
    try {
      const response = await api.get("/auth/sessions");
      setSessions(response.data.sessions || []);
    } catch (e) {
      console.error("Failed to fetch sessions", e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSessions();
  }, []);

  const handleRevoke = async (id: string) => {
    setRevoking(id);
    try {
      await api.delete(`/auth/sessions/${id}`);
      setSessions((prev) => prev.filter((s) => s.id !== id));
    } catch (e) {
      console.error("Failed to revoke session", e);
    } finally {
      setRevoking(null);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 p-4">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Security & Sessions</h1>
        <p className="text-muted-foreground mt-2">
          Manage your active sessions and device history.
        </p>
      </div>

      <div className="rounded-xl border bg-card text-card-foreground shadow-sm overflow-hidden">
        <div className="p-6 border-b bg-muted/40 flex items-center space-x-3">
          <div className="p-2 bg-primary/10 text-primary rounded-lg">
            <Shield className="w-5 h-5" />
          </div>
          <div>
            <h2 className="text-xl font-semibold">Active Sessions</h2>
            <p className="text-sm text-muted-foreground">
              These devices are currently logged into your account.
            </p>
          </div>
        </div>

        <div className="p-0">
          {loading ? (
            <div className="flex justify-center items-center py-12">
              <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
            </div>
          ) : sessions.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              No active sessions found.
            </div>
          ) : (
            <div className="divide-y">
              {sessions.map((session, index) => {
                const { browser, icon: Icon } = parseUA(session.userAgent);
                const isCurrent = index === 0; // Assuming newest is first and is the current one, though realistically we might mark the active token

                return (
                  <div
                    key={session.id}
                    className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-6 gap-4 hover:bg-muted/20 transition-colors"
                  >
                    <div className="flex items-start space-x-4">
                      <div className="p-3 bg-secondary rounded-full">
                        <Icon className="w-6 h-6 text-foreground" />
                      </div>
                      <div>
                        <div className="flex items-center space-x-2">
                          <p className="font-medium text-foreground">{browser}</p>
                          {isCurrent && (
                            <span className="px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-500 text-xs font-medium">
                              Current Session
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-muted-foreground mt-1">
                          IP: {session.ipAddress || "Unknown"}
                        </p>
                        <p className="text-xs text-muted-foreground mt-0.5">
                          Started {formatDistanceToNow(new Date(session.createdAt))} ago
                        </p>
                      </div>
                    </div>

                    {!isCurrent && (
                      <button
                        onClick={() => handleRevoke(session.id)}
                        disabled={revoking === session.id}
                        className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 border border-destructive/20 bg-transparent shadow-sm hover:bg-destructive/10 text-destructive h-9 px-4 py-2 w-full sm:w-auto"
                      >
                        {revoking === session.id ? (
                          <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                          <>
                            <Trash2 className="w-4 h-4 mr-2" />
                            Revoke Access
                          </>
                        )}
                      </button>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';
import { Button, Input, Textarea, Badge, Progress, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Tabs, TabsContent, TabsList, TabsTrigger } from "@pec/ui";


import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { motion } from 'framer-motion';
import {
  Github,
  Star,
  GitFork,
  Code2,
  Plus,
  Edit2,
  Trash2,
  Loader2,
  Check,
  Briefcase,
  Eye,
} from 'lucide-react';

import { toast } from 'sonner';
import { usePermissions } from '@/hooks/usePermissions';
import api from "@pec/api";

import { Project, Skill } from './types';
import { skillCategories, emptyProjectForm, emptySkillForm } from './constants';

export default function StudentPortfolioPage() {
  const router = useRouter();
  const { user, loading: authLoading } = usePermissions();
  const [loading, setLoading] = useState(true);
  const [projects, setProjects] = useState<Project[]>([]);
  const [skills, setSkills] = useState<Skill[]>([]);
  const [githubRepos, setGithubRepos] = useState<any[]>([]);
  const [githubLoading, setGithubLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('projects');

  const [showProjectDialog, setShowProjectDialog] = useState(false);
  const [editingProject, setEditingProject] = useState<Project | null>(null);
  const [projectForm, setProjectForm] = useState(emptyProjectForm);
  const [savingProject, setSavingProject] = useState(false);

  const [showSkillDialog, setShowSkillDialog] = useState(false);
  const [editingSkill, setEditingSkill] = useState<Skill | null>(null);
  const [skillForm, setSkillForm] = useState(emptySkillForm);
  const [savingSkill, setSavingSkill] = useState(false);

  useEffect(() => {
    if (authLoading) return;
    if (!user) {
      router.replace('/auth');
      return;
    }
    fetchPortfolio();
  }, [authLoading, user, router]);

  const fetchPortfolio = async () => {
    try {
      setLoading(true);
      const data = await api.get('/student-portfolio');
      setProjects(data.data.projects || []);
      setSkills(data.data.skills || []);
    } catch (error) {
      console.error('Error fetching portfolio:', error);
      toast.error('Failed to load portfolio');
    } finally {
      setLoading(false);
    }
  };

  const syncGitHub = async () => {
    setGithubLoading(true);
    try {
      const data = await api.get('/social-sync/github/repos');
      setGithubRepos(data.data.repos || []);
      if (data.data.repos?.length > 0) {
        toast.success(`Found ${data.data.repos.length} GitHub repos`);
      } else {
        toast.info(data.data.message || 'No repos found');
      }
    } catch (error) {
      console.error('GitHub sync error:', error);
      toast.error('Failed to sync GitHub repos');
    } finally {
      setGithubLoading(false);
    }
  };

  const importRepo = async (repo: any) => {
    try {
      await api.post('/student-portfolio/projects', {
        studentId: user?.uid,
        title: repo.name,
        description: repo.description || '',
        techStack: repo.techStack || (repo.language ? JSON.stringify([repo.language]) : '[]'),
        githubUrl: repo.githubUrl || repo.url,
        liveUrl: repo.liveUrl || '',
        isFeatured: false,
      });
      toast.success(`Imported ${repo.name}`);
      fetchPortfolio();
    } catch (error) {
      toast.error(`Failed to import ${repo.name}`);
    }
  };

  const openCreateProject = () => {
    setEditingProject(null);
    setProjectForm(emptyProjectForm);
    setShowProjectDialog(true);
  };

  const openEditProject = (project: Project) => {
    setEditingProject(project);
    setProjectForm({
      title: project.title,
      description: project.description,
      techStack: project.techStack,
      githubUrl: project.githubUrl || '',
      liveUrl: project.liveUrl || '',
      imageUrl: project.imageUrl || '',
      startDate: project.startDate ? new Date(project.startDate).toISOString().split('T')[0] : '',
      endDate: project.endDate ? new Date(project.endDate).toISOString().split('T')[0] : '',
      isFeatured: project.isFeatured,
    });
    setShowProjectDialog(true);
  };

  const handleSaveProject = async () => {
    if (!projectForm.title) {
      toast.error('Title is required');
      return;
    }

    setSavingProject(true);
    try {
      const payload = {
        studentId: user?.uid,
        ...projectForm,
        techStack: JSON.stringify(
          projectForm.techStack
            .split(',')
            .map((t) => t.trim())
            .filter(Boolean)
        ),
        startDate: projectForm.startDate || null,
        endDate: projectForm.endDate || null,
        githubUrl: projectForm.githubUrl || null,
        liveUrl: projectForm.liveUrl || null,
        imageUrl: projectForm.imageUrl || null,
      };

      if (editingProject) {
        await api.patch(`/student-portfolio/projects/${editingProject.id}`, payload);
        toast.success('Project updated');
      } else {
        await api.post('/student-portfolio/projects', payload);
        toast.success('Project created');
      }
      setShowProjectDialog(false);
      fetchPortfolio();
    } catch (error) {
      console.error('Save error:', error);
      toast.error('Failed to save project');
    } finally {
      setSavingProject(false);
    }
  };

  const handleDeleteProject = async (id: string) => {
    if (!confirm('Delete this project?')) return;
    try {
      await api.delete(`/student-portfolio/projects/${id}`);
      toast.success('Project deleted');
      fetchPortfolio();
    } catch (error) {
      toast.error('Failed to delete project');
    }
  };

  const openCreateSkill = () => {
    setEditingSkill(null);
    setSkillForm(emptySkillForm);
    setShowSkillDialog(true);
  };

  const openEditSkill = (skill: Skill) => {
    setEditingSkill(skill);
    setSkillForm({ name: skill.name, level: skill.level, category: skill.category });
    setShowSkillDialog(true);
  };

  const handleSaveSkill = async () => {
    if (!skillForm.name) {
      toast.error('Skill name is required');
      return;
    }

    setSavingSkill(true);
    try {
      const payload = { studentId: user?.uid, ...skillForm };

      if (editingSkill) {
        await api.patch(`/student-portfolio/skills/${editingSkill.id}`, payload);
        toast.success('Skill updated');
      } else {
        await api.post('/student-portfolio/skills', payload);
        toast.success('Skill added');
      }
      setShowSkillDialog(false);
      fetchPortfolio();
    } catch (error) {
      console.error('Save error:', error);
      toast.error('Failed to save skill');
    } finally {
      setSavingSkill(false);
    }
  };

  const handleDeleteSkill = async (id: string) => {
    if (!confirm('Delete this skill?')) return;
    try {
      await api.delete(`/student-portfolio/skills/${id}`);
      toast.success('Skill deleted');
      fetchPortfolio();
    } catch (error) {
      toast.error('Failed to delete skill');
    }
  };

  const getTechStack = (techStackStr: string): string[] => {
    try {
      return JSON.parse(techStackStr);
    } catch {
      return techStackStr ? techStackStr.split(',').map((t) => t.trim()) : [];
    }
  };

  const skillsByCategory = skills.reduce(
    (acc, skill) => {
      const cat = skill.category || 'technical';
      if (!acc[cat]) acc[cat] = [];
      acc[cat].push(skill);
      return acc;
    },
    {} as Record<string, Skill[]>
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">Student Portfolio</h1>
          <p className="text-muted-foreground">Showcase your projects, skills, and GitHub work</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={syncGitHub} disabled={githubLoading}>
            {githubLoading ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <Github className="w-4 h-4 mr-2" />
            )}
            Sync GitHub
          </Button>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="w-full justify-start border-b rounded-none h-auto p-0 bg-transparent gap-8">
          {['projects', 'skills', 'github'].map((tab) => (
            <TabsTrigger
              key={tab}
              value={tab}
              className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent data-[state=active]:text-primary px-0 py-3 text-xs font-black uppercase tracking-widest transition-all capitalize"
            >
              {tab}
            </TabsTrigger>
          ))}
        </TabsList>

        <TabsContent value="projects" className="mt-6">
          <div className="flex justify-end mb-4">
            <Button onClick={openCreateProject}>
              <Plus className="w-4 h-4 mr-2" /> Add Project
            </Button>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {projects.map((project, idx) => (
              <motion.div
                key={project.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: idx * 0.05 }}
                className="card-elevated p-5 space-y-3"
              >
                <div className="flex items-start justify-between">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <h3 className="font-semibold truncate">{project.title}</h3>
                      {project.isFeatured && (
                        <Badge variant="default" className="text-xs">
                          <Star className="w-3 h-3 mr-1" /> Featured
                        </Badge>
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground line-clamp-2 mt-1">
                      {project.description}
                    </p>
                  </div>
                </div>

                {getTechStack(project.techStack).length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    {getTechStack(project.techStack)
                      .slice(0, 4)
                      .map((tech: string, i: number) => (
                        <Badge key={i} variant="secondary" className="text-xs">
                          {tech}
                        </Badge>
                      ))}
                    {getTechStack(project.techStack).length > 4 && (
                      <Badge variant="outline" className="text-xs">
                        +{getTechStack(project.techStack).length - 4}
                      </Badge>
                    )}
                  </div>
                )}

                <div className="flex gap-2 pt-2 border-t">
                  {project.githubUrl && (
                    <Button variant="ghost" size="sm" asChild className="flex-1">
                      <a href={project.githubUrl} target="_blank" rel="noopener noreferrer">
                        <Github className="w-3 h-3 mr-1" /> Code
                      </a>
                    </Button>
                  )}
                  {project.liveUrl && (
                    <Button variant="ghost" size="sm" asChild className="flex-1">
                      <a href={project.liveUrl} target="_blank" rel="noopener noreferrer">
                        <Eye className="w-3 h-3 mr-1" /> Demo
                      </a>
                    </Button>
                  )}
                  <Button variant="outline" size="sm" onClick={() => openEditProject(project)}>
                    <Edit2 className="w-3 h-3" />
                  </Button>
                  <Button
                    variant="destructive"
                    size="sm"
                    onClick={() => handleDeleteProject(project.id)}
                  >
                    <Trash2 className="w-3 h-3" />
                  </Button>
                </div>
              </motion.div>
            ))}
          </div>

          {projects.length === 0 && (
            <div className="card-elevated p-12 text-center">
              <Briefcase className="w-12 h-12 mx-auto mb-4 opacity-20" />
              <p className="text-muted-foreground">No projects yet. Add your first project!</p>
            </div>
          )}
        </TabsContent>

        <TabsContent value="skills" className="mt-6">
          <div className="flex justify-end mb-4">
            <Button onClick={openCreateSkill}>
              <Plus className="w-4 h-4 mr-2" /> Add Skill
            </Button>
          </div>

          <div className="grid gap-6 md:grid-cols-2">
            {skillCategories.map(({ id, label, icon: Icon }) => {
              const categorySkills = skillsByCategory[id] || [];
              if (categorySkills.length === 0) return null;

              return (
                <div key={id} className="card-elevated p-5 space-y-4">
                  <div className="flex items-center gap-2">
                    <Icon className="w-5 h-5 text-primary" />
                    <h3 className="font-semibold">{label}</h3>
                  </div>
                  <div className="space-y-3">
                    {categorySkills.map((skill) => (
                      <div key={skill.id} className="space-y-1.5">
                        <div className="flex items-center justify-between">
                          <span className="text-sm font-medium">{skill.name}</span>
                          <div className="flex items-center gap-2">
                            <span className="text-xs text-muted-foreground">{skill.level}%</span>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-6 w-6 p-0"
                              onClick={() => openEditSkill(skill)}
                            >
                              <Edit2 className="w-3 h-3" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-6 w-6 p-0 text-destructive"
                              onClick={() => handleDeleteSkill(skill.id)}
                            >
                              <Trash2 className="w-3 h-3" />
                            </Button>
                          </div>
                        </div>
                        <Progress value={skill.level} className="h-2" />
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>

          {skills.length === 0 && (
            <div className="card-elevated p-12 text-center">
              <Code2 className="w-12 h-12 mx-auto mb-4 opacity-20" />
              <p className="text-muted-foreground">
                No skills added yet. Start building your skill profile!
              </p>
            </div>
          )}
        </TabsContent>

        <TabsContent value="github" className="mt-6">
          <div className="flex justify-end mb-4">
            <Button variant="outline" onClick={syncGitHub} disabled={githubLoading}>
              {githubLoading ? (
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              ) : (
                <Github className="w-4 h-4 mr-2" />
              )}
              Refresh GitHub Repos
            </Button>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {githubRepos.map((repo, idx) => (
              <motion.div
                key={repo.name}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: idx * 0.05 }}
                className="card-elevated p-5 space-y-3"
              >
                <div className="flex items-start justify-between">
                  <h3 className="font-semibold truncate flex-1">{repo.name}</h3>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => importRepo(repo)}
                    title="Import to portfolio"
                  >
                    <Plus className="w-4 h-4" />
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground line-clamp-2">
                  {repo.description || 'No description'}
                </p>
                {repo.language && (
                  <Badge variant="secondary" className="text-xs">
                    {repo.language}
                  </Badge>
                )}
                <div className="flex items-center gap-4 text-xs text-muted-foreground">
                  <span className="flex items-center gap-1">
                    <Star className="w-3 h-3" /> {repo.stars ?? 0}
                  </span>
                  <span className="flex items-center gap-1">
                    <GitFork className="w-3 h-3" /> {repo.forks ?? 0}
                  </span>
                </div>
                <div className="flex gap-2 pt-2 border-t">
                  <Button variant="outline" size="sm" asChild className="flex-1">
                    <a href={repo.githubUrl || repo.url} target="_blank" rel="noopener noreferrer">
                      <Github className="w-3 h-3 mr-1" /> View
                    </a>
                  </Button>
                </div>
              </motion.div>
            ))}
          </div>

          {githubRepos.length === 0 && (
            <div className="card-elevated p-12 text-center">
              <Github className="w-12 h-12 mx-auto mb-4 opacity-20" />
              <p className="text-muted-foreground">
                No GitHub repos loaded. Configure your GitHub username in profile settings and sync.
              </p>
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* Project Dialog */}
      <Dialog open={showProjectDialog} onOpenChange={setShowProjectDialog}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingProject ? 'Edit Project' : 'Add Project'}</DialogTitle>
            <DialogDescription>
              {editingProject ? 'Update project details' : 'Add a new project to your portfolio'}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium">Title *</label>
              <Input
                value={projectForm.title}
                onChange={(e) => setProjectForm({ ...projectForm, title: e.target.value })}
                className="mt-1"
                placeholder="My Awesome Project"
              />
            </div>
            <div>
              <label className="text-sm font-medium">Description</label>
              <Textarea
                value={projectForm.description}
                onChange={(e) => setProjectForm({ ...projectForm, description: e.target.value })}
                className="mt-1"
                placeholder="What does this project do?"
              />
            </div>
            <div>
              <label className="text-sm font-medium">Tech Stack (comma-separated)</label>
              <Input
                value={projectForm.techStack}
                onChange={(e) => setProjectForm({ ...projectForm, techStack: e.target.value })}
                className="mt-1"
                placeholder="React, Node.js, PostgreSQL"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">GitHub URL</label>
                <Input
                  value={projectForm.githubUrl}
                  onChange={(e) => setProjectForm({ ...projectForm, githubUrl: e.target.value })}
                  className="mt-1"
                  placeholder="https://github.com/..."
                />
              </div>
              <div>
                <label className="text-sm font-medium">Live URL</label>
                <Input
                  value={projectForm.liveUrl}
                  onChange={(e) => setProjectForm({ ...projectForm, liveUrl: e.target.value })}
                  className="mt-1"
                  placeholder="https://..."
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Start Date</label>
                <Input
                  type="date"
                  value={projectForm.startDate}
                  onChange={(e) => setProjectForm({ ...projectForm, startDate: e.target.value })}
                  className="mt-1"
                />
              </div>
              <div>
                <label className="text-sm font-medium">End Date</label>
                <Input
                  type="date"
                  value={projectForm.endDate}
                  onChange={(e) => setProjectForm({ ...projectForm, endDate: e.target.value })}
                  className="mt-1"
                />
              </div>
            </div>
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                id="featured"
                checked={projectForm.isFeatured}
                onChange={(e) => setProjectForm({ ...projectForm, isFeatured: e.target.checked })}
                className="rounded"
              />
              <label htmlFor="featured" className="text-sm">
                Featured Project
              </label>
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setShowProjectDialog(false)}>
                Cancel
              </Button>
              <Button onClick={handleSaveProject} disabled={savingProject}>
                {savingProject ? (
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                ) : (
                  <Check className="w-4 h-4 mr-2" />
                )}
                {savingProject ? 'Saving...' : 'Save'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Skill Dialog */}
      <Dialog open={showSkillDialog} onOpenChange={setShowSkillDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingSkill ? 'Edit Skill' : 'Add Skill'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium">Skill Name *</label>
              <Input
                value={skillForm.name}
                onChange={(e) => setSkillForm({ ...skillForm, name: e.target.value })}
                className="mt-1"
                placeholder="e.g., React.js"
              />
            </div>
            <div>
              <label className="text-sm font-medium">Category</label>
              <Select
                value={skillForm.category}
                onValueChange={(v) => setSkillForm({ ...skillForm, category: v })}
              >
                <SelectTrigger className="mt-1">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {skillCategories.map((cat) => (
                    <SelectItem key={cat.id} value={cat.id}>
                      {cat.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium">Proficiency: {skillForm.level}%</label>
              <input
                type="range"
                min={0}
                max={100}
                value={skillForm.level}
                onChange={(e) => setSkillForm({ ...skillForm, level: Number(e.target.value) })}
                className="w-full mt-1"
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setShowSkillDialog(false)}>
                Cancel
              </Button>
              <Button onClick={handleSaveSkill} disabled={savingSkill}>
                {savingSkill ? (
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                ) : (
                  <Check className="w-4 h-4 mr-2" />
                )}
                {savingSkill ? 'Saving...' : 'Save'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

