'use client';

import React from 'react';
import { Button } from '@pec/ui';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@pec/ui';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@pec/ui';
import { Input } from '@pec/ui';
import { Calendar } from 'lucide-react';

interface ExtraClassDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  extraClassForm: {
    courseId: string;
    slotKey: string;
    room: string;
  };
  setExtraClassForm: React.Dispatch<
    React.SetStateAction<{
      courseId: string;
      slotKey: string;
      room: string;
    }>
  >;
  courses: any[];
  timetable: Record<string, any[]>;
  days: string[];
  timeSlots: string[];
  isSlotOwnedByFaculty: (slot: any) => boolean;
  onSchedule: () => Promise<void>;
  onCancel: () => void;
}

export default function ExtraClassDialog({
  open,
  onOpenChange,
  extraClassForm,
  setExtraClassForm,
  courses,
  timetable,
  days,
  timeSlots,
  isSlotOwnedByFaculty,
  onSchedule,
  onCancel,
}: ExtraClassDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Schedule Extra Class</DialogTitle>
          <DialogDescription>Add an extra class session to your timetable</DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          {/* Course Selection */}
          <div className="space-y-2">
            <label className="text-sm font-medium">Course *</label>
            <Select
              value={extraClassForm.courseId}
              onValueChange={(value) =>
                setExtraClassForm((prev) => ({
                  ...prev,
                  courseId: value,
                  slotKey: '', // Reset slot when course changes
                }))
              }
            >
              <SelectTrigger>
                <SelectValue placeholder="Select your course" />
              </SelectTrigger>
              <SelectContent>
                {courses.length > 0 ? (
                  courses.map((course) => (
                    <SelectItem key={course.id} value={course.id}>
                      {course.code} - {course.name}
                    </SelectItem>
                  ))
                ) : (
                  <div className="p-2 text-sm text-muted-foreground">No courses assigned</div>
                )}
              </SelectContent>
            </Select>
          </div>

          {/* Day Selection */}
          {extraClassForm.courseId && (
            <div className="space-y-2">
              <label className="text-sm font-medium">Day *</label>
              <Select
                value={extraClassForm.slotKey?.split('-')[0] || ''}
                onValueChange={(day) => {
                  setExtraClassForm((prev) => ({
                    ...prev,
                    slotKey: `${day}-`, // Placeholder for time selection
                  }));
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select a day" />
                </SelectTrigger>
                <SelectContent>
                  {days.map((day) => (
                    <SelectItem key={day} value={day}>
                      {day}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Time Slot Selection */}
          {extraClassForm.courseId && extraClassForm.slotKey?.split('-')[0] && (
            <div className="space-y-2">
              <label className="text-sm font-medium">Time Slot *</label>
              <Select
                value={extraClassForm.slotKey || ''}
                onValueChange={(value) =>
                  setExtraClassForm((prev) => ({ ...prev, slotKey: value }))
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select available time" />
                </SelectTrigger>
                <SelectContent>
                  {timeSlots
                    .filter((t) => t !== '13:00-14:00')
                    .map((timeSlot) => {
                      const selectedDay = extraClassForm.slotKey?.split('-')[0];
                      const key = `${selectedDay}-${timeSlot}`;
                      const slots = timetable[key] || [];
                      const hasFacultyClass = slots.some((slot: any) => isSlotOwnedByFaculty(slot));
                      const isAvailable = !hasFacultyClass;

                      return (
                        <SelectItem key={key} value={key} disabled={!isAvailable}>
                          <span>
                            {timeSlot}
                            {!isAvailable && ' (Busy)'}
                          </span>
                        </SelectItem>
                      );
                    })}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Room Input */}
          {extraClassForm.courseId && (
            <div className="space-y-2">
              <label className="text-sm font-medium">Room</label>
              <Input
                placeholder="e.g. L-10, Lab 2, or leave blank for TBD"
                value={extraClassForm.room}
                onChange={(e) => setExtraClassForm((prev) => ({ ...prev, room: e.target.value }))}
              />
            </div>
          )}

          {/* Auto-populated Fields Info */}
          {extraClassForm.courseId &&
            extraClassForm.slotKey &&
            !extraClassForm.slotKey.endsWith('-') && (
              <div className="p-3 bg-blue-50 border border-blue-200 rounded-lg space-y-2 text-sm">
                <p className="font-medium text-blue-900">Auto-populated from course:</p>
                <div className="text-xs text-blue-800 space-y-1">
                  {(() => {
                    const course = courses.find((c) => c.id === extraClassForm.courseId);
                    return (
                      <>
                        <div>
                          • <strong>Program:</strong> {course?.department || 'N/A'}
                        </div>
                        <div>
                          • <strong>Semester:</strong> {course?.semester || 'N/A'}
                        </div>
                        {course?.batch && (
                          <div>
                            • <strong>Batch:</strong> {course.batch}
                          </div>
                        )}
                        <div>
                          • <strong>Slot:</strong> {extraClassForm.slotKey.replace('-', ' at ')}
                        </div>
                        <div>
                          • <strong>Room:</strong> {extraClassForm.room || 'TBD'}
                        </div>
                      </>
                    );
                  })()}
                </div>
              </div>
            )}

          {/* Action Buttons */}
          <div className="flex gap-3 pt-4">
            <Button variant="outline" onClick={onCancel} className="flex-1">
              Cancel
            </Button>
            <Button
              onClick={onSchedule}
              className="flex-1"
              disabled={
                !extraClassForm.courseId ||
                !extraClassForm.slotKey ||
                extraClassForm.slotKey.endsWith('-') ||
                courses.length === 0
              }
            >
              <Calendar className="w-4 h-4 mr-2" />
              Schedule
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import React from 'react';
import { Trash2 } from 'lucide-react';
import { EmptyState } from '@/components/common/AsyncState';

interface TimetableDesktopViewProps {
  timetable: Record<string, any[]>;
  DAYS: string[];
  TIME_SLOTS: string[];
  canManageAllTimetable: boolean;
  draggedCourse: any;
  user: any;
  studentAttendanceMap: Map<string, number>;
  filterValues: {
    department: string;
    [key: string]: any;
  };
  handleDragOver: (e: React.DragEvent) => void;
  handleDragLeave: (e: React.DragEvent) => void;
  handleDrop: (e: React.DragEvent, day: string, timeSlot: string) => Promise<void>;
  handleDragEnd: () => void;
  openSlotDialog: (day: string, timeSlot: string) => void;
  applySlotFilters: (slots: any[]) => any[];
  handleDeleteSlot: (slotId: string) => Promise<void>;
}

export default function TimetableDesktopView({
  timetable,
  DAYS,
  TIME_SLOTS,
  canManageAllTimetable,
  draggedCourse,
  user,
  studentAttendanceMap,
  filterValues,
  handleDragOver,
  handleDragLeave,
  handleDrop,
  handleDragEnd,
  openSlotDialog,
  applySlotFilters,
  handleDeleteSlot,
}: TimetableDesktopViewProps) {
  return (
    <div className="hidden md:block card-elevated overflow-x-auto overflow-y-auto max-h-[70vh] timetable-scroll-container">
      <table className="w-full border-collapse">
        <thead>
          <tr className="bg-muted/30">
            <th className="border border-border p-3 text-left text-sm font-medium text-muted-foreground min-w-[100px]">
              Time
            </th>
            {DAYS.map((day) => (
              <th
                key={day}
                className="border border-border p-3 text-center text-sm font-medium text-muted-foreground min-w-[150px]"
              >
                {day}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {TIME_SLOTS.map((timeSlot) => (
            <tr key={timeSlot}>
              <td className="border border-border p-3 text-sm font-medium text-muted-foreground bg-muted/20">
                {timeSlot}
              </td>
              {DAYS.map((day) => {
                const key = `${day}-${timeSlot}`;
                const slotData = timetable[key];
                const isLunch = timeSlot === '13:00-14:00';

                if (isLunch) {
                  return (
                    <td
                      key={`${day}-${timeSlot}`}
                      className="border border-border p-2 bg-muted/40 text-center align-middle"
                    >
                      {day === 'Wednesday' && (
                        <span className="text-[10px] font-bold tracking-[0.2em] uppercase text-muted-foreground/60 vertical-text block rotate-0">
                          Lunch Break
                        </span>
                      )}
                    </td>
                  );
                }

                return (
                  <td
                    key={`${day}-${timeSlot}`}
                    className={`border border-border p-2 relative group transition-colors min-h-[80px] ${
                      canManageAllTimetable ? 'hover:bg-muted/10 cursor-pointer' : ''
                    } ${draggedCourse ? 'drag-target' : ''}`}
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={(e) => handleDrop(e, day, timeSlot)}
                    onDragEnd={handleDragEnd}
                    onClick={() => canManageAllTimetable && openSlotDialog(day, timeSlot)}
                  >
                    {(() => {
                      if (!slotData || slotData.length === 0) {
                        return (
                          <div className="text-xs text-muted-foreground/30 text-center opacity-0 group-hover:opacity-100 transition-opacity">
                            {canManageAllTimetable && 'Drop here'}
                          </div>
                        );
                      }

                      const scopedSlots = applySlotFilters(slotData);

                      if (scopedSlots.length === 0) {
                        return (
                          <div className="text-xs text-muted-foreground/30 text-center opacity-0 group-hover:opacity-100 transition-opacity">
                            {canManageAllTimetable && 'Drop here'}
                          </div>
                        );
                      }

                      return (
                        <div className="space-y-1">
                          {scopedSlots.map((slot: any, idx: number) => (
                            <div
                              key={idx}
                              className="p-2 bg-primary/10 rounded-lg border border-primary/20 relative"
                            >
                              <div className="font-medium text-sm text-foreground">
                                {slot.courseCode || slot.courseName}
                              </div>
                              <div className="text-xs text-muted-foreground mt-1">
                                {slot.facultyName}
                              </div>
                              {slot.room && (
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    window.location.href = `/campus-map?search=${encodeURIComponent(
                                      slot.room
                                    )}`;
                                  }}
                                  className="flex items-center gap-1.5 mt-1.5 text-[10px] font-bold text-primary hover:underline group"
                                >
                                  <span className="bg-primary/10 px-1.5 py-0.5 rounded uppercase tracking-tighter">
                                    {slot.room}
                                  </span>
                                  <span className="opacity-0 group-hover:opacity-100 transition-opacity">
                                    → MAP
                                  </span>
                                </button>
                              )}

                              {user?.role === 'student' &&
                                studentAttendanceMap.has(slot.courseId) && (
                                  <div
                                    className={`mt-2 px-2 py-0.5 rounded-full text-[10px] font-bold inline-flex items-center gap-1 ${
                                      (studentAttendanceMap.get(slot.courseId) || 0) < 75
                                        ? 'bg-destructive/10 text-destructive border border-destructive/20'
                                        : 'bg-success/10 text-success border border-success/20'
                                    }`}
                                  >
                                    <div
                                      className={`w-1.5 h-1.5 rounded-full ${
                                        (studentAttendanceMap.get(slot.courseId) || 0) < 75
                                          ? 'bg-destructive'
                                          : 'bg-success'
                                      }`}
                                    />
                                    {studentAttendanceMap.get(slot.courseId)}% Attended
                                  </div>
                                )}

                              {(user?.role === 'student' || filterValues.department === 'all') && (
                                <div className="text-[9px] opacity-70 mt-1 font-medium">
                                  {slot.department}
                                </div>
                              )}

                              {canManageAllTimetable && (
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    handleDeleteSlot(slot.id);
                                  }}
                                  className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 p-1 hover:bg-destructive/10 rounded text-destructive transition-all"
                                >
                                  <Trash2 className="w-3 h-3" />
                                </button>
                              )}
                            </div>
                          ))}
                        </div>
                      );
                    })()}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
      {Object.keys(timetable).length === 0 && (
        <div className="p-4">
          <EmptyState
            title="No timetable entries"
            description="Add slots manually or use auto-generate."
          />
        </div>
      )}
    </div>
  );
}

'use client';

import React from 'react';
import { Badge } from '@pec/ui';

interface TimetableMobileViewProps {
  timetable: Record<string, any[]>;
  DAYS: string[];
  TIME_SLOTS: string[];
  isWeeklyView: boolean;
  selectedDay: string;
  setSelectedDay: (day: string) => void;
  applySlotFilters: (slots: any[]) => any[];
  getTimeStatus: (slotTime: string, day: string) => string;
  canManageAllTimetable: boolean;
  openSlotDialog: (day: string, timeSlot: string) => void;
  user: any;
  studentAttendanceMap: Map<string, number>;
  facultyDisplayName: string;
}

export default function TimetableMobileView({
  timetable,
  DAYS,
  TIME_SLOTS,
  isWeeklyView,
  selectedDay,
  setSelectedDay,
  applySlotFilters,
  getTimeStatus,
  canManageAllTimetable,
  openSlotDialog,
  user,
  studentAttendanceMap,
  facultyDisplayName,
}: TimetableMobileViewProps) {
  return (
    <div className="md:hidden space-y-5">
      {/* Day Selector (Hidden in Weekly View) */}
      {!isWeeklyView && (
        <div className="flex overflow-x-auto pb-4 gap-2 no-scrollbar snap-x overflow-y-hidden">
          {DAYS.map((day) => (
            <button
              key={day}
              onClick={() => setSelectedDay(day)}
              className={`snap-center shrink-0 min-w-[70px] py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all border-2 flex flex-col items-center gap-1.5 ${
                selectedDay === day
                  ? 'bg-primary border-primary text-primary-foreground shadow-[0_0_15px_rgba(var(--primary-rgb),0.35)] scale-105 z-10'
                  : 'bg-surface/60 backdrop-blur-sm text-muted-foreground border-border/50 hover:border-primary/30 hover:bg-muted/30'
              }`}
              style={
                selectedDay !== day
                  ? {
                      backgroundColor: `hsla(${30 + DAYS.indexOf(day) * 40}, 40%, 15%, 0.1)`,
                    }
                  : {}
              }
            >
              <span className="opacity-50 text-[8px] tracking-normal">{day.slice(0, 3)}</span>
              <span className={selectedDay === day ? 'text-primary-foreground' : 'text-foreground'}>
                {(() => {
                  const now = new Date();
                  const dayIndex = DAYS.indexOf(day);
                  const todayIndex = now.getDay() === 0 ? 6 : now.getDay() - 1;
                  const diff = dayIndex - todayIndex;
                  const date = new Date(now);
                  date.setDate(now.getDate() + diff);
                  return date.getDate();
                })()}
              </span>
            </button>
          ))}
        </div>
      )}

      {/* Timeline Feed or Weekly Matrix */}
      {isWeeklyView ? (
        <div className="space-y-6">
          {DAYS.map((day) => (
            <div key={day} className="space-y-3">
              <h3 className="text-xs font-black uppercase tracking-[0.2em] text-primary/70 px-1 border-l-2 border-primary ml-1">
                {day}
              </h3>
              <div className="grid gap-3 grid-cols-1 sm:grid-cols-2">
                {TIME_SLOTS.map((slot) => {
                  const key = `${day}-${slot}`;
                  const data = applySlotFilters(timetable[key] || []);
                  if (data.length === 0) return null;
                  return (
                    <div
                      key={slot}
                      className="bg-card border border-border/60 rounded-xl p-3 flex items-center gap-3 hover:border-primary/40 transition-colors shadow-sm"
                    >
                      <div className="flex flex-col items-center justify-center bg-muted/30 rounded-lg p-2 min-w-[60px]">
                        <span className="text-[10px] font-bold text-foreground">
                          {slot.split('-')[0]}
                        </span>
                        <span className="text-[8px] text-muted-foreground uppercase">
                          {slot.split('-')[1]}
                        </span>
                      </div>
                      <div className="flex-1">
                        {data.map((s: any, i: number) => (
                          <div key={i} className="text-xs">
                            <p className="font-bold text-foreground line-clamp-1">
                              {s.courseCode || s.courseName}
                            </p>
                            <p className="text-[10px] text-muted-foreground">{s.room}</p>
                          </div>
                        ))}
                      </div>
                      <div className="w-1.5 h-1.5 rounded-full bg-primary/40 shadow-[0_0_8px_rgba(var(--primary-rgb),0.4)]"></div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
          {Object.keys(timetable).length === 0 && (
            <div className="py-12 text-center text-muted-foreground/40 italic text-sm">
              No weekly schedule entries found.
            </div>
          )}
        </div>
      ) : (
        <div className="space-y-4">
          {TIME_SLOTS.map((timeSlot) => {
            const key = `${selectedDay}-${timeSlot}`;
            const slotData = timetable[key];
            const isLunch = timeSlot === '13:00-14:00';
            const status = getTimeStatus(timeSlot, selectedDay);
            const filteredSlots = applySlotFilters(slotData || []);

            if (isLunch) {
              return (
                <div key={timeSlot} className="flex items-center gap-4 opacity-50 my-4">
                  <span className="text-xs font-mono text-muted-foreground w-12 text-right">
                    {timeSlot.split('-')[0]}
                  </span>
                  <div className="h-[1px] flex-1 bg-border border-dashed border-b"></div>
                  <span className="text-xs font-bold uppercase tracking-widest text-muted-foreground">
                    Lunch
                  </span>
                  <div className="h-[1px] flex-1 bg-border border-dashed border-b"></div>
                </div>
              );
            }

            const isCompleted = status === 'completed';
            const isLive = status === 'live';

            if (!filteredSlots || filteredSlots.length === 0) {
              return (
                <div
                  key={timeSlot}
                  className={`flex gap-4 group ${isCompleted ? 'opacity-40 grayscale' : ''}`}
                >
                  <div className="flex flex-col items-end w-12 shrink-0">
                    <span className="text-sm font-bold text-foreground">
                      {timeSlot.split('-')[0]}
                    </span>
                    <span className="text-[10px] text-muted-foreground">
                      {timeSlot.split('-')[1]}
                    </span>
                  </div>
                  {isLive ? (
                    <div className="flex-1 p-3 rounded-2xl border-2 border-primary bg-primary/5 flex items-center justify-center min-h-[80px] relative">
                      <span className="absolute -top-3 left-4 bg-primary text-primary-foreground text-[10px] px-2 py-0.5 rounded-full font-bold animate-pulse">
                        NOW
                      </span>
                      <span className="text-xs text-primary font-medium">Free Slot</span>
                    </div>
                  ) : (
                    <div className="flex-1 p-3 rounded-2xl border border-dashed border-border bg-muted/5 flex items-center justify-center min-h-[80px]">
                      <span className="text-xs text-muted-foreground/40 font-medium">
                        Free Slot
                      </span>
                    </div>
                  )}
                </div>
              );
            }

            return (
              <div key={timeSlot} className={`flex gap-4 ${isCompleted ? 'opacity-50' : ''}`}>
                <div className="flex flex-col items-end w-12 shrink-0">
                  <span
                    className={`text-sm font-bold ${isLive ? 'text-primary' : 'text-foreground'}`}
                  >
                    {timeSlot.split('-')[0]}
                  </span>
                  <span className="text-[10px] text-muted-foreground">
                    {timeSlot.split('-')[1]}
                  </span>
                  <div
                    className={`h-full w-[2px] my-2 rounded-full relative ${
                      isLive ? 'bg-primary' : isCompleted ? 'bg-primary/20' : 'bg-border'
                    }`}
                  >
                    <div
                      className={`absolute top-0 left-1/2 -translate-x-1/2 w-2 h-2 rounded-full ring-4 ring-background ${
                        isLive
                          ? 'bg-primary animate-ping'
                          : isCompleted
                            ? 'bg-primary/50'
                            : 'bg-primary'
                      }`}
                    />
                    {isLive && (
                      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-2 h-2 rounded-full bg-primary ring-4 ring-background" />
                    )}
                  </div>
                </div>
                <div className="flex-1 space-y-3 pb-6">
                  {filteredSlots.map((slot: any, idx: number) => (
                    <div
                      key={idx}
                      className={`relative overflow-hidden rounded-2xl border-l-4 p-4 transition-all
                        ${isLive ? 'bg-card border-l-primary shadow-lg ring-1 ring-primary/20' : ''}
                        ${!isLive && !isCompleted ? 'bg-card border-l-primary shadow-sm hover:shadow-md' : ''}
                        ${isCompleted ? 'bg-muted/10 border-l-muted-foreground/30 shadow-none' : ''}
                      `}
                      onClick={() => canManageAllTimetable && openSlotDialog(selectedDay, timeSlot)}
                    >
                      {isLive && (
                        <div className="absolute top-2 right-2 flex items-center gap-1.5 bg-primary/10 px-2 py-1 rounded-full">
                          <span className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
                          <span className="text-[10px] font-bold text-primary">LIVE</span>
                        </div>
                      )}
                      {isCompleted && (
                        <div className="absolute top-2 right-2 px-2 py-1 rounded-full bg-muted">
                          <span className="text-[10px] font-bold text-muted-foreground">
                            COMPLETED
                          </span>
                        </div>
                      )}
                      <div className="relative z-10">
                        <h4
                          className={`font-bold text-lg line-clamp-1 ${
                            isCompleted ? 'text-muted-foreground' : 'text-foreground'
                          }`}
                        >
                          {slot.courseName}
                        </h4>
                        <div className="flex items-center gap-2 mt-1 mb-3">
                          <Badge
                            variant={isCompleted ? 'outline' : 'secondary'}
                            className="text-[10px] uppercase tracking-wider font-bold"
                          >
                            {slot.courseCode}
                          </Badge>
                          <span className="text-xs text-muted-foreground">|</span>
                          <span
                            className={`text-xs font-medium px-2 py-0.5 rounded text-nowrap ${
                              isLive
                                ? 'text-primary bg-primary/10'
                                : 'text-muted-foreground bg-muted'
                            }`}
                          >
                            Room {slot.room}
                          </span>
                        </div>
                        <div className="flex items-center justify-between text-xs text-muted-foreground">
                          <div className="flex items-center gap-1.5">
                            <div
                              className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] text-white font-bold ${
                                isCompleted
                                  ? 'bg-gray-400'
                                  : 'bg-gradient-to-br from-primary to-purple-600'
                              }`}
                            >
                              {slot.facultyName?.[0] || '?'}
                            </div>
                            <span className="font-medium">{slot.facultyName || 'TBD'}</span>
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

'use client';
import { Button, Badge, Input, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from "@pec/ui";


import { useDeferredValue, useMemo, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
 Users as UsersIcon, UserPlus, Edit, Trash2, Download,
 Shield, ShieldOff, ShieldCheck, Loader2, Search
} from 'lucide-react';

import { toast } from 'sonner';
import { useRouter } from 'next/navigation';
import { useAction } from 'next-safe-action/hooks';
import {
 createUserAction, updateUserAction, deleteUserAction, changeStatusAction
} from './actions';

interface UserManagementViewProps {
 initialUsers: any[];
 isAdmin: boolean;
 isFaculty: boolean;
}

const emptyForm = {
 fullName: '', email: '', role: 'student' as const,
 department: '', employeeId: '', designation: '',
 enrollmentNumber: '', semester: undefined as number | undefined,
};

const ROLE_META: Record<string, { label: string; color: string }> = {
 student:    { label: 'Student',  color: 'bg-blue-500/10 text-blue-500 border-blue-500/20' },
 faculty:    { label: 'Faculty',  color: 'bg-purple-500/10 text-purple-500 border-purple-500/20' },
 college_admin: { label: 'Admin',   color: 'bg-red-500/10 text-red-500 border-red-500/20' },
 super_admin:  { label: 'Super Admin',color: 'bg-orange-500/10 text-orange-500 border-orange-500/20' },
};

const STATUS_META: Record<string, string> = {
 active:  'bg-success/10 text-success border-success/20',
 inactive: 'bg-muted/30 text-muted-foreground border-border',
 suspended: 'bg-destructive/10 text-destructive border-destructive/20',
};

export function UserManagementView({ initialUsers, isAdmin }: UserManagementViewProps) {
 const router = useRouter();
 const [users] = useState(initialUsers);
 const [searchTerm, setSearchTerm] = useState('');
 const [roleFilter, setRoleFilter] = useState('all');
 const [showDialog, setShowDialog] = useState(false);
 const [editingUser, setEditingUser] = useState<any>(null);
 const [form, setForm] = useState(emptyForm);
 const deferredSearch = useDeferredValue(searchTerm);

 const { execute: executeCreate, isPending: isCreating } = useAction(createUserAction, {
  onSuccess: () => { toast.success('User account created!'); setShowDialog(false); router.refresh(); },
  onError: ({ error }) => toast.error(error.serverError || 'Failed to create account.'),
 });

 const { execute: executeUpdate, isPending: isUpdating } = useAction(updateUserAction, {
  onSuccess: () => { toast.success('User updated.'); setShowDialog(false); router.refresh(); },
  onError: ({ error }) => toast.error(error.serverError || 'Update failed.'),
 });

 const { execute: executeDelete } = useAction(deleteUserAction, {
  onSuccess: () => { toast.success('User account deleted.'); router.refresh(); },
  onError: ({ error }) => toast.error(error.serverError || 'Failed to delete account.'),
 });

 const { execute: changeStatus } = useAction(changeStatusAction, {
  onSuccess: () => { toast.success('Status updated.'); router.refresh(); },
  onError: ({ error }) => toast.error(error.serverError || 'Status update failed.'),
 });

 const filteredUsers = useMemo(() => {
  const q = deferredSearch.trim().toLowerCase();
  return users.filter((u: any) => {
   const matchSearch = !q || u.fullName?.toLowerCase().includes(q) || u.email?.toLowerCase().includes(q);
   const matchRole = roleFilter === 'all' || u.role === roleFilter;
   return matchSearch && matchRole;
  });
 }, [deferredSearch, roleFilter, users]);

 const openEditDialog = (u: any) => {
  setEditingUser(u);
  setForm({ fullName: u.fullName, email: u.email, role: u.role || 'student', department: u.department || '', employeeId: u.employeeId || '', designation: u.designation || '', enrollmentNumber: u.enrollmentNumber || '', semester: u.semester });
  setShowDialog(true);
 };

 const handleSubmit = () => {
  if (editingUser) {
   executeUpdate({ ...form, id: editingUser.id });
  } else {
   executeCreate(form);
  }
 };

 const countByRole = (role: string) => users.filter((u: any) => u.role === role).length;

 return (
  <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-10">
   {/* Header */}
   <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
    <div>
     <h1 className="text-3xl font-bold tracking-tight">User Management</h1>
     <p className="text-muted-foreground font-medium italic text-[11px] mt-1">Manage institutional user accounts and access levels</p>
    </div>
    <div className="flex gap-3">
     <Button variant="outline" className="h-11 border-2 font-bold px-6 rounded-sm">
      <Download className="w-4 h-4 mr-2" /> Export
     </Button>
     {isAdmin && (
      <Button onClick={() => { setEditingUser(null); setForm(emptyForm); setShowDialog(true); }} className="h-11 bg-primary text-white font-bold text-[10px] uppercase tracking-widest rounded-sm px-6">
       <UserPlus className="w-4 h-4 mr-2" /> Add User
      </Button>
     )}
    </div>
   </div>

   {/* Stats */}
   <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
    {[
     { label: 'Total Users', value: users.length, icon: UsersIcon, color: 'primary' },
     { label: 'Students', value: countByRole('student'), icon: Shield, color: 'success' },
     { label: 'Faculty', value: countByRole('faculty'), icon: ShieldCheck, color: 'warning' },
     { label: 'Admins', value: countByRole('college_admin'), icon: ShieldOff, color: 'destructive' },
    ].map(({ label, value, icon: Icon, color }) => (
     <div key={label} className="card-elevated p-6 border-b-4 border-r-4 border-primary/10">
      <div className="flex items-center gap-4">
       <div className={`p-3 rounded-sm bg-${color}/10 border border-${color}/20`}><Icon className={`w-6 h-6 text-${color}`} /></div>
       <div>
        <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground/60">{label}</p>
        <p className="text-4xl font-bold mt-1">{value}</p>
       </div>
      </div>
     </div>
    ))}
   </div>

   {/* Filters */}
   <div className="flex flex-col md:flex-row gap-4">
    <div className="relative flex-1">
     <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
     <Input placeholder="Search users..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="h-14 pl-12 border-2 rounded-sm font-bold bg-background/50" />
    </div>
    <Select value={roleFilter} onValueChange={setRoleFilter}>
     <SelectTrigger className="h-14 border-2 rounded-sm font-bold w-full md:w-56 bg-background/50">
      <SelectValue placeholder="All Roles" />
     </SelectTrigger>
     <SelectContent className="border-2 rounded-sm">
      <SelectItem value="all" className="font-bold">All Roles</SelectItem>
      <SelectItem value="student" className="font-bold">Students</SelectItem>
      <SelectItem value="faculty" className="font-bold">Faculty</SelectItem>
      <SelectItem value="college_admin" className="font-bold">Administrators</SelectItem>
     </SelectContent>
    </Select>
   </div>

   {/* Table */}
   <div className="card-elevated border-2 rounded-sm overflow-hidden shadow-[12px_12px_0px_rgba(0,0,0,0.03)]">
    <div className="overflow-x-auto">
     <table className="w-full">
      <thead className="bg-muted/50 border-b-2 border-border">
       <tr>
        {['Name', 'Email Address', 'Role', 'Status', 'Actions'].map((h, i) => (
         <th key={h} className={`p-5 text-[10px] font-bold uppercase tracking-widest text-muted-foreground/60 ${i >= 4 ? 'text-right' : 'text-left'}`}>{h}</th>
        ))}
       </tr>
      </thead>
      <tbody className="divide-y divide-border">
       <AnimatePresence>
        {filteredUsers.length === 0 ? (
         <tr><td colSpan={5} className="p-20 text-center text-muted-foreground font-bold italic text-sm">No user accounts found.</td></tr>
        ) : filteredUsers.map((user: any) => (
         <motion.tr
          key={user.id}
          initial={{ opacity: 0, x: -10 }}
          animate={{ opacity: 1, x: 0 }}
          className="hover:bg-muted/20 transition-all border-l-4 border-transparent hover:border-primary cursor-pointer"
          onClick={() => router.push(`/users/${user.id}`)}
         >
          <td className="p-5 font-bold text-base tracking-tight">{user.fullName}</td>
          <td className="p-5 font-mono text-xs text-muted-foreground font-medium">{user.email}</td>
          <td className="p-5">
           <Badge className={`border rounded-sm font-bold uppercase text-[9px] tracking-widest px-4 py-1.5 ${ROLE_META[user.role]?.color || 'bg-muted text-muted-foreground'}`}>
            {ROLE_META[user.role]?.label || user.role || 'UNKNOWN'}
           </Badge>
          </td>
          <td className="p-5">
           <Badge className={`border rounded-sm font-bold uppercase text-[9px] tracking-widest px-4 py-1.5 ${STATUS_META[user.status || 'active']}`}>
            {(user.status || 'active').toUpperCase()}
           </Badge>
          </td>
          <td className="p-5" onClick={e => e.stopPropagation()}>
           <div className="flex items-center justify-end gap-2">
            {isAdmin && (
             <DropdownMenu>
              <DropdownMenuTrigger asChild>
               <Button variant="ghost" size="sm" className="hover:bg-primary/10 rounded-sm h-9 w-9 p-0">
                <Edit className="w-4 h-4" />
               </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="border-2 border-primary rounded-sm w-52 font-bold">
               <DropdownMenuItem onClick={() => openEditDialog(user)} className="cursor-pointer"><Edit className="w-4 h-4 mr-2" /> Edit Details</DropdownMenuItem>
               <DropdownMenuItem onClick={() => changeStatus({ id: user.id, status: user.status === 'active' ? 'suspended' : 'active' })} className="cursor-pointer">
                <ShieldOff className="w-4 h-4 mr-2" /> {user.status === 'active' ? 'Suspend Account' : 'Activate Account'}
               </DropdownMenuItem>
               <DropdownMenuSeparator />
               <DropdownMenuItem onClick={() => { if (confirm(`Delete user ${user.fullName}?`)) executeDelete({ id: user.id }); }} className="text-destructive cursor-pointer">
                <Trash2 className="w-4 h-4 mr-2" /> Delete Account
               </DropdownMenuItem>
              </DropdownMenuContent>
             </DropdownMenu>
            )}
           </div>
          </td>
         </motion.tr>
        ))}
       </AnimatePresence>
      </tbody>
     </table>
    </div>
    <div className="px-6 py-4 border-t-2 border-border bg-muted/30 flex items-center justify-between">
     <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
      Showing {filteredUsers.length} of {users.length} accounts
     </p>
    </div>
   </div>

   {/* Dialog */}
   <Dialog open={showDialog} onOpenChange={setShowDialog}>
    <DialogContent className="max-w-xl rounded-sm border-2 border-primary shadow-[20px_20px_0px_rgba(0,0,0,0.05)]">
     <DialogHeader className="space-y-3">
      <DialogTitle className="text-3xl font-bold">{editingUser ? 'Edit User details' : 'Add New User'}</DialogTitle>
      <DialogDescription className="text-[10px] font-bold uppercase tracking-widest bg-muted p-2 rounded-sm italic opacity-60">Institutional User Registration</DialogDescription>
     </DialogHeader>
     <div className="space-y-6 pt-4">
      <div className="space-y-2">
       <label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Full Name *</label>
       <Input value={form.fullName} onChange={e => setForm({ ...form, fullName: e.target.value })} className="h-12 border-2 rounded-sm font-bold" />
      </div>
      <div className="grid grid-cols-2 gap-6">
       <div className="space-y-2">
        <label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Email Address *</label>
        <Input type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} className="h-12 border-2 rounded-sm font-bold" />
       </div>
       <div className="space-y-2">
        <label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">User Role *</label>
        <Select value={form.role} onValueChange={(v: any) => setForm({ ...form, role: v })}>
         <SelectTrigger className="h-12 border-2 rounded-sm font-bold">
          <SelectValue />
         </SelectTrigger>
         <SelectContent className="border-2 rounded-sm">
          <SelectItem value="student" className="font-bold">STUDENT</SelectItem>
          <SelectItem value="faculty" className="font-bold">FACULTY</SelectItem>
          <SelectItem value="college_admin" className="font-bold">ADMINISTRATOR</SelectItem>
         </SelectContent>
        </Select>
       </div>
      </div>
      <div className="space-y-2">
       <label className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Department / Assignment</label>
       <Input value={form.department} onChange={e => setForm({ ...form, department: e.target.value })} className="h-12 border-2 rounded-sm font-bold" placeholder="e.g. CSE" />
      </div>
      <div className="flex gap-4 pt-6">
       <Button onClick={handleSubmit} disabled={isCreating || isUpdating} className="flex-1 h-14 bg-primary text-white font-bold uppercase tracking-widest text-[10px] rounded-sm">
        {(isCreating || isUpdating) && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
        {editingUser ? 'Save Changes' : 'Create Account'}
       </Button>
       <Button variant="outline" onClick={() => setShowDialog(false)} className="h-14 border-2 font-bold px-8 uppercase tracking-widest text-[10px] rounded-sm">Cancel</Button>
      </div>
     </div>
    </DialogContent>
   </Dialog>
  </motion.div>
 );
}

'use client';
import { Button, Badge } from "@pec/ui";


import { useRouter } from 'next/navigation';

import { 
  ArrowLeft, 
  Building2, 
  User, 
  BookOpen, 
  Award, 
} from 'lucide-react';

interface UserDetailViewProps {
  user: any;
  enrollments: any[];
  grades: any[];
  attendance: any[];
  payments: any[];
  hostelIssues: any[];
}

export function UserDetailView({ 
  user, 
  enrollments, 
  grades, 
}: UserDetailViewProps) {
  const router = useRouter();

  const getRoleBadgeColor = (role: string) => {
    switch (role) {
      case 'college_admin': return 'destructive';
      case 'faculty': return 'secondary';
      case 'student': return 'default';
      default: return 'outline';
    }
  };

  const formatDate = (date: any) => {
    if (!date) return 'N/A';
    return new Date(date).toLocaleDateString();
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="sm" onClick={() => router.push('/users')}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
          <div>
            <h1 className="text-2xl font-bold">{user.fullName}</h1>
            <p className="text-muted-foreground text-sm">{user.email}</p>
          </div>
        </div>
        <Badge variant={getRoleBadgeColor(user.role)}>
          {user.role?.toUpperCase()}
        </Badge>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <div className="card-elevated p-6 space-y-4">
          <h2 className="text-lg font-semibold flex items-center gap-2"><User className="w-5 h-5" /> Info</h2>
          <div className="space-y-2 text-sm">
             <p><span className="text-muted-foreground">Email:</span> {user.email}</p>
             <p><span className="text-muted-foreground">Phone:</span> {user.phone || 'N/A'}</p>
             <p><span className="text-muted-foreground">DOB:</span> {formatDate(user.dateOfBirth)}</p>
          </div>
        </div>
        <div className="card-elevated p-6 space-y-4">
          <h2 className="text-lg font-semibold flex items-center gap-2"><Building2 className="w-5 h-5" /> Academic</h2>
          <div className="space-y-2 text-sm">
             <p><span className="text-muted-foreground">Dept:</span> {user.department}</p>
             <p><span className="text-muted-foreground">Role:</span> {user.role}</p>
