interface RoleOption {
  value: UserRole;
  label: string;
  description: string;
  icon: any;
  color: string;
}

const roleOptions: RoleOption[] = [
  {
    value: 'student',
    label: 'Student',
    description: 'Access courses, attendance, grades, and placement opportunities',
    icon: GraduationCap,
    color: 'bg-foreground'
  },
  {
    value: 'faculty',
    label: 'Faculty',
