import { Button } from "@pec/ui";
import { StudentProfileView } from './ProfileView';
import { User } from 'lucide-react';

import Link from 'next/link';
import { getServerSession } from '@/lib/server-auth';

interface PageProps {
  params: Promise<{ id: string }>;
}

async function getStudentData(id: string, token?: string) {
  const API_URL = process.env.INTERNAL_API_URL || process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000";
  const base = API_URL.endsWith('/') ? API_URL.slice(0, -1) : API_URL;
  
  const headers: Record<string, string> = {
    'Content-Type': 'application/json'
  };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  try {
    const [userRes, profileRes, summaryRes] = await Promise.all([
      fetch(`${base}/users/${id}`, { headers, next: { revalidate: 60 } }),
      fetch(`${base}/student-profiles/${id}`, { headers, next: { revalidate: 60 } }),
      token ? fetch(`${base}/attendance/summary?studentId=${id}`, { headers, next: { revalidate: 60 } }) : Promise.resolve(null),
    ]);

    if (!userRes.ok) return null;
    const userData = (await userRes.json()).data;

    const profileData = profileRes?.ok ? (await profileRes.json()).data : null;
    const summaryData = summaryRes && summaryRes.ok ? (await summaryRes.json()).data : null;

    return { userData, profileData, summaryData };
  } catch (error) {
    console.error('Error fetching student server-side:', error);
    return null;
  }
}

async function getGithubStats(username: string) {
  if (!username) return null;
  try {
    const resp = await fetch(`https://api.github.com/users/${username.replace('@', '')}`, {
       next: { revalidate: 3600 } // Cache github stats for 1 hr
    });
    if (resp.ok) {
      const data = await resp.json();
      return {
        repos: data.public_repos,
        followers: data.followers,
        avatar: data.avatar_url,
      };
    }
  } catch (e) {
    console.error(e);
  }
  return null;
}

export default async function PublicStudentProfilePage({ params }: PageProps) {
  const { id } = await params;
  const session = await getServerSession();
  const data = await getStudentData(id, session?.token);

  if (!data || !data.userData) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-background p-4 text-center">
        <div className="w-16 h-16 bg-secondary rounded-full flex items-center justify-center mb-4">
          <User className="w-8 h-8 text-muted-foreground" />
        </div>
        <h1 className="text-2xl font-bold mb-2">User not found</h1>
        <p className="text-muted-foreground mb-6">The profile you are looking for does not exist.</p>
        <Link href="/">
          <Button>Go Home</Button>
        </Link>
      </div>
    );
  }

  const githubStats = data.profileData?.githubUsername 
    ? await getGithubStats(data.profileData.githubUsername)
    : null;

  const summary = data.summaryData;
  const stats = summary
    ? {
        attendance: summary.totalSummary?.percentage ?? null,
        credits: Array.isArray(summary.courses) ? summary.courses.length : null,
      }
    : null;

  return (
    <StudentProfileView 
      userData={data.userData}
      profileData={data.profileData || {}}
      stats={stats}
      githubStats={githubStats}
      currentUser={null} // We can get this from server cookies if needed
    />
  );
}

'use client';
import { Button, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@pec/ui";
import { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import Papa from 'papaparse';
import * as ExcelJS from 'exceljs';
import { Upload, FileSpreadsheet, CheckCircle, XCircle, AlertCircle, Download } from 'lucide-react';

interface BulkUploadProps {
  entityType: 'users' | 'courses' | 'departments' | 'faculty' | 'fees' | 'timetable' | 'attendance' | 'grades' | 'exams' | 'assignments' | 'materials' | 'jobs';
  onImport: (data: any[]) => Promise<{ success: number; failed: number; errors: string[] }>;
  templateColumns: string[];
  sampleData?: any[];
}

export default function BulkUpload({ entityType, onImport, templateColumns, sampleData }: BulkUploadProps) {
  const [uploadedData, setUploadedData] = useState<any[]>([]);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [showPreview, setShowPreview] = useState(false);
  const [importing, setImporting] = useState(false);
  const [importResult, setImportResult] = useState<{ success: number; failed: number; errors: string[] } | null>(null);

  const onDrop = useCallback((acceptedFiles: File[]) => {
    const file = acceptedFiles[0];
    if (!file) return;

    const fileExtension = file.name.split('.').pop()?.toLowerCase();

    if (fileExtension === 'csv') {
      Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: (results) => {
          validateAndSetData(results.data);
        },
        error: (error) => {
          setValidationErrors([`CSV Parse Error: ${error.message}`]);
        }
      });
    } else if (fileExtension === 'xlsx' || fileExtension === 'xls') {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const buffer = e.target?.result as ArrayBuffer;
        const workbook = new ExcelJS.Workbook();
        await workbook.xlsx.load(buffer);
        const worksheet = workbook.worksheets[0];
        
        const jsonData: any[] = [];
        const headers: string[] = [];
        
        worksheet.eachRow((row, rowNumber) => {
          if (rowNumber === 1) {
            row.eachCell((cell, colNumber) => {
              headers[colNumber] = cell.value?.toString() || `Column${colNumber}`;
            });
          } else {
            const rowData: any = {};
            row.eachCell((cell, colNumber) => {
              rowData[headers[colNumber]] = cell.value;
            });
            jsonData.push(rowData);
          }
        });
        validateAndSetData(jsonData);
      };
      reader.readAsArrayBuffer(file);
    }
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'text/csv': ['.csv'],
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
      'application/vnd.ms-excel': ['.xls']
    },
    maxFiles: 1
  });

  const validateAndSetData = (data: any[]) => {
    const errors: string[] = [];
    
    // Check if data is empty
    if (!data || data.length === 0) {
      errors.push('File is empty');
      setValidationErrors(errors);
      return;
    }

    // Check for required columns
    const firstRow = data[0];
    const missingColumns = templateColumns.filter(col => !(col in firstRow));
    
    if (missingColumns.length > 0) {
      errors.push(`Missing required columns: ${missingColumns.join(', ')}`);
    }

    // Validate each row
    data.forEach((row, index) => {
      templateColumns.forEach(col => {
        if (!row[col] || row[col].toString().trim() === '') {
          errors.push(`Row ${index + 2}: Missing value for "${col}"`);
        }
      });
    });

    setValidationErrors(errors);
    setUploadedData(data);
    setShowPreview(true);
  };

  const handleImport = async () => {
    if (validationErrors.length > 0) {
      return;
    }

    setImporting(true);
    try {
      const result = await onImport(uploadedData);
      setImportResult(result);
    } catch (error) {
      setImportResult({
        success: 0,
        failed: uploadedData.length,
        errors: [(error as Error).message]
      });
    } finally {
      setImporting(false);
    }
  };

  const downloadTemplate = async () => {
    const template = sampleData || [
      templateColumns.reduce((obj, col) => ({ ...obj, [col]: 'Sample' }), {})
    ];

    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet(entityType);
    
    worksheet.columns = templateColumns.map(col => ({ header: col, key: col }));
    template.forEach(row => worksheet.addRow(row));
    
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${entityType}_template.xlsx`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const resetUpload = () => {
    setUploadedData([]);
    setValidationErrors([]);
    setShowPreview(false);
    setImportResult(null);
  };

  return (
    <div className="space-y-4">
      {/* Download Template Button */}
      <div className="flex justify-end">
        <Button variant="outline" onClick={downloadTemplate} size="sm">
          <Download className="w-4 h-4 mr-2" />
          Download Template
        </Button>
      </div>

      {/* Upload Area */}
      <div
        {...getRootProps()}
        className={`border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-colors ${
          isDragActive ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/50'
        }`}
      >
        <input {...getInputProps()} />
        <Upload className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
        {isDragActive ? (
          <p className="text-lg font-medium">Drop the file here...</p>
        ) : (
          <>
            <p className="text-lg font-medium mb-2">Drag & drop CSV or Excel file here</p>
            <p className="text-sm text-muted-foreground">or click to browse</p>
          </>
        )}
        <div className="mt-4 flex items-center justify-center gap-2 text-xs text-muted-foreground">
          <FileSpreadsheet className="w-4 h-4" />
          Supports .csv, .xlsx, .xls
        </div>
      </div>

      {/* Preview Dialog */}
      <Dialog open={showPreview} onOpenChange={setShowPreview}>
        <DialogContent className="max-w-6xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Preview Import Data</DialogTitle>
            <DialogDescription>
              Review the data before importing. {uploadedData.length} records found.
            </DialogDescription>
          </DialogHeader>

          {/* Validation Errors */}
          {validationErrors.length > 0 && (
            <div className="bg-destructive/10 border border-destructive rounded-lg p-4">
              <div className="flex items-center gap-2 mb-2">
                <AlertCircle className="w-5 h-5 text-destructive" />
                <h4 className="font-semibold text-destructive">Validation Errors ({validationErrors.length})</h4>
              </div>
              <ul className="list-disc list-inside space-y-1 text-sm max-h-40 overflow-y-auto">
                {validationErrors.slice(0, 10).map((error, idx) => (
                  <li key={idx} className="text-destructive">{error}</li>
                ))}
                {validationErrors.length > 10 && (
                  <li className="text-muted-foreground">... and {validationErrors.length - 10} more errors</li>
                )}
              </ul>
            </div>
          )}

          {/* Import Result */}
          {importResult && (
            <div className={`border rounded-lg p-4 ${importResult.failed > 0 ? 'bg-destructive/10 border-destructive' : 'bg-success/10 border-success'}`}>
              <div className="flex items-center gap-2 mb-2">
                {importResult.failed > 0 ? (
                  <XCircle className="w-5 h-5 text-destructive" />
                ) : (
                  <CheckCircle className="w-5 h-5 text-success" />
                )}
                <h4 className="font-semibold">Import Results</h4>
              </div>
              <div className="space-y-1 text-sm">
                <p className="text-success">✓ {importResult.success} records imported successfully</p>
                <p className="text-destructive">✗ {importResult.failed} records failed</p>
              </div>
              {importResult.errors.length > 0 && (
                <ul className="list-disc list-inside mt-2 space-y-1 text-sm max-h-40 overflow-y-auto">
                  {importResult.errors.map((error, idx) => (
                    <li key={idx} className="text-destructive">{error}</li>
                  ))}
                </ul>
              )}
            </div>
          )}

          {/* Data Preview Table */}
          {!importResult && (
            <div className="border rounded-lg overflow-hidden">
              <div className="overflow-x-auto max-h-96">
                <table className="w-full text-sm">
                  <thead className="bg-muted/30 border-b sticky top-0">
                    <tr>
                      {templateColumns.map((col) => (
                        <th key={col} className="text-left p-3 font-medium text-muted-foreground whitespace-nowrap">
                          {col}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border">
                    {uploadedData.slice(0, 50).map((row, idx) => (
                      <tr key={idx} className="hover:bg-muted/20">
                        {templateColumns.map((col) => (
                          <td key={col} className="p-3 whitespace-nowrap">
                            {row[col] || <span className="text-muted-foreground italic">empty</span>}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {uploadedData.length > 50 && (
                <div className="p-3 bg-muted/20 text-center text-sm text-muted-foreground">
                  Showing first 50 of {uploadedData.length} records
                </div>
              )}
            </div>
          )}

          {/* Actions */}
          <div className="flex gap-2 pt-4">
            {!importResult ? (
              <>
                <Button
                  onClick={handleImport}
                  disabled={validationErrors.length > 0 || importing}
                  className="flex-1"
                >
                  {importing ? 'Importing...' : `Import ${uploadedData.length} Records`}
                </Button>
                <Button variant="outline" onClick={resetUpload}>
                  Cancel
                </Button>
              </>
            ) : (
              <Button onClick={() => { resetUpload(); setShowPreview(false); }} className="flex-1">
                Close
              </Button>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { Button } from "@pec/ui";
import React from "react";
import { AlertTriangle, RefreshCw } from "lucide-react";

interface ErrorBoundaryState {
  hasError: boolean;
}

export class ErrorBoundary extends React.Component<
  React.PropsWithChildren,
  ErrorBoundaryState
> {
  state: ErrorBoundaryState = { hasError: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("Unhandled UI error:", error, errorInfo);
  }

  private handleReload = () => {
    window.location.reload();
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-background flex items-center justify-center px-4">
          <div className="max-w-md w-full card-elevated p-8 text-center space-y-4">
            <div className="w-14 h-14 rounded-2xl bg-destructive/10 text-destructive mx-auto flex items-center justify-center">
              <AlertTriangle className="w-7 h-7" />
            </div>
            <div className="space-y-2">
              <h1 className="text-2xl font-semibold text-foreground">
                Something went wrong
              </h1>
              <p className="text-sm text-muted-foreground">
                The page hit an unexpected error. Reload to recover.
              </p>
            </div>
            <Button onClick={this.handleReload} className="w-full">
              <RefreshCw className="w-4 h-4 mr-2" />
              Reload App
            </Button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

'use client';
import { Button } from "@pec/ui";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useEffect, useState } from "react";
import { safeLocalStorage } from "@/lib/ssr-safe";

// Unified accent color themes - must match index.css definitions
const accentThemes = [
  { id: "pec-gold", name: "PEC Gold", color: "#F59E0B" },
  { id: "emerald", name: "Emerald", color: "#10B981" },
  { id: "sapphire", name: "Sapphire", color: "#3B82F6" },
  { id: "amethyst", name: "Amethyst", color: "#8B5CF6" },
];

/**
 * Apply an accent theme class to the document root.
 * Guarded with typeof document check — safe to call in useEffect.
 */
function applyAccentTheme(accentId: string) {
  if (typeof document === 'undefined') return;
  const root = document.documentElement;
  accentThemes.forEach(({ id }) => root.classList.remove(`accent-${id}`));
  root.classList.add(`accent-${accentId}`);
}

export function LandingColorTheme() {
  // SSR-SAFE: Default to 0, hydrate from localStorage in useEffect.
  // If we read localStorage in useState initializer, server renders index 0
  // but client may have a saved value → hydration mismatch.
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const rawSavedAccent = safeLocalStorage.get("accent-color");
    const savedAccent = !rawSavedAccent || rawSavedAccent === "golden" ? "pec-gold" : rawSavedAccent;
    const index = accentThemes.findIndex((t) => t.id === savedAccent);
    if (index !== -1) {
      setCurrentIndex(index);
      applyAccentTheme(savedAccent);
      safeLocalStorage.set("accent-color", savedAccent);
    }
  }, []);

  const cycleTheme = (direction: "next" | "prev") => {
    const newIndex =
      direction === "next"
        ? (currentIndex + 1) % accentThemes.length
        : (currentIndex - 1 + accentThemes.length) % accentThemes.length;

    const newTheme = accentThemes[newIndex];
    setCurrentIndex(newIndex);
    safeLocalStorage.set("accent-color", newTheme.id);
    applyAccentTheme(newTheme.id);
  };

  const currentTheme = accentThemes[currentIndex];

  return (
    <div className="flex items-center gap-1 bg-accent/10 rounded-lg p-0.5 border border-accent/20">
      <Button
        variant="ghost"
        size="icon"
        className="h-6 w-6 hover:bg-accent/20 text-muted-foreground hover:text-accent"
        onClick={() => cycleTheme("prev")}
        title="Previous Color"
      >
        <ChevronLeft className="h-3 w-3" />
      </Button>

      <div className="flex items-center justify-center w-6 h-6">
        <div
          className="w-3 h-3 rounded-full shadow-sm ring-2 ring-background transition-all"
          style={{ backgroundColor: currentTheme?.color }}
          title={currentTheme?.name}
        />
      </div>

      <Button
        variant="ghost"
        size="icon"
        className="h-6 w-6 hover:bg-accent/20 text-muted-foreground hover:text-accent"
        onClick={() => cycleTheme("next")}
        title="Next Color"
      >
        <ChevronRight className="h-3 w-3" />
      </Button>
    </div>
  );
}

import { motion } from 'framer-motion';
import { ReactNode } from 'react';

interface ScrollRevealProps {
  children: ReactNode;
  direction?: 'up' | 'down' | 'left' | 'right' | 'scale' | 'fade';
  delay?: number;
  duration?: number;
  distance?: number;
  className?: string;
  stagger?: number;
  once?: boolean;
}

/** 
 * Modular ScrollReveal using Framer Motion. 
 * Provides declarative scroll-triggered animations.
 */
export const ScrollReveal: React.FC<ScrollRevealProps> = ({
  children,
  direction = 'up',
  delay = 0,
  duration = 0.8,
  distance = 50,
  className = '',
  stagger = 0,
  once = true,
}) => {
  const getVariants = () => {
    const initial: any = { opacity: 0 };
    switch (direction) {
      case 'up': initial.y = distance; break;
      case 'down': initial.y = -distance; break;
      case 'left': initial.x = distance; break;
      case 'right': initial.x = -distance; break;
      case 'scale': initial.scale = 0.8; break;
    }
    return {
      hidden: initial,
      visible: {
        opacity: 1,
        x: 0,
        y: 0,
        scale: 1,
        transition: {
          delay,
          duration,
          ease: "easeInOut" as const,
          staggerChildren: stagger,
        }
      }
    };
  };

  return (
    <motion.div
      initial="hidden"
      whileInView="visible"
      viewport={{ once, margin: "-100px" }}
      variants={getVariants()}
      className={className}
    >
      {children}
    </motion.div>
  );
};

