import { Button, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@pec/ui";
import React, { useState, useCallback } from 'react';
import { Upload, X, FileText, AlertCircle, CheckCircle, Loader2 } from 'lucide-react';

import { toast } from 'sonner';
import Papa from 'papaparse';

interface PDFImportDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  entityType: string;
  onImport: (data: any[]) => Promise<{ success: number; failed: number; errors: string[] }>;
  templateColumns: string[];
  sampleData?: any[];
}

export default function PDFImportDialog({
  open,
  onOpenChange,
  entityType,
  onImport,
  templateColumns,
  sampleData = []
}: PDFImportDialogProps) {
  const [file, setFile] = useState<File | null>(null);
  const [importing, setImporting] = useState(false);
  const [dragActive, setDragActive] = useState(false);
  const [parsedData, setParsedData] = useState<any[]>([]);
  const [importResult, setImportResult] = useState<{
    success: number;
    failed: number;
    errors: string[];
  } | null>(null);

  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, []);

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  const handleFile = (selectedFile: File) => {
    const fileExtension = selectedFile.name.split('.').pop()?.toLowerCase();
    
    if (fileExtension !== 'csv') {
      toast.error('Please upload a CSV file');
      return;
    }

    setFile(selectedFile);
    parseCSV(selectedFile);
  };

  const parseCSV = (csvFile: File) => {
    Papa.parse(csvFile, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.errors.length > 0) {
          toast.error('Error parsing CSV file');
          console.error('CSV Parse Errors:', results.errors);
          return;
        }

        // Validate columns
        const fileColumns = Object.keys(results.data[0] || {});
        const missingColumns = templateColumns.filter(col => !fileColumns.includes(col));
        
        if (missingColumns.length > 0) {
          toast.error(`Missing required columns: ${missingColumns.join(', ')}`);
          return;
        }

        setParsedData(results.data as any[]);
        toast.success(`Parsed ${results.data.length} rows successfully`);
      },
      error: (error) => {
        toast.error('Failed to parse CSV file');
        console.error('Parse Error:', error);
      }
    });
  };

  const handleImport = async () => {
    if (parsedData.length === 0) {
      toast.error('No data to import');
      return;
    }

    setImporting(true);
    try {
      const result = await onImport(parsedData);
      setImportResult(result);
      
      if (result.success > 0) {
        toast.success(`Successfully imported ${result.success} ${entityType}(s)`);
      }
      if (result.failed > 0) {
        toast.error(`Failed to import ${result.failed} ${entityType}(s)`);
      }
    } catch (error) {
      toast.error('Import failed');
      console.error('Import Error:', error);
    } finally {
      setImporting(false);
    }
  };

  const downloadTemplate = () => {
    const csv = Papa.unparse({
      fields: templateColumns,
      data: sampleData.length > 0 ? sampleData : [templateColumns.reduce((obj, col) => ({ ...obj, [col]: '' }), {})]
    });

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${entityType}_import_template.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const reset = () => {
    setFile(null);
    setParsedData([]);
    setImportResult(null);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Import {entityType}</DialogTitle>
          <DialogDescription>
            Upload a CSV file to bulk import {entityType}. Download the template to see the required format.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* Template Download */}
          <div className="flex justify-between items-center p-4 border border-border rounded-lg bg-muted/20">
            <div className="flex items-center gap-2">
              <FileText className="w-5 h-5 text-primary" />
              <div>
                <p className="font-medium text-sm">Download Template</p>
                <p className="text-xs text-muted-foreground">
                  Required columns: {templateColumns.join(', ')}
                </p>
              </div>
            </div>
            <Button variant="outline" size="sm" onClick={downloadTemplate}>
              Download
            </Button>
          </div>

          {/* File Upload Area */}
          <div
            className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${
              dragActive ? 'border-primary bg-primary/5' : 'border-border'
            }`}
            onDragEnter={handleDrag}
            onDragLeave={handleDrag}
            onDragOver={handleDrag}
            onDrop={handleDrop}
          >
            {!file ? (
              <>
                <Upload className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
                <p className="text-sm font-medium mb-1">
                  Drag and drop your CSV file here
                </p>
                <p className="text-xs text-muted-foreground mb-4">or</p>
                <label>
                  <Button variant="outline" size="sm" asChild>
                    <span>Browse Files</span>
                  </Button>
                  <input
                    type="file"
                    accept=".csv"
                    onChange={handleFileInput}
                    className="hidden"
                  />
                </label>
              </>
            ) : (
              <div className="space-y-4">
                <div className="flex items-center justify-between p-3 bg-background border border-border rounded">
                  <div className="flex items-center gap-2">
                    <FileText className="w-5 h-5 text-primary" />
                    <div className="text-left">
                      <p className="text-sm font-medium">{file.name}</p>
                      <p className="text-xs text-muted-foreground">
                        {parsedData.length} rows parsed
                      </p>
                    </div>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={reset}
                    disabled={importing}
                  >
                    <X className="w-4 h-4" />
                  </Button>
                </div>

                {parsedData.length > 0 && (
                  <div className="text-left p-3 bg-success/10 border border-success/20 rounded">
                    <div className="flex items-start gap-2">
                      <CheckCircle className="w-5 h-5 text-success mt-0.5" />
                      <div>
                        <p className="text-sm font-medium text-success">
                          File validated successfully
                        </p>
                        <p className="text-xs text-muted-foreground mt-1">
                          Ready to import {parsedData.length} {entityType}(s)
                        </p>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Import Result */}
          {importResult && (
            <div className="space-y-2">
              {importResult.success > 0 && (
                <div className="p-3 bg-success/10 border border-success/20 rounded">
                  <div className="flex items-center gap-2">
                    <CheckCircle className="w-5 h-5 text-success" />
                    <p className="text-sm font-medium text-success">
                      Successfully imported {importResult.success} {entityType}(s)
                    </p>
                  </div>
                </div>
              )}
              
              {importResult.failed > 0 && (
                <div className="p-3 bg-destructive/10 border border-destructive/20 rounded">
                  <div className="flex items-start gap-2">
                    <AlertCircle className="w-5 h-5 text-destructive mt-0.5" />
                    <div className="flex-1">
                      <p className="text-sm font-medium text-destructive mb-2">
                        Failed to import {importResult.failed} {entityType}(s)
                      </p>
                      {importResult.errors.length > 0 && (
                        <div className="text-xs text-muted-foreground space-y-1 max-h-32 overflow-y-auto">
                          {importResult.errors.slice(0, 5).map((error, idx) => (
                            <p key={idx}>• {error}</p>
                          ))}
                          {importResult.errors.length > 5 && (
                            <p>... and {importResult.errors.length - 5} more errors</p>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Actions */}
          <div className="flex justify-end gap-2 pt-4">
            <Button
              variant="outline"
              onClick={() => {
                reset();
                onOpenChange(false);
              }}
              disabled={importing}
            >
              Cancel
            </Button>
            <Button
              onClick={handleImport}
              disabled={!file || parsedData.length === 0 || importing}
            >
              {importing ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Importing...
                </>
              ) : (
                `Import ${parsedData.length} ${entityType}(s)`
              )}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import Link from "next/link";
import { usePathname, useParams } from "next/navigation";
import {
  LayoutDashboard,
  MessageCircle,
  User,
  UtensilsCrossed,
} from "lucide-react";
import { cn } from "@/lib/utils";

export function BottomNav() {
  const pathname = usePathname() || "/";
  const params = useParams<{ orgSlug?: string | string[] }>();
  const orgSlug = typeof params?.orgSlug === "string" ? params.orgSlug : null;

  const navItems = [
    {
      label: "Home",
      icon: LayoutDashboard,
      path: "/dashboard",
    },
    {
      label: "Chat",
      icon: MessageCircle,
      path: "/chat",
    },
    {
      label: "Canteen",
      icon: UtensilsCrossed,
      path: "/canteen",
    },
    {
      label: "Profile",
      icon: User,
      path: "/profile",
    },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 z-50 bg-background/80 backdrop-blur-lg border-t border-border lg:hidden pb-safe">
      <nav className="flex justify-around items-center h-16 px-1">
        {navItems.map((item) => {
          const orgPrefix = orgSlug ? `/${orgSlug}` : "";
          const currentPath =
            orgPrefix && pathname.startsWith(orgPrefix)
              ? pathname.slice(orgPrefix.length) || "/"
              : pathname;

          const itemPath = item.path || "/";
          const isActive =
            currentPath === itemPath || currentPath.startsWith(itemPath + "/");
          const finalPath = orgSlug ? `/${orgSlug}${itemPath}` : itemPath;

          return (
            <Link
              key={itemPath}
              href={finalPath as any}
              className={cn(
                "flex flex-col items-center justify-center w-full h-full gap-1 active:scale-95 transition-transform",
                isActive
                  ? "text-primary"
                  : "text-muted-foreground hover:text-foreground",
              )}
            >
              <div className="relative">
                <item.icon
                  className={cn("w-6 h-6", isActive && "fill-current")}
                />
                {isActive && (
                  <div className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-1 h-1 bg-primary rounded-full" />
                )}
              </div>
              <span className="text-[10px] font-medium">{item.label}</span>
            </Link>
          );
        })}
      </nav>
    </div>
  );
}

import { Button, Input, CommandDialog, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList, CommandSeparator, CommandShortcut } from "@pec/ui";
import { useEffect, useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import { Search } from 'lucide-react';

type SearchableRoute = {
  title: string;
  path: string;
  icon: React.ComponentType<{ className?: string }>;
  keywords: string[];
};

export default function CommandMenu() {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [routes, setRoutes] = useState<SearchableRoute[]>([]);

  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setOpen((prevOpen) => !prevOpen);
      }
    };

    document.addEventListener('keydown', down);
    return () => document.removeEventListener('keydown', down);
  }, []);

  useEffect(() => {
    if (!open || routes.length > 0) return;

    let cancelled = false;
    void import('@/utils/searchableRoutes').then((mod) => {
      if (!cancelled) {
        setRoutes(mod.searchableRoutes as SearchableRoute[]);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [open, routes.length]);

  const filteredRoutes = useMemo(() => {
    const normalized = query.toLowerCase();
    return routes
      .filter(
        (route) =>
          route.title.toLowerCase().includes(normalized) ||
          route.keywords.some((keyword) => keyword.includes(normalized)),
      )
      .slice(0, 5);
  }, [query, routes]);

  return (
    <>
      <div className="relative" onClick={() => setOpen(true)}>
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input
          placeholder="Search... (Ctrl+K)"
          className="pl-10 bg-white/5 border border-white/10 shadow-sm hover:bg-white/10 transition-colors focus-visible:ring-1 focus-visible:ring-primary cursor-pointer text-foreground placeholder:text-muted-foreground"
          readOnly
        />
      </div>

      <CommandDialog open={open} onOpenChange={setOpen}>
        <CommandInput
          placeholder="Type to search pages, students, or data..."
          value={query}
          onValueChange={setQuery}
        />
        <CommandList>
          <CommandEmpty>
            <div className="py-2 px-4 text-sm">
              No results found.
              <Button
                variant="link"
                className="px-1 h-auto font-normal text-primary"
                onClick={() => {
                  setOpen(false);
                  router.push(`/search?q=${encodeURIComponent(query)}`);
                }}
              >
                Search for &quot;{query}&quot;
              </Button>
            </div>
          </CommandEmpty>

          <CommandGroup heading="Pages">
            {filteredRoutes.map((route) => (
              <CommandItem
                key={route.path}
                onSelect={() => {
                  setOpen(false);
                  router.push(route.path as any);
                }}
              >
                <route.icon className="mr-2 h-4 w-4" />
                <span>{route.title}</span>
              </CommandItem>
            ))}
          </CommandGroup>

          <CommandSeparator />

          <CommandGroup heading="Actions">
            <CommandItem
              onSelect={() => {
                setOpen(false);
                router.push(`/search?q=${encodeURIComponent(query)}`);
              }}
            >
              <Search className="mr-2 h-4 w-4" />
              <span>Search all for &quot;{query}&quot;</span>
              <CommandShortcut>↵</CommandShortcut>
            </CommandItem>
          </CommandGroup>
        </CommandList>
      </CommandDialog>
    </>
  );
}

