function NoticePreviewList({ router }: { router: any }) {
  const [notices, setNotices] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    void (async () => {
      try {
        const res = await api.get('/noticeboard', { params: { limit: 4, offset: 0 } });
        setNotices(res?.data?.data || []);
      } catch {
        // Silently skip
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  if (loading) return (
    <div className="py-8 text-center text-[10px] uppercase font-bold tracking-widest text-muted-foreground/30 animate-pulse">
      Securing Updates...
    </div>
  );

  if (notices.length === 0) return (
    <div className="py-12 text-center">
      <Bell className="w-8 h-8 mx-auto mb-2 opacity-10" />
      <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground opacity-40">System Clear</p>
    </div>
  );

  return (
    <div className="space-y-1">
      {notices.map((n, i) => (
        <button
          key={n.id || i}
          className="w-full text-left p-3 hover:bg-secondary transition-colors group flex items-start gap-3 rounded-sm"
          onClick={() => router.push(`/noticeboard#${n.id}`)}
        >
          <div className={cn(
            "mt-1 w-2 h-2 rounded-full flex-shrink-0",
            n.important ? "bg-destructive animate-pulse" : (n.pinned ? "bg-primary" : "bg-muted-foreground/30")
          )} />
          <div className="space-y-1 min-w-0 flex-1">
            <h4 className="text-xs font-bold text-foreground line-clamp-1 group-hover:text-primary transition-colors uppercase tracking-tight">
              {n.title}
            </h4>
            <p className="text-[10px] text-muted-foreground line-clamp-2 leading-[1.3] font-medium opacity-80">
              {n.content}
            </p>
            <div className="flex items-center gap-2 pt-1">
              <span className="text-[9px] font-bold uppercase text-muted-foreground/50 tracking-widest">
                {new Date(n.publishedAt || n.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
              </span>
              {n.category && (
                <span className="text-[8px] font-bold uppercase py-0.5 px-1.5 bg-muted/40 border border-border/40 text-muted-foreground/80 tracking-widest rounded-sm">
                  {n.category}
                </span>
              )}
            </div>
          </div>
        </button>
      ))}
    </div>
  );
}

'use client';

import { usePathname, useSearchParams } from 'next/navigation';
import { MouseEvent as ReactMouseEvent, useEffect, useMemo, useRef, useState, Suspense } from 'react';
import { Loader } from '@pec/ui';

const isModifiedEvent = (event: MouseEvent | ReactMouseEvent) =>
  event.metaKey || event.ctrlKey || event.shiftKey || event.altKey;

function RouteTransitionLoaderInner() {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const [isNavigating, setIsNavigating] = useState(false);

  const currentRouteKey = useMemo(() => {
    const params = searchParams.toString();
    return `${pathname}${params ? `?${params}` : ''}`;
  }, [pathname, searchParams]);

  const previousRouteKeyRef = useRef(currentRouteKey);
  const startTimerRef = useRef<number | null>(null);
  const mountedRef = useRef(false);

  const startNavigation = () => {
    if (!mountedRef.current) return;
    if (startTimerRef.current !== null) {
      window.clearTimeout(startTimerRef.current);
    }
    // Defer state update so we don't flash for fast loads (200ms threshold)
    startTimerRef.current = window.setTimeout(() => {
      if (mountedRef.current) {
        setIsNavigating(true);
      }
      startTimerRef.current = null;
    }, 200);
  };

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      if (startTimerRef.current !== null) {
        window.clearTimeout(startTimerRef.current);
        startTimerRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (previousRouteKeyRef.current !== currentRouteKey) {
      setIsNavigating(false);
      previousRouteKeyRef.current = currentRouteKey;
      if (startTimerRef.current !== null) {
        window.clearTimeout(startTimerRef.current);
        startTimerRef.current = null;
      }
    }
  }, [currentRouteKey]);

  useEffect(() => {
    if (!isNavigating) return;
    const timeout = window.setTimeout(() => setIsNavigating(false), 15000);
    return () => window.clearTimeout(timeout);
  }, [isNavigating]);

  useEffect(() => {
    const handleDocumentClick = (event: MouseEvent) => {
      if (event.defaultPrevented || event.button !== 0 || isModifiedEvent(event)) {
        return;
      }

      const target = event.target as HTMLElement | null;
      const anchor = target?.closest('a[href]') as HTMLAnchorElement | null;
      if (!anchor) {
        return;
      }

      if (anchor.target && anchor.target !== '_self') {
        return;
      }

      if (anchor.hasAttribute('download') || anchor.getAttribute('rel')?.includes('external')) {
        return;
      }

      const nextUrl = new URL(anchor.href, window.location.href);
      const isInternal = nextUrl.origin === window.location.origin;
      const isSameRoute =
        nextUrl.pathname === window.location.pathname && nextUrl.search === window.location.search;

      if (!isInternal || isSameRoute) {
        return;
      }

      startNavigation();
    };

    const handlePopState = () => {
      startNavigation();
    };

    document.addEventListener('click', handleDocumentClick, true);
    window.addEventListener('popstate', handlePopState);

    return () => {
      document.removeEventListener('click', handleDocumentClick, true);
      window.removeEventListener('popstate', handlePopState);
    };
  }, []);

  useEffect(() => {
    const originalPushState = window.history.pushState;
    const originalReplaceState = window.history.replaceState;

    const shouldStartForUrl = (url: string | URL | null | undefined) => {
      if (!url) return false;
      const nextUrl = new URL(url.toString(), window.location.href);
      const isInternal = nextUrl.origin === window.location.origin;
      const isDifferentRoute =
        nextUrl.pathname !== window.location.pathname || nextUrl.search !== window.location.search;
      return isInternal && isDifferentRoute;
    };

    window.history.pushState = function (...args) {
      if (shouldStartForUrl(args[2])) {
        startNavigation();
      }
      return originalPushState.apply(this, args);
    };

    window.history.replaceState = function (...args) {
      if (shouldStartForUrl(args[2])) {
        startNavigation();
      }
      return originalReplaceState.apply(this, args);
    };

    return () => {
      window.history.pushState = originalPushState;
      window.history.replaceState = originalReplaceState;
    };
  }, []);

  if (!isNavigating) {
    return null;
  }

  return (
    <div role="status" aria-live="polite" aria-label="Loading page">
      <Loader />
    </div>
  );
}

export function RouteTransitionLoader() {
  return (
    <Suspense fallback={null}>
      <RouteTransitionLoaderInner />
    </Suspense>
  );
}

