export function Sidebar({
  role,
  collapsed,
  onToggle,
  isMobile,
  mobileMenuOpen,
  onMobileClose,
  width,
  onWidthChange,
}: SidebarProps) {
  const { ability } = useAuth();
  const location = usePathname();
  const appLogoSrc = '/logo.png';

  const [isResizing, setIsResizing] = useState(false);
  const sidebarRef = useRef<HTMLElement>(null);

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsResizing(true);
  }, []);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizing) return;

      const newWidth = e.clientX;
      if (newWidth >= MIN_WIDTH && newWidth <= MAX_WIDTH) {
        onWidthChange(newWidth);
        localStorage.setItem(SIDEBAR_WIDTH_KEY, newWidth.toString());
      }
    };

    const handleMouseUp = () => {
      setIsResizing(false);
    };

    if (isResizing) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'ew-resize';
      document.body.style.userSelect = 'none';
    }

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
  }, [isResizing]);

  const filteredItems = navItems.filter((item) => {
    if (!item.permission) return true;
    if (!ability) return false;
    return ability.can(item.permission.action, item.permission.subject as any);
  });

  const sectionConfig: Array<{ title: string; paths: string[] }> = [
    {
      title: 'Core',
      paths: [
        '/dashboard',
        '/profile',
        '/chat',
        '/noticeboard',
        '/clubs',
        '/users',
        '/departments',
        '/faculty',
      ],
    },
    {
      title: 'Academics',
      paths: [
        '/courses',
        '/academic-schedule',
        '/attendance',
        '/score-sheet',
        '/course-materials',
        '/resume-builder',
      ],
    },
    {
      title: 'Campus',
      paths: [
        '/finance',
        '/marketplace',
        '/hostel-issues',
        '/canteen',
        '/campus-map',
        '/admin/canteen',
        '/admin/hostel',
      ],
    },
    {
      title: 'System',
      paths: ['/settings', '/help', '/admin/observability', '/admin/academic-calendar', '/admin/roles'],
    },
  ];

  const groupedItems = sectionConfig
    .map((section) => ({
      title: section.title,
      items: filteredItems.filter((item) => section.paths.includes(item.path)),
    }))
    .filter((section) => section.items.length > 0);

  const renderNavItem = (item: NavItem) => {
    const currentPath = location ?? '';
    let isActive = false;

    if (item.path === '/settings') {
      isActive =
        currentPath === item.path ||
        currentPath === '/admin/college-settings' ||
        currentPath === '/admin/hostel';
    } else if (item.path === '/departments') {
      isActive = currentPath === item.path || currentPath.startsWith('/departments/');
    } else if (item.path === '/faculty') {
      isActive = currentPath === item.path || currentPath.startsWith('/faculty/');
    } else {
      isActive =
        currentPath === item.path ||
        currentPath.startsWith(item.path + '/') ||
        (item.path !== '/' && currentPath.startsWith(item.path));
    }

    return (
      <li key={item.path} className={cn(!collapsed && 'flex')}>
        <Link
          href={item.path as any}
          className={cn(
            'sidebar-item group',
            !collapsed && 'w-full',
            collapsed && 'justify-center gap-0 px-0',
            isActive && 'sidebar-item-active'
          )}
        >
          {(() => {
            const Icon = item.icon as any;
            return (
              <div
                className={cn(
                  'flex items-center',
                  collapsed ? 'justify-center w-full' : 'w-full px-2'
                )}
              >
                {collapsed ? (
                  <Icon
                    className={cn(
                      'w-5 h-5 shrink-0 transition-all duration-300',
                      isActive
                        ? 'text-primary scale-110 drop-shadow-[0_0_8px_hsl(var(--primary)/0.5)]'
                        : 'text-sidebar-foreground/60 group-hover:text-sidebar-foreground group-hover:scale-110'
                    )}
                    strokeWidth={isActive ? 2.5 : 1.8}
                  />
                ) : (
                  <AnimatePresence mode="wait">
                    <motion.span
                      initial={{ opacity: 0, x: -5 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, x: -5 }}
                      className="swiss-nav-label truncate"
                    >
                      {item.label}
                    </motion.span>
                  </AnimatePresence>
                )}
              </div>
            );
          })()}
        </Link>
      </li>
    );
  };

  return (
    <>
      {/* Backdrop for mobile */}
      <AnimatePresence>
        {isMobile && mobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onMobileClose}
            className="fixed inset-0 z-[90] bg-background/70 lg:hidden"
          />
        )}
      </AnimatePresence>

      <aside
        ref={sidebarRef}
        className={cn(
          'fixed left-0 top-0 z-[100] h-screen bg-sidebar border-r border-sidebar-border transition-all duration-300 flex flex-col shadow-sm',
          isMobile && !mobileMenuOpen && '-translate-x-full',
          isMobile && mobileMenuOpen && 'translate-x-0'
        )}
        style={{
          width: collapsed ? undefined : width,
          minWidth: collapsed ? undefined : width,
          maxWidth: collapsed ? undefined : width,
        }}
      >
        {/* Mesh Atmosphere */}
        <div className="sidebar-mesh" aria-hidden="true" />
        {/* Resize Handle */}
        {!isMobile && !collapsed && (
          <div
            onMouseDown={handleMouseDown}
            onClick={(e) => e.stopPropagation()}
            className={cn(
              'absolute top-0 right-0 w-1 h-full cursor-ew-resize group z-10',
              'hover:bg-primary/20',
              'flex items-center justify-center',
              isResizing && 'bg-primary/30'
            )}
          >
            <GripVertical className="w-3 h-3 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity" />
          </div>
        )}

        {/* Sidebar Header Controls */}
        <div
          className={cn(
            'min-h-20 flex items-center border-b border-sidebar-border shrink-0',
            collapsed ? 'justify-center px-2' : 'justify-between px-4'
          )}
        >
          {isMobile ? (
            <button
              onClick={onMobileClose}
              className="p-1.5 hover:bg-sidebar-accent transition-colors"
              title="Close menu"
            >
              <X className="w-5 h-5 text-sidebar-foreground" />
            </button>
          ) : collapsed ? (
            <button
              onClick={onToggle}
              className="p-2 hover:bg-sidebar-accent transition-colors"
              title="Expand sidebar"
            >
              <ChevronRight className="w-5 h-5 text-sidebar-foreground" />

              <span className="sr-only">Expand sidebar</span>
            </button>
          ) : (
            <>
              <div className="h-10 w-10 shrink-0 relative overflow-hidden flex items-center justify-center">
                <Image
                  src={appLogoSrc}
                  alt="App logo"
                  fill
                  sizes="40px"
                  className="object-contain"
                  priority
                />
              </div>
              <button
                onClick={onToggle}
                className="p-1.5 hover:bg-sidebar-accent transition-colors"
                title="Collapse sidebar"
              >
                <ChevronLeft className="w-4 h-4 text-sidebar-foreground" />
              </button>
            </>
          )}
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto py-3 px-2.5">
          {collapsed || isMobile ? (
            <ul className="space-y-0.5">{filteredItems.map(renderNavItem)}</ul>
          ) : (
            <div className="space-y-3">
              {groupedItems.map((section) => (
                <div key={section.title}>
                  <p className="sidebar-section-label px-2 pb-1">{section.title}</p>
                  <ul className="space-y-0.5">{section.items.map(renderNavItem)}</ul>
                </div>
              ))}
            </div>
          )}
        </nav>

        {/* Mobile Fixed Bottom Controls */}
        {!collapsed && (
          <div className="lg:hidden mt-auto px-4 py-4 border-t border-sidebar-border bg-sidebar-accent/5">
            <div className="flex flex-col gap-4">
              <div className="flex items-center justify-between gap-3">
                <div className="scale-90 origin-left">
                  <ThemeToggler />
                </div>
                <div className="h-6 w-[1px] bg-border" />
                <div className="scale-90">
                  <LandingColorTheme />
                </div>
              </div>
              <div className="w-full pt-2 border-t border-sidebar-border/30">
                <GoogleTranslate containerId="google_translate_sidebar" />
              </div>
            </div>
          </div>
        )}
      </aside>
    </>
  );
}

'use client';
import { Dialog, DialogContent, DialogTitle, DialogDescription, Badge, Button } from "@pec/ui";


import { useState } from 'react';

import { 
  MapPin, 
  Users, 
  Edit, 
  Trash2,
