            variant="ghost" 
            onClick={onClose} 
            className="text-[10px] font-black uppercase tracking-[0.4em] text-muted-foreground/30 hover:text-primary transition-colors h-auto p-0 hover:bg-transparent"
          >
            Terminal View [X]
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

'use client';
import { Button, Badge, Input, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@pec/ui";


import { useState, useMemo } from 'react';
import { 
  format, 
  isSameDay, 
  startOfMonth, 
  endOfMonth, 
  eachDayOfInterval, 
  isSameMonth, 
  getDay, 
  addMonths, 
  subMonths,
  isToday as isDateToday,
  startOfToday
} from 'date-fns';
import { 
  ChevronLeft, 
  ChevronRight, 
  Filter, 
  Search, 
  Calendar as CalendarIcon,
  Clock,
  MapPin,
  Plus
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

import { EventDetailModal } from './EventDetailModal';
import { getEventDotColor, getEventLabel, getEventColor, EVENT_LABELS, CATEGORY_LABELS } from './calendar-utils';
import { cn } from '@/lib/utils';

interface AcademicCalendarEvent {
  id: string;
  title: string;
  description: string;
  date: string;
  endDate: string | null;
  startTime: string | null;
  endTime: string | null;
  eventType: string;
  category: string;
  location: string | null;
  importance: string;
  targetAudience: string | null;
  rawData: any;
  isEditable: boolean;
  createdAt: string;
  updatedAt: string;
}

interface InteractiveCalendarProps {
  events: AcademicCalendarEvent[];
  isAdmin?: boolean;
  onEventEdit?: (event: AcademicCalendarEvent) => void;
  onEventDelete?: (id: string) => void;
  onEventsChange?: () => void;
  onCreateEventAtDate?: (date: string) => void;
}

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

export function InteractiveCalendar({
  events,
  isAdmin = false,
  onEventEdit,
  onEventDelete,
  onEventsChange,
  onCreateEventAtDate,
}: InteractiveCalendarProps) {
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(startOfToday());
  const [currentMonth, setCurrentMonth] = useState<Date>(new Date());
  const [selectedEvent, setSelectedEvent] = useState<AcademicCalendarEvent | null>(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [eventTypeFilter, setEventTypeFilter] = useState<string>('all');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  const filteredEvents = useMemo(() => {
    return events.filter((event) => {
      const matchesType = eventTypeFilter === 'all' || event.eventType === eventTypeFilter;
      const matchesCategory = categoryFilter === 'all' || event.category === categoryFilter;
      const matchesSearch = searchQuery === '' || 
        event.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
        event.description.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesType && matchesCategory && matchesSearch;
    });
  }, [events, eventTypeFilter, categoryFilter, searchQuery]);

  const eventsByDate = useMemo(() => {
    const map: Record<string, AcademicCalendarEvent[]> = {};
    filteredEvents.forEach((event) => {
      const dateKey = format(new Date(event.date), 'yyyy-MM-dd');
      if (!map[dateKey]) map[dateKey] = [];
      map[dateKey].push(event);
    });
    return map;
  }, [filteredEvents]);

  const calendarDays = useMemo(() => {
    const start = startOfMonth(currentMonth);
    const end = endOfMonth(currentMonth);
    const days = eachDayOfInterval({ start, end });
    
    const startPadding = getDay(start);
    const paddedDays: (Date | null)[] = Array(startPadding).fill(null);
    
    return [...paddedDays, ...days];
  }, [currentMonth]);

  const selectedDateEvents = useMemo(() => {
    if (!selectedDate) return [];
    const dateKey = format(selectedDate, 'yyyy-MM-dd');
    return eventsByDate[dateKey] || [];
  }, [selectedDate, eventsByDate]);

  const uniqueEventTypes = useMemo(() => Array.from(new Set(events.map((e) => e.eventType))), [events]);
  const uniqueCategories = useMemo(() => Array.from(new Set(events.map((e) => e.category))), [events]);

  const handlePrevMonth = () => setCurrentMonth(subMonths(currentMonth, 1));
  const handleNextMonth = () => setCurrentMonth(addMonths(currentMonth, 1));
  const handleToday = () => {
    const today = startOfToday();
    setSelectedDate(today);
    setCurrentMonth(today);
  };

  return (
    <div className="space-y-6 pb-12">
      {/* Compact Controls Bar */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={handleToday} className="font-semibold text-xs gap-1.5">
            <CalendarIcon className="w-3.5 h-3.5" />
            Today
          </Button>
        </div>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
          <Input
            placeholder="Search events..."
            className="pl-9 w-[240px] h-9 text-sm"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* Main Grid Content */}
      <div className="grid grid-cols-1 xl:grid-cols-12 gap-6 items-start">
        {/* Calendar Area */}
        <div className="xl:col-span-8 space-y-4">
          <div className="bg-card border border-border rounded-lg p-6 shadow-sm relative overflow-hidden">
            {/* Calendar Controls */}
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mb-8 border-b border-border pb-5">
              <div className="flex items-baseline gap-3">
                <h3 className="text-3xl font-bold tracking-tight text-foreground uppercase">
                  {format(currentMonth, 'MMMM')}
                </h3>
                <span className="text-3xl font-light text-muted-foreground/30 tracking-tight">
                  {format(currentMonth, 'yyyy')}
                </span>
              </div>
              <div className="flex gap-0 bg-muted/20 p-0 rounded-sm border border-border self-stretch sm:self-auto overflow-hidden">
                <Button variant="ghost" size="icon" onClick={handlePrevMonth} className="rounded-none h-12 w-12 hover:bg-background transition-all border-r border-border">
                  <ChevronLeft className="h-6 w-6" />
                </Button>
                <Button variant="ghost" size="icon" onClick={handleNextMonth} className="rounded-none h-12 w-12 hover:bg-background transition-all">
                  <ChevronRight className="h-6 w-6" />
                </Button>
              </div>
            </div>

            {/* Calendar Grid Header */}
            <div className="grid grid-cols-7 gap-0 border-b border-border/20 mb-4">
              {WEEKDAYS.map((day) => (
                <div key={day} className="text-center text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/40 py-4 border-r last:border-r-0 border-border/10">
                  {day}
                </div>
              ))}
            </div>

            {/* Calendar Grid Body */}
            <AnimatePresence mode="wait">
              <motion.div
                key={currentMonth.toISOString()}
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                transition={{ duration: 0.2, ease: "easeOut" }}
                className="grid grid-cols-7 gap-2 md:gap-4"
              >
                {calendarDays.map((day, idx) => {
                  if (!day) {
                    return <div key={`empty-${idx}`} className="h-24 md:h-32 border border-transparent" />;
                  }

                  const dateKey = format(day, 'yyyy-MM-dd');
                  const dayEvents = eventsByDate[dateKey] || [];
                  const isToday = isDateToday(day);
                  const isSelected = selectedDate && isSameDay(day, selectedDate);
                  const isCurrentMonth = isSameMonth(day, currentMonth);

                  return (
                    <motion.button
                      key={dateKey}
                      whileTap={{ scale: 0.98 }}
                      onClick={() => setSelectedDate(day)}
                      className={cn(
                        "min-h-[100px] md:min-h-[140px] p-4 rounded-sm border transition-all relative flex flex-col items-start gap-4 text-left overflow-hidden group hover:bg-muted/40",
                        !isCurrentMonth ? "opacity-10 pointer-events-none" : "bg-card hover:border-primary",
                        isSelected ? "bg-primary text-primary-foreground border-primary z-10" : "border-border/60",
                        isToday && !isSelected ? "border-primary/40 bg-primary/5" : ""
                      )}
                    >
                      <div className="flex justify-between w-full items-start">
                        <span className={cn(
                          "text-2xl font-bold tracking-tight transition-all font-display",
                          isSelected ? "text-primary-foreground" : "text-foreground",
                          isToday && !isSelected ? "text-primary" : ""
                        )}>
                          {format(day, 'd')}
                        </span>
                        {isToday && (
                          <div className={cn(
                            "w-1.5 h-1.5 rounded-full",
                            isSelected ? "bg-primary-foreground" : "bg-primary"
                          )} />
                        )}
                      </div>
                      
                      <div className="flex flex-col gap-1.5 w-full mt-auto">
                        {dayEvents.slice(0, 3).map((event) => (
                          <div
                            key={event.id}
                            className={cn(
                              "text-[9px] px-2 py-1 border-l-2 font-bold transition-all leading-tight uppercase tracking-wider",
                              isSelected 
                                ? "bg-primary-foreground/10 text-primary-foreground border-white/40" 
                                : getEventColor(event.eventType)
                            )}
                            title={event.title}
                          >
                            <span className="truncate block">{event.title}</span>
                          </div>
                        ))}
                        {dayEvents.length > 2 && (
                          <div className={cn(
                            "text-[9px] px-2 py-0.5 font-black uppercase tracking-widest opacity-60",
                            isSelected ? "text-primary-foreground" : "text-muted-foreground"
                          )}>
                            + {dayEvents.length - 2} More
                          </div>
                        )}
                      </div>
                    </motion.button>
                  );
                })}
              </motion.div>
            </AnimatePresence>
          </div>

          {/* Filtering Controls */}
          <div className="bg-card border border-border rounded-sm p-8 flex flex-wrap items-center gap-8 shadow-sm">
            <div className="flex items-center gap-3">
              <Filter className="w-5 h-5 text-primary" />
              <h4 className="font-bold text-xs uppercase tracking-[0.2em] text-muted-foreground font-display">Refine Scope</h4>
            </div>
            
            <div className="h-10 w-[1px] bg-border hidden md:block" />
 
            <div className="flex items-center gap-4 flex-1">
              <Select value={eventTypeFilter} onValueChange={setEventTypeFilter}>
                <SelectTrigger className="w-[200px] rounded-sm border-border bg-background focus:ring-0 uppercase text-[10px] font-black tracking-widest h-12">
                  <SelectValue placeholder="Event Type" />
                </SelectTrigger>
                <SelectContent className="rounded-sm border-border bg-card">
                  <SelectItem value="all" className="uppercase text-[10px] font-bold">All Types</SelectItem>
                  {uniqueEventTypes.map((type) => (
                    <SelectItem key={type} value={type} className="uppercase text-[10px] font-bold">{EVENT_LABELS[type] || type}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
 
              <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                <SelectTrigger className="w-[200px] rounded-sm border-border bg-background focus:ring-0 uppercase text-[10px] font-black tracking-widest h-12">
                  <SelectValue placeholder="Category" />
                </SelectTrigger>
                <SelectContent className="rounded-sm border-border bg-card">
                  <SelectItem value="all" className="uppercase text-[10px] font-bold">All Categories</SelectItem>
                  {uniqueCategories.map((cat) => (
                    <SelectItem key={cat} value={cat} className="uppercase text-[10px] font-bold">{CATEGORY_LABELS[cat] || cat}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>

        {/* Sidebar Area - Daily Agenda */}
        <div className="xl:col-span-4 space-y-8">
          <div className="bg-card border border-border rounded-sm overflow-hidden shadow-sm sticky top-8">
            {/* Sidebar Header */}
            <div className="bg-muted/10 p-10 border-b border-border flex items-center justify-between bg-grid-pattern">
              <div className="space-y-2">
                <h3 className="font-bold text-2xl tracking-tight uppercase font-display">Daily Brief</h3>
                <div className="flex items-center gap-2 text-[10px] text-primary font-black uppercase tracking-[0.2em]">
                  {selectedDate ? format(selectedDate, 'EEEE · MMM d') : 'Select a date'}
                </div>
              </div>
              {isAdmin && onCreateEventAtDate && (
                <Button
                  size="sm"
                  onClick={() => selectedDate && onCreateEventAtDate(format(selectedDate, 'yyyy-MM-dd'))}
                  disabled={!selectedDate}
                  className="rounded-none h-10 px-4 font-black uppercase tracking-widest"
                >
                  <Plus className="w-4 h-4 mr-2" />
                  Add Event
                </Button>
              )}
            </div>

            <div className="p-6">
              <AnimatePresence mode="wait">
                <motion.div
                  key={selectedDate?.toISOString()}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.2 }}
                  className="space-y-4"
                >
                  {selectedDateEvents.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-24 text-center">
                      <h4 className="font-bold text-xs uppercase tracking-[0.3em] text-muted-foreground/40 mb-4 font-display">Structural Void</h4>
                      <p className="text-[10px] text-muted-foreground/30 max-w-[180px] font-bold uppercase tracking-widest leading-loose">
                        No events mapped for this coordinates.
                      </p>
                    </div>
                  ) : (
                    <div className="space-y-6 relative before:absolute before:left-[17px] before:top-2 before:bottom-2 before:w-[1px] before:bg-border/20">
                      {selectedDateEvents.map((event) => (
                        <motion.button
                          key={event.id}
                          whileHover={{ x: 6 }}
                          onClick={() => {
                            setSelectedEvent(event);
                            setIsDetailOpen(true);
                          }}
                          className="w-full text-left pl-10 relative group"
                        >
                          <div className={cn(
                            "absolute left-0 top-1.5 w-[35px] h-[35px] rounded-xl flex items-center justify-center border bg-background group-hover:scale-110 transition-all duration-300 z-10 shadow-lg",
                            getEventDotColor(event.eventType).replace('bg-', 'border-').split(' ')[0], // Border color from dot color
                          )}>
                            <div className={cn("w-2 h-2 rounded-full", getEventDotColor(event.eventType))} />
                          </div>

                          <div className="bg-muted/5 group-hover:bg-muted/10 border border-border/60 group-hover:border-primary p-6 rounded-sm transition-all duration-300">
                            <div className="flex items-start justify-between gap-4 mb-4">
                              <h4 className="font-bold text-sm tracking-tight text-foreground uppercase font-display leading-tight">
                                {event.title}
                              </h4>
                              <Badge variant="outline" className={cn(
                                "text-[8px] h-5 rounded-none px-2 font-black uppercase tracking-widest shrink-0 border-border",
                                getEventColor(event.eventType)
                              )}>
                                {getEventLabel(event.eventType)}
                              </Badge>
                            </div>
                            
                            <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
                              <div className="flex items-center gap-1.5 text-[10px] text-muted-foreground font-bold uppercase tracking-widest">
                                <Clock className="w-3 h-3 text-primary" />
                                {event.startTime || 'All Day'}
                              </div>
                              {event.location && (
                                <div className="flex items-center gap-1.5 text-[10px] text-muted-foreground font-bold uppercase tracking-widest truncate max-w-[150px]">
                                  <MapPin className="w-3 h-3 text-primary" />
                                  <span className="truncate">{event.location}</span>
                                </div>
                              )}
                            </div>
                          </div>
                        </motion.button>
                      ))}
                    </div>
                  )}
                </motion.div>
              </AnimatePresence>
            </div>

            {/* Legend Section */}
            <div className="p-8 bg-muted/10 border-t border-border/10">
              <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/40 mb-6 flex items-center gap-3">
                <div className="w-4 h-[1px] bg-primary/40" />
                Index
              </h4>
              <div className="grid grid-cols-1 gap-3">
                {Object.entries(EVENT_LABELS).map(([type, label]) => (
                  <div key={type} className="flex items-center justify-between group cursor-default">
                    <div className="flex items-center gap-3">
                      <div className={cn("w-2 h-2 rounded-sm rotate-45", getEventDotColor(type))} />
                      <span className="text-[10px] font-bold text-muted-foreground group-hover:text-foreground transition-colors uppercase tracking-widest">{label}</span>
                    </div>
                    <div className="w-8 h-[1px] bg-border/10" />
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      <EventDetailModal
        event={selectedEvent}
        isOpen={isDetailOpen}
        onClose={() => {
          setIsDetailOpen(false);
          setSelectedEvent(null);
        }}
        isAdmin={isAdmin}
        onEdit={onEventEdit}
        onDelete={(id) => {
          onEventDelete?.(id);
          onEventsChange?.();
        }}
      />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Loader2 } from "lucide-react";
import { useAuth } from '@/features/auth/hooks/useAuth';
import { InteractiveCalendar } from "@/features/academic-calendar/InteractiveCalendar";
import AdminAcademicCalendarPage from "@/app/(protected)/admin/academic-calendar/page";
import api from "@pec/api";

export default function CalendarTab() {
  const { user, loading: authLoading } = useAuth();
  const [events, setEvents] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const isAdmin = ["college_admin", "super_admin", "admin"].includes(
    user?.role || ""
  );

  useEffect(() => {
    if (authLoading) return;
    if (isAdmin) {
      setLoading(false);
      return;
    }

    async function loadEvents() {
      try {
        const response = await api.get("/academic-calendar");
        const data = response.data?.data ?? response.data ?? [];
        setEvents(data);
      } catch (error) {
        console.error("Failed to fetch calendar events:", error);
      } finally {
        setLoading(false);
      }
    }

    loadEvents();
  }, [authLoading, isAdmin]);

  if (authLoading || loading) {
    return (
      <div className="min-h-[400px] flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (isAdmin) {
    return <AdminAcademicCalendarPage />;
  }

  return (
    <div className="container mx-auto py-8 px-4 max-w-7xl">
      <InteractiveCalendar events={events || []} isAdmin={false} />
    </div>
  );
}

'use client';
import { extractData } from "@/lib/utils";
import { Tabs, TabsContent, TabsList, TabsTrigger, Button, Input, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Badge, Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@pec/ui";


import { useEffect, useMemo, useState } from 'react';
import { motion } from 'framer-motion';
import { Loader2, Plus, Trash2, Upload } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';

import BulkUpload from '@/components/BulkUpload';

import api from "@pec/api";

import { useAuth } from '@/features/auth/hooks/useAuth';

type Course = {
  id: string;
  code: string;
  name: string;
  department?: string | null;
};

type Department = {
  id: string;
  name: string;
};

type ExamSchedule = {
  id: string;
  courseId: string;
  courseName: string;
  courseCode: string;
  department?: string | null;
  examType: string;
  date: string;
  startTime: string;
  endTime: string;
  room: string;
};

const examTypeOptions = ['Midterm', 'Final', 'Practical', 'Quiz'];

const formatDate = (value: string) => {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return parsed.toLocaleDateString();
};

const isUpcoming = (value: string) => {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return false;
  const startOfToday = new Date();
  startOfToday.setHours(0, 0, 0, 0);
  return date.getTime() >= startOfToday.getTime();
};

export default function ExaminationsTab() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();

  useEffect(() => {
    if (authLoading) return;
    if (!user) router.replace('/auth');
  }, [authLoading, user, router]);

  if (authLoading || !user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  const role = user.role;
  const isCollegeAdmin = ['college_admin', 'admin', 'moderator'].includes(role || '');

  if (isCollegeAdmin) {
    return <CollegeAdminExaminations />;
  }

  if (role === 'faculty' || role === 'student') {
    return (
      <DepartmentUpcomingExams
        role={role}
        department={user.department || null}
      />
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center">
      <p className="text-muted-foreground">Access denied</p>
    </div>
  );
}

function CollegeAdminExaminations() {
  const [loading, setLoading] = useState(true);
  const [schedules, setSchedules] = useState<ExamSchedule[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [showBulkUpload, setShowBulkUpload] = useState(false);

  const [departmentFilter, setDepartmentFilter] = useState('all');
  const [examTypeFilter, setExamTypeFilter] = useState('all');
  const [dateScope, setDateScope] = useState<'all' | 'upcoming'>('all');

  const [scheduleForm, setScheduleForm] = useState({
    courseId: '',
    examType: 'Final',
    date: '',
    startTime: '',
    endTime: '',
    room: '',
  });

  const selectedCourse = useMemo(
    () => courses.find((c) => c.id === scheduleForm.courseId),
    [courses, scheduleForm.courseId],
  );

  const loadSchedules = async () => {
    const params: Record<string, unknown> = {
      ...(departmentFilter !== 'all' ? { department: departmentFilter } : {}),
      ...(dateScope === 'upcoming' ? { upcoming: true } : {}),
    };
    const rows = extractData<any>((await api.get('/examinations/schedules', { params: { ...params, limit: 2000 } })).data);
    setSchedules(rows);
  };

  const bootstrap = async () => {
    try {
      setLoading(true);
      const [allCourses, allDepartments] = await Promise.all([
        api.get('/courses', { params: { limit: 2000 } }).then(res => extractData<any>(res.data)),
        api.get('/departments', { params: { limit: 2000 } }).then(res => extractData<any>(res.data)),
      ]);
      setCourses(allCourses);
      setDepartments(allDepartments);
      await loadSchedules();
    } catch (error) {
      console.error(error);
      toast.error('Failed to load examinations data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void bootstrap();
  }, []);

  useEffect(() => {
    if (loading) return;
    void loadSchedules();
  }, [departmentFilter, dateScope]);

  const filteredSchedules = useMemo(() => {
    return schedules.filter((schedule) => {
      const typeOk = examTypeFilter === 'all' || schedule.examType === examTypeFilter;
      return typeOk;
    });
  }, [schedules, examTypeFilter]);

  const handleAddSchedule = async () => {
    if (!scheduleForm.courseId || !scheduleForm.date || !scheduleForm.startTime || !scheduleForm.endTime || !scheduleForm.room) {
      toast.error('Please complete all schedule fields');
      return;
    }

    try {
      await api.post('/examinations/schedules', scheduleForm);
      toast.success('Exam schedule added');
      setScheduleForm({
        courseId: '',
        examType: 'Final',
        date: '',
        startTime: '',
        endTime: '',
        room: '',
      });
      await loadSchedules();
    } catch (error) {
      console.error(error);
      toast.error('Failed to add schedule');
    }
  };

  const handleDeleteSchedule = async (id: string) => {
    if (!confirm('Delete this schedule?')) return;
    try {
      await api.delete(`/examinations/schedules/${id}`);
      toast.success('Schedule deleted');
      await loadSchedules();
    } catch (error) {
      console.error(error);
      toast.error('Failed to delete schedule');
    }
  };

  const handleBulkImport = async (rows: any[]) => {
    let success = 0;
    let failed = 0;
    const errors: string[] = [];

    for (const row of rows) {
      try {
        const course = courses.find(
          (c) => String(c.code || '').toLowerCase() === String(row.courseCode || '').toLowerCase(),
        );

        if (!course) {
          throw new Error(`Course not found for code: ${row.courseCode}`);
        }

        await api.post('/examinations/schedules', {
          courseId: course.id,
          examType: row.examType || 'Final',
          date: row.date,
          startTime: row.startTime,
          endTime: row.endTime,
          room: row.room,
        });

        success += 1;
      } catch (error) {
        failed += 1;
        errors.push((error as Error).message);
      }
    }

    await loadSchedules();
    return { success, failed, errors };
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="space-y-6">
      <div className="flex items-center gap-3 pb-2">
        <h2 className="text-base font-bold text-foreground">Manage Examinations</h2>
        <span className="text-xs text-muted-foreground">All departments</span>
      </div>

      <Tabs defaultValue="schedule" className="space-y-4">
        <TabsList>
          <TabsTrigger value="schedule">Schedule</TabsTrigger>
          <TabsTrigger value="upload">Bulk Upload</TabsTrigger>
        </TabsList>

        <TabsContent value="schedule" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-6 gap-3">
            <Select value={scheduleForm.courseId} onValueChange={(value) => setScheduleForm((p) => ({ ...p, courseId: value }))}>
              <SelectTrigger className="md:col-span-2"><SelectValue placeholder="Course" /></SelectTrigger>
              <SelectContent>
                {courses.map((course) => (
                  <SelectItem key={course.id} value={course.id}>
                    {course.code} - {course.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            <Select value={scheduleForm.examType} onValueChange={(value) => setScheduleForm((p) => ({ ...p, examType: value }))}>
              <SelectTrigger><SelectValue placeholder="Exam type" /></SelectTrigger>
              <SelectContent>
                {examTypeOptions.map((type) => (
                  <SelectItem key={type} value={type}>{type}</SelectItem>
                ))}
              </SelectContent>
            </Select>

            <Input type="date" value={scheduleForm.date} onChange={(e) => setScheduleForm((p) => ({ ...p, date: e.target.value }))} />
            <Input type="time" value={scheduleForm.startTime} onChange={(e) => setScheduleForm((p) => ({ ...p, startTime: e.target.value }))} />
            <Input type="time" value={scheduleForm.endTime} onChange={(e) => setScheduleForm((p) => ({ ...p, endTime: e.target.value }))} />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-6 gap-3">
            <Input
              className="md:col-span-4"
              placeholder="Room"
              value={scheduleForm.room}
              onChange={(e) => setScheduleForm((p) => ({ ...p, room: e.target.value }))}
            />
