'use client';
import { useEffect, useState } from 'react';
import { RolePermissions, UserRole, getRolePermissions } from '@/features/auth/lib/rolePermissions';
import {  authClient  } from "@pec/api";
import {  buildApiUrl  } from "@pec/api";
import { AppAbility, buildAbilityFor } from '@/lib/casl-ability';
import { safeLocalStorage, safeDocument, safeWindow, isBrowser } from '@/lib/ssr-safe';

export interface CurrentUser {
  id: string;
  uid: string;
  email: string | null;
  fullName: string | null;
  name: string | null;
  role: UserRole | null;
  roles?: string[];
  organizationId?: string;
  department?: string;
  enrollmentNumber?: string;
  permissions: RolePermissions;
  ability?: AppAbility;
  avatar: string | null;
  verified: boolean;
  profileComplete: boolean;
  semester?: number | null;
}

interface UseAuthResult {
  user: CurrentUser | null;
  token: string | null;
  loading: boolean;
  isLoading: boolean;
  error: string | null;
  isAuthenticated: boolean;
  ability?: AppAbility;
  logout: () => Promise<void>;
  login: (email: string, password: string) => Promise<void>;
}

const AUTH_CACHE_TTL_MS = 0;

export const clearAuthCache = () => {
  cachedToken = null;
  cachedUser = null;
  cachedAt = 0;
  inFlightRequest = null;
};

let cachedToken: string | null = null;
let cachedUser: CurrentUser | null = null;
let cachedAt = 0;
let inFlightRequest: Promise<CurrentUser | null> | null = null;
let redirectInProgress = false;

const isAllowedRole = (role: string | null | undefined): role is UserRole => {
  return ['student', 'faculty', 'college_admin', 'admin'].includes(role as string);
};


function hasRefreshMarkerCookie(): boolean {
  return safeDocument.hasCookiePrefix('refresh_present=');
}

function isOnAuthPage(): boolean {
  const pathname = safeWindow.getPathname();
  return pathname === '/auth' || pathname.startsWith('/auth/');
}

function safeRedirectToAuth(): void {
  if (!isBrowser()) return;
  if (isOnAuthPage() || redirectInProgress) return;
  redirectInProgress = true;
  safeWindow.navigate('/auth?clear_session=true');
}

async function fetchProfile(token: string, force = false): Promise<CurrentUser | null> {
  const now = Date.now();
  const cacheValid = !force && cachedToken === token && now - cachedAt < AUTH_CACHE_TTL_MS;

  if (cacheValid) {
    return cachedUser;
  }

  if (inFlightRequest) {
    return inFlightRequest;
  }

  inFlightRequest = (async () => {
    const res = await fetch(buildApiUrl(`/v1/auth/profile?t=${Date.now()}`), {
      headers: {
        Authorization: `Bearer ${token}`,
      },
      credentials: 'include',
      cache: 'no-store',
    });

    if (res.status === 401 || res.status === 403) {
      safeLocalStorage.remove('auth_user');
      authClient.logout();
      clearAuthCache();
      safeRedirectToAuth();
      return null;
    }

    if (!res.ok) {
      const err = new Error('Failed to fetch profile');
      (err as any).status = res.status;
      throw err;
    }

    const payload = await res.json();
    const userId = payload.id || payload.uid || payload.sub;
    const role = isAllowedRole(payload.role) ? payload.role : null;
    const fullName = payload.fullName || payload.name || 'User';
    const roles = Array.isArray(payload.roles) ? payload.roles : role ? [role] : [];

    const permsRes = await fetch(buildApiUrl(`/v1/auth/me/permissions?t=${Date.now()}`), {
      headers: { Authorization: `Bearer ${token}` },
      credentials: 'include',
      cache: 'no-store'
    });
    const permsData = permsRes.ok ? await permsRes.json() : { permissions: [] };
    const caslPermissions = permsData.permissions || [];
    const ability = buildAbilityFor(caslPermissions);

    const user: CurrentUser = {
      id: userId,
      uid: userId,
      email: payload.email,
      fullName,
      name: payload.name || fullName,
      role,
      roles,
      organizationId: payload.organizationId || undefined,
      department: payload.department || undefined,
      enrollmentNumber: payload.enrollmentNumber || undefined,
      semester: typeof payload.semester === 'number' ? payload.semester : undefined,
      permissions: getRolePermissions(role || 'student'),
      ability,
      avatar: payload.avatar || null,
      verified: payload.verified || false,
      profileComplete: payload.profileComplete || false,
    };

    cachedToken = token;
    cachedUser = user;
    cachedAt = Date.now();

    return user;
  })();

  try {
    return await inFlightRequest;
  } finally {
    inFlightRequest = null;
  }
}

export function useAuth(): UseAuthResult {
  // SSR-SAFE: All useState initializers return server-safe defaults (null/null/true).
  // The real values are loaded inside the useEffect below, which only runs on the client.
  // This prevents server/client HTML mismatches (hydration errors).
  const [user, setUser] = useState<CurrentUser | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let mounted = true;

    const syncUser = async (force = false) => {
      try {
        let currentToken = authClient.getAccessToken();

        if (!currentToken && hasRefreshMarkerCookie()) {
          try {
            currentToken = await authClient.refreshAccessToken();
          } catch (err: any) {
            const status = err.response?.status || err.status;
            if (status !== 429 && !(status >= 500)) {
              currentToken = null;
            } else {
              // It's a transient 500/429 error. We shouldn't force a logout.
              // We'll leave currentToken null but skip the session clear block
              // by re-throwing to let the outer block handle it.
              throw err;
            }
          }
        }

        setToken(currentToken);

        if (!currentToken) {
          clearAuthCache();
          safeLocalStorage.remove('auth_user');
          setUser(null);
          if (mounted) setLoading(false);
          const protectedPrefixes = ['/dashboard', '/courses', '/users', '/chat', '/settings', '/faculty', '/departments', '/attendance'];
          if (protectedPrefixes.some(p => safeWindow.getPathname().startsWith(p))) {
            safeRedirectToAuth();
          }
          return;
        }

        const resolvedUser = await fetchProfile(currentToken, force);

        if (mounted) {
          setUser(resolvedUser);
          setError(null);
        }
      } catch (err) {
        if (mounted) {
          setError(err instanceof Error ? err.message : 'An error occurred');
        }
        const status = (err as any)?.response?.status || (err as any)?.status;
        console.error('[useAuth] Outer catch hit. Error:', err, 'Status:', status);
        
        if (status !== 429 && !(status >= 500)) {
          authClient.resetSession();
          clearAuthCache();
          safeLocalStorage.remove('auth_user');
          if (mounted) {
            setToken(null);
            setUser(null);
          }
          safeRedirectToAuth();
        }
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    };

    syncUser();

    const onAuthChange = () => {
      setLoading(true);
      syncUser(true);
    };

    const onAuthFailed = () => {
      clearAuthCache();
      safeLocalStorage.remove('auth_user');
      setUser(null);
      setToken(null);
      safeRedirectToAuth();
    };

    window.addEventListener('auth-change', onAuthChange);
    window.addEventListener('auth-failed', onAuthFailed);

    // We no longer hydrate from localStorage to prevent client-side privilege spoofing.
    // The UI will securely wait for the backend to return the accurate profile via fetchProfile().
    if (!hasRefreshMarkerCookie()) {
      safeLocalStorage.remove('auth_user');
    }

    // Sync token from authClient (browser-only)
    setToken(authClient.getAccessToken());

    return () => {
      mounted = false;
      window.removeEventListener('auth-change', onAuthChange);
      window.removeEventListener('auth-failed', onAuthFailed);
    };
  }, []);

  const logout = async () => {
    try { await authClient.logout(); } catch (e) {}
    clearAuthCache();
    safeLocalStorage.remove('auth_user');
    setUser(null);
    setToken(null);
    safeRedirectToAuth();
  };

  const login = async (email: string, password: string) => {
    setLoading(true);
    try {
      await authClient.login({ email, password });
      const currentToken = authClient.getAccessToken();
      setToken(currentToken);
      safeWindow.dispatch('auth-change');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Login failed');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  return {
    user,
    token,
    loading,
    isLoading: loading,
    error,
    isAuthenticated: !!user,
    ability: user?.ability,
    logout,
    login,
  };
}

export function useHasPermission(requiredPermission: keyof RolePermissions): boolean {
  const { user } = useAuth();
  return user?.permissions[requiredPermission] ?? false;
}

export function useHasAllPermissions(requiredPermissions: (keyof RolePermissions)[]): boolean {
  const { user } = useAuth();
  if (!user) return false;
  return requiredPermissions.every((perm) => user.permissions[perm]);
}

export function useHasAnyPermission(requiredPermissions: (keyof RolePermissions)[]): boolean {
  const { user } = useAuth();
  if (!user) return false;
  return requiredPermissions.some((perm) => user.permissions[perm]);
}

export function useUserRole(): UserRole | null {
  const { user } = useAuth();
  return user?.role ?? null;
}

export function useIsRole(role: UserRole | UserRole[]): boolean {
  const { user } = useAuth();
  if (!user || !user.role) return false;
  if (Array.isArray(role)) {
    return role.includes(user.role);
  }
  return user.role === role;
}

export function useAbility() {
  const { user } = useAuth();
  return user?.ability;
}

'use client';

import { useRef, useMemo, useState, useCallback, useEffect } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls, Text, Html, Sky } from '@react-three/drei';
import * as THREE from 'three';

// ─── Dark-mode hook ───────────────────────────────────────────────────────────

function useIsDarkMode(): boolean {
  const [isDark, setIsDark] = useState(false);
  useEffect(() => {
    const check = () => setIsDark(document.documentElement.classList.contains('dark'));
    check();
    const obs = new MutationObserver(check);
    obs.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
    return () => obs.disconnect();
  }, []);
  return isDark;
}

// ─── Night sky CSS layer ──────────────────────────────────────────────────────
// Sits BEHIND the canvas (zIndex 0). The canvas uses alpha:true so sky pixels
// (where no 3D geometry is drawn) are transparent — stars/moon show through.
// Buildings & ground are opaque 3D geometry, so they correctly block this layer.

const seed01 = (value: number) => {
  const x = Math.sin(value * 12.9898) * 43758.5453;
  return x - Math.floor(x);
};

const STAR_DATA = Array.from({ length: 110 }, (_, i) => {
  const x = seed01(i + 1);
  const y = seed01(i + 101);
  const bigStar = i % 19 === 0;
  return {
    left: `${(x * 100).toFixed(2)}%`,
    top: `${(y * 58).toFixed(2)}%`,
    r: bigStar ? 1.8 : x > 0.84 ? 1.15 : 0.75,
    opacity: 0.32 + y * 0.38 + (bigStar ? 0.08 : 0),
  };
});

function NightSkyLayer() {
  return (
    <div
      aria-hidden
      style={{
        position: 'absolute',
        inset: 0,
        zIndex: 0,
        background: 'linear-gradient(to bottom, #02060f 0%, #060d1f 55%, #0d1b2e 100%)',
        pointerEvents: 'none',
      }}
    >
      {/* Stars */}
      {STAR_DATA.map((s, i) => (
        <div
          key={i}
          style={{
            position: 'absolute',
            left: s.left,
            top: s.top,
            width: s.r * 2,
            height: s.r * 2,
            borderRadius: '50%',
            background: 'white',
            opacity: s.opacity,
            boxShadow: s.r > 1.2 ? `0 0 ${s.r * 2.4}px rgba(255,255,255,0.6)` : undefined,
          }}
        />
      ))}

      {/* Moon — crescent via two overlapping circles */}
      <div style={{ position: 'absolute', top: '9%', right: '14%' }}>
        {/* Moon disc */}
        <div
          style={{
            width: 46,
            height: 46,
            borderRadius: '50%',
            background: '#fff9e0',
            boxShadow: '0 0 18px 6px rgba(255,248,180,0.35)',
            position: 'relative',
          }}
        >
          {/* Crescent shadow */}
          <div
            style={{
              position: 'absolute',
              top: -4,
              left: 8,
              width: 40,
              height: 40,
              borderRadius: '50%',
              background: 'linear-gradient(to bottom, #02060f, #060d1f)',
            }}
          />
        </div>
      </div>
    </div>
  );
}

// ─── Category Configuration ───────────────────────────────────────────────────

interface CategoryCfg {
  color: string;
  emissive: string;
  label: string;
  heightBase: number;
  heightPerArea: number;
}

const CATEGORY_CFG: Record<string, CategoryCfg> = {
  academic: {
    color: '#3b82f6',
    emissive: '#1e3a8a',
    label: 'Academic',
    heightBase: 0.55,
    heightPerArea: 0.002,
  },
  hostel: {
    color: '#10b981',
    emissive: '#064e3b',
    label: 'Hostel',
    heightBase: 0.9,
    heightPerArea: 0.001,
  },
  sports: {
    color: '#ef4444',
    emissive: '#7f1d1d',
    label: 'Sports',
    heightBase: 0.08,
    heightPerArea: 0.0005,
  },
  food: {
    color: '#f97316',
    emissive: '#7c2d12',
    label: 'Food',
    heightBase: 0.35,
    heightPerArea: 0.001,
  },
  admin: {
    color: '#8b5cf6',
    emissive: '#3b0764',
    label: 'Admin',
    heightBase: 0.6,
    heightPerArea: 0.0015,
  },
};

const FALLBACK_CFG: CategoryCfg = {
  color: '#6b7280',
  emissive: '#1f2937',
  label: 'Other',
  heightBase: 0.4,
  heightPerArea: 0.001,
};

function getBuildingHeight(region: { category: string; width: number; height: number }): number {
  const cfg = CATEGORY_CFG[region.category] ?? FALLBACK_CFG;
  return Math.min(cfg.heightBase + region.width * region.height * cfg.heightPerArea, 1.8);
}

const toWorld = (v: number) => v / 10 - 5;

interface FlyTarget {
  lookAt: THREE.Vector3;
  camPos: THREE.Vector3;
}

// ─── Building ────────────────────────────────────────────────────────────────

function Building({
  region,
  isSelected,
  isHovered,
  isDark,
  onClick,
  onHover,
  onUnhover,
}: {
  region: any;
  isSelected: boolean;
  isHovered: boolean;
  isDark: boolean;
  onClick: () => void;
  onHover: () => void;
  onUnhover: () => void;
}) {
  const meshRef = useRef<THREE.Mesh>(null);
  const scaleRef = useRef(1);
  const cfg = CATEGORY_CFG[region.category] ?? FALLBACK_CFG;
  const height = getBuildingHeight(region);
  const w = region.width / 10;
  const d = region.height / 10;
  const x = toWorld(region.x) + w / 2;
  const z = toWorld(region.y) + d / 2;

  const baseEmissive = isDark ? 0.66 : 0;
  const targetScale = isSelected ? 1.08 : isHovered ? 1.05 : 1.0;
  const targetEmissive = isSelected ? 1.02 : isHovered ? 0.82 : baseEmissive;

  useFrame(() => {
    if (!meshRef.current) return;
    scaleRef.current = THREE.MathUtils.lerp(scaleRef.current, targetScale, 0.14);
    meshRef.current.scale.setScalar(scaleRef.current);
    const mat = meshRef.current.material as THREE.MeshStandardMaterial;
    mat.emissiveIntensity = THREE.MathUtils.lerp(mat.emissiveIntensity, targetEmissive, 0.14);
  });

  return (
    <group position={[x, 0, z]}>
      <mesh
        ref={meshRef}
        position={[0, height / 2, 0]}
        castShadow
        receiveShadow
        onClick={(e) => {
          e.stopPropagation();
          onClick();
        }}
        onPointerOver={(e) => {
          e.stopPropagation();
          onHover();
          document.body.style.cursor = 'pointer';
        }}
        onPointerOut={() => {
          onUnhover();
          document.body.style.cursor = 'default';
        }}
      >
        <boxGeometry args={[w, height, d]} />
        <meshStandardMaterial
          color={cfg.color}
          emissive={cfg.emissive}
          emissiveIntensity={baseEmissive}
          roughness={isDark ? 0.62 : 0.55}
          metalness={isDark ? 0.08 : 0.15}
        />
      </mesh>
      <mesh position={[0, height + 0.005, 0]}>
        <boxGeometry args={[w + 0.01, 0.012, d + 0.01]} />
        <meshStandardMaterial
          color={isDark ? cfg.color : cfg.emissive}
          roughness={0.85}
          metalness={0}
          emissive={isDark ? cfg.emissive : '#000000'}
          emissiveIntensity={isDark ? 0.22 : 0}
        />
      </mesh>
      <Text
        position={[0, height + 0.28, 0]}
        fontSize={Math.max(0.1, Math.min(0.16, w * 0.25))}
        color={isDark ? '#cbd5e1' : 'white'}
        anchorX="center"
        anchorY="middle"
        outlineWidth={0.025}
        outlineColor={isDark ? '#0f172a' : '#000000'}
        maxWidth={w * 2}
        lineHeight={1.1}
      >
        {region.name}
      </Text>
      {isSelected && (
        <Html
          position={[0, height + 0.7, 0]}
          center
          distanceFactor={9}
          zIndexRange={[100, 0]}
          style={{ pointerEvents: 'none', userSelect: 'none' }}
        >
          <div
            style={{
              background: 'rgba(8,12,28,0.92)',
              backdropFilter: 'blur(14px)',
              WebkitBackdropFilter: 'blur(14px)',
              border: `1.5px solid ${cfg.color}60`,
              borderRadius: '12px',
              padding: '10px 14px',
              color: 'white',
              minWidth: '148px',
              maxWidth: '180px',
              textAlign: 'center',
              boxShadow: `0 0 24px ${cfg.color}50,0 4px 16px rgba(0,0,0,0.6)`,
              fontFamily: 'Inter,system-ui,sans-serif',
            }}
          >
            <div
              style={{
                width: 8,
                height: 8,
                borderRadius: '50%',
                background: cfg.color,
                margin: '0 auto 6px',
                boxShadow: `0 0 10px ${cfg.color}`,
              }}
            />
            <div style={{ fontSize: 13, fontWeight: 700, color: cfg.color, marginBottom: 4 }}>
              {region.name}
            </div>
            <div style={{ fontSize: 11, opacity: 0.72, marginBottom: 8, lineHeight: 1.4 }}>
              {region.description}
            </div>
            <span
              style={{
                display: 'inline-block',
                background: `${cfg.color}22`,
                border: `1px solid ${cfg.color}55`,
                color: cfg.color,
                borderRadius: 20,
                fontSize: 10,
                padding: '2px 9px',
                fontWeight: 600,
              }}
            >
              {cfg.label}
            </span>
          </div>
        </Html>
      )}
    </group>
  );
}

// ─── Road ────────────────────────────────────────────────────────────────────

function Road({ road, isDark }: { road: any; isDark: boolean }) {
  const segments = useMemo(() => {
    if (!road.points || !Array.isArray(road.points) || road.points.length < 2) return [];
    const out: { cx: number; cz: number; len: number; angle: number; w: number }[] = [];
    for (let i = 0; i < road.points.length - 1; i++) {
      const p1 = road.points[i],
        p2 = road.points[i + 1];
      const x1 = toWorld(p1.x),
        z1 = toWorld(p1.y);
      const x2 = toWorld(p2.x),
        z2 = toWorld(p2.y);
      const len = Math.sqrt((x2 - x1) ** 2 + (z2 - z1) ** 2);
      if (len < 0.001) continue;
      out.push({
        cx: (x1 + x2) / 2,
        cz: (z1 + z2) / 2,
        len,
        angle: Math.atan2(z2 - z1, x2 - x1),
        w: road.width / 10,
      });
    }
    return out;
  }, [road]);

  return (
    <group>
      {segments.map((seg, i) => (
        <group key={i} position={[seg.cx, 0.004, seg.cz]} rotation={[0, -seg.angle, 0]}>
          <mesh receiveShadow rotation={[-Math.PI / 2, 0, 0]}>
            <planeGeometry args={[seg.len, seg.w]} />
            <meshStandardMaterial
              color={isDark ? '#25304a' : '#2d3748'}
              roughness={0.95}
              metalness={0}
            />
          </mesh>
          <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0.001]}>
            <planeGeometry args={[seg.len * 0.88, seg.w * 0.09]} />
            <meshStandardMaterial
              color={isDark ? '#fde68a' : '#ffffff'}
              opacity={isDark ? 0.72 : 0.5}
              transparent
              roughness={1}
            />
          </mesh>
        </group>
      ))}
    </group>
  );
}

// ─── Ground ──────────────────────────────────────────────────────────────────

function Ground({ isDark }: { isDark: boolean }) {
  return (
    <>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[14, 14, 1, 1]} />
        <meshStandardMaterial
          color={isDark ? '#26432c' : '#3d6b42'}
          roughness={0.96}
          metalness={0}
        />
      </mesh>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.001, 0]}>
        <planeGeometry args={[16, 16]} />
        <meshStandardMaterial color={isDark ? '#172117' : '#2d5233'} roughness={1} metalness={0} />
      </mesh>
    </>
  );
}

// ─── Inner Scene ─────────────────────────────────────────────────────────────

function InnerScene({
  regions,
  roads,
  selectedRegion,
  onSelectRegion,
  isDark,
}: {
  regions: any[];
  roads: any[];
  selectedRegion: any;
  onSelectRegion: (r: any) => void;
  isDark: boolean;
}) {
  const orbitRef = useRef<any>(null);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const flyTargetRef = useRef<FlyTarget | null>(null);
  const { camera, scene, gl } = useThree();

  useEffect(() => {
    if (isDark) {
      // Transparent clear — the CSS NightSkyLayer behind the canvas shows through
      scene.background = null;
      gl.setClearColor(0x000000, 0); // fully transparent clear
    } else {
      scene.background = new THREE.Color('#c8dff2');
      gl.setClearColor(0xc8dff2, 1);
    }
  }, [isDark, scene, gl]);

  useFrame(() => {
    const ft = flyTargetRef.current;
    if (!ft || !orbitRef.current) return;
    camera.position.lerp(ft.camPos, 0.06);
    orbitRef.current.target.lerp(ft.lookAt, 0.06);
    orbitRef.current.update();
    if (
      camera.position.distanceTo(ft.camPos) < 0.08 &&
      orbitRef.current.target.distanceTo(ft.lookAt) < 0.08
    ) {
      flyTargetRef.current = null;
    }
  });

  const handleSelect = useCallback(
    (region: any) => {
      const isSame = selectedRegion?.id === region.id;
      onSelectRegion(isSame ? null : region);
      if (!isSame) {
        const h = getBuildingHeight(region);
        const wx = toWorld(region.x) + region.width / 20;
        const wz = toWorld(region.y) + region.height / 20;
        flyTargetRef.current = {
          lookAt: new THREE.Vector3(wx, h / 2, wz),
          camPos: new THREE.Vector3(wx + 2.8, h + 2.5, wz + 4.0),
        };
      } else {
        flyTargetRef.current = null;
      }
    },
    [selectedRegion, onSelectRegion]
  );

  return (
    <>
      {/* Day sky — removed in night so sky pixels are transparent (shows CSS layer) */}
      {!isDark && (
        <Sky
          sunPosition={[100, 30, 60]}
          turbidity={6}
          rayleigh={0.8}
          mieCoefficient={0.005}
          mieDirectionalG={0.8}
        />
      )}

      {/* Fog — day only; night has no fog so depth doesn't hide buildings */}
      {!isDark && <fog attach="fog" color="#c8dff2" near={18} far={38} />}

      {/* Lighting */}
      {isDark ? (
        <>
          <ambientLight intensity={0.3} color="#2a3c66" />
          <directionalLight
            position={[-10, 16, -8]}
            intensity={0.5}
            color="#d8e4ff"
            castShadow={false}
          />
          <hemisphereLight args={['#11204a', '#162416', 0.36]} />
        </>
      ) : (
        <>
          <ambientLight intensity={0.25} />
          <hemisphereLight args={['#87ceeb', '#3d6b42', 0.55]} />
          <directionalLight
            position={[10, 14, 8]}
            intensity={1.4}
            castShadow
            shadow-mapSize-width={2048}
            shadow-mapSize-height={2048}
            shadow-camera-near={0.1}
            shadow-camera-far={60}
            shadow-camera-left={-13}
            shadow-camera-right={13}
            shadow-camera-top={13}
            shadow-camera-bottom={-13}
            shadow-bias={-0.0005}
          />
          <pointLight position={[-7, 6, -7]} intensity={0.18} color="#ffe4b5" />
        </>
      )}

      <Ground isDark={isDark} />
      {roads.map((road) => (
        <Road key={road.id} road={road} isDark={isDark} />
      ))}
      {regions.map((region) => (
        <Building
          key={region.id}
          region={region}
          isSelected={selectedRegion?.id === region.id}
          isHovered={hoveredId === region.id}
          isDark={isDark}
          onClick={() => handleSelect(region)}
          onHover={() => setHoveredId(region.id)}
          onUnhover={() => setHoveredId(null)}
        />
      ))}

      <OrbitControls
        ref={orbitRef}
        enablePan
        enableZoom
        enableRotate
        minDistance={2}
        maxDistance={22}
        maxPolarAngle={Math.PI / 2.15}
        dampingFactor={0.08}
        enableDamping
      />
    </>
  );
}

// ─── Public Component ─────────────────────────────────────────────────────────

export default function CampusMap3D({
  regions,
  roads,
  selectedRegion,
  onSelectRegion,
}: {
  regions: any[];
  roads: any[];
  selectedRegion: any;
  onSelectRegion: (region: any) => void;
}) {
  const isDark = useIsDarkMode();

  return (
    <div className="relative w-full h-[620px] rounded-xl overflow-hidden border border-border shadow-2xl">
      {/* Night sky layer — sits BEHIND the canvas (zIndex 0).
          Stars/moon are visible only through sky pixels where no 3D geometry
          is drawn. Buildings & ground are solid WebGL geometry → block this layer. */}
      {isDark && <NightSkyLayer />}

      {/* Canvas at zIndex 1, alpha:true so sky is transparent in night */}
      <Canvas
        shadows={!isDark}
        camera={{ position: [8, 8, 8], fov: 50 }}
        gl={{ antialias: true, powerPreference: 'high-performance', alpha: true }}
        dpr={[1, 1.5]}
        style={{ position: 'absolute', inset: 0, zIndex: 1 }}
      >
        <InnerScene
          regions={regions}
          roads={roads}
          selectedRegion={selectedRegion}
          onSelectRegion={onSelectRegion}
          isDark={isDark}
        />
      </Canvas>

      {/* UI overlays at zIndex 2 (above canvas) */}

      {/* Controls hint */}
      <div
        style={{ zIndex: 2 }}
        className="absolute bottom-3 left-1/2 -translate-x-1/2 bg-black/55 backdrop-blur-md text-white/90 text-[11px] px-4 py-1.5 rounded-full pointer-events-none select-none tracking-wide shadow-lg"
      >
        🖱 Drag to rotate &nbsp;·&nbsp; Scroll to zoom &nbsp;·&nbsp; Click a building to explore
      </div>

      {/* Legend */}
      <div
        style={{ zIndex: 2 }}
        className={`absolute top-3 left-3 backdrop-blur-md rounded-xl px-3 py-2.5 pointer-events-none select-none shadow-lg border transition-all duration-500 ${isDark ? 'bg-slate-900/75 border-slate-700/50' : 'bg-black/55 border-transparent'}`}
      >
        <p className="text-white/50 text-[9px] font-semibold uppercase tracking-widest mb-1.5">
          Legend
        </p>
        <div className="space-y-1.5">
          {Object.entries(CATEGORY_CFG).map(([key, val]) => (
            <div key={key} className="flex items-center gap-2">
              <span
                className="w-2.5 h-2.5 rounded-full flex-shrink-0"
                style={{ background: val.color, boxShadow: `0 0 6px ${val.color}88` }}
              />
              <span className="text-white/80 text-[11px]">{val.label}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { Dialog, DialogContent, DialogHeader, DialogTitle, Button, Input, Textarea, Badge, Tabs, TabsContent, TabsList, TabsTrigger } from "@pec/ui";
import { useState, useEffect } from "react";
import { 
  Users, 
  Crown, 
  UserPlus, 
  UserMinus, 
  Edit, 
  X,
  Hash,
  MessageCircle
} from "lucide-react";

import { ChatRoom } from '@pec/shared';
import { useAuth } from '@/features/auth/hooks/useAuth';
import { 
  getMembersForGroup,
  addMemberToGroup, 
  removeMemberFromGroup,
  makeUserAdmin,
  removeUserAdmin,
  updateGroupInfo
} from "@/lib/chatManagement.service";
import { createOrFindDMRoom, deleteChatRoom } from "@/lib/chatRooms.service";
import { toast } from "sonner";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  room: ChatRoom | null;
  onRoomSelect?: (roomId: string) => void; // NEW: Callback to switch to a DM
}

export function ChatInfoDialog({ open, onOpenChange, room, onRoomSelect }: Props) {
  const { user } = useAuth();
  const [members, setMembers] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [newMemberEmail, setNewMemberEmail] = useState("");
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState("");
  const [editDescription, setEditDescription] = useState("");

  const isDM = room?.type === "dm";
  const userRole = user?.role as string;
  const isAdmin = room?.admins?.includes(user?.uid || "") || userRole === "admin" || userRole === "college_admin";
  const canDeleteRoom = !!room && (isDM || (room.type === "group" && !room.isSystem && isAdmin));

  useEffect(() => {
    if (room && open && !isDM) {
      loadMembers();
    }
    if (room) {
      setEditTitle(room.title);
      setEditDescription(room.description || "");
    }
  }, [room, open]);

  const loadMembers = async () => {
    if (!room) return;
    setIsLoading(true);
    try {
      const memberData = await getMembersForGroup(room);
      // Sort members alphabetically by name
      const sortedMembers = memberData.sort((a, b) => {
        const nameA = a.fullName || a.email || "";
        const nameB = b.fullName || b.email || "";
        return nameA.localeCompare(nameB);
      });
      setMembers(sortedMembers);
    } catch (error) {
      console.error("Error loading members:", error);
      toast.error("Failed to load members");
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddMember = async () => {
    if (!room || !newMemberEmail.trim()) return;
    
    setIsLoading(true);
    try {
      await addMemberToGroup(room.id, newMemberEmail);
      toast.success("Member added successfully");
      setNewMemberEmail("");
      await loadMembers();
    } catch (error: any) {
      toast.error(error.message || "Failed to add member");
    } finally {
      setIsLoading(false);
    }
  };

  const handleRemoveMember = async (userId: string) => {
    if (!room) return;
    
    try {
      await removeMemberFromGroup(room.id, userId);
      toast.success("Member removed");
      await loadMembers();
    } catch (error) {
      toast.error("Failed to remove member");
    }
  };

  const handleToggleAdmin = async (userId: string, isCurrentlyAdmin: boolean) => {
    if (!room) return;
    
    try {
      if (isCurrentlyAdmin) {
        await removeUserAdmin(room.id, userId);
        toast.success("Admin removed");
      } else {
        await makeUserAdmin(room.id, userId);
        toast.success("User promoted to admin");
      }
      await loadMembers();
    } catch (error) {
      toast.error("Failed to update admin status");
    }
  };

  const handleSaveInfo = async () => {
    if (!room) return;
    
    try {
      await updateGroupInfo(room.id, {
        title: editTitle,
        description: editDescription
      });
      toast.success("Group info updated");
      setIsEditing(false);
    } catch (error) {
      toast.error("Failed to update group info");
    }
  };

  const handleMemberClick = async (member: any) => {
    if (!user || member.uid === user.uid) return; // Don't DM yourself
    
    try {
      const dmRoom = await createOrFindDMRoom(
        user.uid,
        member.uid,
        user.organizationId
      );
      
      toast.success(`Opening chat with ${member.fullName}`);
      if (onRoomSelect) {
       onRoomSelect(dmRoom.id);
      }
      onOpenChange(false); // Close dialog
    } catch (error) {
      console.error("Error opening DM:", error);
      toast.error("Failed to open chat");
    }
  };

  const handleDeleteRoom = async () => {
    if (!room || isLoading) return;

    const label = isDM ? "this direct message" : "this group";
    const confirmed = window.confirm(`Delete ${label}? This action cannot be undone.`);
    if (!confirmed) return;

    setIsLoading(true);
    try {
      await deleteChatRoom(room.id);
      window.dispatchEvent(new Event("chat-rooms-updated"));
      toast.success(isDM ? "Direct message deleted" : "Group deleted");
      onOpenChange(false);
    } catch (error: any) {
      toast.error(error?.message || "Failed to delete room");
    } finally {
      setIsLoading(false);
    }
  };

  if (!room) return null;

  const getRoomIcon = () => {
    switch (room.type) {
      case "dm":
        return <MessageCircle className="w-5 h-5" />;
      case "general":
        return <Users className="w-5 h-5" />;
      case "semester":
        return <Hash className="w-5 h-5" />;
      case "department":
        return <Users className="w-5 h-5" />;
      default:
        return <Users className="w-5 h-5" />;
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-2xl max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <div className="flex items-center gap-3">
            <div className="p-3 rounded-full bg-primary/10">
              {getRoomIcon()}
            </div>
            <div className="flex-1">
              {isEditing ? (
                <Input
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  className="text-lg font-semibold"
                />
              ) : (
                <DialogTitle>{room.title}</DialogTitle>
              )}
              {!isDM && (
                <p className="text-sm text-muted-foreground mt-1">
                  {members.length} {members.length === 1 ? "member" : "members"}
                </p>
              )}
            </div>
            {isAdmin && !isDM && (
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setIsEditing(!isEditing)}
              >
                {isEditing ? <X className="w-4 h-4" /> : <Edit className="w-4 h-4" />}
              </Button>
            )}
          </div>
        </DialogHeader>

        {isDM ? (
          // DM Info
          <div className="space-y-4">
            <div className="p-4 rounded-lg bg-secondary/50">
              <h3 className="font-medium mb-2">Chat Info</h3>
              <p className="text-sm text-muted-foreground">
                This is a private conversation between you and another user.
              </p>
            </div>
            {canDeleteRoom && (
              <Button variant="destructive" className="w-full" onClick={handleDeleteRoom}>
                Delete Chat
              </Button>
            )}
          </div>
        ) : (
          // Group Info & Management
          <Tabs defaultValue="info" className="w-full">
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="info">Info</TabsTrigger>
              <TabsTrigger value="members">Members</TabsTrigger>
              {isAdmin && <TabsTrigger value="settings">Settings</TabsTrigger>}
            </TabsList>

            <TabsContent value="info" className="space-y-4">
              <div>
                <label className="text-sm font-medium">Description</label>
                {isEditing ? (
                  <Textarea
                    value={editDescription}
                    onChange={(e) => setEditDescription(e.target.value)}
                    placeholder="Add a group description..."
                    className="mt-2"
                  />
                ) : (
                  <p className="text-sm text-muted-foreground mt-2">
                    {room.description || "No description"}
                  </p>
                )}
              </div>

              {room.type === "semester" && (
                <div>
                  <label className="text-sm font-medium">Semester</label>
                  <p className="text-sm text-muted-foreground mt-1">
                    Semester {room.semester}
                  </p>
                </div>
              )}

              {room.type === "department" && (
                <div>
                  <label className="text-sm font-medium">Department</label>
                  <p className="text-sm text-muted-foreground mt-1">
                    {room.department}
                  </p>
                </div>
              )}

              {isEditing && (
                <Button onClick={handleSaveInfo} className="w-full">
                  Save Changes
                </Button>
              )}
            </TabsContent>

            <TabsContent value="members" className="space-y-4">
              <div className="space-y-2">
                {isLoading ? (
                  <p className="text-center text-sm text-muted-foreground py-4">
                    Loading members...
                  </p>
                ) : (
                  members.map((member) => {
                    const isMemberAdmin = room.admins?.includes(member.uid);
                    const isCurrentUser = member.uid === user?.uid;
                    
                    return (
                      <div
                        key={member.uid}
                        onClick={() => handleMemberClick(member)}
                        className="flex items-center justify-between p-3 rounded-lg bg-secondary/50 hover:bg-secondary cursor-pointer transition-colors"
                      >
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                            <span className="text-sm font-medium">
                              {member.fullName?.charAt(0).toUpperCase() || "U"}
                            </span>
                          </div>
                          <div>
                            <p className="font-medium">
                              {member.fullName || "Unknown User"}
                              {isCurrentUser && " (You)"}
                            </p>
                            <p className="text-xs text-muted-foreground">
                              {member.email}
                            </p>
                          </div>
                          {isMemberAdmin && (
                            <Badge variant="secondary" className="ml-2">
                              <Crown className="w-3 h-3 mr-1" />
                              Admin
                            </Badge>
                          )}
                        </div>

                        {isAdmin && !isCurrentUser && (
                          <div className="flex gap-2" onClick={(e) => e.stopPropagation()}>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleToggleAdmin(member.uid, isMemberAdmin)}
                            >
                              {isMemberAdmin ? "Remove Admin" : "Make Admin"}
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => handleRemoveMember(member.uid)}
                            >
                              <UserMinus className="w-4 h-4" />
                            </Button>
                          </div>
                        )}
                      </div>
                    );
                  })
                )}
              </div>
            </TabsContent>

            {isAdmin && (
              <TabsContent value="settings" className="space-y-4">
                <div>
                  <h3 className="font-medium mb-3">Add Member</h3>
                  <div className="flex gap-2">
                    <Input
                      placeholder="Enter email address..."
                      value={newMemberEmail}
                      onChange={(e) => setNewMemberEmail(e.target.value)}
                      onKeyDown={(e) => e.key === "Enter" && handleAddMember()}
                    />
                    <Button onClick={handleAddMember} disabled={isLoading}>
                      <UserPlus className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
                {canDeleteRoom && (
                  <Button variant="destructive" className="w-full" onClick={handleDeleteRoom}>
                    Delete Group
                  </Button>
                )}
              </TabsContent>
            )}
          </Tabs>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { Button, Textarea, ScrollArea } from "@pec/ui";
import { useState, useRef, useEffect, KeyboardEvent, forwardRef, useImperativeHandle } from 'react';
import { Send, Paperclip, X } from 'lucide-react';

import { useAuth } from '@/features/auth/hooks/useAuth';

import { toast } from 'sonner';
import { getFileType, uploadMedia, validateFileSize } from '@/lib/cloudinary.service';
import { sendMediaMessage } from '@/lib/messages.service';
import { fetchChatUsers } from '@/lib/chatRooms.service';

// Generate consistent color for user based on their ID
const getUserColor = (userId: string) => {
  const colors = [
    '#E91E63', '#9C27B0', '#673AB7', '#3F51B5', '#2196F3', '#00BCD4',
    '#009688', '#4CAF50', '#8BC34A', '#FF9800', '#FF5722', '#795548',
  ];
  let hash = 0;
  for (let i = 0; i < userId.length; i++) {
    hash = userId.charCodeAt(i) + ((hash << 5) - hash);
  }
  return colors[Math.abs(hash) % colors.length];
};

interface ChatInputProps {
  onSend: (message: string, metadata?: { mentions?: string[]; parentId?: string; replyTo?: { text: string; senderName: string } }) => void;
  disabled?: boolean;
  placeholder?: string;
  roomId?: string; // For media upload
  replyingTo?: { id: string; text: string; senderName: string } | null;
  onCancelReply?: () => void;
}

export interface ChatInputRef {
  focus: () => void;
}

export const ChatInput = forwardRef<ChatInputRef, ChatInputProps>(function ChatInput({
  onSend,
  disabled = false,
  placeholder = 'Type a message...',
  replyingTo = null,
  onCancelReply,
  roomId = ''
}, ref) {
  const { user } = useAuth();
  const [message, setMessage] = useState('');
  const [mentionSearch, setMentionSearch] = useState('');
  const [showMentions, setShowMentions] = useState(false);
  const [allUsers, setAllUsers] = useState<{ uid: string; fullName: string }[]>([]);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useImperativeHandle(ref, () => ({
    focus: () => {
      textareaRef.current?.focus();
    }
  }));

  useEffect(() => {
    if (!user?.uid) return;
    fetchUsers();
  }, [user?.uid]);

  const fetchUsers = async () => {
    try {
      const users = (await fetchChatUsers()).filter((u) => u.uid !== user?.uid);
      console.log('Fetched users for mentions:', users.length);
      setAllUsers(users);
    } catch (error) {
      console.error('Error fetching users for mentions:', error);
    }
  };

  const handleSend = () => {
    const trimmedMessage = message.trim();
    if (trimmedMessage && !disabled) {
      // Find mentions in text
      const mentions = allUsers
        .filter(u => trimmedMessage.includes(`@${u.fullName}`))
        .map(u => u.uid);

      onSend(trimmedMessage, { 
        mentions: mentions.length > 0 ? mentions : undefined,
        parentId: replyingTo?.id,
        replyTo: replyingTo ? { text: replyingTo.text, senderName: replyingTo.senderName } : undefined
      });
      setMessage('');
      if (onCancelReply) onCancelReply();
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
      }
    }
  };

  const handleInputChange = (val: string) => {
    setMessage(val);
    const lastAt = val.lastIndexOf('@');
    if (lastAt !== -1 && lastAt >= val.lastIndexOf(' ')) {
      const query = val.substring(lastAt + 1);
      setMentionSearch(query);
      setShowMentions(true);
    } else {
      setShowMentions(false);
    }
  };

  const insertMention = (u: { uid: string; fullName: string }) => {
    const lastAt = message.lastIndexOf('@');
    const cursor = textareaRef.current?.selectionEnd || message.length;
    const newVal = message.substring(0, lastAt) + `@${u.fullName} ` + message.substring(cursor);
    setMessage(newVal);
    setShowMentions(false);
    textareaRef.current?.focus();
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 120)}px`;
    }
  }, [message]);

  const isEmpty = message.trim().length === 0;
  const filteredMentionUsers = allUsers.filter(u => 
    u.fullName.toLowerCase().includes(mentionSearch.toLowerCase())
  ).slice(0, 5);

  return (
    <div className="flex flex-col w-full relative">
      {/* Reply Preview */}
      {replyingTo && (
        <div className="bg-secondary/30 border-b border-border/50">
          <div className="px-4 py-2 flex justify-between items-center">
            <div className="flex-1 min-w-0 flex items-center gap-2">
              <div className="w-1 h-10 bg-primary rounded-full"></div>
              <div className="flex-1 min-w-0">
                <p className="text-xs font-semibold text-primary">Replying to {replyingTo.senderName}</p>
                <p className="text-sm text-muted-foreground truncate">{replyingTo.text}</p>
              </div>
            </div>
            <Button variant="ghost" size="icon" className="h-8 w-8 rounded-full hover:bg-muted transition-all" onClick={onCancelReply}>
              <X className="w-4 h-4" />
            </Button>
          </div>
        </div>
      )}

      {/* Mention Dropdown */}
      {showMentions && filteredMentionUsers.length > 0 && (
        <div className="absolute bottom-full left-4 right-4 mb-2 bg-card border border-border shadow-xl rounded-xl overflow-hidden animate-scale-in z-50">
          <ScrollArea className="h-48">
            <div className="p-2 space-y-1">
              {filteredMentionUsers.map(u => (
                <button
                  key={u.uid}
                  className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-accent text-left rounded-lg transition-colors"
                  onClick={() => insertMention(u)}
                >
                  <div 
                    className="w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold text-white"
                    style={{ backgroundColor: getUserColor(u.uid) }}
                  >
                    {u.fullName[0]}
                  </div>
                  <span className="text-sm font-medium">{u.fullName}</span>
                </button>
              ))}
            </div>
          </ScrollArea>
        </div>
      )}

      <div className="chat-input-area bg-background border-t border-border">
        <div className="w-full py-2">
          <div className="flex gap-2 items-end px-2">
            {/* Attachment Button */}
            {roomId && (
              <>
                <input
                  type="file"
                  id={`file-upload-${roomId}`}
                  className="hidden"
                  onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      if (!user?.uid) {
                        toast.error('You must be signed in to upload files');
                        e.target.value = '';
                        return;
                      }

                      if (!validateFileSize(file)) {
                        toast.error('File exceeds the allowed size limit');
                        e.target.value = ''; // Reset input
                        return;
                      }

                      // Upload file
                      const loadingToast = toast.loading('Uploading file...');
                      try {
                        const fileUrl = await uploadMedia(file, user.uid);
                        const fileType = getFileType(file.type);

                        // Send media message
                        await sendMediaMessage(roomId, fileUrl, fileType, {
                          fileName: file.name,
                          fileSize: file.size
                        });

                        toast.success('File sent successfully', { id: loadingToast });
                      } catch (error) {
                        console.error('File upload error:', error);
                        toast.error('Failed to upload file', { id: loadingToast });
                      }
                      
                      e.target.value = ''; // Reset input
                    }
                  }}
                />
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-11 w-11 shrink-0 rounded-full hover:bg-accent transition-all"
                  onClick={() => document.getElementById(`file-upload-${roomId}`)?.click()}
                  title="Attach file (max 10MB)"
                >
                  <Paperclip className="w-5 h-5 text-muted-foreground" />
                </Button>
              </>
            )}

            <div className="flex-1 bg-secondary/50 rounded-3xl border border-border/50 px-4 py-2 flex items-center gap-2">
              <Textarea
                ref={textareaRef}
                value={message}
                onChange={(e) => handleInputChange(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder={placeholder}
                disabled={disabled}
                className="flex-1 min-h-[28px] max-h-[120px] resize-none bg-transparent border-0 px-0 py-1 text-[15px] text-foreground placeholder:text-muted-foreground/60 focus-visible:ring-0 focus-visible:ring-offset-0 shadow-none"
                rows={1}
              />
            </div>
            
            <Button
              onClick={handleSend}
              disabled={isEmpty || disabled}
              size="icon"
              className="h-11 w-11 shrink-0 rounded-full bg-primary hover:bg-primary/90 text-primary-foreground shadow-md disabled:opacity-50 disabled:cursor-not-allowed transition-all"
            >
              <Send className="w-5 h-5" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
});

import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger, Button } from "@pec/ui";
import { cn } from '@/lib/utils';
import { Download, FileText, Star, Trash2, Copy, MoreVertical, Reply } from 'lucide-react';
import { deleteMessage, toggleStarMessage } from '@/lib/messages.service';
import { useAuth } from '@/features/auth/hooks/useAuth';
import { toast } from 'sonner';
import { useState } from 'react';
import { ImageLightbox } from '@/features/chat/ImageLightbox';

import Link from 'next/link';

// Generate consistent color for user based on their ID
const getUserColor = (userId: string) => {
  const colors = [
    '#E91E63', // Pink
    '#9C27B0', // Purple
    '#673AB7', // Deep Purple
    '#3F51B5', // Indigo
    '#2196F3', // Blue
    '#00BCD4', // Cyan
    '#009688', // Teal
    '#4CAF50', // Green
    '#8BC34A', // Light Green
    '#FF9800', // Orange
    '#FF5722', // Deep Orange
    '#795548', // Brown
  ];
  
  let hash = 0;
  for (let i = 0; i < userId.length; i++) {
    hash = userId.charCodeAt(i) + ((hash << 5) - hash);
  }
  
  return colors[Math.abs(hash) % colors.length];
};

export interface Message {
  id: string;
  content: string;
  senderId: string;
  senderName: string;
  timestamp: Date;
  isOwn: boolean;
  type?: "text" | "image" | "video" | "file";
  mediaUrl?: string;
  fileName?: string;
  fileSize?: number;
  starredBy?: string[];
  deletedAt?: any;
  replyTo?: { text: string; senderName: string };
  mentions?: string[];
  parentId?: string;
}

interface ChatMessageProps {
  message: Message;
  showSenderName?: boolean;
  roomId?: string;
  onReply?: (message: Message) => void;
  onReplyClick?: () => void;
}

export function ChatMessage({ message, showSenderName = true, roomId = '', onReply = () => {}, onReplyClick }: ChatMessageProps) {
  const { user } = useAuth();
  const [lightboxImage, setLightboxImage] = useState<string | null>(null);
  const isStarred = message.starredBy?.includes(user?.uid || "") || false;
  const userRole = user?.role as string;
  const isAdmin = userRole === "admin" || userRole === "college_admin";
  const canDelete = message.isOwn || isAdmin; // Owner or admin can delete
  const canStar = !!roomId; // Anyone can star if roomId exists
  const canCopy = !!message.content; // Can copy if there's text

  const formattedTime = message.timestamp.toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: true,
  });

  const formatFileSize = (bytes?: number) => {
    if (!bytes) return "";
    const mb = bytes / 1024 / 1024;
    return mb > 1 ? `${mb.toFixed(2)} MB` : `${(bytes / 1024).toFixed(2)} KB`;
  };

  const handleDelete = async () => {
    if (!roomId) return;
    try {
      await deleteMessage(roomId, message.id, true);
      toast.success("Message deleted");
    } catch (error) {
      toast.error("Failed to delete message");
    }
  };

  const handleStar = async () => {
    if (!user || !roomId) return;
    try {
      await toggleStarMessage(roomId, message.id, user.uid, !isStarred);
      toast.success(isStarred ? "Removed from starred" : "Added to starred");
    } catch (error) {
      toast.error("Failed to star message");
    }
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(message.content);
    toast.success("Copied to clipboard");
  };

  if (message.deletedAt) {
    return (
      <div className={cn('flex flex-col gap-1', message.isOwn ? 'items-end' : 'items-start')}>
        <div className="chat-bubble bg-muted/50 italic text-muted-foreground opacity-60">
          <p className="text-sm">This message was deleted</p>
        </div>
      </div>
    );
  }

  return (
    <div
      className={cn(
        'flex mb-4 group',
        message.isOwn ? 'justify-end' : 'justify-start'
      )}
    >
      <div className="flex flex-col gap-1.5 max-w-[85%] md:max-w-[80%] px-3">
        {showSenderName && !message.isOwn && (
          <Link 
            href={`/users/${message.senderId}`} 
            className="text-xs font-bold px-2 hover:underline transition-colors"
            style={{ color: getUserColor(message.senderId) }}
          >
            {message.senderName}
          </Link>
        )}
        
        <div className="relative">
          <div
            className={cn(
              'rounded-2xl px-4 py-2.5 shadow-md transition-all duration-200',
              message.isOwn 
                ? 'bg-gradient-to-br from-primary to-primary/90 text-primary-foreground rounded-br-md' 
                : 'bg-card border border-border text-foreground rounded-bl-md hover:shadow-lg'
            )}
          >
            {/* Reply Reference */}
            {message.replyTo && (
              <div 
                className="mb-2.5 p-2.5 bg-background/30 backdrop-blur-sm rounded-lg border-l-3 border-primary text-xs cursor-pointer hover:bg-background/40 transition-colors"
                onClick={onReplyClick}
              >
                <p className="font-semibold text-primary text-[11px] mb-0.5">↩️ {message.replyTo.senderName}</p>
                <p className="truncate opacity-90">{message.replyTo.text}</p>
              </div>
            )}

            {/* Media Content */}
            {message.type === "image" && message.mediaUrl && (
              <img 
                src={message.mediaUrl} 
                alt="Shared image" 
                className="rounded-lg mb-2 max-w-full cursor-pointer hover:opacity-90"
                onClick={() => setLightboxImage(message.mediaUrl!)}
              />
            )}

            {message.type === "video" && message.mediaUrl && (
              <video 
                src={message.mediaUrl} 
                controls 
                className="rounded-lg mb-2 max-w-xs"
              />
            )}

            {message.type === "file" && message.mediaUrl && (
              <a
                href={message.mediaUrl}
                download={message.fileName || "download"}
                className="flex items-center gap-3 p-3 bg-background/10 rounded-xl mb-2 hover:bg-background/20 hover:scale-[1.02] transition-all cursor-pointer border border-border/50"
              >
                <div className="p-2 bg-primary/10 rounded-lg">
                  <FileText className="w-5 h-5 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold truncate">{message.fileName || "File"}</p>
                  <p className="text-xs opacity-70">{formatFileSize(message.fileSize)}</p>
                </div>
                <div className="p-2 bg-primary/20 rounded-lg">
                  <Download className="w-4 h-4 text-primary" />
                </div>
              </a>
            )}

            {/* Text Content with Mention Highlighting */}
            {message.content && (
              <p className="text-[15px] leading-relaxed break-words">
                {message.content.split(/(@\w+(?:\s\w+)?)/g).map((part, i) => {
                  if (part.startsWith('@')) {
                    return (
                      <span 
                        key={i} 
                        className={cn(
                          "font-semibold px-1.5 py-0.5 rounded mx-0.5",
                          message.isOwn 
                            ? "bg-primary-foreground/20 text-primary-foreground" 
                            : "bg-primary/15 text-primary"
                        )}
                      >
                        {part}
                      </span>
                    );
                  }
                  return part;
                })}
              </p>
            )}
          </div>

          {/* Message Actions */}
          {roomId && (
            <div className={cn(
              "absolute top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-all duration-200",
              message.isOwn ? "-left-9" : "-right-9"
            )}>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="icon" className="h-7 w-7 rounded-full bg-background/80 backdrop-blur-sm shadow-md hover:bg-background hover:scale-110 transition-all">
                    <MoreVertical className="w-4 h-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  <DropdownMenuItem onClick={() => onReply(message)}>
                    <Reply className="w-4 h-4 mr-2" />
                    Reply
                  </DropdownMenuItem>
                  
                  {canCopy && (
                    <DropdownMenuItem onClick={handleCopy}>
                      <Copy className="w-4 h-4 mr-2" />
                      Copy
                    </DropdownMenuItem>
                  )}
                  
                  {canStar && (
                    <DropdownMenuItem onClick={handleStar}>
                      <Star className={`w-4 h-4 mr-2 ${isStarred ? "fill-yellow-400" : ""}`} />
                      {isStarred ? "Unstar" : "Star"}
                    </DropdownMenuItem>
                  )}

                  {canDelete && (
                    <DropdownMenuItem onClick={handleDelete} className="text-destructive">
                      <Trash2 className="w-4 h-4 mr-2" />
                      Delete
                    </DropdownMenuItem>
                  )}
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          )}
        </div>
        
        <span className={cn('text-[10px] text-muted-foreground px-1', message.isOwn ? 'text-right' : 'text-left')}>
          {formattedTime}
          {isStarred && <Star className="w-3 h-3 inline ml-1 fill-yellow-400" />}
        </span>
      </div>

      {/* Image Lightbox */}
      {lightboxImage && (
        <ImageLightbox
          imageUrl={lightboxImage}
          onClose={() => setLightboxImage(null)}
        />
      )}
    </div>
  );
}

import { Select, SelectContent, SelectGroup, SelectItem, SelectLabel, SelectTrigger, SelectValue } from "@pec/ui";
import { Hash, Users, Building2, ShieldCheck } from "lucide-react";

import { ChatRoom } from '@pec/shared';
import { UserRole } from '@pec/shared';

interface Props {
  rooms: ChatRoom[];
  selectedRoom: string;
  onRoomChange: (id: string) => void;
  loading?: boolean;
  userRole: UserRole;
}

export function ChatRoomSelector({
  rooms,
  selectedRoom,
  onRoomChange,
  loading,
  userRole,
}: Props) {
  const isStudent = userRole === "student";

  const generalRooms = rooms.filter((r) => r.type === "general");
  const semesterRooms = rooms.filter((r) => r.type === "semester");
  const departmentRooms = rooms.filter((r) => r.type === "department");
  const groupRooms = rooms.filter((r: any) => r.type === "group");

  // Logic to find selected data or fallback to the general room data
  const selectedRoomData = 
    rooms.find((r) => r.id === selectedRoom) || 
    rooms.find((r) => r.id === "general");

  return (
    <Select 
      // Ensure value is "general" if selectedRoom is empty
      value={selectedRoom || "general"} 
      onValueChange={onRoomChange}
    >
      <SelectTrigger className="w-[260px] bg-secondary border-border">
        <div className="flex items-center gap-2">
          {!isStudent ? (
            <ShieldCheck className="w-4 h-4 text-primary" />
          ) : (
            <Hash className="w-4 h-4 text-muted-foreground" />
          )}
          <SelectValue placeholder={loading ? "Loading…" : "General Chat"}>
            {selectedRoomData?.title}
          </SelectValue>
        </div>
      </SelectTrigger>

      <SelectContent className="bg-card border-border z-50 max-h-[400px]">
        {/* SECTION 1: GENERAL */}
        {generalRooms.length > 0 && (
          <SelectGroup>
            <SelectLabel className="text-[10px] uppercase text-muted-foreground font-bold tracking-wider px-2 py-1.5">
              Community
            </SelectLabel>
            {generalRooms.map((room) => (
              <SelectItem key={room.id} value={room.id}>
                <div className="flex items-center gap-2">
                  <Users className="w-3.5 h-3.5" />
                  <span>{room.title}</span>
                </div>
              </SelectItem>
            ))}
          </SelectGroup>
        )}

        {/* SECTION 2: DEPARTMENTS */}
        {departmentRooms.length > 0 && (
          <SelectGroup>
            <SelectLabel className="text-[10px] uppercase text-muted-foreground font-bold tracking-wider px-2 py-1.5 mt-2">
              {isStudent ? "Your Department" : "All Departments"}
            </SelectLabel>
            {departmentRooms.map((room) => (
              <SelectItem key={room.id} value={room.id}>
                <div className="flex items-center gap-2">
                  <Building2 className="w-3.5 h-3.5" />
                  <span className="truncate max-w-[190px]">
                    {room.department || room.title}
                  </span>
                </div>
              </SelectItem>
            ))}
          </SelectGroup>
        )}

        {/* SECTION 3: SEMESTERS */}
        {semesterRooms.length > 0 && (
          <SelectGroup>
            <SelectLabel className="text-[10px] uppercase text-muted-foreground font-bold tracking-wider px-2 py-1.5 mt-2">
              {isStudent ? "Your Semester" : "All Semesters"}
            </SelectLabel>
            {semesterRooms.map((room) => (
              <SelectItem key={room.id} value={room.id}>
                <div className="flex items-center gap-2">
                  <Hash className="w-3.5 h-3.5" />
                  <span>{room.title}</span>
                </div>
              </SelectItem>
            ))}
          </SelectGroup>
        )}
        {/* SECTION 4: GROUPS */}
        {groupRooms.length > 0 && (
          <SelectGroup>
            <SelectLabel className="text-[10px] uppercase text-muted-foreground font-bold tracking-wider px-2 py-1.5 mt-2">
              Groups
            </SelectLabel>
            {groupRooms.map((room) => (
              <SelectItem key={room.id} value={room.id}>
                <div className="flex items-center gap-2">
                  <Users className="w-3.5 h-3.5 text-primary" />
                  <span className="truncate max-w-[190px]">{room.title}</span>
                </div>
              </SelectItem>
            ))}
          </SelectGroup>
        )}
      </SelectContent>
    </Select>
  );
}

import { Input, Button } from "@pec/ui";
import { Hash, Users, Building2, Search, Plus, MessageCircle } from "lucide-react";
import { ChatRoom } from '@pec/shared';
import { UserRole } from '@pec/shared';
import { cn } from "@/lib/utils";

import { useState } from "react";
import { NewChatDialog } from "@/features/chat/NewChatDialog";
import { CreateGroupDialog } from "@/features/chat/CreateGroupDialog";
import { useAuth } from '@/features/auth/hooks/useAuth';

interface Props {
  rooms: ChatRoom[];
  selectedRoom: string;
  onRoomChange: (id: string) => void;
  loading?: boolean;
  userRole: UserRole;
  userId?: string; // NEW: for DM name display
  isMobileOpen?: boolean;
  onMobileClose?: () => void;
}

export function ChatSidebar({
  rooms,
  selectedRoom,
  onRoomChange,
  loading,
  userRole,
  userId,
  isMobileOpen = false,
  onMobileClose,
}: Props) {
  const { user } = useAuth();
  const [searchQuery, setSearchQuery] = useState("");
  const [isNewChatOpen, setIsNewChatOpen] = useState(false);
  const [isCreateGroupOpen, setIsCreateGroupOpen] = useState(false);
  const isStudent = userRole === "student";
  const isChatAdmin = userRole === "college_admin";

  // Helper: Get display title for DMs (show other person's name)
  const getRoomDisplayTitle = (room: ChatRoom): string => {
    if (room.type === "dm" && room.participants && room.participantNames && userId) {
      const otherUserId = room.participants.find(id => id !== userId);
      if (otherUserId && room.participantNames[otherUserId]) {
        return String(room.participantNames[otherUserId]);
      }
    }
    return room.title ?? "";
  };

  // Filter rooms based on search
  const filteredRooms = rooms.filter((room) =>
    room && getRoomDisplayTitle(room).toLowerCase().includes((searchQuery || "").toLowerCase())
  );

  const dmRooms = filteredRooms.filter((r) => r.type === "dm");
  const communityRooms = filteredRooms.filter((r) => r.type === "general");
  const departmentRooms = filteredRooms.filter((r) => r.type === "department");
  const clubRooms =
    userRole === "faculty"
      ? []
      : filteredRooms.filter((r) => r.type === "club");
  const groupRooms = filteredRooms.filter(
    (r) => r.type === "group" || r.type === "semester"
  );

  const handleRoomClick = (roomId: string) => {
    onRoomChange(roomId);
    if (onMobileClose) {
      onMobileClose();
    }
  };

  const getRoomIcon = (type: string) => {
    switch (type) {
      case "general":
        return Users;
      case "department":
        return Building2;
      case "semester":
        return Hash;
      case "group":
        return Users;
      case "dm":
        return MessageCircle;
      default:
        return Hash;
    }
  };

  return (
    <>
      {/* Sidebar */}
      <aside
        className="chat-sidebar w-full lg:w-80 bg-card border-r border-border flex flex-col h-full"
      >
        {/* Search header */}
        <div className="p-4 border-b border-border space-y-3">
          <div className="flex items-center gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                placeholder="Search chats..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            {!isChatAdmin && (
              <>
                <Button
                  size="icon"
                  variant="outline"
                  onClick={() => setIsCreateGroupOpen(true)}
                  title="Create new group"
                >
                  <Users className="w-4 h-4" />
                </Button>
                <Button
                  size="icon"
                  variant="default"
                  onClick={() => setIsNewChatOpen(true)}
                  title="Start new DM"
                >
                  <Plus className="w-4 h-4" />
                </Button>
              </>
            )}
          </div>
        </div>

        {/* Rooms list */}
        <div className="flex-1 overflow-y-auto chat-sidebar-list">
          {loading ? (
            <div className="flex items-center justify-center h-32 text-sm text-muted-foreground">
              Loading chats...
            </div>
          ) : (
            <div className="p-2 space-y-1">
              {/* Direct Messages */}
              {dmRooms.length > 0 && (
                <div className="mb-4">
                  <div className="px-3 py-2 text-xs text-muted-foreground font-semibold">
                    Direct Messages
                  </div>
                  {dmRooms.map((room) => {
                    const Icon = MessageCircle;
                    return (
                      <button
                        key={room.id}
                        onClick={() => handleRoomClick(room.id)}
                        className={cn(
                          "chat-room-item w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-150 text-left",
                          selectedRoom === room.id
                            ? "bg-primary text-primary-foreground font-medium"
                            : "text-foreground/70 hover:text-foreground hover:bg-secondary"
                        )}
                      >
                        <Icon className="w-4 h-4 shrink-0" />
                        <span className="truncate text-sm">{getRoomDisplayTitle(room)}</span>
                      </button>
                    );
                  })}
                </div>
              )}

              {/* Community */}
              {communityRooms.length > 0 && (
                <div className="mb-4">
                  <div className="px-3 py-2 text-xs text-muted-foreground font-semibold">
                    Community
                  </div>
                  {communityRooms.map((room) => {
                    const Icon = getRoomIcon(room.type);
                    return (
                      <button
                        key={room.id}
                        onClick={() => handleRoomClick(room.id)}
                        className={cn(
                          "chat-room-item w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-150 text-left",
                          selectedRoom === room.id
                            ? "bg-primary text-primary-foreground font-medium"
                            : "text-foreground/70 hover:text-foreground hover:bg-secondary"
                        )}
                      >
                        <Icon className="w-4 h-4 shrink-0" />
                        <span className="truncate text-sm">{room.title}</span>
                      </button>
                    );
                  })}
                </div>
              )}

              {/* Department Groups */}
              {departmentRooms.length > 0 && (
                <div className="mb-4">
                  <div className="px-3 py-2 text-xs text-muted-foreground font-semibold">
                    Department Groups
                  </div>
                  {departmentRooms.map((room) => {
                    const Icon = getRoomIcon(room.type);
                    return (
                      <button
                        key={room.id}
                        onClick={() => handleRoomClick(room.id)}
                        className={cn(
                          "chat-room-item w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-150 text-left",
                          selectedRoom === room.id
                            ? "bg-primary text-primary-foreground font-medium"
                            : "text-foreground/70 hover:text-foreground hover:bg-secondary"
                        )}
                      >
                          <Icon className="w-4 h-4 shrink-0" />
                        <span className="truncate text-sm">{room.title}</span>
                      </button>
                    );
                  })}
                </div>
              )}

              {/* Club Groups */}
              {clubRooms.length > 0 && (
                <div className="mb-4">
                  <div className="px-3 py-2 text-xs text-muted-foreground font-semibold">
                    Club Groups
                  </div>
                  {clubRooms.map((room) => {
                    const Icon = getRoomIcon(room.type);
                    return (
                      <button
                        key={room.id}
                        onClick={() => handleRoomClick(room.id)}
                        className={cn(
                          "chat-room-item w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-150 text-left",
                          selectedRoom === room.id
                            ? "bg-primary text-primary-foreground font-medium"
                            : "text-foreground/70 hover:text-foreground hover:bg-secondary"
                        )}
                      >
                        <Icon className="w-4 h-4 shrink-0" />
                        <span className="truncate text-sm">{room.title}</span>
                      </button>
                    );
                  })}
                </div>
              )}

              {/* Groups */}
              {groupRooms.length > 0 && (
                <div className="mb-4">
                  <div className="px-3 py-2 text-xs text-muted-foreground font-semibold">
                    Groups
                  </div>
                  {groupRooms.map((room) => {
                    const Icon = getRoomIcon(room.type);
                    return (
                      <button
                        key={room.id}
                        onClick={() => handleRoomClick(room.id)}
                        className={cn(
                          "chat-room-item w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-150 text-left",
                          selectedRoom === room.id
                            ? "bg-primary text-primary-foreground font-medium shadow-md shadow-primary/20"
                            : "text-foreground/70 hover:text-foreground hover:bg-secondary"
                        )}
                      >
                        <Icon className="w-4 h-4 shrink-0" />
                        <span className="truncate text-sm">{room.title}</span>
                      </button>
                    );
                  })}
                </div>
              )}

              {/* No results */}
              {filteredRooms.length === 0 && (
                <div className="flex flex-col items-center justify-center h-32 text-center px-4">
                  <p className="text-sm text-muted-foreground">No chats found</p>
                  {searchQuery && (
                    <button
                      onClick={() => setSearchQuery("")}
                      className="text-xs text-primary mt-2 hover:underline"
                    >
                      Clear search
                    </button>
                  )}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Debug/Role Indicator */}
        <div className="p-2 border-t border-border bg-muted/20">
          <p className="text-[10px] text-center text-muted-foreground uppercase tracking-widest font-mono">
            {userRole || "Guest"} view
          </p>
        </div>
      </aside>

      {/* New Chat Dialog */}
      <NewChatDialog
        open={isNewChatOpen}
        onOpenChange={setIsNewChatOpen}
        onRoomCreated={onRoomChange}
      />

      {/* Create Group Dialog */}
      {user && (
        <CreateGroupDialog
          open={isCreateGroupOpen}
          onOpenChange={setIsCreateGroupOpen}
          onGroupCreated={onRoomChange}
          currentUser={{
            uid: user.uid,
            organizationId: user.organizationId
          }}
        />
      )}
    </>
  );
}

import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, Input, Button, Badge } from "@pec/ui";
import { useState, useEffect } from "react";
import { Search, Loader2, X, Check } from "lucide-react";

import api from "@pec/api";
import { createGroupRoom } from "@/lib/chatRooms.service";
import { toast } from "sonner";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onGroupCreated: (roomId: string) => void;
  currentUser: { uid: string; organizationId: string };
}

export function CreateGroupDialog({ open, onOpenChange, onGroupCreated, currentUser }: Props) {
  const [name, setName] = useState("");
  const [search, setSearch] = useState("");
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [selectedUsers, setSelectedUsers] = useState<any[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isCreating, setIsCreating] = useState(false);

  useEffect(() => {
    const searchUsers = async () => {
      if (search.length < 2) {
        setSearchResults([]);
        return;
      }

      setIsSearching(true);
      try {
        const res = await api.get("/chat/users", { params: { q: search } });
        setSearchResults(res.data?.data || res.data || []);
      } catch (error) {
        console.error("Search error:", error);
      } finally {
        setIsSearching(false);
      }
    };

    const timer = setTimeout(searchUsers, 500);
    return () => clearTimeout(timer);
  }, [search]);

  const handleToggleUser = (user: any) => {
    if (selectedUsers.find((u) => u.id === user.id)) {
      setSelectedUsers(selectedUsers.filter((u) => u.id !== user.id));
    } else {
      setSelectedUsers([...selectedUsers, user]);
    }
  };

  const handleCreate = async () => {
    if (!name.trim()) {
      toast.error("Please enter a group name");
      return;
    }

    if (selectedUsers.length === 0) {
      toast.error("Please select at least one participant");
      return;
    }

    setIsCreating(true);
    try {
      const room = await createGroupRoom(
        name.trim(),
        selectedUsers.map((u) => u.id)
      );
      toast.success(`Group "${name}" created!`);
      onGroupCreated(room.id);
      window.dispatchEvent(new Event("chat-rooms-updated"));
      onOpenChange(false);
      reset();
    } catch (error) {
      toast.error("Failed to create group");
      console.error(error);
    } finally {
      setIsCreating(false);
    }
  };

  const reset = () => {
    setName("");
    setSearch("");
    setSelectedUsers([]);
    setSearchResults([]);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Create New Group</DialogTitle>
          <DialogDescription>
            Create a private space for your team or project.
          </DialogDescription>
        </DialogHeader>
        <div className="flex flex-col gap-4 py-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">Group Name</label>
            <Input
              placeholder="e.g. Project Alpha"
              value={name}
              onChange={(e) => setName(e.target.value)}
              disabled={isCreating}
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Add Participants</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                placeholder="Search by name or email..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-10"
                disabled={isCreating}
              />
            </div>

            {selectedUsers.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2">
                {selectedUsers.map((u) => (
                  <Badge key={u.id} variant="secondary" className="gap-1">
                    {u.name || u.email}
                    <X
                      className="w-3 h-3 cursor-pointer hover:text-destructive"
                      onClick={() => handleToggleUser(u)}
                    />
                  </Badge>
                ))}
              </div>
            )}

            <div className="max-h-40 overflow-y-auto border rounded-md mt-2">
              {isSearching ? (
                <div className="p-4 flex justify-center">
                  <Loader2 className="w-4 h-4 animate-spin text-muted-foreground" />
                </div>
              ) : searchResults.length > 0 ? (
                searchResults.map((user) => (
                  <button
                    key={user.id}
                    className="w-full flex items-center justify-between px-3 py-2 hover:bg-secondary text-sm transition-colors"
                    onClick={() => handleToggleUser(user)}
                  >
                    <div className="text-left">
                      <p className="font-medium">{user.name}</p>
                      <p className="text-xs text-muted-foreground">{user.email}</p>
                    </div>
                    {selectedUsers.find((u) => u.id === user.id) && (
                      <Check className="w-4 h-4 text-primary" />
                    )}
                  </button>
                ))
              ) : search.length >= 2 ? (
                <p className="p-4 text-center text-xs text-muted-foreground">No users found</p>
              ) : null}
            </div>
          </div>

          <Button onClick={handleCreate} disabled={isCreating || !name.trim() || selectedUsers.length === 0}>
            {isCreating ? (
              <>
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                Creating...
              </>
            ) : (
              "Create Group"
            )}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";
import { Button } from "@pec/ui";


declare global {
  interface Window {
    SpeechRecognition: any;
    webkitSpeechRecognition: any;
  }
}

import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Bot, Send, X, Mic, Volume2, VolumeX } from "lucide-react";

import { useAuth } from "@/features/auth/hooks/useAuth";
import {  isAuthError  } from "@pec/api";
import {  buildApiUrl  } from "@pec/api";
import {  authClient  } from "@pec/api";
import { useRouter } from "next/navigation";
import { useResizable } from "./hooks/useResizable";
import { useSpeechToText } from "./hooks/useSpeechToText";
import { ChatMessageItem } from "./components/ChatMessageItem";

const SYSTEM_PROMPT = `
You are the PEC AI Assistant — an intelligent campus agent for PEC University.
Always address the user by name when available. Be concise, helpful, and action-oriented.
You have access to real backend tools that fetch live data. NEVER fabricate or invent data.

TOOLS AND BEHAVIOR:

1. GRADES — call tool get_user_grades. The data will be shown automatically in a table.
   After the tool runs, write a short 1-2 sentence summary (CGPA, best/worst subject). Do NOT list or repeat raw data.

2. ATTENDANCE — call tool get_user_attendance. The report will be shown automatically in a table.
   After the tool runs, write a short 1-2 sentence summary (overall %, any courses at risk). Do NOT list or repeat raw data.

3. SCHEDULE/TIMETABLE — call tool get_user_schedule. The timetable will be shown automatically.
   After the tool runs, mention how many classes they have today. Do NOT list or repeat raw data.

4. HOSTEL ISSUES — call tool get_hostel_issues. The issues list will be shown automatically.
   After the tool runs, write a short 1-2 sentence summary. Do NOT repeat or list raw data.

5. CANTEEN MENU — call tool get_canteen_menu or get_night_canteen_menu. The menu will be shown automatically.
   After the tool runs, write a short 1-2 sentence summary. Do NOT repeat or list raw data.

6. CLUBS — call tool get_clubs. The clubs list will be shown automatically.
   After the tool runs, write a short 1-2 sentence summary. Do NOT repeat or list raw data.

7. FINANCE/FEES — call tool get_finance_summary. The summary card will be shown automatically.
   After the tool runs, write a short 1-2 sentence summary. Do NOT repeat or list raw data.

8. EVENTS/CALENDAR — call tool get_upcoming_events. The events list will be shown automatically.
   After the tool runs, write a short 1-2 sentence summary of the next upcoming event. Do NOT repeat or list raw data.

9. NAVIGATION — when user asks to go to, visit, open, or be taken to any page:
   ALWAYS call the navigate_to_page tool. Do NOT write the path as text.
   Valid pages: Marketplace, Attendance, Grades, Timetable, Noticeboard, Canteen, Finance, Profile, Clubs, Hostel, Dashboard.
   After the tool runs, write a short friendly confirmation (e.g. "Taking you to the Marketplace now! 🛒").

10. QUICK REPLIES — always end with 2-3 options:
<UI:SuggestionChip>["option 1", "option 2", "option 3"]</UI>

Rules:
- Do NOT emit components like <UI:GradesTable>, <UI:HostelIssuesList>, or <UI:CanteenMenuList> tags — the system handles that automatically.
- Do NOT invent any data. If a tool fails or returns empty, tell the user clearly.
- Keep responses concise and helpful.
`;

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  timestamp: Date;
}

const FloatingAIChat = () => {
  const [isOpen, setIsOpen] = useState(false);
  const { user, isAuthenticated, isLoading: authLoading } = useAuth();
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const router = useRouter();

  // Sizing physics extracted to custom hook
  const { width, height, handleResizeStart } = useResizable();

  // Speech-to-text logic extracted to custom hook
  const { isListening, micError, setMicError, interimText, handleMicClick } = useSpeechToText(
    (finalText) => setInputValue((prev) => (prev ? prev + " " : "") + finalText)
  );

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "auto" });
  };

  useEffect(() => {
    setMessages([
      {
        id: "1",
        role: "assistant",
        content: "Hello! I'm your **PEC AI Assistant**. How can I help you today?\n<UI:SuggestionChip>[\"Show me my grades\", \"What is my attendance?\", \"Take me to the marketplace\"]</UI>",
        timestamp: new Date(),
      },
    ]);
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isTyping]);

  const speakText = (text: string) => {
    if (!isVoiceEnabled || !window.speechSynthesis) return;
    
    // Clean up UI tags and markdown
    const cleanText = text
      .replace(/<UI:.*?>[\s\S]*?<\/UI>/g, '')
      .replace(/[\*\#\_]/g, '')
      .trim();

    if (!cleanText) return;

    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(cleanText);
    window.speechSynthesis.speak(utterance);
  };

  const handleSend = async (overrideText?: string) => {
    const textToSend = overrideText || inputValue;
    if (!textToSend.trim() || isTyping) return;

    if (authLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: "user",
      content: textToSend.trim(),
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInputValue("");
    setIsTyping(true);

    try {
      const requestBody = {
        messages: [
          {
            role: "system",
            content: SYSTEM_PROMPT,
          },
          ...messages.slice(-6).map((m) => ({ role: m.role, content: m.content })),
          { role: "user", content: userMessage.content },
        ],
      };

      const aiResponseId = (Date.now() + 1).toString();
      const fullUrl = buildApiUrl('/ai/completion');
      const token = authClient.getAccessToken();

      const fetchRes = await fetch(fullUrl, {
        method: 'POST',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { 'Authorization': `Bearer ${token}` } : {})
        },
        body: JSON.stringify(requestBody)
      });

      if (!fetchRes.ok) {
        throw new Error('Network response was not ok');
      }

      const reader = fetchRes.body?.getReader();
      const decoder = new TextDecoder();
      
      if (!reader) throw new Error('No readable stream');

      let done = false;
      let fullText = "";
      let hasCreatedMessage = false;
      let buffer = ""; // Buffer to handle network data splitting / fragmentation

      while (!done) {
        const { value, done: readerDone } = await reader.read();
        done = readerDone;
        if (value) {
          // Stream decoding
          const chunk = decoder.decode(value, { stream: !done });
          const text = buffer + chunk;
          const lines = text.split('\n');
          buffer = lines.pop() || ""; // Save partial line for next iteration
          
          for (const line of lines) {
            if (line.startsWith('data: ') && line !== 'data: [DONE]') {
              try {
                const data = JSON.parse(line.slice(6));
                
                const ensureMessageExists = (initialContent: string = "") => {
                  if (!hasCreatedMessage) {
                    hasCreatedMessage = true;
                    setIsTyping(false); // Hide thinking dots when content starts showing
                    setMessages(prev => [
                      ...prev,
                      {
                        id: aiResponseId,
                        role: "assistant",
                        content: initialContent,
                        timestamp: new Date(),
                      }
                    ]);
                  }
                };

                if (data.tool) {
                  let thinkingText = "⚙️ Working...";
                  if (data.tool === "get_user_grades") thinkingText = "📊 Fetching your academic transcript...";
                  else if (data.tool === "get_user_attendance") thinkingText = "📅 Calculating your attendance & predictions...";
                  else if (data.tool === "get_user_schedule") thinkingText = "🗓️ Loading your weekly timetable...";
                  else if (data.tool === "navigate_to_page") thinkingText = "🚦 Navigating...";
                  else if (data.tool === "search_marketplace") thinkingText = "🛍️ Searching the marketplace...";
                  else if (data.tool === "get_upcoming_events") thinkingText = "🎉 Finding upcoming college events...";
                  else if (data.tool === "search_college_notices") thinkingText = "🔍 Scanning college notices...";
                  else if (data.tool === "get_hostel_issues") thinkingText = "🔧 Loading reported hostel issues...";
                  else if (data.tool === "get_canteen_menu") thinkingText = "🍔 Fetching day canteen menu...";
                  else if (data.tool === "get_night_canteen_menu") thinkingText = "🌙 Fetching night canteen menu...";
                  else if (data.tool === "get_clubs") thinkingText = "👥 Retrieving list of student clubs...";
                  else if (data.tool === "get_finance_summary") thinkingText = "💳 Gathering your pending dues & fee status...";
                  
                  ensureMessageExists(`_${thinkingText}_`);
                  setMessages(prev => 
                    prev.map(msg => 
                      msg.id === aiResponseId ? { ...msg, content: `_${thinkingText}_` } : msg
                    )
                  );
                } else if (data.navigate) {
                  const navPath = data.navigate as string;
                  const navName = navPath.replace('/', '').replace('-', ' ').replace(/\b\w/g, (c) => c.toUpperCase()) || 'Page';
                  ensureMessageExists(`↗️ Taking you to **${navName}**...`);
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId
                        ? {
                            ...msg,
                            content: `↗️ Taking you to **${navName}**...`,
                          }
                        : msg
                    )
                  );
                  setTimeout(() => router.push(navPath), 600);
                } else if (data.gradesData) {
                  ensureMessageExists();
                  fullText += `<UI:GradesTable>${JSON.stringify(data.gradesData)}</UI>`;
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.attendanceData) {
                  ensureMessageExists();
                  fullText += `<UI:AttendanceTable>${JSON.stringify(data.attendanceData)}</UI>`;
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.scheduleData) {
                  ensureMessageExists();
                  fullText += `<UI:ScheduleTable>${JSON.stringify(data.scheduleData)}</UI>`;
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.hostelIssuesData) {
                  ensureMessageExists();
                  fullText += `<UI:HostelIssuesList>${JSON.stringify(data.hostelIssuesData)}</UI>`;
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.canteenData) {
                  ensureMessageExists();
                  fullText += `<UI:CanteenMenuList>${JSON.stringify(data.canteenData)}</UI>`;
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.nightCanteenData) {
                  ensureMessageExists();
                  fullText += `<UI:NightCanteenMenuList>${JSON.stringify(data.nightCanteenData)}</UI>`;
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.clubsData) {
                  ensureMessageExists();
                  fullText += `<UI:ClubsList>${JSON.stringify(data.clubsData)}</UI>`;
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.financeData) {
                  ensureMessageExists();
                  fullText += `<UI:FinanceSummaryCard>${JSON.stringify(data.financeData)}</UI>`;
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.eventsData) {
                  ensureMessageExists();
                  fullText += `<UI:EventsList>${JSON.stringify(data.eventsData)}</UI>`;
                  setMessages(prev =>
                    prev.map(msg =>
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.text) {
                  ensureMessageExists();
                  fullText += data.text;
                  setMessages(prev => 
                    prev.map(msg => 
                      msg.id === aiResponseId ? { ...msg, content: fullText } : msg
                    )
                  );
                } else if (data.error) {
                  throw new Error(data.error);
                }
              } catch (e) {
                // Ignore parse errors from chunk fragmentation
              }
            }
          }
        }
      }

      // If the model printed suggest arrays, tag them
      if (fullText) {
        const bareChipsRegex = /(\[(?:\s*"[^"]*"\s*(?:,\s*"[^"]*"\s*)*)\])\s*$/;
        const chipMatch = fullText.match(bareChipsRegex);

        if (chipMatch && !fullText.includes('<UI:SuggestionChip>')) {
          const arrayStr = chipMatch[1];
          const beforeChips = fullText.slice(0, fullText.lastIndexOf(arrayStr)).trimEnd();
          fullText = `${beforeChips}\n<UI:SuggestionChip>${arrayStr}</UI>`;
          setMessages(prev =>
            prev.map(msg =>
              msg.id === aiResponseId ? { ...msg, content: fullText } : msg
            )
          );
        }
      }

      speakText(fullText);

    } catch (error) {
      console.error("AI Error:", error);
      const message = isAuthError(error)
        ? "Your session has expired. Please sign in again to continue."
        : "I'm sorry, I'm having trouble connecting to my brain. Please try again later.";
      setMessages((prev) => [
        ...prev,
        {
          id: Date.now().toString(),
          role: "assistant",
          content: message,
          timestamp: new Date(),
        },
      ]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

