}

const attendanceRowColor = (pct: number) => {
  if (pct >= 85) return 'bg-emerald-50 dark:bg-emerald-900/10';
  if (pct >= 75) return 'bg-blue-50 dark:bg-blue-900/10';
  if (pct >= 65) return 'bg-amber-50 dark:bg-amber-900/10';
  return 'bg-red-50 dark:bg-red-900/10';
};

const attendanceBadge = (pct: number) => {
  if (pct >= 85) return 'text-emerald-700 bg-emerald-100 dark:text-emerald-300 dark:bg-emerald-900/40';
  if (pct >= 75) return 'text-blue-700 bg-blue-100 dark:text-blue-300 dark:bg-blue-900/40';
  if (pct >= 65) return 'text-amber-700 bg-amber-100 dark:text-amber-300 dark:bg-amber-900/40';
  return 'text-red-700 bg-red-100 dark:text-red-300 dark:bg-red-900/40';
};

const progressBar = (pct: number) => {
  const clamp = Math.min(100, Math.max(0, pct));
  const color = pct >= 85 ? 'bg-emerald-500' : pct >= 75 ? 'bg-blue-500' : pct >= 65 ? 'bg-amber-500' : 'bg-red-500';
  return (
    <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-1.5 mt-1">
      <div className={`h-1.5 rounded-full transition-all ${color}`} style={{ width: `${clamp}%` }} />
    </div>
  );
};

export const AttendanceTable = ({ data }: { data: AttendanceData }) => {
  if (!data) return null;

  // Legacy fallback: if old format with records[]
  if (!data.courses && data.records) {
    const records = data.records;
    const total = records.length;
    const present = records.filter((r: any) => r.status === 'present').length;
    const percentage = total > 0 ? Math.round((present / total) * 100) : 0;
    const isGood = percentage >= 75;
    return (
      <div className="w-full bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm overflow-hidden my-3">
        <div className={`${isGood ? 'bg-emerald-600' : 'bg-red-600'} px-4 py-3 flex items-center justify-between text-white`}>
          <div className="flex items-center gap-2">
            <Calendar className="w-4 h-4" />
            <span className="font-semibold text-sm">Attendance Summary</span>
          </div>
          <span className="font-bold text-sm">{percentage}%</span>
        </div>
        <div className="p-3 text-xs text-gray-500 dark:text-gray-400">
          {present}/{total} classes attended
        </div>
      </div>
    );
  }

  const courses = data.courses ?? [];
  const total = data.totalSummary;

  if (courses.length === 0) {
    return (
      <div className="w-full bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm p-5 my-3 text-center text-sm text-gray-500">
        {data.message ?? 'No attendance records found.'}
      </div>
    );
  }

  const overallPct = total?.percentage ?? 0;
  const overallColor = overallPct >= 75 ? 'from-emerald-600 to-teal-600' : 'from-red-600 to-rose-600';

  return (
    <div className="w-full bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-md overflow-hidden my-3">
      {/* Header */}
      <div className={`bg-gradient-to-r ${overallColor} px-4 py-3 flex items-center justify-between text-white`}>
        <div className="flex items-center gap-2">
          <Calendar className="w-4 h-4" />
          <span className="font-semibold text-sm">Attendance Report</span>
        </div>
        <div className="flex items-center gap-2 text-sm">
          <span className="text-white/80 text-xs">{total?.present ?? 0}/{total?.total ?? 0} classes</span>
          <span className="font-bold bg-white/20 px-2 py-0.5 rounded-full">{overallPct}% overall</span>
        </div>
      </div>

      {/* Overall progress bar */}
      <div className="px-4 pt-2 pb-1">
        <div className="flex justify-between text-[10px] text-gray-400 mb-1">
          <span>Overall attendance</span>
          <span className={overallPct >= 75 ? 'text-emerald-600 font-semibold' : 'text-red-600 font-semibold'}>
            {overallPct >= 75 ? '✓ Above 75% threshold' : '⚠ Below 75% threshold'}
          </span>
        </div>
        {progressBar(overallPct)}
      </div>

      {/* Per-course table */}
      <div className="overflow-x-auto">
        <table className="w-full text-sm mt-2">
          <thead>
            <tr className="text-[11px] text-gray-400 dark:text-gray-500 uppercase border-b border-gray-100 dark:border-gray-700">
              <th className="text-left px-4 py-2 font-medium">Course</th>
              <th className="text-center px-2 py-2 font-medium">P</th>
              <th className="text-center px-2 py-2 font-medium">A</th>
              <th className="text-center px-2 py-2 font-medium">L</th>
              <th className="text-center px-2 py-2 font-medium">Total</th>
              <th className="text-left px-3 py-2 font-medium">Status</th>
            </tr>
          </thead>
          <tbody>
            {courses.map((c, idx) => (
              <tr
                key={idx}
                className={`border-b border-gray-50 dark:border-gray-700/50 ${attendanceRowColor(c.percentage)}`}
              >
                <td className="px-4 py-2.5">
                  <div className="font-medium text-gray-800 dark:text-gray-200 text-xs leading-tight truncate max-w-[110px]" title={c.courseName}>
                    {c.courseName}
                  </div>
                  <div className="text-[10px] text-gray-400 font-mono">{c.courseCode}</div>
                  {progressBar(c.percentage)}
                </td>
                <td className="px-2 py-2.5 text-center text-emerald-600 dark:text-emerald-400 font-medium text-xs">{c.present}</td>
                <td className="px-2 py-2.5 text-center text-red-500 dark:text-red-400 font-medium text-xs">{c.absent}</td>
                <td className="px-2 py-2.5 text-center text-amber-500 dark:text-amber-400 font-medium text-xs">{c.late}</td>
                <td className="px-2 py-2.5 text-center">
                  <span className={`text-[11px] font-bold px-1.5 py-0.5 rounded ${attendanceBadge(c.percentage)}`}>
                    {c.percentage}%
                  </span>
                </td>
                <td className="px-3 py-2.5">
                  {c.canSkip > 0 ? (
                    <span className="flex items-center gap-1 text-emerald-600 dark:text-emerald-400 text-[11px] font-medium whitespace-nowrap">
                      <TrendingUp className="w-3 h-3" /> Skip {c.canSkip}
                    </span>
                  ) : c.needed > 0 ? (
                    <span className="flex items-center gap-1 text-red-600 dark:text-red-400 text-[11px] font-medium whitespace-nowrap">
                      <AlertTriangle className="w-3 h-3" /> Need {c.needed}
                    </span>
                  ) : (
                    <span className="flex items-center gap-1 text-gray-500 text-[11px] whitespace-nowrap">
                      <Minus className="w-3 h-3" /> Borderline
                    </span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Legend */}
      <div className="bg-gray-50 dark:bg-gray-900/30 px-4 py-2 text-[10px] text-gray-400 border-t border-gray-100 dark:border-gray-700 flex gap-3 flex-wrap">
        <span>P = Present · A = Absent · L = Late (0.5 credit)</span>
      </div>
    </div>
  );
};

import { useState, useEffect } from 'react';

export const useResizable = (minWidth = 320, minHeight = 400) => {
  const [width, setWidth] = useState(400);
  const [height, setHeight] = useState(600);

  useEffect(() => {
    const handleScreenResize = () => {
      const maxW = window.innerWidth - 32;
      const maxH = window.innerHeight - 100;
      setWidth(prev => Math.min(prev, maxW));
      setHeight(prev => Math.min(prev, maxH));
    };
    handleScreenResize();
    window.addEventListener("resize", handleScreenResize);
    return () => window.removeEventListener("resize", handleScreenResize);
  }, []);

  const handleResizeStart = (
    e: React.MouseEvent | React.TouchEvent | any,
    direction: "n" | "w" | "nw"
  ) => {
    e.preventDefault();
    const startWidth = width;
    const startHeight = height;
    const startX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const startY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    const handleMouseMove = (moveEvent: MouseEvent | TouchEvent) => {
      const currentX = 'touches' in moveEvent ? moveEvent.touches[0].clientX : moveEvent.clientX;
      const currentY = 'touches' in moveEvent ? moveEvent.touches[0].clientY : moveEvent.clientY;

      const deltaX = currentX - startX;
      const deltaY = currentY - startY;

      const maxW = window.innerWidth - 32;
      const maxH = window.innerHeight - 100;

      if (direction === "w" || direction === "nw") {
        const newWidth = Math.max(minWidth, Math.min(maxW, startWidth - deltaX));
        setWidth(newWidth);
      }
      if (direction === "n" || direction === "nw") {
        const newHeight = Math.max(minHeight, Math.min(maxH, startHeight - deltaY));
        setHeight(newHeight);
      }
    };

    const handleMouseUp = () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
      document.removeEventListener("touchmove", handleMouseMove);
      document.removeEventListener("touchend", handleMouseUp);
    };

    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleMouseUp);
    document.addEventListener("touchmove", handleMouseMove, { passive: true });
    document.addEventListener("touchend", handleMouseUp);
  };

  return { width, height, handleResizeStart };
};

import { useState, useRef, useEffect } from 'react';

export const useSpeechToText = (onTranscriptFinal: (text: string) => void) => {
  const [isListening, setIsListening] = useState(false);
  const [micError, setMicError] = useState<string | null>(null);
  const [interimText, setInterimText] = useState("");
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  const handleMicClick = async () => {
    setMicError(null);

    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      setMicError("Voice input isn't supported in this browser. Try Chrome or Edge.");
      return;
    }

    if (isListening) {
      recognitionRef.current?.stop();
      return;
    }

    try {
      await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch {
      setMicError("Microphone access denied. Please allow mic permission in your browser and try again.");
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognitionRef.current = recognition;

    recognition.continuous = false;
    recognition.interimResults = true;
    recognition.lang = 'en-US';
    recognition.maxAlternatives = 1;

    recognition.onstart = () => {
      setIsListening(true);
      setInterimText("");
    };

    recognition.onresult = (event: any) => {
      let interim = "";
      let final = "";
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const t = event.results[i][0].transcript;
        if (event.results[i].isFinal) {
          final += t;
        } else {
          interim += t;
        }
      }
      if (interim) setInterimText(interim);
      if (final) {
        setInterimText("");
        onTranscriptFinal(final.trim());
      }
    };

    recognition.onerror = (event: any) => {
      setIsListening(false);
      setInterimText("");
      recognitionRef.current = null;
      if (event.error === 'not-allowed' || event.error === 'permission-denied') {
        setMicError("Microphone access was blocked. Check browser permissions and reload.");
      } else if (event.error === 'no-speech') {
        setMicError("No speech detected. Tap the mic and speak clearly.");
      } else if (event.error === 'network') {
        setMicError("Network error during voice recognition. Check your connection.");
      } else {
        setMicError(`Voice error: ${event.error}`);
      }
    };

    recognition.onend = () => {
      setIsListening(false);
      setInterimText("");
      recognitionRef.current = null;
    };

    try {
      recognition.start();
    } catch (err: any) {
      setIsListening(false);
      setMicError(`Could not start voice input: ${err?.message ?? "unknown error"}.`);
    }
  };

  return { isListening, micError, setMicError, interimText, handleMicClick };
};

'use client';
import { Button, Textarea } from "@pec/ui";


import { useState } from 'react';
import { Loader2, X } from 'lucide-react';

import { toast } from 'sonner';
import api from "@pec/api";
import { useAuth } from '@/features/auth/hooks/useAuth';
import { uploadMedia } from '@/lib/cloudinary.service';
import {
  MediaUpload,
  type UploadedMedia,
} from '@/features/clubs/MediaUpload';

interface ClubProposalDialogProps {
  clubId: string;
  clubName: string;
  isOpen: boolean;
  onClose: () => void;
  onSubmitSuccess: () => void;
}

interface UploadedFile {
  url: string;
  kind: 'image' | 'audio' | 'video' | 'file';
  name: string;
  mimeType: string;
}

export function ClubProposalDialog({
  clubId,
  clubName,
  isOpen,
  onClose,
  onSubmitSuccess,
}: ClubProposalDialogProps) {
  const { user } = useAuth();
  const [proposal, setProposal] = useState('');
  const [media, setMedia] = useState<UploadedMedia[]>([]);
  const [loading, setLoading] = useState(false);

  const handleMediaAdd = (newMedia: UploadedMedia) => {
    setMedia((prev) => [...prev, newMedia]);
  };

  const handleMediaRemove = (id: string) => {
    setMedia((prev) => prev.filter((m) => m.id !== id));
  };

  const uploadFile = async (
    file: File,
    kind: 'image' | 'audio' | 'video' | 'file',
  ): Promise<UploadedFile> => {
    if (!user?.uid) {
      throw new Error('You must be signed in to upload media');
    }
    const url = await uploadMedia(file, user.uid);
    return {
      url,
      kind,
      name: file.name,
      mimeType: file.type,
    };
  };

  const handleSubmit = async () => {
    const proposalText = proposal.trim();

    if (!proposalText || proposalText.length < 10) {
      toast.error('Proposal must be at least 10 characters');
      return;
    }

    try {
      setLoading(true);

      // Upload all files
      const uploadedMedia: UploadedFile[] = [];
      for (const m of media) {
        const uploaded = await uploadFile(m.file, m.kind);
        uploadedMedia.push(uploaded);
      }

      // Submit proposal
      await api.post(`/chat/clubs/${clubId}/join-request`, {
        proposalText,
        media: uploadedMedia,
      });

      toast.success('Proposal submitted successfully!');
      setProposal('');
      setMedia([]);
      onSubmitSuccess();
      onClose();
    } catch (error: any) {
      console.error(error);
      toast.error(
        error?.response?.data?.error?.message ||
          'Failed to submit proposal',
      );
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
      <div className="bg-background rounded-lg shadow-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        <div className="sticky top-0 bg-background border-b border-border p-6 flex items-center justify-between">
          <div>
            <h2 className="text-xl font-bold text-foreground">Join Club</h2>
            <p className="text-sm text-muted-foreground mt-1">{clubName}</p>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={onClose}
            disabled={loading}
          >
            <X className="w-4 h-4" />
          </Button>
        </div>

        <div className="p-6 space-y-4">
          <div>
            <label className="text-sm font-medium text-foreground">
              Write Your Proposal
            </label>
            <p className="text-xs text-muted-foreground mt-1">
              Explain why you want to join this club and what you can contribute
            </p>
            <Textarea
              placeholder="Write a compelling proposal (minimum 10 characters)..."
              value={proposal}
              onChange={(e) => setProposal(e.target.value)}
              rows={4}
              className="mt-2"
              disabled={loading}
            />
            <p className="text-xs text-muted-foreground mt-1">
              {proposal.length} characters
            </p>
          </div>

          <MediaUpload
            onMediaAdd={handleMediaAdd}
            onMediaRemove={handleMediaRemove}
            maxFiles={5}
            maxSize={50 * 1024 * 1024}
          />

          <div className="border-t border-border pt-4 flex gap-2 justify-end">
            <Button variant="outline" onClick={onClose} disabled={loading}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} disabled={loading}>
              {loading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {loading ? 'Submitting...' : 'Submit Proposal'}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';
import { Button, Textarea, Badge } from "@pec/ui";


import { useEffect, useState } from 'react';
import { Loader2, Check, X, ChevronDown } from 'lucide-react';

import { toast } from 'sonner';
import api from "@pec/api";

interface ClubJoinRequest {
  id: string;
  requesterName: string;
  requesterEmail: string;
  clubName: string;
  proposalText: string;
  media: Array<{
    url: string;
    kind: 'image' | 'audio' | 'video' | 'file';
    name: string;
    mimeType: string;
  }>;
  status: 'pending' | 'approved' | 'rejected';
  createdAt: string;
}

export function ClubRequestsReview() {
  const [requests, setRequests] = useState<ClubJoinRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [reviewingId, setReviewingId] = useState<string | null>(null);
  const [reviewNote, setReviewNote] = useState('');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    void loadRequests();
  }, []);

  const loadRequests = async () => {
    try {
      setLoading(true);
      const res = await api.get('/chat/clubs/requests');
      setRequests(res.data?.data || []);
    } catch (error) {
      console.error(error);
      toast.error('Failed to load requests');
    } finally {
      setLoading(false);
    }
  };

  const handleReview = async (
    requestId: string,
    action: 'approve' | 'reject',
  ) => {
    const note = reviewNote.trim();

    if (action === 'reject' && !note) {
      toast.error('Rejection requires a note');
      return;
    }

    try {
      setSubmitting(true);
      await api.patch(`/chat/clubs/requests/${requestId}`, {
        action,
        reviewNote: note || undefined,
      });

      toast.success(action === 'approve' ? 'Request approved' : 'Request rejected');
      setReviewingId(null);
      setReviewNote('');
      await loadRequests();
    } catch (error: any) {
      console.error(error);
      toast.error(error?.response?.data?.error?.message || 'Failed to review request');
    } finally {
      setSubmitting(false);
    }
  };

  const renderMediaPreview = (media: ClubJoinRequest['media'][0]) => {
    switch (media.kind) {
      case 'image':
        return (
          <a
            href={media.url}
            target="_blank"
            rel="noopener noreferrer"
            className="w-24 h-24 rounded"
          >
            <img
              src={media.url}
              alt={media.name}
              className="w-24 h-24 rounded object-cover"
            />
          </a>
        );
      case 'audio':
        return <audio controls src={media.url} className="w-48" />;
      case 'video':
        return <video controls src={media.url} className="w-48 h-auto rounded" />;
      default:
        return (
          <a
            href={media.url}
            target="_blank"
            rel="noopener noreferrer"
            className="text-primary hover:underline text-sm"
          >
            Attachment: {media.name}
          </a>
        );
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  const pendingRequests = requests.filter((r) => r.status === 'pending');
  const reviewedRequests = requests.filter((r) => r.status !== 'pending');

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-xl font-bold text-foreground">Club Join Requests</h2>
        <p className="text-sm text-muted-foreground mt-1">
          Review and approve/reject user proposals to join clubs
        </p>
      </div>

      {pendingRequests.length > 0 && (
        <div>
          <h3 className="text-lg font-semibold text-foreground mb-3">
            Pending Requests ({pendingRequests.length})
          </h3>
          <div className="space-y-3">
            {pendingRequests.map((request) => (
              <div key={request.id} className="card-elevated ui-card-pad space-y-3">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <h4 className="font-semibold text-foreground">
                        {request.requesterName}
                      </h4>
                      <Badge variant="secondary">{request.clubName}</Badge>
                    </div>
                    <p className="text-sm text-muted-foreground">
                      {request.requesterEmail}
                    </p>
                    <p className="text-xs text-muted-foreground mt-1">
                      Submitted {new Date(request.createdAt).toLocaleDateString()}
                    </p>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() =>
                      setExpandedId(expandedId === request.id ? null : request.id)
                    }
                  >
                    <ChevronDown
                      className={`w-4 h-4 transition-transform ${
                        expandedId === request.id ? 'rotate-180' : ''
                      }`}
                    />
                  </Button>
                </div>

                {expandedId === request.id && (
                  <div className="border-t border-border pt-3 space-y-3">
                    <div>
                      <p className="text-sm font-medium text-foreground mb-2">Proposal</p>
                      <p className="text-sm text-foreground bg-muted p-3 rounded whitespace-pre-wrap">
                        {request.proposalText}
                      </p>
                    </div>

                    {request.media.length > 0 && (
                      <div>
                        <p className="text-sm font-medium text-foreground mb-2">
                          Supporting Media ({request.media.length})
                        </p>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {request.media.map((m, idx) => (
                            <div key={idx} className="border border-border rounded p-2">
                              {renderMediaPreview(m)}
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {reviewingId === request.id ? (
                      <div className="border-t border-border pt-3 space-y-3">
                        <div>
                          <label className="text-sm font-medium text-foreground">
                            Review Note
                          </label>
                          <Textarea
                            placeholder="Add a note for the user (optional for approval, required for rejection)"
                            value={reviewNote}
                            onChange={(e) => setReviewNote(e.target.value)}
                            rows={3}
                            disabled={submitting}
                          />
                        </div>
                        <div className="flex gap-2 justify-end">
                          <Button
                            variant="outline"
                            onClick={() => {
                              setReviewingId(null);
                              setReviewNote('');
                            }}
                            disabled={submitting}
                          >
                            Cancel
                          </Button>
                          <Button
                            variant="destructive"
                            onClick={() => handleReview(request.id, 'reject')}
                            disabled={submitting}
                          >
                            {submitting && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            Reject
                          </Button>
                          <Button
                            onClick={() => handleReview(request.id, 'approve')}
                            disabled={submitting}
                          >
                            {submitting && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            Approve
                          </Button>
                        </div>
                      </div>
                    ) : (
                      <div className="flex gap-2 justify-end border-t border-border pt-3">
                        <Button variant="outline" onClick={() => setReviewingId(request.id)}>
                          <X className="w-4 h-4 mr-2" />
                          Reject
                        </Button>
                        <Button onClick={() => setReviewingId(request.id)}>
                          <Check className="w-4 h-4 mr-2" />
                          Review & Approve
                        </Button>
                      </div>
                    )}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {pendingRequests.length === 0 && (
        <div className="card-elevated ui-card-pad text-center py-8">
          <p className="text-muted-foreground">No pending requests</p>
        </div>
      )}

      {reviewedRequests.length > 0 && (
        <div>
          <h3 className="text-lg font-semibold text-foreground mb-3">
            Review History ({reviewedRequests.length})
          </h3>
          <div className="space-y-2">
            {reviewedRequests.map((request) => (
              <div
                key={request.id}
                className="card-elevated ui-card-pad p-3 flex items-center justify-between"
              >
                <div>
                  <p className="font-medium text-foreground">{request.requesterName}</p>
                  <p className="text-sm text-muted-foreground">{request.clubName}</p>
                </div>
                <Badge
                  variant={request.status === 'approved' ? 'default' : 'destructive'}
                >
                  {request.status}
                </Badge>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';
import { Button } from "@pec/ui";


import { useState } from 'react';
import { X, Upload, Image as ImageIcon, FileText, Mic, Video } from 'lucide-react';

import { toast } from 'sonner';

export type MediaType = 'image' | 'audio' | 'video' | 'file';

export interface UploadedMedia {
  id: string;
  name: string;
  kind: MediaType;
  mimeType: string;
  file: File;
  preview?: string;
}

interface MediaUploadProps {
  onMediaAdd: (media: UploadedMedia) => void;
  onMediaRemove: (id: string) => void;
  maxFiles?: number;
  maxSize?: number;
}

export function MediaUpload({
  onMediaAdd,
  onMediaRemove,
  maxFiles = 5,
  maxSize = 50 * 1024 * 1024,
}: MediaUploadProps) {
  const [uploadedFiles, setUploadedFiles] = useState<UploadedMedia[]>([]);

  const getMediaType = (mimeType: string): MediaType => {
    if (mimeType.startsWith('image/')) return 'image';
    if (mimeType.startsWith('audio/')) return 'audio';
    if (mimeType.startsWith('video/')) return 'video';
    return 'file';
  };

  const getMediaIcon = (kind: MediaType) => {
    switch (kind) {
      case 'image':
        return <ImageIcon className="w-4 h-4" />;
      case 'audio':
        return <Mic className="w-4 h-4" />;
      case 'video':
        return <Video className="w-4 h-4" />;
      default:
        return <FileText className="w-4 h-4" />;
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);

    if (uploadedFiles.length + files.length > maxFiles) {
      toast.error(`Maximum ${maxFiles} files allowed`);
      return;
    }

    for (const file of files) {
      if (file.size > maxSize) {
        toast.error(
          `File ${file.name} exceeds maximum size of ${maxSize / 1024 / 1024}MB`,
        );
        continue;
      }

      const kind = getMediaType(file.type);
      const media: UploadedMedia = {
        id: `${Date.now()}-${Math.random()}`,
        name: file.name,
        kind,
        mimeType: file.type,
        file,
        preview: kind === 'image' ? URL.createObjectURL(file) : undefined,
      };

      setUploadedFiles((prev) => [...prev, media]);
      onMediaAdd(media);
    }

    e.target.value = '';
  };

  const handleRemove = (id: string) => {
    setUploadedFiles((prev) => {
      const removed = prev.find((m) => m.id === id);
      if (removed?.preview) {
        URL.revokeObjectURL(removed.preview);
      }
      return prev.filter((m) => m.id !== id);
    });
    onMediaRemove(id);
  };

  return (
    <div className="space-y-3">
      <div>
        <label className="text-sm font-medium text-foreground">
          Media Attachments
          <span className="text-muted-foreground ml-2">
            ({uploadedFiles.length}/{maxFiles})
          </span>
        </label>
        <p className="text-xs text-muted-foreground mt-1">
          Upload images, audio, video, or documents to support your proposal
        </p>
      </div>

      <div className="relative">
        <input
          type="file"
          multiple
          accept="image/*,audio/*,video/*,.pdf,.doc,.docx,.txt,.xlsx,.csv"
          onChange={handleFileSelect}
          className="hidden"
          id="media-upload"
          disabled={uploadedFiles.length >= maxFiles}
        />
        <label htmlFor="media-upload">
          <Button
            asChild
            variant="outline"
            className="w-full cursor-pointer"
            disabled={uploadedFiles.length >= maxFiles}
          >
            <span>
              <Upload className="w-4 h-4 mr-2" />
              Click to upload or drag files
            </span>
          </Button>
        </label>
      </div>

      {uploadedFiles.length > 0 && (
        <div className="space-y-2">
          {uploadedFiles.map((media) => (
            <div
              key={media.id}
              className="flex items-center justify-between p-3 bg-muted rounded-lg"
            >
              <div className="flex items-center gap-3 flex-1 min-w-0">
                <div className="text-primary">{getMediaIcon(media.kind)}</div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-foreground truncate">
                    {media.name}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {media.kind}
                    {media.mimeType && ` | ${media.mimeType.split('/')[1]}`}
                  </p>
                </div>
              </div>
              {media.preview && media.kind === 'image' && (
                <img
                  src={media.preview}
                  alt={media.name}
                  className="w-10 h-10 rounded object-cover"
                />
              )}
              <Button
                variant="ghost"
                size="sm"
                onClick={() => handleRemove(media.id)}
                className="ml-2"
              >
                <X className="w-4 h-4" />
              </Button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

