'use client';
import { Button, Input, Label, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Dialog, DialogContent, DialogHeader, DialogTitle, Card, useToast } from "@pec/ui";
import { useState } from 'react';
import { useTimetableControllerCreateV1 } from '@pec/api';
import { usePermissions } from '@/hooks/usePermissions';
import { Calendar, Plus, Edit, Bell } from 'lucide-react';

interface FacultyScheduleManagerProps {
  courses: any[];
  onScheduleAdded?: () => void;
}

export function FacultyScheduleManager({ courses, onScheduleAdded }: FacultyScheduleManagerProps) {
  const createTimetable = useTimetableControllerCreateV1();
  const { toast } = useToast();
  const { user } = usePermissions();
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    courseId: '',
    date: '',
    startTime: '',
    endTime: '',
    room: '',
    type: 'extra' as 'extra' | 'makeup',
    reason: '',
  });

  const handleAddExtraClass = async () => {
    try {
      if (!user || !formData.courseId || !formData.date || !formData.startTime || !formData.endTime) {
        toast({
          title: 'Missing Information',
          description: 'Please fill in all required fields',
          variant: 'destructive',
        });
        return;
      }

      setLoading(true);

      const course = courses.find(c => c.id === formData.courseId);
      if (!course) return;

      // Conflict checking and notifications are handled by the backend
      await createTimetable.mutateAsync({
        data: {
          courseId: formData.courseId,
          date: formData.date,
          startTime: formData.startTime,
          endTime: formData.endTime,
          room: formData.room,
          type: formData.type,
          reason: formData.reason,
        } as any,
      });

      toast({
        title: 'Class Added',
        description: `${formData.type === 'extra' ? 'Extra' : 'Makeup'} class scheduled successfully`,
      });

      setShowAddDialog(false);
      setFormData({
        courseId: '',
        date: '',
        startTime: '',
        endTime: '',
        room: '',
        type: 'extra',
        reason: '',
      });

      if (onScheduleAdded) {
        onScheduleAdded();
      }
    } catch (error) {
      console.error('Error adding class:', error);
      toast({
        title: 'Error',
        description: 'Failed to add class',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4">
      <Card className="p-6">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-lg font-semibold text-foreground">Schedule Management</h3>
            <p className="text-sm text-muted-foreground">Add extra classes or makeup sessions</p>
          </div>
          <Button onClick={() => setShowAddDialog(true)}>
            <Plus className="w-4 h-4 mr-2" />
            Add Class
          </Button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="flex items-center gap-3 p-4 bg-secondary/50 rounded-lg">
            <Calendar className="w-5 h-5 text-primary" />
            <div>
              <p className="text-sm font-medium text-foreground">Extra Classes</p>
              <p className="text-xs text-muted-foreground">Schedule additional sessions</p>
            </div>
          </div>
          <div className="flex items-center gap-3 p-4 bg-secondary/50 rounded-lg">
            <Edit className="w-5 h-5 text-primary" />
            <div>
              <p className="text-sm font-medium text-foreground">Makeup Classes</p>
              <p className="text-xs text-muted-foreground">Reschedule missed sessions</p>
            </div>
          </div>
        </div>
      </Card>

      <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Add Class</DialogTitle>
          </DialogHeader>

          <div className="space-y-4">
            <div className="space-y-2">
              <Label>Course *</Label>
              <Select
                value={formData.courseId}
                onValueChange={(value) => setFormData({ ...formData, courseId: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select course" />
                </SelectTrigger>
                <SelectContent>
                  {courses.map((course) => (
                    <SelectItem key={course.id} value={course.id}>
                      {course.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Type *</Label>
              <Select
                value={formData.type}
                onValueChange={(value: 'extra' | 'makeup') => setFormData({ ...formData, type: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="extra">Extra Class</SelectItem>
                  <SelectItem value="makeup">Makeup Class</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Date *</Label>
              <Input
                type="date"
                value={formData.date}
                onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                min={new Date().toISOString().split('T')[0]}
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label>Start Time *</Label>
                <Input
                  type="time"
                  value={formData.startTime}
                  onChange={(e) => setFormData({ ...formData, startTime: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <Label>End Time *</Label>
                <Input
                  type="time"
                  value={formData.endTime}
                  onChange={(e) => setFormData({ ...formData, endTime: e.target.value })}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Room</Label>
              <Input
                placeholder="e.g., Room 301"
                value={formData.room}
                onChange={(e) => setFormData({ ...formData, room: e.target.value })}
              />
            </div>

            <div className="space-y-2">
              <Label>Reason (Optional)</Label>
              <Input
                placeholder="e.g., Exam preparation"
                value={formData.reason}
                onChange={(e) => setFormData({ ...formData, reason: e.target.value })}
              />
            </div>

            <div className="flex items-center gap-2 p-3 bg-blue-50 dark:bg-blue-950 rounded-lg">
              <Bell className="w-4 h-4 text-blue-600 dark:text-blue-400" />
              <p className="text-xs text-blue-700 dark:text-blue-300">
                Students will be notified about this class
              </p>
            </div>

            <div className="flex gap-3 pt-4">
              <Button
                variant="outline"
                onClick={() => setShowAddDialog(false)}
                className="flex-1"
                disabled={loading}
              >
                Cancel
              </Button>
              <Button
                onClick={handleAddExtraClass}
                className="flex-1"
                disabled={loading || createTimetable.isPending}
              >
                {loading || createTimetable.isPending ? 'Adding...' : 'Add Class'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

export default FacultyScheduleManager;

import { Input, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@pec/ui";
import { Filter } from "lucide-react";

export type TimetableFilterValues = {
  department: string;
  academicYear: string;
  batch: string;
  courseQuery: string;
  facultyQuery: string;
  roomQuery: string;
};

type TimetableFiltersProps = {
  canManageAllTimetable: boolean;
  isFaculty: boolean;
  facultyDepartment?: string;
  departmentOptions: string[];
  batchOptions: string[];
  values: TimetableFilterValues;
  onChange: (next: Partial<TimetableFilterValues>) => void;
};

const YEAR_OPTIONS = [1, 2, 3, 4];

export default function TimetableFilters({
  canManageAllTimetable,
  isFaculty,
  facultyDepartment,
  departmentOptions,
  batchOptions,
  values,
  onChange,
}: TimetableFiltersProps) {
  if (!canManageAllTimetable && !isFaculty) {
    return null;
  }

  return (
    <div className="card-elevated ui-card-pad">
      <div className="space-y-4">
        <h3 className="text-sm font-semibold text-foreground flex items-center gap-2">
          <Filter className="w-4 h-4 text-primary" />
          {canManageAllTimetable ? "Institutional Filters" : "Branch Filters"}
        </h3>

        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <Select
            value={values.department}
            onValueChange={(value) => onChange({ department: value })}
            disabled={isFaculty}
          >
            <SelectTrigger>
              <SelectValue placeholder="Branch" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Branches</SelectItem>
              {(isFaculty && facultyDepartment ? [facultyDepartment] : departmentOptions).map((dept) => (
                <SelectItem key={dept} value={dept}>
                  {dept}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <Select
            value={values.academicYear}
            onValueChange={(value) => onChange({ academicYear: value })}
          >
            <SelectTrigger>
              <SelectValue placeholder="Year" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Years</SelectItem>
              {YEAR_OPTIONS.map((year) => (
                <SelectItem key={year} value={String(year)}>
                  Year {year}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          {canManageAllTimetable && (
            <Select value={values.batch} onValueChange={(value) => onChange({ batch: value })}>
              <SelectTrigger>
                <SelectValue placeholder="Batch" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Batches</SelectItem>
                {batchOptions.map((batch) => (
                  <SelectItem key={batch} value={batch}>
                    {batch}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          )}

          {canManageAllTimetable && (
            <>
              <Input
                placeholder="Search course"
                value={values.courseQuery}
                onChange={(event) => onChange({ courseQuery: event.target.value })}
              />
              <Input
                placeholder="Search faculty"
                value={values.facultyQuery}
                onChange={(event) => onChange({ facultyQuery: event.target.value })}
              />
              <Input
                placeholder="Search room"
                value={values.roomQuery}
                onChange={(event) => onChange({ roomQuery: event.target.value })}
              />
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import { ChatRoom } from '@pec/shared';
import { fetchChatRooms } from "@/lib/chatRooms.service";

export function useChatRooms(user: any, initialRooms?: ChatRoom[]) {
  const [rooms, setRooms] = useState<ChatRoom[]>(initialRooms || []);
  const [loading, setLoading] = useState(!initialRooms);
  const requestIdRef = useRef(0);

  const userId = user?.uid;

  const loadRooms = useCallback(async (expectedUserId?: string) => {
    // If we have initial rooms and it's the first run, we skip fetching
    if (initialRooms && rooms.length > 0 && loading === false) {
       // but we still want to fetch once eventually if it was server-only data
       // For simplicity, let's just let it run if it's the first time
    }
    const userId = expectedUserId ?? user?.uid;
    const requestId = ++requestIdRef.current;

    if (!user || !userId) {
      setRooms([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    try {
      const nextRooms = await fetchChatRooms(user);
      const uniqueRooms = nextRooms.filter(
        (room, index, arr) => arr.findIndex((candidate) => candidate.id === room.id) === index,
      );
      if (requestIdRef.current === requestId && user?.uid === userId) {
        setRooms(uniqueRooms);
      }
    } finally {
      if (requestIdRef.current === requestId) {
        setLoading(false);
      }
    }
  }, [user]);

  useEffect(() => {
    void loadRooms(userId);

    return () => {
      requestIdRef.current += 1;
    };
  }, [loadRooms, userId]);

  useEffect(() => {
    const handleRoomsUpdated = () => {
      void loadRooms();
    };

    window.addEventListener("chat-rooms-updated", handleRoomsUpdated);
    return () => {
      window.removeEventListener("chat-rooms-updated", handleRoomsUpdated);
    };
  }, [loadRooms]);

  return { rooms, loading, refreshRooms: loadRooms };
}

'use client';
import { extractData } from "@/lib/utils";

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/features/auth/hooks/useAuth';
import { User, Course, DashboardStats, AdminDashboardData } from '@pec/shared';
import api from "@pec/api";
import { toast } from 'sonner';

export function useAdminDashboard(initialData?: AdminDashboardData) {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();

  const [loading, setLoading] = useState(!initialData);
  const [courses, setCourses] = useState<Course[]>(initialData?.courses || []);
  const [users, setUsers] = useState<User[]>(initialData?.users || []);
  const [stats, setStats] = useState<DashboardStats>(
    initialData?.stats || {
      totalStudents: 0,
      totalFaculty: 0,
      totalCourses: 0,
    }
  );

  // Course Dialog states
  const [showCourseDialog, setShowCourseDialog] = useState(false);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [courseForm, setCourseForm] = useState({
    code: '',
    name: '',
    department: '',
    semester: 1,
    credits: 3,
    facultyName: '',
    maxStudents: 60,
    description: '',
  });

  // User Dialog states
  const [showUserDialog, setShowUserDialog] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userForm, setUserForm] = useState({
    fullName: '',
    email: '',
    role: 'student',
    department: '',
    enrollmentNumber: '',
    semester: 1,
  });

  // Search states
  const [courseSearchQuery, setCourseSearchQuery] = useState('');
  const [userSearchQuery, setUserSearchQuery] = useState('');

  const isAdmin = ['college_admin', 'admin', 'super_admin'].includes(user?.role || '');

  const filteredCourses = (courses || []).filter((course) => {
    const query = courseSearchQuery.toLowerCase();
    return (
      course.name?.toLowerCase().includes(query) ||
      course.code?.toLowerCase().includes(query) ||
      course.department?.toLowerCase().includes(query)
    );
  });

  const filteredUsers = (users || []).filter((user) => {
    const query = userSearchQuery.toLowerCase();
    return (
      user.fullName?.toLowerCase().includes(query) ||
      user.email?.toLowerCase().includes(query) ||
      user.role?.toLowerCase().includes(query)
    );
  });

  const fetchAdminData = useCallback(async () => {
    try {
      const [coursesData, usersData, statsRes] = await Promise.all([
        api.get('/courses', { params: { limit: 2000 } }).then(res => extractData<any>(res.data)),
        api.get('/users', { params: { limit: 2000 } }).then(res => extractData<any>(res.data)),
        api.get('/admin/dashboard-stats'),
      ]);

      setCourses(coursesData);
      setUsers(usersData);

      const serverStats = statsRes.data?.success ? statsRes.data.data : statsRes.data;
      if (serverStats) {
        setStats(serverStats);
      }
    } catch (error) {
      console.error('Error fetching admin data:', error);
      throw error;
    }
  }, []);

  useEffect(() => {
    if (authLoading) return;

    if (!user) {
      // Let middleware handle the redirect — don't force it from client
      return;
    }

    if (!isAdmin) {
      toast.error('Access denied. Admin only.');
      router.replace('/dashboard');
      return;
    }

    // Skip initial fetch if we already have server data
    if (initialData && courses.length > 0) {
      setLoading(false);
      return;
    }

    void (async () => {
      try {
        await fetchAdminData();
      } catch (error) {
        toast.error('Failed to load admin data');
      } finally {
        setLoading(false);
      }
    })();
  }, [authLoading, user, isAdmin, router, fetchAdminData, initialData]);

  const resetCourseForm = () => {
    setCourseForm({
      code: '',
      name: '',
      department: '',
      semester: 1,
      credits: 3,
      facultyName: '',
      maxStudents: 60,
      description: '',
    });
  };

  const resetUserForm = () => {
    setUserForm({
      fullName: '',
      email: '',
      role: 'student',
      department: '',
      enrollmentNumber: '',
      semester: 1,
    });
  };

  const handleCreateCourse = async () => {
    try {
      await api.post('/courses', {
        ...courseForm,
        credits: Number(courseForm.credits),
        semester: Number(courseForm.semester),
        instructor: courseForm.facultyName,
        status: 'active',
      });
      toast.success('Course created successfully!');
      setShowCourseDialog(false);
      resetCourseForm();
      await fetchAdminData();
    } catch (error) {
      toast.error('Failed to create course');
    }
  };

  const handleUpdateCourse = async () => {
    if (!editingCourse) return;
    try {
      await api.patch(`/courses/${editingCourse.id}`, {
        ...courseForm,
        credits: Number(courseForm.credits),
        semester: Number(courseForm.semester),
        instructor: courseForm.facultyName,
      });
      toast.success('Course updated successfully!');
      setShowCourseDialog(false);
      setEditingCourse(null);
      resetCourseForm();
      await fetchAdminData();
    } catch (error) {
      toast.error('Failed to update course');
    }
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm('Are you sure you want to delete this course?')) return;
    try {
      await api.delete(`/courses/${courseId}`);
      toast.success('Course deleted successfully!');
      await fetchAdminData();
    } catch (error) {
      toast.error('Failed to delete course');
    }
  };

  const handleCreateUser = async () => {
    try {
      await api.post('/users', {
        ...userForm,
        semester: Number(userForm.semester),
      });
      toast.success('User created successfully!');
      setShowUserDialog(false);
      resetUserForm();
      await fetchAdminData();
    } catch (error) {
      toast.error('Failed to create user');
    }
  };

  const handleUpdateUser = async () => {
    if (!editingUser) return;
    try {
      await api.patch(`/users/${editingUser.id}`, {
        ...userForm,
        semester: Number(userForm.semester),
      });
      toast.success('User updated successfully!');
      setShowUserDialog(false);
      setEditingUser(null);
      resetUserForm();
      await fetchAdminData();
    } catch (error) {
      toast.error('Failed to update user');
    }
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm('Are you sure you want to delete this user?')) return;
    try {
      await api.delete(`/users/${userId}`);
      toast.success('User deleted successfully!');
      await fetchAdminData();
    } catch (error) {
      toast.error('Failed to delete user');
    }
  };

  const openEditCourseDialog = (course: any) => {
    setEditingCourse(course);
    setCourseForm({
      code: course.code,
      name: course.name,
      department: course.department,
      semester: course.semester,
      credits: course.credits,
      facultyName: course.instructor || course.facultyName || '',
      maxStudents: course.maxStudents || 60,
      description: course.description || '',
    });
    setShowCourseDialog(true);
  };

  const openEditUserDialog = (user: any) => {
    setEditingUser(user);
    setUserForm({
      fullName: user.fullName,
      email: user.email,
      role: user.role,
      department: user.department || '',
      enrollmentNumber: user.enrollmentNumber || '',
      semester: user.semester || 1,
    });
    setShowUserDialog(true);
  };

  return {
    loading,
    courses: filteredCourses,
    users: filteredUsers,
    stats,
    courseSearchQuery,
    setCourseSearchQuery,
    userSearchQuery,
    setUserSearchQuery,
    showCourseDialog,
    setShowCourseDialog,
    editingCourse,
    courseForm,
    setCourseForm,
    showUserDialog,
    setShowUserDialog,
    editingUser,
    userForm,
    setUserForm,
    handleCreateCourse,
    handleUpdateCourse,
    handleDeleteCourse,
    handleCreateUser,
    handleUpdateUser,
    handleDeleteUser,
    openEditCourseDialog,
    openEditUserDialog,
    resetCourseForm,
    resetUserForm,
    user,
    setEditingCourse,
    setEditingUser,
  };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { ChatMessage, subscribeToMessages, sendMessage as apiSendMessage, sendMediaMessage as apiSendMedia } from '@/lib/messages.service';

export function useChatMessages(roomId: string | null) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [limit, setLimit] = useState(20);
  const lastRoomId = useRef<string | null>(null);

  useEffect(() => {
    if (!roomId) {
      setMessages([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    
    // Subscribe to messages (polling)
    const unsubscribe = subscribeToMessages(roomId, (newMessages) => {
      setMessages(newMessages);
      setLoading(false);
      // If we got fewer than the limit, there are no more messages (simplistic check for polling)
      if (newMessages.length < limit) {
        setHasMore(false);
      } else {
        setHasMore(true);
      }
    }, limit);

    return () => {
      unsubscribe();
    };
  }, [roomId, limit]);

  const loadMore = useCallback(() => {
    if (!loading && hasMore) {
      setLimit(prev => prev + 20);
    }
  }, [loading, hasMore]);

  const sendMessage = useCallback(async (roomId: string, text: string, metadata?: any) => {
    await apiSendMessage(roomId, text, metadata);
  }, []);

  const sendMedia = useCallback(async (roomId: string, mediaUrl: string, type: any, options?: any) => {
    await apiSendMedia(roomId, mediaUrl, type, options);
  }, []);

  return {
    messages,
    loading,
    hasMore,
    loadMore,
    sendMessage,
    sendMedia,
  };
}

import { useState, useEffect } from "react";
import { useCollegeSettings } from "./useCollegeSettings";
import { safeLocalStorage } from "@/lib/ssr-safe";

export function useCollegeBrandingColors() {
  const { settings } = useCollegeSettings();
  const [selectedColor, setSelectedColorState] = useState<string>("");

  // Default colors if college hasn't set any
  const defaultColors = ["#3B82F6", "#EF4444", "#10B981", "#F59E0B", "#8B5CF6"];
  const availableColors = settings?.brandingColors || defaultColors;

  // Convert hex to HSL for CSS variables
  const hexToHSL = (hex: string) => {
    const r = parseInt(hex.slice(1, 3), 16) / 255;
    const g = parseInt(hex.slice(3, 5), 16) / 255;
    const b = parseInt(hex.slice(5, 7), 16) / 255;

    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    let h = 0,
      s = 0,
      l = (max + min) / 2;

    if (max !== min) {
      const d = max - min;
      s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
      switch (max) {
        case r:
          h = ((g - b) / d + (g < b ? 6 : 0)) / 6;
          break;
        case g:
          h = ((b - r) / d + 2) / 6;
          break;
        case b:
          h = ((r - g) / d + 4) / 6;
          break;
      }
    }

    return `${Math.round(h * 360)} ${Math.round(s * 100)}% ${Math.round(
      l * 100
    )}%`;
  };

  // Apply color to CSS variables — guarded for SSR safety
  const applyColorToCss = (color: string) => {
    if (typeof document === 'undefined') return;
    const hsl = hexToHSL(color);
    document.documentElement.style.setProperty("--primary", hsl);
  };

  useEffect(() => {
    const saved = safeLocalStorage.get("accentColor");
    if (saved && availableColors.includes(saved)) {
      setSelectedColorState(saved);
      applyColorToCss(saved);
    } else {
      setSelectedColorState(availableColors[0]);
      applyColorToCss(availableColors[0]);
    }
  }, [availableColors]);

  const setColor = (color: string) => {
    if (availableColors.includes(color)) {
      setSelectedColorState(color);
      safeLocalStorage.set("accentColor", color);
      applyColorToCss(color);
    }
  };

  return {
    colors: availableColors,
    selectedColor: selectedColor,
    setColor,
  };
}

import { useState, useEffect } from "react";
import api from "@pec/api";
import type { CollegeSettings } from '@pec/shared';

export function useCollegeSettings() {
  const [settings, setSettings] = useState<CollegeSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const response = await api.get("/college-settings");
        // Handle result-wrapper from ok() utility in backend
        const data = response.data?.success ? response.data.data : response.data;
        if (data) {
          setSettings(data as CollegeSettings);
        } else {
          setSettings(null);
        }
        setError(null);
      } catch (err) {
        console.error("Error fetching college settings:", err);
        setError(
          err instanceof Error ? err.message : "Failed to load settings",
        );
      } finally {
        setLoading(false);
      }
    };

    fetchSettings();
  }, []);

  return { settings, loading, error };
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/features/auth/hooks/useAuth';
import api from "@pec/api";
import {  isAuthError  } from "@pec/api";
import { toast } from 'sonner';

export function useFacultyDashboard(initialData?: any, serverUser?: any) {
  const router = useRouter();
  const { user: clientUser, loading: authLoading } = useAuth();
  
  // Use server user as fallback to prevent layout shift
  const user = clientUser || serverUser;

  const [showQRModal, setShowQRModal] = useState(false);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);
  const [showScheduleManager, setShowScheduleManager] = useState(false);
  
  const [courses, setCourses] = useState<any[]>(initialData?.courses || []);
  const [notices, setNotices] = useState<any[]>(initialData?.notices || []);
  const [courseCards, setCourseCards] = useState<any[]>(initialData?.courseCards || []);
  const [todaySchedule, setTodaySchedule] = useState<any[]>(initialData?.todaySchedule || []);
  const [loading, setLoading] = useState(!initialData || (initialData?.courses?.length === 0));
  const [stats, setStats] = useState(initialData?.stats || { activeCount: 0, studentCount: 0, lowAttendanceCount: 0 });

  const fetchFacultyData = useCallback(async () => {
    if (!user || user.role !== 'faculty') return;

    const hasPrecomputedCards = Array.isArray(initialData?.courseCards);
    const hasPrecomputedSchedule = Array.isArray(initialData?.todaySchedule);
    const hasPrecomputedStats = Boolean(initialData?.stats);
    const canUseInitialSnapshot =
      Boolean(initialData) &&
      courses.length > 0 &&
      hasPrecomputedCards &&
      hasPrecomputedSchedule &&
      hasPrecomputedStats;

    // Skip first refetch only when server snapshot is complete.
    if (canUseInitialSnapshot) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      type ApiResponse<T> = { success: boolean; data: T; meta?: any };
      const [coursesRes, noticesRes, timetableRes] = await Promise.all([
        api.get<ApiResponse<any>>('/courses', { params: { facultyId: user.uid, limit: 200, offset: 0 } }),
        api.get<ApiResponse<any>>('/noticeboard', { params: { limit: 5 } }).catch(() => ({ data: { data: [] } }) as any),
        api.get<ApiResponse<any>>('/timetable').catch(() => ({ data: { data: [] } }) as any),
      ]);

      let facultyCourses = coursesRes.data.data || [];
      const allNotices = noticesRes.data.data || [];
      const allTimetable = timetableRes.data.data || [];

      setNotices(allNotices);

      if (!facultyCourses.length) {
        let facultyName = user.fullName || user.name || '';
        try {
          const profileRes = await api.get<ApiResponse<any>>('/auth/profile');
          const profile = profileRes?.data?.data || profileRes?.data;
          facultyName = profile?.fullName || profile?.name || facultyName;
        } catch {
          // ignore profile fetch failure
        }

        const allCoursesRes = await api.get<ApiResponse<any>>('/courses', { params: { limit: 200, offset: 0 } });
        const allCourses = allCoursesRes.data.data || [];
        const name = String(facultyName || '').toLowerCase();
        facultyCourses = allCourses.filter((c: any) => {
          if (c.facultyId === user.uid || c.instructorId === user.uid) return true;
          if (!name) return false;
          const instructor = (c.instructor || c.facultyName || c.instructorName || '').toLowerCase();
          return instructor.includes(name);
        });
      }

      setCourses(facultyCourses);

      const enrollmentResponses = await Promise.all(
        facultyCourses.map((course: any) =>
          api.get<ApiResponse<any>>('/enrollments', {
            params: { courseId: course.id, status: 'active', limit: 200, offset: 0 },
          }).catch(() => ({ data: { data: [] } }) as any)
        )
      );

      const allEnrollments = enrollmentResponses.flatMap((res) => res.data.data || []);
      const uniqueStudents = new Set(allEnrollments.map((e: any) => e.studentId));

      const enrollmentByCourse = allEnrollments.reduce((acc: Record<string, number>, item: any) => {
        const key = String(item.courseId || '');
        if (!key) return acc;
        acc[key] = (acc[key] || 0) + 1;
        return acc;
      }, {});

      let overallLowAttendanceCount = 0;
      const courseMetrics = facultyCourses.reduce((acc: Record<string, any>, course: any) => {
         const courseEnrollments = allEnrollments.filter((e: any) => String(e.courseId) === String(course.id));
         const sumAttendance = courseEnrollments.reduce((sum: number, e: any) => sum + (Number(e.attendancePercentage || e.avgAttendance || e.attendance) || 85), 0);
         const avgAtt = courseEnrollments.length > 0 ? Math.round(sumAttendance / courseEnrollments.length) : (course.avgAttendance || 0);
         
         const lowAttStudents = courseEnrollments.filter((e: any) => (Number(e.attendancePercentage || e.avgAttendance || e.attendance) || 100) < 75).length;
         overallLowAttendanceCount += lowAttStudents;

         acc[course.id] = { avgAttendance: avgAtt, progress: course.syllabusProgress || course.progress || 45 };
         return acc;
      }, {});

      setStats({
        activeCount: facultyCourses.length,
        studentCount: uniqueStudents.size,
        lowAttendanceCount: overallLowAttendanceCount,
      });

      setCourseCards(
        facultyCourses.map((course: any) => ({
          id: course.id,
          code: course.code || 'COURSE',
          name: course.name || 'Course',
          students: enrollmentByCourse[String(course.id)] || 0,
          progress: courseMetrics[course.id]?.progress || 0,
          avgAttendance: courseMetrics[course.id]?.avgAttendance || 0,
        }))
      );

      // Prepare Today's Schedule
      const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
      const today = days[new Date().getDay()].toLowerCase();
      const facultyTimetable = allTimetable.filter((t: any) => 
        facultyCourses.some(c => c.id === t.courseId) && String(t.day || '').toLowerCase() === today
      );

      setTodaySchedule(facultyTimetable.map((t: any) => {
        const course = facultyCourses.find(c => c.id === t.courseId);
        return {
          id: t.id,
          time: `${t.startTime} - ${t.endTime}`,
          course: course?.name || 'Class',
          section: t.batch || 'N/A',
          room: t.room || 'TBA',
          students: enrollmentByCourse[String(t.courseId)] || 0,
          status: 'upcoming' as const,
        };
      }));

      setSelectedCourse((prev: any) => prev || (facultyCourses.length > 0 ? facultyCourses[0] : null));
    } catch (error) {
      if (isAuthError(error)) {
        toast.error('Session expired. Please login again.');
        router.replace('/auth');
        return;
      }

      console.error('Error fetching faculty data:', error);
      toast.error('Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  }, [user, initialData]);

  useEffect(() => {
    if (authLoading) return;

    if (!user || user.role !== 'faculty') {
      // Let middleware handle the redirect — don't force it from client
      return;
    }

    void fetchFacultyData();
  }, [authLoading, user, router, fetchFacultyData]);

  const handleGenerateQR = () => {
    if (!selectedCourse) {
      toast.error('Please select a course first');
      return;
    }
    setShowQRModal(true);
  };

  return {
    loading,
    user,
    courses,
    notices,
    courseCards,
    todaySchedule,
    stats,
    selectedCourse,
    setSelectedCourse,
    showQRModal,
    setShowQRModal,
    showScheduleManager,
    setShowScheduleManager,
    handleGenerateQR,
    router,
  };
}

import { useEffect, useState } from 'react';
import { getFacultyPermissions, type FacultyPermissions } from '@/lib/accessControl';

interface UseFacultyPermissionsProps {
  facultyId: string | null;
  resourceType: 'course' | 'assignment' | 'attendance' | 'material' | 'grade' | 'exam';
  resourceData?: any;
}
// Hook to get faculty permissions for a resource.
export function useFacultyPermissions({
  facultyId,
  resourceType,
  resourceData
}: UseFacultyPermissionsProps) {
  const [permissions, setPermissions] = useState<FacultyPermissions>({
    canView: false,
    canCreate: false,
    canEdit: false,
    canDelete: false,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadPermissions() {
      if (!facultyId) {
        setLoading(false);
        return;
      }

      try {
        const perms = await getFacultyPermissions(facultyId, resourceType, resourceData);
        setPermissions(perms);
      } catch (error) {
        console.error('Error loading faculty permissions:', error);
      } finally {
        setLoading(false);
      }
    }

    loadPermissions();
  }, [facultyId, resourceType, resourceData?.id, resourceData?.courseId]);

  return { permissions, loading };
}

