  const handleSkillsChange = (field: string, value: string) => {
    setResumeData((prev) => ({
      ...prev,
      skills: { ...prev.skills, [field]: value },
    }));
  };

  const extractTextFromPDF = async (file: File): Promise<string> => {
    try {
      const pdfjs = await getPdfJs();
      const arrayBuffer = await file.arrayBuffer();
      const loadingTask = pdfjs.getDocument({
        data: arrayBuffer,
        useWorkerFetch: false,
        isEvalSupported: false,
      });
      const pdf = await loadingTask.promise;
      let fullText = "";
      for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const textContent = await page.getTextContent();
        const pageText = textContent.items.map((item: any) => item.str).join(" ");
        fullText += pageText + "\n";
      }
      return fullText;
    } catch (error) {
      console.error("Text extraction failed:", error);
      throw new Error("Could not read PDF text.");
    }
  };

  const optimizeImageForVision = async (file: File): Promise<string> => {
    const MAX_IMAGE_BYTES = 850_000;
    const MAX_DIMENSION = 1400;
    const initialDataUrl = await new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
    const image = await new Promise<HTMLImageElement>((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = initialDataUrl;
    });
    let scale = Math.min(1, MAX_DIMENSION / Math.max(image.naturalWidth, image.naturalHeight));
    let quality = 0.82;
    let bestDataUrl = initialDataUrl;
    for (let attempt = 0; attempt < 5; attempt++) {
      const width = Math.max(1, Math.round(image.naturalWidth * scale));
      const height = Math.max(1, Math.round(image.naturalHeight * scale));
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      if (!ctx) throw new Error("Canvas context failed");
      ctx.drawImage(image, 0, 0, width, height);
      bestDataUrl = canvas.toDataURL("image/jpeg", quality);
      if (bestDataUrl.length * 0.75 <= MAX_IMAGE_BYTES) return bestDataUrl;
      scale *= 0.82;
      quality = Math.max(0.58, quality - 0.1);
    }
    return bestDataUrl;
  };

  const handleAnalyze = async (customFile?: File) => {
    if (!jobDescription.trim()) {
      toast.error("Please enter a job description first");
      return;
    }
    setIsAnalyzing(true);
    setAnalysisResult(null);
    let resumeContext = "";
    const deterministicFallback = () =>
      buildDeterministicFallbackAnalysis(resumeContext || JSON.stringify(resumeData, null, 2), jobDescription);

    try {
      const targetFile = customFile || (selectedResume === "upload" ? uploadedFile : null);
      let userContent: any = "";
      if (targetFile) {
        if (targetFile.type.includes("pdf")) {
          resumeContext = await extractTextFromPDF(targetFile);
        } else {
          const optimizedImageDataUrl = await optimizeImageForVision(targetFile);
          resumeContext = `[IMAGE_RESUME_UPLOAD:${targetFile.name}]`;
          userContent = [
            { type: "text", text: `Analyze this resume image against JD: ${jobDescription}` },
            { type: "image_url", image_url: { url: optimizedImageDataUrl } }
          ];
        }
      } else {
        resumeContext = JSON.stringify(resumeData, null, 2);
      }
      if (!userContent) {
        userContent = `Analyze resume against JD.\nJD: ${jobDescription}\nResume: ${resumeContext}`;
      }
      const response = await callOpenAI({
        model: "gpt-4o-mini",
        messages: [
          { role: "system", content: "Expert ATS. Return strictly JSON." },
          { role: "user", content: userContent }
        ],
        response_format: { type: "json_object" },
      });
      const content = response?.choices?.[0]?.message?.content;
      let normalized = deterministicFallback();
      try {
        const parsed = JSON.parse(extractJsonObjectFromText(content));
        normalized = normalizeAnalysisResult(parsed);
      } catch {}
      setAnalysisResult(applyDeterministicScoreGuard(normalized, resumeContext, jobDescription));
      toast.success("AI Analysis Complete!");
    } catch (error: any) {
      console.error("Analysis Error:", error);
      setAnalysisResult(applyDeterministicScoreGuard(deterministicFallback(), resumeContext || JSON.stringify(resumeData, null, 2), jobDescription));
      toast.info("Used fallback analysis.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const downloadPDF = async () => {
    const { jsPDF } = await import("jspdf");
    const doc = new jsPDF();
    let yPos = 20;
    doc.setFontSize(20);
    doc.setFont("helvetica", "bold");
    doc.text(resumeData.personalInfo.name.toUpperCase(), 105, yPos, { align: "center" });
    yPos += 6;
    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    const contactParts = [
      resumeData.personalInfo.location,
      resumeData.personalInfo.phone,
      resumeData.personalInfo.email,
      resumeData.personalInfo.linkedin,
      resumeData.personalInfo.github,
    ].filter(Boolean).join(" | ");
    doc.text(contactParts, 105, yPos, { align: "center" });
    yPos += 10;

    const addSection = (title: string) => {
      doc.setFontSize(11); doc.setFont("helvetica", "bold");
      doc.text(title.toUpperCase(), 14, yPos);
      doc.setLineWidth(0.5); doc.line(14, yPos + 2, 196, yPos + 2);
      yPos += 7;
    };

    if (resumeData.education.length > 0) {
      addSection("Education");
      resumeData.education.forEach((edu) => {
        doc.setFontSize(10); doc.setFont("helvetica", "bold");
        doc.text(edu.institution, 14, yPos);
        doc.setFont("helvetica", "normal"); doc.text(edu.year, 196, yPos, { align: "right" });
        yPos += 5;
        doc.setFont("helvetica", "italic"); doc.text(`${edu.degree} in ${edu.major}`, 14, yPos);
        if (edu.gpa) doc.text(`GPA: ${edu.gpa}`, 196, yPos, { align: "right" });
        yPos += 5;
        if (edu.coursework.length > 0) {
          doc.setFont("helvetica", "normal"); doc.setFontSize(9);
          const split = doc.splitTextToSize(`Relevant Coursework: ${edu.coursework.join(", ")}`, 180);
          doc.text(split, 14, yPos); yPos += split.length * 4 + 3;
        }
      });
    }

    if (resumeData.experience.length > 0) {
      addSection("Work Experience");
      resumeData.experience.forEach((exp) => {
        doc.setFontSize(10); doc.setFont("helvetica", "bold");
        doc.text(exp.company, 14, yPos);
        doc.setFont("helvetica", "normal"); doc.text(exp.location, 196, yPos, { align: "right" });
        yPos += 5;
        doc.setFont("helvetica", "italic"); doc.text(exp.title, 14, yPos);
        doc.setFont("helvetica", "normal"); doc.text(exp.duration, 196, yPos, { align: "right" });
        yPos += 5;
        exp.description.forEach((d) => {
          if (!d) return;
          doc.setFontSize(9);
          const split = doc.splitTextToSize(`• ${d}`, 180);
          doc.text(split, 18, yPos); yPos += split.length * 4;
        });
        yPos += 3;
      });
    }

    if (resumeData.projects.length > 0) {
      addSection("Projects");
      resumeData.projects.forEach((proj) => {
        doc.setFontSize(10); doc.setFont("helvetica", "bold");
        doc.text(proj.name, 14, yPos);
        doc.setFont("helvetica", "normal"); doc.text(proj.date, 196, yPos, { align: "right" });
        yPos += 5;
        proj.description.forEach((d) => {
          if (!d) return;
          doc.setFontSize(9);
          const split = doc.splitTextToSize(`• ${d}`, 180);
          doc.text(split, 18, yPos); yPos += split.length * 4;
        });
        yPos += 3;
      });
    }

    addSection("Skills");
    const skills = [
      { l: "Technical", v: resumeData.skills.technical },
      { l: "Programming", v: resumeData.skills.programming },
      { l: "Languages", v: resumeData.skills.languages },
      { l: "Certifications", v: resumeData.skills.certifications },
    ];
    doc.setFontSize(9);
    skills.forEach((s) => {
      if (s.v) {
        doc.setFont("helvetica", "bold"); doc.text(`${s.l}:`, 14, yPos);
        doc.setFont("helvetica", "normal");
        const split = doc.splitTextToSize(s.v, 150);
        doc.text(split, 45, yPos); yPos += split.length * 4 + 2;
      }
    });

    doc.save(`${resumeData.personalInfo.name}_Resume.pdf`);
  };

  return {
    loading,
    resumeData,
    setResumeData,
    handlePersonalInfoChange,
    handleEducationChange,
    addExperience,
    removeExperience,
    handleExperienceChange,
    addProject,
    removeProject,
    handleProjectChange,
    handleSkillsChange,
    handleSaveResume,
    isSavingResume,
    hasUnsavedResumeChanges,
    downloadPDF,
    zoom,
    setZoom,
    preview,
    setPreview,
    activeTab,
    setActiveTab,
    jobDescription,
    setJobDescription,
    isAnalyzing,
    analysisResult,
    handleAnalyze,
    selectedResume,
    setSelectedResume,
    uploadedFile,
    setUploadedFile,
    settings,
  };
}

'use client';
import { extractData } from "@/lib/utils";
import api from "@pec/api";

import { useState, useEffect, useMemo, useCallback } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';

import { searchableRoutes } from '@/utils/searchableRoutes';

export function useSearchPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const initialQuery = searchParams.get('q') || '';
  const [searchTerm, setSearchTerm] = useState(initialQuery);
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState({
    users: [] as any[],
    jobs: [] as any[],
    drives: [] as any[],
    pages: [] as any[],
    subjects: [] as any[],
  });

  const performSearch = useCallback(async (term: string) => {
    if (!term.trim()) return;
    setLoading(true);

    try {
      const [usersRes, jobsRes, subjectsRes] = await Promise.allSettled([
        api.get('/users', { params: { limit: 2000 } }).then(res => extractData<any>(res.data)),
        api.get('/jobs', { params: { limit: 2000 } }).then(res => extractData<any>(res.data)),
        api.get('/courses', { params: { limit: 2000 } }).then(res => extractData<any>(res.data)),
      ]);

      const lowerTerm = term.trim().toLowerCase();
      const users =
        usersRes.status === 'fulfilled'
          ? usersRes.value || []
          : [];
      const jobs =
        jobsRes.status === 'fulfilled'
          ? jobsRes.value || []
          : [];
      const subjects =
        subjectsRes.status === 'fulfilled'
          ? subjectsRes.value || []
          : [];

      const filteredUsers = users
        .map((u: any) => ({
          ...u,
          fullName: u.fullName || u.name || '',
        }))
        .filter((u: any) =>
          String(u.fullName || '').toLowerCase().includes(lowerTerm) ||
          String(u.email || '').toLowerCase().includes(lowerTerm),
        );

      const filteredJobs = jobs.filter(
        (j: any) =>
          String(j.title || '').toLowerCase().includes(lowerTerm) ||
          String(j.company || j.companyName || '').toLowerCase().includes(lowerTerm),
      );

      const filteredDrives = filteredJobs
        .map((job: any) => ({
          id: `drive-${job.id}`,
          companyName: job.company || job.companyName,
          role: job.title,
          date: job.deadline,
          location: job.location,
          status: 'upcoming' // Default status
        }))
        .sort((a: any, b: any) => {
          const left = new Date(a.date || 0).getTime();
          const right = new Date(b.date || 0).getTime();
          return left - right;
        });

      const filteredSubjects = subjects.filter(
        (c: any) =>
          String(c.name || '').toLowerCase().includes(lowerTerm) ||
          String(c.code || '').toLowerCase().includes(lowerTerm),
      );

      const filteredPages = searchableRoutes.filter(route => 
         route.title.toLowerCase().includes(lowerTerm) || 
         route.keywords.some(k => k.toLowerCase().includes(lowerTerm))
      );

      setResults({
        users: filteredUsers,
        jobs: filteredJobs,
        drives: filteredDrives,
        pages: filteredPages,
        subjects: filteredSubjects,
      });

    } catch (error) {
      console.error("Search error:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (initialQuery) {
      performSearch(initialQuery);
    }
  }, [initialQuery, performSearch]);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      router.push(`/search?q=${encodeURIComponent(searchTerm)}`);
    }
  };

  const hasResults = useMemo(
    () =>
      results.users.length > 0 ||
      results.jobs.length > 0 ||
      results.drives.length > 0 ||
      results.pages.length > 0 ||
      results.subjects.length > 0,
    [results],
  );

  return {
    searchTerm,
    setSearchTerm,
    loading,
    results,
    handleSearchSubmit,
    hasResults,
    initialQuery,
  };
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { useAuth } from '@/features/auth/hooks/useAuth';
import api from "@pec/api";
import type { 
  StudentProfile, 
  Course, 
} from '@pec/shared';

type NoticeboardItem = {
  id: string;
  title: string;
  content: string;
  category: 'news' | 'update' | 'event' | 'alert' | string;
  important?: boolean;
  pinned?: boolean;
  authorName?: string;
  publishedAt?: string;
};

interface StudentStats {
  attendancePercentage: number;
  enrolledCourses: number;
}

export function useStudentDashboard(initialData?: any, initialUser?: any) {
  const router = useRouter();
  const { orgSlug } = useParams<{ orgSlug: string }>();
  const { user, loading: authLoading } = useAuth();
  
  // Use SSR data if provided, otherwise show loading
  const [loading, setLoading] = useState(!initialData);
  const firstName = initialUser?.fullName?.split(' ')[0] || 'Student';
  const [profileData] = useState<StudentProfile | null>(initialUser ? {
    department: initialUser.department,
    semester: initialUser.semester,
    enrollmentNumber: initialUser.enrollmentNumber,
  } as any : null);
  

  const [stats, setStats] = useState<StudentStats>({
    attendancePercentage: initialData?.summary?.totalSummary?.percentage || 0,
    enrolledCourses: initialData?.summary?.courses?.length || 0,
  });
  
  const [todayClasses, setTodayClasses] = useState<any[]>([]);
  const [scheduleDay, setScheduleDay] = useState<string>('Today');
  const [enrolledCoursesList, setEnrolledCoursesList] = useState<Course[]>(initialData?.summary?.courses || []);
  const [noticeboardItems, setNoticeboardItems] = useState<NoticeboardItem[]>(initialData?.noticeboard || initialData?.notices || []);
  const [todayEvents, setTodayEvents] = useState<any[]>([]);
  const [requiredAttendancePercentage, setRequiredAttendancePercentage] = useState<number>(75);
  const [loadError, setLoadError] = useState<string | null>(null);

  const processDashboardData = useCallback((summary: any, allCourses: Course[], timetableData: any[], noticeboardData: any[] = [], calendarData: any[] = []) => {
    setNoticeboardItems(Array.isArray(noticeboardData) ? noticeboardData : []);
    if (summary && typeof summary === 'object') {
      const statsObj = summary.totalSummary || {};
      const summaryCourses = Array.isArray(summary.courses) ? summary.courses : [];
      const fallbackCourses = Array.isArray(allCourses) ? allCourses : [];
      
      // Enrich enrolled courses with full details from summary (now comprehensive)
      const normalizedEnrolled: Course[] = summaryCourses.map((course: any, index: number) => {
        const idToMatch = String(course.courseId || course.id || '');
        
        return {
          id: idToMatch || `course-${index}`,
          code: course.courseCode ?? course.code ?? 'COURSE',
          name: course.courseName ?? course.name ?? 'Course',
          department: course.department ?? 'General',
          semester: course.semester ?? 0,
          credits: course.credits ?? 0,
          facultyName: course.instructor ?? course.facultyName ?? '',
          maxStudents: course.maxStudents ?? 0,
          enrolledStudents: course.enrolledStudents ?? 0,
          description: course.description ?? '',
          type: course.type ?? 'Core',
          instructor: (course.instructor ?? course.facultyName) as string,
        };
      });

      setEnrolledCoursesList(normalizedEnrolled);
      setStats({
        attendancePercentage: typeof statsObj.percentage === 'number' ? statsObj.percentage : 0,
        enrolledCourses: normalizedEnrolled.length,
      });
      
      const enrolledCourseIds = new Set(normalizedEnrolled.map((c: any) => String(c.id)).filter(id => id && id !== 'undefined'));
      const daysOfWeek = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
      const todayStr = new Date().toLocaleDateString('en-US', { weekday: 'long' });
      
      const safeTimetable = Array.isArray(timetableData) ? timetableData : [];
      
      const scheduleItems = safeTimetable
        .filter((t: any) => enrolledCourseIds.has(String(t.courseId)))
        .map((t: any) => {
          const course = normalizedEnrolled.find((c: any) => String(c.id) === String(t.courseId));
          return {
            ...t,
            id: t.id || `schedule-${t.courseId}-${t.day}-${t.startTime}`,
            courseCode: course?.code || t.courseCode || 'CLS',
            courseName: course?.name || t.courseName || 'Class',
            instructor: (course?.instructor || t.facultyName || t.instructor || 'Faculty') as string,
            room: (t.room || t.location || 'TBA') as string,
          };
        });

      const getScheduleForDay = (dayName: string) => {
        return scheduleItems
          .filter((item: any) => String(item.day).toLowerCase() === dayName.toLowerCase())
          .sort((a: any, b: any) => (a.startTime || '').localeCompare(b.startTime || ''));
      };

      // Process today's calendar events
      let tEvents: any[] = [];
      if (Array.isArray(calendarData)) {
        const localTodayStr = new Date().toLocaleDateString('en-CA'); // YYYY-MM-DD
        tEvents = calendarData.filter((e: any) => {
          if (!e.date) return false;
          return e.date.startsWith(localTodayStr);
        });
        setTodayEvents(tEvents);
      }

      let activeSchedule = getScheduleForDay(todayStr);
      let displayLabel = 'Today';

      if (activeSchedule.length === 0 && tEvents.length === 0) {
        const todayIndex = daysOfWeek.indexOf(todayStr);
        for (let i = 1; i < 7; i++) {
          const nextDayIndex = (todayIndex + i) % 7;
          const nextDay = daysOfWeek[nextDayIndex];
          const nextSchedule = getScheduleForDay(nextDay);
          
          if (nextSchedule.length > 0) {
            activeSchedule = nextSchedule;
            displayLabel = i === 1 ? 'Tomorrow' : nextDay;
            break;
          }
        }
      }

      setTodayClasses(activeSchedule);
      setScheduleDay(displayLabel);
    }
  }, []);

  const fetchCollegeSettings = useCallback(async () => {
    try {
      const response = await api.get('/college-settings');
      const data = response.data?.success ? response.data.data : response.data;
      if (data) {
        const value = Number(data?.attendanceRequiredPercentage);
        if (!Number.isNaN(value) && value > 0) {
          setRequiredAttendancePercentage(Math.max(0, Math.min(100, Math.round(value))));
        }
      }
    } catch {
      // Ignore settings errors and use default threshold
    }
  }, []);

  const fetchStudentStats = useCallback(async () => {
    if (!user) return;
    try {
      setLoadError(null);
      
      const getData = (res: any) => {
        if (res?.data?.success && res.data.data) return res.data.data;
        if (res?.data) return res.data;
        return res;
      };

      const [summaryRes, timetableRes, noticeboardRes, calendarRes] = await Promise.all([
        api.get('/attendance/summary'),
        api.get('/timetable'),
        api.get('/noticeboard', { params: { limit: 4, offset: 0 } }),
        api.get('/academic-calendar').catch(() => ({ data: [] })),
      ]);

      processDashboardData(
        getData(summaryRes),
        [], // allCourses no longer needed for details
        getData(timetableRes) || [],
        getData(noticeboardRes) || [],
        getData(calendarRes) || []
      );

      const notices = getData(noticeboardRes);
      setNoticeboardItems(Array.isArray(notices?.data) ? notices.data : Array.isArray(notices) ? notices : []);
      void fetchCollegeSettings();

    } catch (error) {
      console.error('Error fetching dashboard stats:', error);
      setLoadError('Unable to refresh dashboard data.');
    } finally {
      setLoading(false);
    }
  }, [user, processDashboardData, fetchCollegeSettings]);

  // Handle hydration or manual refresh
  useEffect(() => {
    if (initialData && initialData.summary) {
      processDashboardData(
        initialData.summary,
        [], // allCourses no longer provided/needed
        initialData.timetable || [],
        initialData.noticeboard || initialData.notices || [],
        initialData.calendar || []
      );
      void fetchCollegeSettings();
      
      const dashboardNotices = initialData.noticeboard || initialData.notices;
      if (Array.isArray(dashboardNotices) && dashboardNotices.length > 0) {
        setNoticeboardItems(dashboardNotices);
      } else {
        void (async () => {
          try {
            const res = await api.get('/noticeboard', { params: { limit: 4, offset: 0 } });
            const notices = res?.data?.success ? res.data.data : res?.data;
            if (Array.isArray(notices)) setNoticeboardItems(notices);
          } catch {
            // Ignore noticeboard errors for dashboard render
          }
        })();
      }
      setLoading(false);
    } else if (initialData && !initialData.summary) {
      // If SSR passed initialData but it's empty (e.g. serverFetch failed), we must fetch client-side!
      void fetchStudentStats();
    }
  }, [initialData, processDashboardData, fetchCollegeSettings, fetchStudentStats]);

  useEffect(() => {
    if (authLoading) return;

    if (!user) {
      // Let middleware handle the redirect — don't force it from client
      return;
    }

    if (user.role !== 'student') {
      router.replace('/dashboard');
      return;
    }

    if (!initialData) {
      void fetchStudentStats();
    } else {
      void fetchCollegeSettings();
    }
  }, [authLoading, user, router, fetchStudentStats, initialData, fetchCollegeSettings]);

  // Inject urgent attendance alert if below threshold
  useEffect(() => {
    if (stats.attendancePercentage > 0 && stats.attendancePercentage < requiredAttendancePercentage) {
      setNoticeboardItems(prev => {
        if (prev.some(n => n.id === 'attendance-alert-system')) return prev;
        return [{
          id: 'attendance-alert-system',
          title: 'CRITICAL: Low Attendance',
          content: `Your attendance is currently ${stats.attendancePercentage}%, which is below the required ${requiredAttendancePercentage}%. Please attend upcoming classes to avoid debarment.`,
          category: 'alert',
          important: true,
          publishedAt: new Date().toISOString()
        }, ...prev];
      });
    } else {
      setNoticeboardItems(prev => prev.filter(n => n.id !== 'attendance-alert-system'));
    }
  }, [stats.attendancePercentage, requiredAttendancePercentage]);

  return {
    loading,
    firstName,
    profileData,
    stats,
    todayClasses,
    todayEvents,
    scheduleDay,
    enrolledCoursesList,
    noticeboardItems,
    requiredAttendancePercentage,
    loadError,
    setLoading,
    fetchStudentStats,
    orgSlug,
  };
}

import { AXIOS_INSTANCE } from "@pec/api";

const normalizeCourse = (doc: any) => {
  const data = doc?.data ? doc.data() : doc;
  if (!data) return null;
  const id = doc?.id || data.id;
  if (!id) return null;
  return { id, courseId: id, ...data };
};

const fetchFacultyCourses = async (facultyId: string) => {
  const { data: snapshotData } = await AXIOS_INSTANCE.get(`/api/v1/courses?facultyId=${facultyId}`);
  const snapshot = { docs: snapshotData.map((d: any) => ({ id: d.id, data: () => d })) };
  return snapshot.docs
    .map((doc: any) => normalizeCourse(doc))
    .filter(Boolean) as Array<{ id: string; courseId: string; [key: string]: any }>;
};

/**
 * Check if user has faculty access to a specific resource
 */
export async function checkFacultyAccess(
  facultyId: string,
  resourceType: 'course' | 'student' | 'assignment',
  resourceId: string
): Promise<boolean> {
  try {
    if (resourceType === 'course') {
      const facultyCourses = await fetchFacultyCourses(facultyId);
      return facultyCourses.some(course => course.courseId === resourceId || course.id === resourceId);
    }
    
    if (resourceType === 'student') {
      const facultyCourses = await fetchFacultyCourses(facultyId);
      const courseIds = new Set(facultyCourses.map(c => c.courseId || c.id));

      if (courseIds.size === 0) return false;

      const { data: snapshotData } = await AXIOS_INSTANCE.get(`/api/v1/enrollments?studentId=${resourceId}`);
      const snapshot = { docs: snapshotData.map((d: any) => ({ id: d.id, data: () => d })) };
      const enrollments = snapshot.docs.map((doc: any) => doc.data?.() ?? doc.data);
      return enrollments.some((en: any) => courseIds.has(en?.courseId));
    }
    
    return false;
  } catch (error) {
    console.error('Error checking faculty access:', error);
    return false;
  }
}
// Get all courses assigned to a faculty member.
export async function getFacultyAssignments(facultyId: string) {
  try {
    return await fetchFacultyCourses(facultyId);
  } catch (error) {
    console.error('Error fetching faculty assignments:', error);
    return [];
  }
}
// Filter courses to show only faculty-assigned courses.
export async function filterCoursesByFaculty(
  courses: any[],
  facultyId: string
): Promise<any[]> {
  try {
    const assignments = await getFacultyAssignments(facultyId);
    const assignedCourseIds = assignments.map(a => a.courseId || a.id);
    
    return courses.filter(course => assignedCourseIds.includes(course.id));
  } catch (error) {
    console.error('Error filtering courses:', error);
    return courses;
  }
}
// Filter students to show only those enrolled in faculty's courses.
export async function filterStudentsByFaculty(
  students: any[],
  facultyId: string
): Promise<any[]> {
  try {
    const assignments = await getFacultyAssignments(facultyId);
    const courseIds = assignments.map(a => a.courseId || a.id);
    
    if (courseIds.length === 0) return [];
    
    // Fetch enrollments for all faculty courses via backend REST API
    const allEnrollments = await Promise.all(
      courseIds.map(courseId =>
        AXIOS_INSTANCE.get(`/api/v1/enrollments?courseId=${courseId}`)
          .then(r => (Array.isArray(r.data) ? r.data : r.data?.data ?? []) as any[])
          .catch(() => [] as any[])
      )
    );
    const enrolledStudentIds = new Set(
      allEnrollments.flat().map((e: any) => e.studentId)
    );
    
    return students.filter(student => enrolledStudentIds.has(student.id));
  } catch (error) {
    console.error('Error filtering students:', error);
    return students;
  }
}
// Filter attendance records by faculty's courses.
export async function filterAttendanceByFaculty(
  attendanceRecords: any[],
  facultyId: string
): Promise<any[]> {
  try {
    const assignments = await getFacultyAssignments(facultyId);
    const courseIds = assignments.map(a => a.courseId || a.id);
    
    return attendanceRecords.filter(record => courseIds.includes(record.courseId));
  } catch (error) {
    console.error('Error filtering attendance:', error);
    return attendanceRecords;
  }
}
// Check if user has admin or specific role.
export function hasRole(userRole: string, requiredRoles: string[]): boolean {
  return requiredRoles.includes(userRole);
}
// Get faculty-specific data filter.
export function getFacultyDataFilter(facultyId: string, dataType: 'courses' | 'students' | 'attendance') {
  return {
    facultyId,
    dataType,
    async apply(data: any[]) {
      switch (dataType) {
        case 'courses':
          return filterCoursesByFaculty(data, facultyId);
        case 'students':
          return filterStudentsByFaculty(data, facultyId);
        case 'attendance':
          return filterAttendanceByFaculty(data, facultyId);
        default:
          return data;
      }
    }
  };
}
