import { User } from '@pec/shared';

/**
 * Permission utility functions for role-based access control
 * Provides consistent permission checking across the application
 */
export interface UserPermissions {
  // View permissions
  canViewDashboard: boolean;
  canAccessCourses: boolean;
  canAccessFinance: boolean;
  canAccessReports: boolean;
  canAccessAdmin: boolean;
  canEditProfile: boolean;
  canManageCourses: boolean;
  canManageUsers: boolean;
  canManageFinance: boolean;
  canManageInstitution: boolean;
}

/**
 * Get permissions object for a user based on their role
 */
export function getUserPermissions(user: User | null): UserPermissions {
  if (!user) {
    return getDefaultPermissions();
  }

  // If permissions are already in user object, return them
  if ((user as any).permissions) {
    return (user as any).permissions as UserPermissions;
  }

  // Otherwise, derive from role
  return getRolePermissions(user.role);
}

/**
 * Get default (no access) permissions
 */
function getDefaultPermissions(): UserPermissions {
  return {
    canViewDashboard: false,
    canAccessCourses: false,
    canAccessFinance: false,
    canAccessReports: false,
    canAccessAdmin: false,
    canEditProfile: false,
    canManageCourses: false,
    canManageUsers: false,
    canManageFinance: false,
    canManageInstitution: false,
  };
}

/**
 * Get permissions based on role
 */
export function getRolePermissions(role: string): UserPermissions {
  const basePermissions = getDefaultPermissions();

  switch (role) {
    case "college_admin":
      return {
        ...basePermissions,
        canViewDashboard: true,
        canAccessCourses: true,
        canAccessFinance: true,
        canAccessReports: true,
        canAccessAdmin: true,
        canEditProfile: true,
        canManageCourses: true,
        canManageUsers: true,
        canManageFinance: true,
        canManageInstitution: true,
      };

    case "faculty":
      return {
        ...basePermissions,
        canViewDashboard: true,
        canAccessCourses: true,
        canAccessFinance: true,
        canAccessReports: true,
        canAccessAdmin: true,
        canEditProfile: true,
        canManageCourses: true,
        canManageUsers: true,
        canManageFinance: true,
        canManageInstitution: true,
      };

    case "student":
      return {
        ...basePermissions,
        canViewDashboard: true,
        canAccessCourses: true,
        canAccessFinance: true,
        canEditProfile: true,
      };

    default:
      return basePermissions;
  }
}

/**
 * Check if user is admin
 */
export function isAdmin(user: User | null): boolean {
  return ["college_admin", "faculty"].includes(user?.role || "");
}

/**
 * Check if user is faculty
 */
export function isFaculty(user: User | null): boolean {
  return user?.role === "faculty";
}

/**
 * Check if user is student
 */
export function isStudent(user: User | null): boolean {
  return user?.role === "student";
}

/**
 * Check if user is placement officer
 */
export function isPlacementOfficer(user: User | null): boolean {
  return false;
}

/**
 * Check if user is recruiter
 */
export function isRecruiter(user: User | null): boolean {
  return false;
}

/**
 * Check if user can manage (admin or faculty)
 */
export function canManageContent(user: User | null): boolean {
  return isAdmin(user) || isFaculty(user);
}

import { cookies } from 'next/headers';
import { unstable_cache } from 'next/cache';
import { resolveInternalApiBaseUrl } from './internal-api-url';

/**
 * Authenticated SSR fetch via the Next.js proxy (/api -> localhost:8000).
 *
 * Uses the internal server URL for SSR (server -> backend directly for speed,
 * no client round-trip). Falls back gracefully on failure.
 */
export async function serverFetch(endpoint: string, options: RequestInit = {}) {
  const cookieStore = await cookies();
  const accessToken = cookieStore.get('access_token')?.value;
  const refreshToken = cookieStore.get('refresh_token')?.value;

  if (!accessToken && !refreshToken) {
    // No session at all — skip the fetch silently
    return null;
  }

  // Always use the internal backend URL for Server→Backend calls (avoids Proxy hop)
  const path = endpoint.startsWith('/') ? endpoint.slice(1) : endpoint;
  const baseUrl = resolveInternalApiBaseUrl();
  const url = `${baseUrl}/${path}`;

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'Cookie': `access_token=${accessToken ?? ''}; refresh_token=${refreshToken ?? ''}`,
    ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
    ...(options.headers as Record<string, string> ?? {}),
  };

  try {
    const res = await fetch(url, {
      ...options,
      headers,
      // No caching during SSR so we always get fresh data
      cache: 'no-store',
    });

    if (!res.ok) {
      if (res.status !== 401 && res.status !== 403) {
        console.warn(`[serverFetch] ${res.status} ${res.statusText} — ${url}`);
      }
      return null;
    }

    const json = await res.json();
    // Unwrap { success, data } envelope or return raw if different shape
    return json?.success === true ? json.data : json;
  } catch (err: any) {
    // ECONNREFUSED = backend not started yet — log once, don't crash SSR
    if (err?.cause?.code !== 'ECONNREFUSED') {
      console.error(`[serverFetch] fetch error — ${url}:`, err?.message ?? err);
    }
    return null;
  }
}

/**
 * Cached public fetch for shared/static data (department lists, course catalog, etc.).
 * Uses Next.js Data Cache with tag-based invalidation.
 *
 * Usage:
 *   const depts = await cachedServerFetch('/departments?limit=200', ['departments'], 3600);
 *
 * After a mutation, call:
 *   revalidateTag('departments'); // inside a Server Action
 */
export function cachedServerFetch(
  endpoint: string,
  tags: string[],
  revalidate = 3600,
) {
  const path = endpoint.startsWith('/') ? endpoint.slice(1) : endpoint;
  const url = `${resolveInternalApiBaseUrl()}/${path}`;

  return unstable_cache(
    async () => {
      try {
        const res = await fetch(url, {
          headers: { 'Content-Type': 'application/json' },
        });
        if (!res.ok) return null;
        const json = await res.json();
        return json?.success === true ? json.data : json;
      } catch {
        return null;
      }
    },
    [url],
    { tags, revalidate },
  )();
}

/**
 * SSR-safe wrappers for browser-only APIs.
 *
 * These are safe to call during SSR/RSC — they return `null`/`false`/`''`
 * on the server and delegate to the real browser API on the client.
 * This prevents Next.js hydration mismatches.
 */

export const isBrowser = (): boolean => typeof window !== 'undefined';

export const safeLocalStorage = {
  get: (key: string): string | null => {
    if (!isBrowser()) return null;
    try { return window.localStorage.getItem(key); } catch { return null; }
  },
  set: (key: string, value: string): void => {
    if (!isBrowser()) return;
    try { window.localStorage.setItem(key, value); } catch {}
  },
  remove: (key: string): void => {
    if (!isBrowser()) return;
    try { window.localStorage.removeItem(key); } catch {}
  },
};

export const safeDocument = {
  /**
   * Read a specific cookie by name. Returns `null` on server.
   */
  getCookie: (name: string): string | null => {
    if (typeof document === 'undefined') return null;
    const match = document.cookie
      .split(';')
      .map((c) => c.trim())
      .find((c) => c.startsWith(`${name}=`));
    return match ? decodeURIComponent(match.slice(name.length + 1)) : null;
  },
  /**
   * Check if a cookie with a given prefix exists. Returns `false` on server.
   */
  hasCookiePrefix: (prefix: string): boolean => {
    if (typeof document === 'undefined') return false;
    return document.cookie.split(';').some((c) => c.trim().startsWith(prefix));
  },
  /**
   * Set a CSS custom property on documentElement. No-op on server.
   */
  setCssVar: (property: string, value: string): void => {
    if (typeof document === 'undefined') return;
    document.documentElement.style.setProperty(property, value);
  },
  /**
   * Toggle CSS classes on documentElement. No-op on server.
   */
  toggleRootClass: (remove: string[], add: string): void => {
    if (typeof document === 'undefined') return;
    document.documentElement.classList.remove(...remove);
    document.documentElement.classList.add(add);
  },
};

export const safeWindow = {
  /**
   * Get current pathname. Returns `''` on server.
   */
  getPathname: (): string => {
    if (!isBrowser()) return '';
    return window.location.pathname;
  },
  /**
   * Navigate to a URL. No-op on server.
   */
  navigate: (url: string): void => {
    if (!isBrowser()) return;
    window.location.href = url;
  },
  /**
   * Get inner width. Returns `0` on server (treat as unknown until mounted).
   */
  getInnerWidth: (): number => {
    if (!isBrowser()) return 0;
    return window.innerWidth;
  },
  /**
   * Dispatch a custom event. No-op on server.
   */
  dispatch: (event: string): void => {
    if (!isBrowser()) return;
    window.dispatchEvent(new Event(event));
  },
};

