        roomNumber: `${student.departmentCode.charAt(0)}-${201 + i}`,
        status: i % 3 === 0 ? 'Open' : i % 3 === 1 ? 'InProgress' : 'Resolved',
        createdAt: daysAgo(i),
        updatedAt: daysAgo(i % 2),
      },
    });
  }
