export async function seedMarketplace(students: StudentSeed[] = []) {
  console.log('Seeding marketplace listings...');

  const studentPool =
    students.length > 0
      ? students
      : await prisma.user.findMany({
          where: { roles: { some: { role: { name: 'student' } } } },
          select: { id: true, email: true, name: true },
        });

  if (studentPool.length === 0) {
    throw new Error('No students found. Seed students before seeding marketplace listings.');
  }

  // Pick a spread of students as sellers
  const sellerCount = Math.min(studentPool.length, 10);
  const sellers = studentPool.slice(0, sellerCount);

  let created = 0;
  for (let i = 0; i < DUMMY_LISTINGS.length; i++) {
    const listing = DUMMY_LISTINGS[i];
    const seller = sellers[i % sellerCount];

    // Randomise created date across last 60 days for realism
    const daysBack = Math.floor((i / DUMMY_LISTINGS.length) * 55) + 1;

    await prisma.marketplaceListing.create({
      data: {
        title: listing.title,
        description: listing.description,
        price: listing.price,
        category: listing.category,
        condition: listing.condition,
        images: listing.images,
        status: i === 2 || i === 10 ? 'Sold' : 'Available', // mark a couple as sold
        sellerId: seller.id,
        createdAt: daysAgo(daysBack),
      },
    });
    created++;
  }

  console.log(`  ✓ Created ${created} marketplace listings`);

  // Seed some chats
  const listings = await prisma.marketplaceListing.findMany({ take: 5, orderBy: { createdAt: 'desc' } });
  let chatsCreated = 0;
  for (const listing of listings) {
    const buyer = studentPool.find(s => s.id !== listing.sellerId);
    if (!buyer) continue;

    const chat = await prisma.marketplaceChat.create({
      data: {
        listingId: listing.id,
        buyerId: buyer.id,
      }
    });

    await prisma.marketplaceMessage.createMany({
      data: [
        { chatId: chat.id, senderId: buyer.id, text: 'Hi, is this still available?' },
        { chatId: chat.id, senderId: listing.sellerId, text: 'Yes, it is. Are you on campus?' },
      ]
    });
    chatsCreated++;
  }
  console.log(`  ✓ Created ${chatsCreated} marketplace chats`);
}

