import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import * as ExcelJS from 'exceljs';
import * as bcrypt from 'bcrypt';

@Injectable()
export class AdminService {
  async getDashboardStats() {
    const [students, faculty, courses, departments] = await Promise.all([
      this.prisma.user.count({ where: { roles: { some: { role: { name: 'student' } } } } }),
      this.prisma.user.count({ where: { roles: { some: { role: { name: 'faculty' } } } } }),
      this.prisma.course.count(),
      this.prisma.department.count(),
    ]);

    return {
      totalStudents: students,
      totalFaculty: faculty,
      totalCourses: courses,
      totalDepartments: departments,
    };
  }

  constructor(private readonly prisma: PrismaService) {}

  async processUserBulk(file: any) {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(file.buffer as any);
    const worksheet = workbook.worksheets[0];

    const data: any[] = [];
    const headers: string[] = [];

    worksheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) {
        row.eachCell((cell, colNumber) => {
          headers[colNumber] = cell.value?.toString() || `Column${colNumber}`;
        });
      } else {
        const rowData: any = {};
        row.eachCell((cell, colNumber) => {
          rowData[headers[colNumber]] = cell.value;
        });
        data.push(rowData);
      }
    });

    const results = { imported: 0, failed: 0, errors: [] as any[] };

    for (const row of data as any[]) {
      try {
        const { email, name, role, password, department, semester, enrollmentNumber } = row;
        
        if (!email || !name || !role) throw new Error('Missing required fields');

        const hashedPassword = await bcrypt.hash(password || 'password123', 10);
        
        await this.prisma.user.create({
          data: {
            email,
            name,
            role,
            password: hashedPassword,
            ...(role === 'student' ? {
              studentProfile: {
                create: {
                  enrollmentNumber: enrollmentNumber || `PEC-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
                  department: department || 'General',
                  semester: parseInt(semester) || 1,
                }
              }
            } : {})
          }
        });
        results.imported++;
      } catch (e) {
        results.failed++;
        results.errors.push({ email: (row as any).email, error: e.message });
      }
    }

    return results;
  }

  async processAttendanceBulk(file: any) {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(file.buffer as any);
    const worksheet = workbook.worksheets[0];

    const data: any[] = [];
    const headers: string[] = [];

    worksheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) {
        row.eachCell((cell, colNumber) => {
          headers[colNumber] = cell.value?.toString() || `Column${colNumber}`;
        });
      } else {
        const rowData: any = {};
        row.eachCell((cell, colNumber) => {
          rowData[headers[colNumber]] = cell.value;
        });
        data.push(rowData);
      }
    });

    const results = { imported: 0, failed: 0, errors: [] as any[] };

    for (const row of data as any[]) {
      try {
        const { email, date, subject, status } = row;
        const user = await this.prisma.user.findUnique({ where: { email } });
        if (!user) throw new Error(`User with email ${email} not found`);

        await this.prisma.attendance.upsert({
          where: {
            studentId_date_subject: {
              studentId: user.id,
              date: new Date(date),
              subject
            }
          },
          update: { status },
          create: {
            studentId: user.id,
            date: new Date(date),
            subject,
            status
          }
        });
        results.imported++;
      } catch (e) {
        results.failed++;
        results.errors.push({ row, error: e.message });
      }
    }
    return results;
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { AttendanceRepository } from '../attendance/attendance.repository';
import { TimetableRepository } from '../timetable/timetable.repository';
import type { ToolCallResult } from './ai-tools.service';

/**
 * AiAcademicToolsService
 *
 * Handles all student-academic-profile tools:
 *   - get_user_grades
 *   - get_user_attendance
 *   - get_user_schedule
 *   - get_upcoming_exams
 *   - get_enrolled_courses
 */
@Injectable()
export class AiAcademicToolsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly attendanceRepo: AttendanceRepository,
    private readonly timetableRepo: TimetableRepository,
  ) {}

  // ── Grades ───────────────────────────────────────────────────────────────

  async getGrades(userId: string | undefined): Promise<ToolCallResult> {
    if (!userId) {
      return { functionResult: JSON.stringify({ error: 'User not authenticated' }) };
    }
    const raw = await this.fetchGrades(userId);
    return {
      functionResult: JSON.stringify({
        displayed: true,
        message:
          'The grades have been shown to the user in a formatted table. Write a short 1-2 sentence summary (e.g. CGPA, strongest subject). Do NOT repeat or list the raw data.',
      }),
      sseEvents: [{ gradesData: JSON.parse(raw) }],
    };
  }

  // ── Attendance ───────────────────────────────────────────────────────────

  async getAttendance(userId: string | undefined): Promise<ToolCallResult> {
    if (!userId) {
      return { functionResult: JSON.stringify({ error: 'User not authenticated' }) };
    }
    const raw = await this.fetchAttendance(userId);
    return {
      functionResult: JSON.stringify({
        displayed: true,
        message:
          'The attendance report has been shown to the user in a formatted table with per-subject breakdown and skip/attend predictions. Write a short 1-2 sentence summary of their overall status. Do NOT repeat or list the raw data.',
      }),
      sseEvents: [{ attendanceData: JSON.parse(raw) }],
    };
  }

  // ── Schedule ─────────────────────────────────────────────────────────────

  async getSchedule(
    userId: string | undefined,
    day?: string,
    courseCode?: string,
    startTime?: string,
  ): Promise<ToolCallResult> {
    if (!userId) {
      return { functionResult: JSON.stringify({ error: 'User not authenticated' }) };
    }
    const raw = await this.fetchSchedule(userId, day, courseCode, startTime);
    return {
      functionResult: JSON.stringify({
        displayed: true,
        message:
          'The filtered weekly timetable has been shown to the user in a formatted day-grouped schedule. Write a short 1-2 sentence summary. Do NOT repeat or list the raw data.',
      }),
      sseEvents: [{ scheduleData: JSON.parse(raw) }],
    };
  }

  // ── Upcoming Exams ───────────────────────────────────────────────────────

  async getUpcomingExams(userId: string | undefined): Promise<ToolCallResult> {
    if (!userId) {
      return { functionResult: JSON.stringify({ error: 'User not authenticated' }) };
    }
    return { functionResult: await this.fetchUpcomingExams(userId) };
  }

  // ── Enrolled Courses ─────────────────────────────────────────────────────

  async getEnrolledCourses(userId: string | undefined): Promise<ToolCallResult> {
    if (!userId) {
      return { functionResult: JSON.stringify({ error: 'User not authenticated' }) };
    }
    return { functionResult: await this.fetchEnrolledCourses(userId) };
  }

  // ── Private data-fetching helpers ─────────────────────────────────────────

  private gpToLetter(gp: number): string {
    if (gp >= 9.0) return 'A+';
    if (gp >= 8.0) return 'A';
    if (gp >= 7.0) return 'B+';
    if (gp >= 6.0) return 'B';
    if (gp >= 5.0) return 'C+';
    if (gp >= 4.0) return 'C';
    return 'F';
  }

  private async fetchGrades(userId: string): Promise<string> {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      select: { name: true },
    });

    const entries = await this.prisma.cgpaEntry.findMany({
      where: { userId },
      take: 500,
      orderBy: [{ semester: 'asc' }, { createdAt: 'desc' }],
      select: {
        subjectName: true,
        courseCode: true,
        gradePoint: true,
        credits: true,
        semester: true,
        courseType: true,
      },
    });

    if (!entries || entries.length === 0) {
      return JSON.stringify({
        user: user?.name ?? null,
        CGPA: null,
        subjects: [],
        message: 'No grade entries found. Add grades in the CGPA tracker.',
      });
    }

    const seen = new Set<string>();
    const subjects: Array<{
      code: string;
      name: string;
      grade: string;
      gradePoint: number;
      credits: number;
      semester: number;
      type: string;
    }> = [];

    let totalWeighted = 0;
    let totalCredits = 0;

    for (const e of entries) {
      const key = (e.subjectName || e.courseCode || 'Unknown').toLowerCase();
      const gp = Number(e.gradePoint ?? 0);
      const credits = Number(e.credits ?? 3);

      totalWeighted += gp * credits;
      totalCredits += credits;

      if (!seen.has(key)) {
        seen.add(key);
        subjects.push({
          code: e.courseCode ?? '—',
          name: e.subjectName ?? e.courseCode ?? 'Unknown',
          grade: this.gpToLetter(gp),
          gradePoint: gp,
          credits,
          semester: e.semester,
          type: e.courseType ?? 'core',
        });
      }
    }

    const cgpa = totalCredits > 0 ? Number((totalWeighted / totalCredits).toFixed(2)) : null;
    return JSON.stringify({ user: user?.name ?? null, CGPA: cgpa, subjects });
  }

  private async fetchAttendance(userId: string): Promise<string> {
    const TARGET = 75;
    const summary = await this.attendanceRepo.getStudentSummary(userId);

    if (!summary.courses || summary.courses.length === 0) {
      return JSON.stringify({
        totalSummary: { present: 0, total: 0, percentage: 0 },
        courses: [],
        message: 'No attendance records found yet.',
      });
    }

    const targetRatio = TARGET / 100;

    const enrichedCourses = summary.courses.map((course) => {
      const effectivePresent = course.present + course.late * 0.5;
      let needed = 0;
      let canSkip = 0;
      let statusMsg = '';

      if (course.percentage < TARGET) {
        needed = Math.ceil(
          (targetRatio * course.total - effectivePresent) / (1 - targetRatio),
        );
        needed = Math.max(0, needed);
        statusMsg = needed > 0 ? `Attend ${needed} more to reach 75%` : 'Borderline';
      } else {
        canSkip = Math.floor(effectivePresent / targetRatio - course.total);
        canSkip = Math.max(0, canSkip);
        statusMsg = canSkip > 0 ? `Safe to skip ${canSkip} classes` : 'Maintenance mode';
      }

      return {
        courseCode: course.courseCode,
        courseName: course.courseName,
        present: course.present,
        absent: course.absent,
        late: course.late,
        total: course.total,
        percentage: course.percentage,
        canSkip,
        needed,
        status: statusMsg,
      };
    });

    return JSON.stringify({ totalSummary: summary.totalSummary, courses: enrichedCourses });
  }

  private async fetchSchedule(
    userId: string,
    day?: string,
    courseCode?: string,
    startTime?: string,
  ): Promise<string> {
    const profile = await this.prisma.studentProfile.findUnique({
      where: { userId },
      select: { department: true, semester: true },
    });

    const enrollments = await this.prisma.enrollment.findMany({
      where: { studentId: userId, status: 'active' },
      take: 200,
      select: { courseId: true, courseCode: true, courseName: true, batch: true },
    });

    let entries: any[];

    if (enrollments.length > 0) {
      const courseIds = enrollments.map((e) => e.courseId).filter(Boolean) as string[];
      entries = await this.timetableRepo.findManyByCourseIds(courseIds);
    } else if (profile) {
      const result = await this.timetableRepo.findMany({
        department: profile.department,
        semester: profile.semester,
      } as any) as any;
      entries = (result as any).items ?? result;
    } else {
      return JSON.stringify({ message: 'No enrolled courses or student profile found.', schedule: [] });
    }

    if (!entries || entries.length === 0) {
      return JSON.stringify({ message: 'No timetable entries found for your courses yet.', schedule: [] });
    }

    const dayOrder = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    const grouped: Record<string, any[]> = {};

    for (const entry of entries) {
      const entryDay = entry.day ?? 'Unknown';
      if (day && entryDay.toLowerCase() !== day.toLowerCase()) continue;
      if (courseCode && entry.courseCode?.toLowerCase() !== courseCode.toLowerCase()) continue;
      if (startTime && !entry.startTime?.includes(startTime)) continue;

      if (!grouped[entryDay]) grouped[entryDay] = [];
      grouped[entryDay].push({
        startTime: entry.startTime,
        endTime: entry.endTime,
        courseCode: entry.courseCode,
        courseName: entry.courseName,
        room: entry.room ?? '—',
        facultyName: entry.facultyName ?? '—',
      });
    }

    for (const d of Object.keys(grouped)) {
      grouped[d].sort((a, b) => a.startTime.localeCompare(b.startTime));
    }

    const schedule = dayOrder
      .filter((d) => grouped[d] && grouped[d].length > 0)
      .map((d) => ({ day: d, entries: grouped[d] }));

    if (schedule.length === 0) {
      return JSON.stringify({
        message: 'No timetable entries found matching your specified filters.',
        schedule: [],
      });
    }

    return JSON.stringify({ schedule });
  }

  private async fetchUpcomingExams(userId: string): Promise<string> {
    try {
      const profile = await this.prisma.studentProfile.findUnique({
        where: { userId },
        select: { department: true },
      });

      if (!profile?.department) {
        return JSON.stringify({ message: 'No student profile found. Complete your profile first.', exams: [] });
      }

      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const exams = await this.prisma.examSchedule.findMany({
        where: {
          deletedAt: null,
          date: { gte: today },
          course: { department: profile.department },
        },
        orderBy: { date: 'asc' },
        take: 10,
        select: {
          courseCode: true,
          courseName: true,
          examType: true,
          date: true,
          startTime: true,
          endTime: true,
          room: true,
        },
      });

      if (exams.length === 0) {
        return JSON.stringify({ department: profile.department, message: 'No upcoming exams scheduled.', exams: [] });
      }

      return JSON.stringify({ department: profile.department, exams });
    } catch (err) {
      return JSON.stringify({ error: 'Failed to fetch exam schedule: ' + err.message });
    }
  }

  private async fetchEnrolledCourses(userId: string): Promise<string> {
    try {
      const enrollments = await this.prisma.enrollment.findMany({
        where: { studentId: userId, status: 'active' },
        take: 200,
        orderBy: { enrolledAt: 'desc' },
        select: {
          courseId: true,
          courseName: true,
          courseCode: true,
          semester: true,
          batch: true,
          enrolledAt: true,
        },
      });

      if (enrollments.length === 0) {
        return JSON.stringify({ message: 'No active course enrollments found.', courses: [] });
      }

      return JSON.stringify({ courses: enrollments, total: enrollments.length });
    } catch (err) {
      return JSON.stringify({ error: 'Failed to fetch enrolled courses: ' + err.message });
    }
  }
}

import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { GenerativeModel, GoogleGenerativeAI } from '@google/generative-ai';

/**
 * AiCalendarParserService
 *
 * Uses Google Gemini to parse a base64-encoded academic-calendar PDF and
 * return a structured array of calendar events.  Extracted from AiService to
 * give it a single, focused responsibility.
 */
@Injectable()
export class AiCalendarParserService {
  private geminiModel: GenerativeModel | null = null;

  constructor() {
    const geminiApiKey = process.env.GEMINI_API_KEY;
    if (geminiApiKey) {
      const genAI = new GoogleGenerativeAI(geminiApiKey);
      this.geminiModel = genAI.getGenerativeModel({ model: 'gemini-2.0-flash' });
    }
  }

  async parseAcademicCalendarPdf(pdfBase64: string): Promise<any[]> {
    if (!this.geminiModel) {
      throw new InternalServerErrorException('Gemini API key is not configured.');
    }

    try {
      const pdfBuffer = Buffer.from(pdfBase64, 'base64');

      const prompt = `You are an expert at extracting academic calendar information from PDF documents. Analyze this academic calendar PDF and extract ALL events, holidays, exam schedules, and important dates.

Return ONLY a valid JSON array with the following structure for each event:
[
  {
    "title": "Event name/title",
    "description": "Detailed description of the event",
    "date": "YYYY-MM-DD format",
    "endDate": "YYYY-MM-DD format or null if single day",
    "startTime": "HH:MM or null if not specified",
    "endTime": "HH:MM or null if not specified",
    "eventType": "one of: holiday|exam|event|deadline|working-day|orientation|registration|result|recess",
    "category": "broader category like: academic|examination|holiday|administrative|cultural|sports|technical",
    "location": "venue or null if not specified",
    "importance": "one of: high|medium|low",
    "targetAudience": "who it applies to: all|students|faculty|specific-department or null"
  }
]

Rules:
1. Extract EVERY event and date mentioned in the calendar
2. Use the current academic year context (2025-2026) if years are not explicitly mentioned
3. For date ranges, create separate start and end dates
4. For recurring events, create individual entries
5. If a date is ambiguous, make your best guess based on context
6. Return ONLY the JSON array, no markdown formatting, no explanations
7. If no date is found for an event, skip it
8. Parse tables carefully - they often contain exam schedules`;

      const result = await this.geminiModel.generateContent([
        prompt,
        {
          inlineData: {
            data: pdfBuffer.toString('base64'),
            mimeType: 'application/pdf',
          },
        },
      ]);

      const response = await result.response;
      let text = response.text();

      // Strip any markdown code fences the model may add
      text = text.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

      const jsonMatch = text.match(/\[[\s\S]*\]/);
      if (!jsonMatch) {
        throw new Error('Could not parse calendar events from AI response');
      }

      return JSON.parse(jsonMatch[0]);
    } catch (error) {
      throw new InternalServerErrorException(
        error.message || 'Failed to parse academic calendar PDF',
      );
    }
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import type { ToolCallResult } from './ai-tools.service';

/**
 * AiCampusToolsService
 *
 * Handles all campus-related tools:
 *   - get_canteen_menu
 *   - get_night_canteen_menu
 *   - get_clubs
 *   - get_hostel_issues
 *   - navigate_to_page
 */
@Injectable()
export class AiCampusToolsService {
  constructor(private readonly prisma: PrismaService) {}

  // ── Hostel Issues ────────────────────────────────────────────────────────

  async getHostelIssues(userId: string | undefined): Promise<ToolCallResult> {
    if (!userId) {
      return { functionResult: JSON.stringify({ error: 'User not authenticated' }) };
    }
    const raw = await this.fetchHostelIssues(userId);
    return {
      functionResult: JSON.stringify({
        displayed: true,
        message:
          'The list of reported hostel issues has been shown to the user in a formatted dashboard widget. Write a short 1-2 sentence summary. Do NOT repeat or list the raw data.',
      }),
      sseEvents: [{ hostelIssuesData: JSON.parse(raw) }],
    };
  }

  // ── Canteen Menu ─────────────────────────────────────────────────────────

  async getCanteenMenu(category?: string): Promise<ToolCallResult> {
    const raw = await this.fetchCanteenMenu(category);
    return {
      functionResult: JSON.stringify({
        displayed: true,
        message:
          'The canteen menu has been shown to the user in a formatted interactive grid. Write a short 1-2 sentence summary. Do NOT repeat or list the raw data.',
      }),
      sseEvents: [{ canteenData: JSON.parse(raw) }],
    };
  }

  // ── Clubs ────────────────────────────────────────────────────────────────

  async getClubs(): Promise<ToolCallResult> {
    const raw = await this.fetchClubs();
    return {
      functionResult: JSON.stringify({
        displayed: true,
        message:
          'The list of student clubs has been shown to the user. Write a short 1-2 sentence summary. Do NOT repeat or list the raw data.',
      }),
      sseEvents: [{ clubsData: JSON.parse(raw) }],
    };
  }

  // ── Night Canteen Menu ────────────────────────────────────────────────────

  async getNightCanteenMenu(category?: string): Promise<ToolCallResult> {
    const raw = await this.fetchNightCanteenMenu(category);
    return {
      functionResult: JSON.stringify({
        displayed: true,
        message:
          'The night canteen menu has been shown to the user in a formatted interactive grid. Write a short 1-2 sentence summary. Do NOT repeat or list the raw data.',
      }),
      sseEvents: [{ nightCanteenData: JSON.parse(raw) }],
    };
  }

  // ── Navigation ───────────────────────────────────────────────────────────

  navigate(path: string, pageName: string): ToolCallResult {
    const resolvedPath = path ?? '/dashboard';
    const resolvedName = pageName ?? resolvedPath;
    return {
      functionResult: JSON.stringify({ navigated: true, path: resolvedPath, pageName: resolvedName }),
      sseEvents: [{ navigate: resolvedPath }],
    };
  }

  // ── Private data-fetching helpers ─────────────────────────────────────────

  private async fetchHostelIssues(userId: string): Promise<string> {
    try {
      const issues = await this.prisma.hostelIssue.findMany({
        where: { studentId: userId },
        orderBy: { createdAt: 'desc' },
        take: 10,
        select: {
          title: true,
          category: true,
          roomNumber: true,
          status: true,
          priority: true,
          description: true,
          createdAt: true,
        },
      });
      return JSON.stringify({ issues });
    } catch (err) {
      return JSON.stringify({ error: 'Failed to fetch hostel issues: ' + err.message });
    }
  }

  private async fetchCanteenMenu(category?: string): Promise<string> {
    try {
      const items = await this.prisma.canteenItem.findMany({
        where: {
          isAvailable: true,
          ...(category ? { category: { contains: category, mode: 'insensitive' } } : {}),
        },
        orderBy: [{ category: 'asc' }, { name: 'asc' }],
        take: 25,
        select: { name: true, price: true, category: true, description: true, stock: true },
      });
      return JSON.stringify({ items });
    } catch (err) {
      return JSON.stringify({ error: 'Failed to fetch canteen menu: ' + err.message });
    }
  }

  private async fetchClubs(): Promise<string> {
    try {
      const clubs = await this.prisma.club.findMany({
        orderBy: { name: 'asc' },
        select: { name: true, createdAt: true },
      });
      return JSON.stringify({ clubs });
    } catch (err) {
      return JSON.stringify({ error: 'Failed to fetch clubs: ' + err.message });
    }
  }

  private async fetchNightCanteenMenu(category?: string): Promise<string> {
    try {
      const items = await this.prisma.canteenItem.findMany({
        where: {
          isAvailable: true,
          ...(category ? { category: { contains: category, mode: 'insensitive' } } : {}),
        },
        orderBy: [{ category: 'asc' }, { name: 'asc' }],
        take: 25,
        select: { name: true, price: true, category: true, description: true, stock: true },
      });
      return JSON.stringify({
        items,
        note: 'This is the night canteen menu available for after-hours ordering.',
      });
    } catch (err) {
      return JSON.stringify({ error: 'Failed to fetch night canteen menu: ' + err.message });
    }
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { RagService } from './rag.service';
import type { ToolCallResult } from './ai-tools.service';

/**
 * AiDiscoveryToolsService
 *
 * Handles college discovery and search tools:
 *   - search_college_notices (RAG)
 *   - search_marketplace
 *   - get_upcoming_events
 *   - get_finance_summary
 */
@Injectable()
export class AiDiscoveryToolsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly ragService: RagService,
  ) {}

  // ── Notices (RAG) ────────────────────────────────────────────────────────

  async searchCollegeNotices(query: string): Promise<ToolCallResult> {
    const results = await this.ragService.getCollegeNotices(query);
    return { functionResult: JSON.stringify(results) };
  }

  // ── Marketplace ──────────────────────────────────────────────────────────

  async searchMarketplace(query: string): Promise<ToolCallResult> {
    const listings = await this.prisma.marketplaceListing.findMany({
      where: {
        title: { contains: query, mode: 'insensitive' },
        status: 'Available',
      },
      take: 5,
      select: {
        id: true,
        title: true,
        price: true,
        category: true,
        condition: true,
        description: true,
      },
    });
    return { functionResult: JSON.stringify(listings) };
  }

  // ── Events ───────────────────────────────────────────────────────────────

  async getUpcomingEvents(): Promise<ToolCallResult> {
    const events = await this.prisma.academicCalendarEvent.findMany({
      where: { date: { gte: new Date() } },
      orderBy: { date: 'asc' },
      take: 8,
      select: {
        title: true,
        description: true,
        date: true,
        eventType: true,
        importance: true,
      },
    });
    return {
      functionResult: JSON.stringify({
        displayed: true,
        message:
          'The upcoming events timeline has been shown to the user. Write a short 1-2 sentence summary. Do NOT repeat or list the raw data.',
      }),
      sseEvents: [{ eventsData: { events } }],
    };
  }

  // ── Finance Summary ──────────────────────────────────────────────────────

  async getFinanceSummary(userId: string | undefined): Promise<ToolCallResult> {
    if (!userId) {
      return { functionResult: JSON.stringify({ error: 'User not authenticated' }) };
    }
    const raw = await this.fetchFinanceSummary(userId);
    return {
      functionResult: JSON.stringify({
        displayed: true,
        message:
          'The fee payment summary has been shown to the user in a formatted dashboard widget. Write a short 1-2 sentence summary of their dues. Do NOT repeat or list the raw data.',
      }),
      sseEvents: [{ financeData: JSON.parse(raw) }],
    };
  }

  // ── Private data-fetching helpers ─────────────────────────────────────────

  private async fetchFinanceSummary(userId: string): Promise<string> {
    try {
      const fees = await this.prisma.feeRecord.findMany({
        where: { studentId: userId, deletedAt: null },
        orderBy: { dueDate: 'asc' },
        select: {
          id: true,
          amount: true,
          lateFeeAmount: true,
          description: true,
          category: true,
          status: true,
          dueDate: true,
          semester: true,
          month: true,
        },
      });

      if (fees.length === 0) {
        return JSON.stringify({ message: 'No fee records found.', totalPending: 0, totalPaid: 0, overdueCount: 0 });
      }

      const totalPending = fees
        .filter((f) => f.status === 'pending')
        .reduce((s, f) => s + f.amount + f.lateFeeAmount, 0);

      const totalPaid = fees
        .filter((f) => f.status === 'paid')
        .reduce((s, f) => s + f.amount, 0);

      const now = new Date();
      const overdueFees = fees.filter(
        (f) => f.status === 'pending' && new Date(f.dueDate) < now,
      );

      const pendingFees = fees
        .filter((f) => f.status === 'pending')
        .map((f) => ({
          category: f.category,
          description: f.description,
          amount: f.amount + f.lateFeeAmount,
          dueDate: f.dueDate,
          semester: f.semester,
          month: f.month,
          overdue: new Date(f.dueDate) < now,
        }));

      return JSON.stringify({
        totalPending,
        totalPaid,
        overdueCount: overdueFees.length,
        pendingFees,
      });
    } catch (err) {
      return JSON.stringify({ error: 'Failed to fetch finance summary: ' + err.message });
    }
  }
}

import { Injectable, ServiceUnavailableException } from '@nestjs/common';
import OpenAI from 'openai';
import type { Response as ExpressResponse } from 'express';
import { TOOL_DEFINITIONS } from './ai-tools.registry';
import { AiToolsService } from './ai-tools.service';

/**
 * Maximum number of non-system messages kept in the context window per request.
 * System prompts are always preserved; only the trailing MAX_HISTORY
 * conversational turns are forwarded to the model.
 */
const MAX_HISTORY_MESSAGES = 20;

/**
 * AiOrchestrationService
 *
 * Owns:
 *  - OpenAI client initialisation & model routing (OpenAI / GitHub Models)
 *  - Message-history truncation
 *  - The agentic tool-call loop
 *  - SSE streaming of the final answer to the frontend
 *
 * Delegates all individual tool execution to AiToolsService.
 */
@Injectable()
export class AiOrchestrationService {
  private openaiClient: OpenAI | null = null;
  private readonly isGithubModelsProvider: boolean;

  constructor(private readonly toolsService: AiToolsService) {
    this.isGithubModelsProvider = Boolean(
      process.env.GITHUB_AI_API_KEY || process.env.GITHUB_TOKEN,
    );

    const openaiApiKey =
      process.env.GITHUB_AI_API_KEY ||
      process.env.GITHUB_TOKEN ||
      process.env.OPENAI_API_KEY;

    if (openaiApiKey) {
      this.openaiClient = new OpenAI({
        apiKey: openaiApiKey,
        baseURL: this.isGithubModelsProvider
          ? 'https://models.github.ai/inference'
          : undefined,
      });
    }
  }

  // ── Public API ─────────────────────────────────────────────────────────────

  async getCompletion(
    body: any,
    res: ExpressResponse,
    userId?: string,
  ): Promise<void> {
    if (!this.openaiClient) {
      throw new ServiceUnavailableException(
        'AI provider is not configured on the server.',
      );
    }

    try {
      const resolvedModel = this.resolveModel(body?.model);

      // ── 1. Truncate history to keep context manageable ─────────────────
      const messages = this.truncateHistory([...(body.messages ?? [])]);

      // ── 2. First LLM call — let the model pick tools ───────────────────
      let response = await this.openaiClient.chat.completions.create({
        ...body,
        model: resolvedModel,
        messages,
        tools: TOOL_DEFINITIONS as any,
        tool_choice: 'auto',
        stream: false,
      });

      let responseMessage = response.choices[0].message;

      // ── 3. Agentic loop — resolve all tool calls ───────────────────────
      while (responseMessage.tool_calls && responseMessage.tool_calls.length > 0) {
        messages.push(responseMessage);

        for (const toolCall of responseMessage.tool_calls) {
          if (toolCall.type !== 'function') continue;

          const toolName = toolCall.function.name;
          const toolArgs = JSON.parse(toolCall.function.arguments || '{}');

          // Notify frontend which tool is running
          res.write(`data: ${JSON.stringify({ tool: toolName })}\n\n`);

          const { functionResult, sseEvents } = await this.toolsService.dispatch(
            toolName,
            toolArgs,
            userId,
          );

          // Emit any side-effect SSE events (e.g. gradesData, navigate)
          if (sseEvents) {
            for (const event of sseEvents) {
              res.write(`data: ${JSON.stringify(event)}\n\n`);
            }
          }

          messages.push({
            tool_call_id: toolCall.id,
            role: 'tool',
            name: toolName,
            content: functionResult,
          } as any);
        }

        // Next LLM call — may trigger more tools or produce final answer
        response = await this.openaiClient.chat.completions.create({
          ...body,
          model: resolvedModel,
          messages,
          tools: TOOL_DEFINITIONS as any,
          tool_choice: 'auto',
          stream: false,
        });
        responseMessage = response.choices[0].message;
      }

      // ── 4. Stream the final answer ─────────────────────────────────────
      const finalContent = responseMessage.content ?? '';

      if (finalContent.trim()) {
        res.write(`data: ${JSON.stringify({ text: finalContent })}\n\n`);
      } else {
        // Fallback: no cached content — make a real streaming call
        const stream = await this.openaiClient.chat.completions.create({
          ...body,
          model: resolvedModel,
          messages,
          stream: true,
          tools: undefined,
          tool_choice: undefined,
        });
        for await (const chunk of stream as any) {
          const content = chunk.choices[0]?.delta?.content ?? '';
          if (content) {
            res.write(`data: ${JSON.stringify({ text: content })}\n\n`);
          }
        }
      }

      res.write('data: [DONE]\n\n');
      res.end();
    } catch (error) {
      console.error('[AI] Error:', error);
      res.write(
        `data: ${JSON.stringify({ error: error.message || 'AI request failed' })}\n\n`,
      );
      res.write('data: [DONE]\n\n');
      res.end();
    }
  }

  // ── Private helpers ────────────────────────────────────────────────────────

  /**
   * Keeps the system prompt(s) intact and trims the conversational turns to the
   * trailing MAX_HISTORY_MESSAGES entries.  This prevents unbounded token growth
   * for long chat sessions.
   */
  private truncateHistory(messages: any[]): any[] {
    const system = messages.filter((m) => m.role === 'system');
    const rest = messages.filter((m) => m.role !== 'system');
    const recent = rest.slice(-MAX_HISTORY_MESSAGES);
    return [...system, ...recent];
  }

  /**
   * Resolves the model string, adding the "openai/" prefix required by the
   * GitHub Models inference endpoint when needed.
   */
  private resolveModel(requestedModel?: string): string {
    const base =
      typeof requestedModel === 'string' && requestedModel.trim().length > 0
        ? requestedModel.trim()
        : this.isGithubModelsProvider
          ? 'openai/gpt-4o-mini'
          : 'gpt-4o-mini';

    if (this.isGithubModelsProvider && !base.includes('/')) {
      return `openai/${base}`;
    }
    return base;
  }
}

