 * sub-services; AiService just wires them together so the external interface
 * stays unchanged.
 *
 * Sub-service responsibilities:
 *   AiOrchestrationService  — agentic loop, SSE streaming, model routing, history truncation
 *   AiToolsService          — individual tool dispatch + data fetching
 *   AiCalendarParserService — Gemini-powered PDF → calendar events
 *   RagService              — Qdrant vector search for college notices
 */
@Injectable()
export class AiService {
  constructor(
    private readonly orchestration: AiOrchestrationService,
    private readonly calendarParser: AiCalendarParserService,
  ) {}

  /**
   * Handle an AI chat-completion request and stream the response as SSE.
   * Called by AiController.
   */
  getCompletion(body: any, res: ExpressResponse, userId?: string): Promise<void> {
    return this.orchestration.getCompletion(body, res, userId);
  }

  /**
   * Parse an academic calendar PDF (base64-encoded) using Gemini vision.
   * Called by AiController / AcademicCalendarModule.
   */
  parseAcademicCalendarPdf(pdfBase64: string): Promise<any[]> {
    return this.calendarParser.parseAcademicCalendarPdf(pdfBase64);
  }
}

import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { QdrantClient } from '@qdrant/js-client-rest';
import OpenAI from 'openai';

@Injectable()
export class RagService {
  private qdrantClient: QdrantClient;
  private openaiClient: OpenAI;

  constructor() {
    this.qdrantClient = new QdrantClient({
      url: process.env.QDRANT_URL || 'http://localhost:6333',
      apiKey: process.env.QDRANT_API_KEY,
      timeout: 5000, // 5 seconds timeout to prevent event loop starvation
    });

    const openaiApiKey = process.env.GITHUB_AI_API_KEY || process.env.OPENAI_API_KEY;
    if (openaiApiKey) {
      this.openaiClient = new OpenAI({
        apiKey: openaiApiKey,
        baseURL: process.env.GITHUB_AI_API_KEY ? 'https://models.github.ai/inference' : undefined,
      });
    }
  }

  async getCollegeNotices(query: string, limit: number = 3): Promise<any[]> {
    if (!this.openaiClient) {
      throw new InternalServerErrorException('OpenAI client not configured for embeddings.');
    }

    try {
      const isGithub = Boolean(process.env.GITHUB_AI_API_KEY);
      const embeddingModel = isGithub ? 'openai/text-embedding-3-small' : 'text-embedding-3-small'; 

      // 1. Generate Embedding for the query
      const embeddingResponse = await this.openaiClient.embeddings.create({
        model: embeddingModel,
        input: query,
      });
      const queryVector = embeddingResponse.data[0].embedding;

      // 2. Query Qdrant
      const searchResult = await this.qdrantClient.search('college_notices', {
        vector: queryVector,
        limit,
        with_payload: true,
      });

      // 3. Format Results
      return searchResult.map(res => ({
        id: res.id,
        score: res.score,
        ...(res.payload || {}),
      }));
    } catch (error) {
      console.error('Error fetching notices from Qdrant:', error);
      return [{ error: 'Could not fetch college notices at this time.' }];
    }
  }
}

