import { UpdateAttendanceSessionDto } from './dto/update-attendance-session.dto';

@Injectable()
export class AttendanceSessionService {
  constructor(private readonly repo: AttendanceSessionRepository) {}

  async create(data: CreateAttendanceSessionDto) {
    // Standard NestJS service logic
    return this.repo.create(data as any);
  }

  async findAll(query: any) {
    return this.repo.findAll(query);
  }

  async findOne(id: string) {
    const session = await this.repo.findById(id);
    if (!session) throw new NotFoundException(`Attendance session with ID ${id} not found`);
    return session;
  }

  async findByQrCode(qrCode: string) {
    return this.repo.findByQrCode(qrCode);
  }

  async countBySession(sessionId: string): Promise<number> {
    return this.repo.countBySession(sessionId);
  }

  async update(id: string, data: UpdateAttendanceSessionDto) {
    return this.repo.update(id, data as any);
  }

  async remove(id: string) {
    return this.repo.remove(id);
  }
}

import {
  BadRequestException,
  Controller,
  Get,
  Post,
  Body,
  Patch,
  Param,
  Delete,
  Query,
  ParseUUIDPipe,
  Request,
  UploadedFile,
  UseGuards,
  Res,
  UseInterceptors,
} from '@nestjs/common';
import type { FastifyReply } from 'fastify';
import { FileInterceptor } from '@nestjs/platform-express';
import { Throttle } from '@nestjs/throttler';
import { AttendanceService } from './attendance.service';
import { AttendanceQueryDto } from './dto/attendance-query.dto';
import { CreateAttendanceDto } from './dto/create-attendance.dto';
import { UpdateAttendanceDto } from './dto/update-attendance.dto';
import { CreateWaiverRequestDto } from './dto/create-waiver-request.dto';
import { ZodValidationPipe } from '../common/pipes/zod-validation.pipe';
import { attendanceSchema } from '@pec/shared';
import { ok } from '../common/utils/api-response';
import { AuthGuard } from '../auth/auth.guard';
import { PoliciesGuard } from '../auth/guards/policies.guard';
import { CheckPolicies } from '../auth/decorators/check-policies.decorator';




@UseGuards(AuthGuard, PoliciesGuard)
@Controller('attendance')
export class AttendanceController {
  @CheckPolicies((ability) => ability.can('read', 'Attendance'))
  @Get('faculty-stats')
  async getFacultyStats(@Request() req: any) {
    const data = await this.attendanceService.getFacultyStats(req.user.sub);
    return ok(data);
  }

  constructor(private readonly attendanceService: AttendanceService) {}

  @CheckPolicies((ability) => ability.can('read', 'Attendance'))
  @Get('summary')
  async getSummary(@Request() req: any, @Query('studentId') studentId?: string) {
    const targetId = req.user?.role === 'student' ? req.user.sub : studentId;
    if (!targetId) throw new BadRequestException('Student ID is required');
    const data = await this.attendanceService.getStudentSummary(targetId);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('read', 'Attendance'))
  @Get('waivers/my')
  async getMyWaiverRequests(@Request() req: any) {
    const data = await this.attendanceService.getWaiverRequestsForStudent(req.user.sub);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('create', 'Attendance'))
  @Post('waivers')
  @Throttle({ short: { limit: 10, ttl: 60000 } })
  async createWaiverRequest(
    @Request() req: any,
    @Body() body: CreateWaiverRequestDto,
  ) {
    const data = await this.attendanceService.createWaiverRequest(req.user.sub, body);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('create', 'Attendance'))
  @Post('waivers/upload')
  @UseInterceptors(FileInterceptor('file', { limits: { fileSize: 5 * 1024 * 1024 } }))
  async uploadWaiverDocument(
    @Request() req: any,
    @UploadedFile() file: Express.Multer.File,
  ) {
    if (!file) {
      throw new BadRequestException('No file uploaded');
    }

    const data = await this.attendanceService.uploadWaiverDocument(file, req.user.sub);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('read', 'Attendance'))
  @Get('waivers/files/:fileName')
  async streamWaiverDocument(
    @Param('fileName') fileName: string,
    @Request() req: any,
    @Res({ passthrough: true }) res: FastifyReply,
  ) {
    const { url } = await this.attendanceService.getWaiverDocument(
      fileName,
      req.user,
    );

    return res.redirect(302, url);
  }

  @CheckPolicies((ability) => ability.can('read', 'Attendance'))
  @Get('export/:courseId')
  async exportExcel(
    @Param('courseId') courseId: string,
    @Res() res: FastifyReply
  ) {
    res.header('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.header('Content-Disposition', `attachment; filename=attendance_${courseId}.xlsx`);
    await this.attendanceService.generateExcel(courseId, res.raw);
    res.raw.end();
  }

  @CheckPolicies((ability) => ability.can('read', 'Attendance'))
  @Get('my/export')
  async exportMyExcel(
    @Request() req: any,
    @Res() res: FastifyReply
  ) {
    res.header('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.header('Content-Disposition', `attachment; filename=my_attendance.xlsx`);
    await this.attendanceService.generateStudentExcel(req.user.sub, res.raw);
    res.raw.end();
  }

  @CheckPolicies((ability) => ability.can('read', 'Attendance'))
  @Get('predict')
  @Throttle({ short: { limit: 20, ttl: 60000 } })
  async getPrediction(@Request() req: any, @Query('studentId') studentId?: string, @Query('target') target?: string) {
    const targetId = req.user?.role === 'student' ? req.user.sub : studentId;
    if (!targetId) throw new BadRequestException('Student ID is required');
    const targetPercentage = target ? parseInt(target) : 75;
    const data = await this.attendanceService.getPrediction(targetId, targetPercentage);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('create', 'Attendance'))
  @Post()
  async create(
    @Body(new ZodValidationPipe(attendanceSchema))
    createAttendanceDto: CreateAttendanceDto,
  ) {
    const data = await this.attendanceService.create(createAttendanceDto);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('read', 'Attendance'))
  @Get()
  async findAll(@Request() req: any, @Query() query: AttendanceQueryDto) {
    const effectiveQuery = { ...query };
    if (req.user?.role === 'student') {
      effectiveQuery.studentId = req.user.sub;
    }

    const result = await this.attendanceService.findAll(effectiveQuery);
    return ok(result.items, {
      total: result.total,
      limit: result.limit,
      offset: result.offset,
    });
  }

  @CheckPolicies((ability) => ability.can('read', 'Attendance'))
  @Get(':id')
  async findOne(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string) {
    const data = await this.attendanceService.findOne(id);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('update', 'Attendance'))
  @Patch(':id')
  async update(
    @Param('id', new ParseUUIDPipe({ version: '4' })) id: string,
    @Body(new ZodValidationPipe(attendanceSchema.partial()))
    updateAttendanceDto: UpdateAttendanceDto,
  ) {
    const data = await this.attendanceService.update(id, updateAttendanceDto);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('delete', 'Attendance'))
  @Delete(':id')
  async remove(@Param('id', new ParseUUIDPipe({ version: '4' })) id: string) {
    const data = await this.attendanceService.remove(id);
    return ok(data);
  }
}

import { Module } from '@nestjs/common';
import { AttendanceController } from './attendance.controller';
import { AttendanceService } from './attendance.service';
import { AttendanceRepository } from './attendance.repository';
import { QueueModule } from '../background-jobs/queue.module';
import { MessagingModule } from '../messaging/messaging.module';

@Module({
  imports: [QueueModule, MessagingModule],
  controllers: [AttendanceController],
  providers: [AttendanceService, AttendanceRepository],
  exports: [AttendanceService, AttendanceRepository],
})
export class AttendanceModule {}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { AttendanceQueryDto } from './dto/attendance-query.dto';
import { CreateAttendanceDto } from './dto/create-attendance.dto';
import { UpdateAttendanceDto } from './dto/update-attendance.dto';
import { BaseRepository } from '../common/repositories/base.repository';
import { randomUUID } from 'crypto';

type WaiverRequestRow = {
  id: string;
  student_id: string;
  course_id: string | null;
  course_code: string | null;
  course_name: string | null;
  from_date: Date;
  to_date: Date;
  reason: string;
  supporting_doc_url: string | null;
  status: string;
  reviewer_note: string | null;
  created_at: Date;
  updated_at: Date;
};

@Injectable()
export class AttendanceRepository extends BaseRepository {
  private waiverTableReady: Promise<void> | null = null;

  constructor(private readonly prisma: PrismaService) {
    super();
  }

  private async ensureWaiverTable(): Promise<void> {
    if (!this.waiverTableReady) {
      this.waiverTableReady = this.prisma.$executeRawUnsafe(`
        CREATE TABLE IF NOT EXISTS attendance_waiver_requests (
          id TEXT PRIMARY KEY,
          student_id TEXT NOT NULL,
          course_id TEXT,
          course_code TEXT,
          course_name TEXT,
          from_date DATE NOT NULL,
          to_date DATE NOT NULL,
          reason TEXT NOT NULL,
          supporting_doc_url TEXT,
          status TEXT NOT NULL DEFAULT 'pending',
          reviewer_note TEXT,
          reviewer_id TEXT,
          reviewed_at TIMESTAMPTZ,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        CREATE INDEX IF NOT EXISTS idx_attendance_waiver_student_created
          ON attendance_waiver_requests(student_id, created_at DESC);

        CREATE INDEX IF NOT EXISTS idx_attendance_waiver_status_created
          ON attendance_waiver_requests(status, created_at DESC);
      `).then(() => undefined);
    }

    await this.waiverTableReady;
  }

  private mapWaiverRow(row: WaiverRequestRow) {
    return {
      id: row.id,
      studentId: row.student_id,
      courseId: row.course_id,
      courseCode: row.course_code,
      courseName: row.course_name,
      fromDate: row.from_date,
      toDate: row.to_date,
      reason: row.reason,
      supportingDocUrl: row.supporting_doc_url,
      status: row.status,
      reviewerNote: row.reviewer_note,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }

  async create(data: CreateAttendanceDto) {
    return this.prisma.attendance.create({
      data: {
        ...data,
        date: new Date(data.date),
      },
    });
  }

  async createWaiverRequest(data: {
    studentId: string;
    courseId?: string;
    courseCode?: string;
    courseName?: string;
    fromDate: string;
    toDate: string;
    reason: string;
    supportingDocUrl?: string;
  }) {
    await this.ensureWaiverTable();

    const id = randomUUID();

    const rows = await this.prisma.$queryRaw<WaiverRequestRow[]>`
      INSERT INTO attendance_waiver_requests (
        id,
        student_id,
        course_id,
        course_code,
        course_name,
        from_date,
        to_date,
        reason,
        supporting_doc_url,
        status
      ) VALUES (
        ${id},
        ${data.studentId},
        ${data.courseId ?? null},
        ${data.courseCode ?? null},
        ${data.courseName ?? null},
        ${new Date(data.fromDate)},
        ${new Date(data.toDate)},
        ${data.reason},
        ${data.supportingDocUrl ?? null},
        'pending'
      )
      RETURNING *
    `;

    return this.mapWaiverRow(rows[0]);
  }

  async getWaiverRequestsForStudent(studentId: string) {
    await this.ensureWaiverTable();

    const rows = await this.prisma.$queryRaw<WaiverRequestRow[]>`
      SELECT *
      FROM attendance_waiver_requests
      WHERE student_id = ${studentId}
      ORDER BY created_at DESC
      LIMIT 50
    `;

    return rows.map((row) => this.mapWaiverRow(row));
  }

  async findMany(query: AttendanceQueryDto) {
    const where = {
      ...(query.studentId ? { studentId: query.studentId } : {}),
      ...(query.subject ? { subject: query.subject } : {}),
      ...(query.courseId ? { subject: query.courseId } : {}),
      ...(query.status ? { status: query.status } : {}),
      ...(query.date
        ? {
            date: {
              gte: new Date(query.date),
              lt: new Date(new Date(query.date).getTime() + 86_400_000),
            },
          }
        : {}),
    };

    return this.findManyWithCount(this.prisma.attendance, {
      query,
      defaultLimit: 20,
      where,
      orderBy: { date: 'desc' },
    });
  }

  async getFacultyStats(facultyId: string) {
    const courses = await this.prisma.course.findMany({ where: { facultyId },
      include: { _count: { select: { enrollments: true } } }
    });

    const courseIds = courses.map(c => c.id);
    
    // Group attendance by status for all courses taught by this faculty
    const statusCounts = await this.prisma.attendance.groupBy({
      by: ['status'],
      where: { 
        courseId: { in: courseIds } 
      },
      _count: { _all: true }
    });

    const activeCount = courses.length;
    const studentCount = courses.reduce((acc, curr) => acc + curr._count.enrollments, 0);

    return {
      activeCount,
      studentCount,
      courses: courses.map(c => ({
        id: c.id,
        code: c.code,
        name: c.name,
        students: c._count.enrollments
      }))
    };
  }

  async getStudentSummary(studentId: string) {
    const [enrollments, aggregates] = await Promise.all([
      this.prisma.enrollment.findMany({ where: { studentId, status: 'active' },
        include: { 
          course: {
            select: { 
              id: true, 
              name: true, 
              code: true, 
              credits: true, 
              semester: true, 
              instructor: true, 
              department: true 
            }
          }
        }
      }),
      this.prisma.attendance.groupBy({
        by: ['courseId', 'subject', 'status'],
        where: { studentId },
        _count: { _all: true }
      })
    ]);

    const statsMap = new Map<string, { present: number; absent: number; late: number; total: number }>();
    
    aggregates.forEach(agg => {
       let courseId = agg.courseId;
       
       // Fallback: match subject to courseId or code if courseId is missing
       if (!courseId && agg.subject) {
         const match = enrollments.find(e => 
           e.courseId === agg.subject || 
           e.course.code === agg.subject || 
           e.course.name === agg.subject
         );
         if (match) courseId = match.courseId;
       }

       if (!courseId) return;
       
       const current = statsMap.get(courseId) || { present: 0, absent: 0, late: 0, total: 0 };
       const count = agg._count._all;
       
       if (agg.status === 'present') current.present += count;
       else if (agg.status === 'absent') current.absent += count;
       else if (agg.status === 'late') current.late += count;
       
       current.total += count;
       statsMap.set(courseId, current);
    });

    const courses = enrollments.map(en => {
      const stats = statsMap.get(en.courseId) || { present: 0, absent: 0, late: 0, total: 0 };
      const percentage = stats.total > 0 ? Math.round(((stats.present + (stats.late * 0.5)) / stats.total) * 100) : 0;
      
      return {
        courseId: en.courseId,
        courseCode: en.course.code,
        courseName: en.course.name,
        credits: en.course.credits,
        semester: en.course.semester,
        instructor: en.course.instructor,
        department: en.course.department,
        present: stats.present,
        late: stats.late,
        absent: stats.absent,
        total: stats.total,
        percentage
      };
    });

    const totalStats = { present: 0, total: 0 };
    statsMap.forEach(s => {
       totalStats.present += (s.present + (s.late * 0.5));
       totalStats.total += s.total;
    });

    return {
      courses,
      totalSummary: {
        present: Math.round(totalStats.present),
        total: totalStats.total,
        percentage: totalStats.total > 0 ? Math.round((totalStats.present / totalStats.total) * 100) : 0
      }
    };
  }

  findById(id: string) {
    return this.prisma.attendance.findUnique({ where: { id } });
  }


  update(id: string, data: UpdateAttendanceDto) {
    return this.prisma.attendance.update({
      where: { id },
      data: {
        ...data,
        ...(data.date ? { date: new Date(data.date) } : {}),
      },
    });
  }

  remove(id: string) {
    return this.prisma.attendance.delete({ where: { id } });
  }
}

import {
  BadRequestException,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';
import { AttendanceRepository } from './attendance.repository';
import { QueueService } from '../background-jobs/queue.service';
import { MessagingService } from '../messaging/messaging.service';
import { AttendanceQueryDto } from './dto/attendance-query.dto';
import { CreateAttendanceDto } from './dto/create-attendance.dto';
import { UpdateAttendanceDto } from './dto/update-attendance.dto';
import { CreateWaiverRequestDto } from './dto/create-waiver-request.dto';
import * as ExcelJS from 'exceljs';
import { resolve } from 'path';

import { S3Service } from '../common/services/s3.service';

@Injectable()
export class AttendanceService {
  constructor(
    private readonly repo: AttendanceRepository,
    private readonly queue: QueueService,
    private readonly messaging: MessagingService,
    private readonly s3: S3Service,
  ) {}

  private readonly PEC_COORDINATES = { lat: 30.7673, lng: 76.7863 };
  private readonly MAX_DISTANCE_METERS = 100;
  private readonly WAIVER_UPLOAD_DIR = resolve(process.cwd(), 'uploads', 'waivers');

  async create(data: CreateAttendanceDto) {
    if (data.lat !== undefined && data.lng !== undefined) {
      const lat = Number(data.lat);
      const lng = Number(data.lng);

      if (isNaN(lat) || isNaN(lng)) {
        throw new BadRequestException('Invalid coordinates provided.');
      }

      const distance = this.calculateDistance(
        lat,
        lng,
        this.PEC_COORDINATES.lat,
        this.PEC_COORDINATES.lng
      );
      
      if (isNaN(distance) || distance > this.MAX_DISTANCE_METERS) {
        throw new BadRequestException(`Location mismatch: You must be on PEC Campus to mark attendance (Current distance: ${isNaN(distance) ? 'unknown' : Math.round(distance)}m)`);
      }
    }
    
    const created = await this.repo.create(data);

    // enqueue a background job for async processing (notifications, analytics, etc.)
    // Fire and forget so we don't block the main flow if RabbitMQ is slow
    this.queue.addJob('attendance-created', {
      attendanceId: created.id,
      studentId: created.studentId,
      courseId: created.courseId,
      date: created.date,
      status: created.status,
    }).catch(e => {
      // In a real production app we'd fall back to an outbox pattern (saving event to DB table)
      console.error('Failed to enqueue attendance-created job', e?.message || e);
    });

    // Also publish via RabbitMQ for other services (Fire and forget)
    this.messaging.emitAttendanceCreated({
      attendanceId: created.id,
      studentId: created.studentId,
      courseId: created.courseId,
      date: created.date,
      status: created.status,
    }).catch(e => {
      console.error('Failed to publish attendance.created event', e?.message || e);
    });

    return created;
  }

  async createWaiverRequest(studentId: string, body: CreateWaiverRequestDto) {
    const fromDate = new Date(body.fromDate);
    const toDate = new Date(body.toDate);

    if (Number.isNaN(fromDate.getTime()) || Number.isNaN(toDate.getTime())) {
      throw new BadRequestException('Invalid waiver date range');
    }

    if (toDate.getTime() < fromDate.getTime()) {
      throw new BadRequestException('To date cannot be before from date');
    }

    const reason = body.reason?.trim();
    if (!reason || reason.length < 10) {
      throw new BadRequestException('Please provide a detailed reason (minimum 10 characters)');
    }

    return this.repo.createWaiverRequest({
      studentId,
      courseId: body.courseId,
      courseCode: body.courseCode,
      courseName: body.courseName,
      fromDate: body.fromDate,
      toDate: body.toDate,
      reason,
      supportingDocUrl: body.supportingDocUrl,
    });
  }

  getWaiverRequestsForStudent(studentId: string) {
    return this.repo.getWaiverRequestsForStudent(studentId);
  }

  async uploadWaiverDocument(file: any, studentId: string) {
    const maxBytes = 5 * 1024 * 1024;
    if (!file.buffer || file.size <= 0) {
      throw new BadRequestException('Uploaded file is empty');
    }

    if (file.size > maxBytes) {
      throw new BadRequestException('File size exceeds 5 MB limit');
    }

    const allowedMimeTypes = new Set([
      'application/pdf',
      'image/jpeg',
      'image/png',
      'image/webp',
    ]);

    if (!allowedMimeTypes.has(file.mimetype)) {
      throw new BadRequestException('Only PDF, JPG, PNG and WEBP files are allowed');
    }

    // Magic number validation to prevent spoofing
    const header = file.buffer.subarray(0, 4).toString('hex').toUpperCase();
    let isValidMagic = false;
    
    if (file.mimetype === 'application/pdf' && header === '25504446') isValidMagic = true;
    else if (file.mimetype === 'image/jpeg' && header.startsWith('FFD8FF')) isValidMagic = true;
    else if (file.mimetype === 'image/png' && header === '89504E47') isValidMagic = true;
    else if (file.mimetype === 'image/webp' && header === '52494646') {
      const webpHeader = file.buffer.subarray(8, 12).toString('utf8');
      if (webpHeader === 'WEBP') isValidMagic = true;
    }

    if (!isValidMagic) {
      throw new BadRequestException('Invalid file content signature. File appears to be spoofed.');
    }

    // Legacy ClamAV scan removed

    const key = await this.s3.uploadFile(file.buffer, file.originalname, file.mimetype);

    return {
      fileName: key,
      url: `/api/attendance/waivers/files/${key}`,
      originalName: file.originalname,
      mimeType: file.mimetype,
      size: file.size,
    };
  }

  async getWaiverDocument(fileName: string, user: { sub: string; role?: string; roles?: string[] }) {
    if (!fileName || fileName.includes('/') || fileName.includes('\\')) {
      throw new BadRequestException('Invalid file name');
    }

    const roles = new Set([...(user.roles ?? []), user.role].filter(Boolean));
    const isPrivileged = roles.has('college_admin') || roles.has('admin');
    if (!isPrivileged && !fileName.startsWith(`${user.sub}_`)) {
      throw new ForbiddenException('You are not allowed to access this document');
    }

    const url = await this.s3.getSignedDownloadUrl(fileName);
    return { url };
  }

  private calculateDistance(lat1: number, lon1: number, lat2: number, lon2: number) {
    const R = 6371e3; // Earth radius in meters
    const phi1 = lat1 * Math.PI / 180;
    const phi2 = lat2 * Math.PI / 180;
    const dPhi = (lat2 - lat1) * Math.PI / 180;
    const dLambda = (lon2 - lon1) * Math.PI / 180;

    const a = Math.sin(dPhi / 2) * Math.sin(dPhi / 2) +
              Math.cos(phi1) * Math.cos(phi2) *
              Math.sin(dLambda / 2) * Math.sin(dLambda / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    return R * c;
  }

  findAll(query: AttendanceQueryDto) {
    return this.repo.findMany(query);
  }

  findOne(id: string) {
    return this.repo.findById(id);
  }

  getStudentSummary(studentId: string) {
    return this.repo.getStudentSummary(studentId);
  }

  update(id: string, data: UpdateAttendanceDto) {
    return this.repo.update(id, data);
  }

  async getFacultyStats(facultyId: string) {
    const summary = await this.repo.getFacultyStats(facultyId);
    return summary;
  }

  async getPrediction(studentId: string, target = 75) {
    const summary = await this.repo.getStudentSummary(studentId);
    const targetRatio = target / 100;

    return summary.courses.map(course => {
      const { present, total, percentage, late } = course;
      const effectivePresent = present + (late * 0.5);
      
      let status = '';
      let needed = 0;
      let canSkip = 0;

      if (percentage < target) {
        // (effectivePresent + x) / (total + x) >= targetRatio
        needed = Math.ceil((targetRatio * total - effectivePresent) / (1 - targetRatio));
        status = needed > 0 ? `Bunking ${needed} more classes will FAIL you. Attend ${needed} more.` : 'Borderline';
      } else {
        // effectivePresent / (total + x) >= targetRatio
        canSkip = Math.floor((effectivePresent / targetRatio) - total);
        status = canSkip > 0 ? `Safe to skip ${canSkip} classes.` : 'Maintenance mode.';
      }

      return {
        ...course,
        target,
        needed: Math.max(0, needed),
        canSkip: Math.max(0, canSkip),
        status,
        recommendation: percentage < target ? `Attend next ${needed} classes.` : `You can skip up to ${canSkip} classes.`
      };
    });
  }

  remove(id: string) {
    return this.repo.remove(id);
  }

  async generateExcel(courseId: string, stream: any) {
    const data = await this.repo.findMany({ courseId, limit: 1000 });
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('Attendance');
    
    worksheet.columns = [
      { header: 'Student ID', key: 'studentId' },
      { header: 'Subject', key: 'subject' },
      { header: 'Date', key: 'date' },
      { header: 'Status', key: 'status' },
      { header: 'CreatedAt', key: 'createdAt' },
    ];

    data.items.forEach((item: any) => {
      worksheet.addRow({
        studentId: item.studentId,
        subject: item.subject,
        date: item.date.toISOString().split('T')[0],
        status: item.status.toUpperCase(),
        createdAt: item.createdAt ? new Date(item.createdAt).toISOString() : 'N/A'
      });
    });

    await workbook.xlsx.write(stream);
  }

  async generateStudentExcel(studentId: string, stream: any) {
    const data = await this.repo.findMany({ studentId, limit: 1000 });
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('My Attendance');
    
    worksheet.columns = [
      { header: 'Subject', key: 'subject' },
      { header: 'Date', key: 'date' },
      { header: 'Status', key: 'status' },
      { header: 'CreatedAt', key: 'createdAt' },
    ];

    data.items.forEach((item: any) => {
      worksheet.addRow({
        subject: item.subject,
        date: item.date.toISOString().split('T')[0],
        status: item.status.toUpperCase(),
        createdAt: item.createdAt ? new Date(item.createdAt).toISOString() : 'N/A'
      });
    });

    await workbook.xlsx.write(stream);
  }
}

