    const club = await this.prisma.club.findUnique({
      where: { id },
      include: {
        createdBy: {
          select: { name: true, avatar: true },
        },
        joinRequests: {
          where: { status: 'approved' },
          include: { requester: { select: { name: true, avatar: true } } },
        },
      },
    });
