import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';

@Catch()
export class GlobalExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(GlobalExceptionFilter.name);

  catch(exception: unknown, host: ArgumentsHost): void {
    const context = host.switchToHttp();
    const response = context.getResponse();
    const request = context.getRequest();

    let status = HttpStatus.INTERNAL_SERVER_ERROR;
    let message = 'Internal server error';
    const isProduction = process.env.NODE_ENV === 'production';

    if (exception instanceof HttpException) {
      status = exception.getStatus();
      const exceptionResponse = exception.getResponse();
      const resolvedMessage =
        typeof exceptionResponse === 'string'
          ? exceptionResponse
          : (exceptionResponse as any)?.message || exception.message;
      message =
        status >= 500
          ? 'Internal server error'
          : Array.isArray(resolvedMessage)
            ? resolvedMessage.join(', ')
            : resolvedMessage;
    } else if (exception instanceof Error && 'code' in exception && typeof exception.code === 'string' && exception.code.startsWith('P2')) {
      const prismaCode = exception.code;
      status = this.mapPrismaErrorToStatus(prismaCode);
      message = this.mapPrismaErrorToMessage(prismaCode);
    }

    const requestId = request?.requestId || request?.headers?.['x-request-id'];

    const payload = {
      success: false,
      error: {
        message: Array.isArray(message) ? message.join(', ') : message,
        statusCode: status,
      },
      requestId,
      timestamp: new Date().toISOString(),
      path: request?.url,
      method: request?.method,
    };

    if (status >= 500) {
      import('@sentry/node').then((Sentry) => {
        Sentry.captureException(exception, {
          extra: {
            reqId: requestId,
            path: request?.url,
            method: request?.method,
          },
        });
      });

      this.logger.error(
        JSON.stringify({
          event: 'request:error',
          requestId,
          method: request?.method,
          path: request?.url,
          statusCode: status,
          message:
            exception instanceof Error
              ? exception.message
              : 'Unknown exception',
          stack:
            !isProduction && exception instanceof Error
              ? exception.stack
              : undefined,
        }),
      );
    }

    response.status(status).send(payload);
  }

  private mapPrismaErrorToStatus(code: string): number {
    switch (code) {
      case 'P2002':
        return HttpStatus.CONFLICT;
      case 'P2025':
        return HttpStatus.NOT_FOUND;
      default:
        return HttpStatus.BAD_REQUEST;
    }
  }

  private mapPrismaErrorToMessage(code: string): string {
    switch (code) {
      case 'P2002':
        return 'Unique constraint violation';
      case 'P2025':
        return 'Record not found';
      default:
        return 'Database operation failed';
    }
  }
}

import {
  CanActivate,
  ExecutionContext,
  HttpException,
  HttpStatus,
  Injectable,
  Logger,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import {
  RATE_LIMIT_OPTIONS_KEY,
  RateLimitOptions,
} from '../decorators/rate-limit-options.decorator';
import { SKIP_RATE_LIMIT_KEY } from '../decorators/skip-rate-limit.decorator';

type RequestEntry = {
  count: number;
  expiresAt: number;
};



@Injectable()
export class RateLimitGuard implements CanActivate {
  private readonly logger = new Logger(RateLimitGuard.name);
  private readonly requests = new Map<string, RequestEntry>();
  private readonly defaultWindowMs = 60_000;
  private readonly defaultLimit = 120;
  private readonly authWindowMs = 60_000;
  private readonly authLimit = 10;
  private readonly authCaptchaThreshold = 3;
  private readonly defaultBanAfterExceeded = 5;
  private readonly defaultBanDurationMs = 30 * 60_000;

  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const skip = this.reflector.getAllAndOverride<boolean>(
      SKIP_RATE_LIMIT_KEY,
      [context.getHandler(), context.getClass()],
    );

    if (skip) {
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const path = String(request?.route?.path || request?.url || 'unknown');
    const ip = this.extractClientIp(request);
    const now = Date.now();

    this.cleanupExpired(now);



    const customLimits = this.reflector.getAllAndOverride<RateLimitOptions>(
      RATE_LIMIT_OPTIONS_KEY,
      [context.getHandler(), context.getClass()],
    );

    const routeLimits = this.resolveRouteLimits(path, customLimits);
    const key = `${ip}:${path}`;

    const existing = this.requests.get(key);
    if (!existing || existing.expiresAt <= now) {
      this.requests.set(key, {
        count: 1,
        expiresAt: now + routeLimits.windowMs,
      });
    } else if (existing.count >= routeLimits.limit) {
      throw new HttpException(
        {
          success: false,
          error: 'Rate limit exceeded',
          retryAfterSeconds: Math.max(
            1,
            Math.ceil((existing.expiresAt - now) / 1000),
          ),
        },
        HttpStatus.TOO_MANY_REQUESTS,
      );
    } else {
      existing.count += 1;
      this.requests.set(key, existing);
    }



    return true;
  }

  private resolveRouteLimits(
    routePath: string,
    custom?: RateLimitOptions,
  ): Required<RateLimitOptions> {
    if (custom) {
      return {
        limit: custom.limit,
        windowMs: custom.windowMs,
        banAfterExceeded:
          custom.banAfterExceeded ?? this.defaultBanAfterExceeded,
        banDurationMs: custom.banDurationMs ?? this.defaultBanDurationMs,
        requireCaptchaAfterExceeded:
          custom.requireCaptchaAfterExceeded ?? this.authCaptchaThreshold,
      };
    }

    if (routePath.includes('/auth/login') || routePath.includes('/otp')) {
      return {
        limit: this.authLimit,
        windowMs: this.authWindowMs,
        banAfterExceeded: 4,
        banDurationMs: 60 * 60_000,
        requireCaptchaAfterExceeded: this.authCaptchaThreshold,
      };
    }

    if (routePath.includes('/payment') || routePath.includes('/finance')) {
      return {
        limit: 15,
        windowMs: 60_000,
        banAfterExceeded: 5,
        banDurationMs: 45 * 60_000,
        requireCaptchaAfterExceeded: 2,
      };
    }

    return {
      limit: this.defaultLimit,
      windowMs: this.defaultWindowMs,
      banAfterExceeded: this.defaultBanAfterExceeded,
      banDurationMs: this.defaultBanDurationMs,
      requireCaptchaAfterExceeded: 6,
    };
  }



  private extractClientIp(request: any): string {
    const forwarded = request?.headers?.['x-forwarded-for'];
    if (typeof forwarded === 'string' && forwarded.length > 0) {
      return forwarded.split(',')[0].trim();
    }
    return request?.ip || request?.socket?.remoteAddress || 'unknown';
  }

  private cleanupExpired(now: number): void {
    for (const [key, value] of this.requests.entries()) {
      if (value.expiresAt <= now) {
        this.requests.delete(key);
      }
    }


  }
}

import { Injectable, NestMiddleware, BadRequestException, ConflictException } from '@nestjs/common';
import type { FastifyRequest, FastifyReply } from 'fastify';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { Cache } from 'cache-manager';
import { Inject } from '@nestjs/common';

@Injectable()
export class IdempotencyMiddleware implements NestMiddleware {
  constructor(@Inject(CACHE_MANAGER) private cacheManager: Cache) {}

  async use(req: FastifyRequest, res: FastifyReply, next: () => void) {
    if (req.method !== 'POST') {
      return next();
    }

    const idempotencyKey = req.headers['x-idempotency-key'];

    if (!idempotencyKey) {
      throw new BadRequestException('Idempotency-Key header is required for this operation to prevent double-billing.');
    }

    const cacheKey = `idempotency:${idempotencyKey}`;
    const existingResponse = await this.cacheManager.get(cacheKey);

    if (existingResponse) {
      throw new ConflictException('A request with this Idempotency Key has already been processed.');
    }

    // Mark as processing
    await this.cacheManager.set(cacheKey, 'processing', 24 * 60 * 60);

    // Overwrite res.send to capture the response
    const originalSend = res.send;
    res.send = function (body) {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        // Safe to cache successful responses
      } else {
        // If it failed, delete the key so they can retry
        // (In a real app, you might use a more robust cleanup on errors)
      }
      return originalSend.call(this, body);
    };

    next();
  }
}

import {
  BadRequestException,
  Injectable,
  NestMiddleware,
} from '@nestjs/common';

import sanitizeHtml = require('sanitize-html');

@Injectable()
export class InputSanitizationMiddleware implements NestMiddleware {
  use(req: any, _res: any, next: () => void): void {
    this.assignSanitizedValue(
      req,
      'body',
      this.sanitizePayload(req.body, 'body'),
    );
    this.assignSanitizedValue(
      req,
      'query',
      this.sanitizePayload(req.query, 'query'),
    );
    this.assignSanitizedValue(
      req,
      'params',
      this.sanitizePayload(req.params, 'params'),
    );
    next();
  }

  private assignSanitizedValue(
    req: Record<string, unknown>,
    key: 'body' | 'query' | 'params',
    value: unknown,
  ): void {
    const current = req[key];

    if (
      current &&
      typeof current === 'object' &&
      value &&
      typeof value === 'object'
    ) {
      for (const existingKey of Object.keys(
        current as Record<string, unknown>,
      )) {
        delete (current as Record<string, unknown>)[existingKey];
      }

      Object.assign(current as Record<string, unknown>, value);
      return;
    }

    Object.defineProperty(req, key, {
      value,
      writable: true,
      configurable: true,
      enumerable: true,
    });
  }

  private sanitizePayload<T>(payload: T, source: string): T {
    if (payload == null) {
      return payload;
    }

    if (Array.isArray(payload)) {
      return payload.map((item) => this.sanitizePayload(item, source)) as T;
    }

    if (typeof payload === 'string') {
      return this.sanitizeString(payload) as T;
    }

    if (typeof payload !== 'object') {
      return payload;
    }

    const nextObject: Record<string, unknown> = {};
    const objPayload = payload as Record<string, unknown>;

    for (const [key, value] of Object.entries(objPayload)) {
      if (key.startsWith('$') || key.includes('.')) {
        throw new BadRequestException(`Invalid key detected in ${source}`);
      }
      nextObject[key] = this.sanitizePayload(value, source);
    }

    return nextObject as T;
  }

  private sanitizeString(value: string): string {
    const sanitized = sanitizeHtml(value, {
      allowedTags: [],
      allowedAttributes: {},
      disallowedTagsMode: 'discard',
    });
    return sanitized.trim();
  }
}

import { Injectable, Logger, NestMiddleware } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class RequestLoggingMiddleware implements NestMiddleware {
  private readonly logger = new Logger(RequestLoggingMiddleware.name);

  constructor(private readonly prisma: PrismaService) {}

  use(req: any, res: any, next: () => void): void {
    const requestId = randomUUID();
    req.requestId = requestId;
    res.setHeader('x-request-id', requestId);

    const start = Date.now();
    const { method, originalUrl, ip } = req;
    const userAgent = req.headers?.['user-agent'];

    this.logger.log(
      JSON.stringify({
        event: 'request:start',
        requestId,
        method,
        path: originalUrl,
        ip,
        userAgent,
      }),
    );

    res.on('finish', () => {
      const durationMs = Date.now() - start;
      const actor = req.user as { sub?: string; role?: string } | undefined;
      const ipAddress =
        typeof req.headers?.['x-forwarded-for'] === 'string'
          ? req.headers['x-forwarded-for'].split(',')[0].trim()
          : req.ip;
      const isSensitiveStatus = [401, 403, 429].includes(res.statusCode);
      const isAuthPath = String(originalUrl).startsWith('/auth');

      this.logger.log(
        JSON.stringify({
          event: 'request:end',
          requestId,
          method,
          path: originalUrl,
          statusCode: res.statusCode,
          durationMs,
          actorUserId: actor?.sub ?? null,
        }),
      );

      if (isSensitiveStatus || isAuthPath) {
        this.logger.warn(
          JSON.stringify({
            event: 'security:signal',
            requestId,
            method,
            path: originalUrl,
            statusCode: res.statusCode,
            actorUserId: actor?.sub ?? null,
            actorRole: actor?.role ?? null,
            ip: ipAddress ?? null,
            userAgent,
          }),
        );
      }

      if (this.shouldPersistAuditTrail(method, originalUrl, actor)) {
        void this.prisma.auditLog
          .create({
            data: {
              actorUserId: actor?.sub ?? null,
              actorRole: actor?.role ?? null,
              action: `HTTP_${method}`,
              entity: 'request',
              entityId: requestId,
              method,
              path: originalUrl,
              ip: ipAddress ?? null,
              statusCode: res.statusCode,
              metadata: JSON.stringify({
                durationMs,
                requestId,
                userAgent,
              }),
            },
          })
          .catch((error: unknown) => {
            this.logger.warn(`Failed to write audit log: ${String(error)}`);
          });
      }
    });

    next();
  }

  private shouldPersistAuditTrail(
    method: string,
    path: string,
    actor?: { sub?: string; role?: string },
  ): boolean {
    if (path === '/' || path.startsWith('/health')) {
      return false;
    }

    if (actor?.sub) {
      return true;
    }

    return ['POST', 'PATCH', 'PUT', 'DELETE'].includes(method);
  }
}

import { BadRequestException, Injectable, PipeTransform } from '@nestjs/common';

@Injectable()
export class ZodValidationPipe implements PipeTransform {
  constructor(private readonly schema: any) {}

  transform(value: unknown): unknown {
    const result = this.schema.safeParse(value);
    if (!result.success) {
      throw new BadRequestException({
        message: 'Validation failed',
        errors: result.error.issues.map((issue: any) => ({
          path: issue.path.join('.'),
          message: issue.message,
          code: issue.code,
        })),
      });
    }
    return result.data;
  }
}

import { PrismaClientKnownRequestError } from '@prisma/client/runtime/library';

export async function withPrismaRetry<T>(
  operation: () => Promise<T>,
  maxRetries = 3,
  delayMs = 100
): Promise<T> {
  let attempt = 0;
  while (attempt < maxRetries) {
    try {
      return await operation();
    } catch (error) {
      if (
        error instanceof PrismaClientKnownRequestError &&
        error.code === 'P2034' // P2034: Transaction failed due to a write conflict or a deadlock.
      ) {
        attempt++;
        if (attempt >= maxRetries) throw error;
        await new Promise((resolve) => setTimeout(resolve, delayMs * attempt)); // Exponential backoff
      } else {
        throw error;
      }
    }
  }
  throw new Error('Prisma retry wrapper failed unexpectedly.');
}

type ListQuery = {
  limit?: number;
  offset?: number;
  cursorId?: string; // Added for cursor-based pagination
};

type FindManyCountDelegate<TItem, TWhere, TOrderBy> = {
  findMany: (args: {
    where?: TWhere;
    take?: number;
    skip?: number;
    cursor?: any;
    orderBy?: TOrderBy | TOrderBy[];
  }) => Promise<TItem[]>;
  count: (args: { where?: TWhere }) => Promise<number>;
};

export type PaginatedResult<TItem> = {
  items: TItem[];
  total: number;
  limit: number;
  offset?: number;
  nextCursor?: string | null;
};

export abstract class BaseRepository {
  protected resolvePagination(
    query: ListQuery,
    defaultLimit: number,
    maxLimit = 200,
  ): { take: number; skip: number } {
    const requestedLimit = query.limit ?? defaultLimit;
    const take = Math.min(Math.max(requestedLimit, 1), maxLimit);
    const skip = Math.max(query.offset ?? 0, 0);

    return { take, skip };
  }

  // Legacy Offset Pagination
  protected async findManyWithCount<TItem, TWhere, TOrderBy>(
    delegate: FindManyCountDelegate<TItem, TWhere, TOrderBy>,
    options: {
      query: ListQuery;
      defaultLimit: number;
      maxLimit?: number;
      where?: TWhere;
      orderBy?: TOrderBy | TOrderBy[];
    },
  ): Promise<PaginatedResult<TItem>> {
    const { take, skip } = this.resolvePagination(
      options.query,
      options.defaultLimit,
      options.maxLimit,
    );

    const [items, total] = await Promise.all([
      delegate.findMany({ where: options.where,
        take,
        skip,
        orderBy: options.orderBy,
      }),
      delegate.count({ where: options.where }),
    ]);

    return {
      items,
      total,
      limit: take,
      offset: skip,
    };
  }

  // Optimized Cursor Pagination for Heavy Tables
  protected async findManyWithCursor<TItem extends { id: string }, TWhere, TOrderBy>(
    delegate: FindManyCountDelegate<TItem, TWhere, TOrderBy>,
    options: {
      query: ListQuery;
      defaultLimit: number;
      maxLimit?: number;
      where?: TWhere;
      orderBy?: TOrderBy | TOrderBy[];
    },
  ): Promise<PaginatedResult<TItem>> {
    const requestedLimit = options.query.limit ?? options.defaultLimit;
    const take = Math.min(Math.max(requestedLimit, 1), options.maxLimit ?? 200);
    const cursor = options.query.cursorId ? { id: options.query.cursorId } : undefined;

    const [items, total] = await Promise.all([
      delegate.findMany({
        where: options.where,
        take: take + 1, // Fetch one extra to check if there is a next page
        skip: cursor ? 1 : 0, // Skip the cursor itself
        cursor: cursor,
        orderBy: options.orderBy,
      }),
      delegate.count({ where: options.where }),
    ]);

    let nextCursor: string | null = null;
    if (items.length > take) {
      const nextItem = items.pop();
      nextCursor = nextItem?.id ?? null;
    }

    return {
      items,
      total,
      limit: take,
      nextCursor,
    };
  }
}

import {
  createCipheriv,
  createDecipheriv,
  createHash,
  randomBytes,
} from 'crypto';

const ENCRYPTED_PREFIX = 'enc:v1:';

const getEncryptionKey = (): Buffer | null => {
  const raw = process.env.FIELD_ENCRYPTION_KEY;
  if (!raw) {
    return null;
  }
  return createHash('sha256').update(raw).digest();
};

export const encryptField = (value?: string | null): string | null => {
  if (!value) return null;
  if (value.startsWith(ENCRYPTED_PREFIX)) return value;

  const key = getEncryptionKey();
  if (!key) return value;

  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', key, iv);
  const encrypted = Buffer.concat([
    cipher.update(value, 'utf8'),
    cipher.final(),
  ]);
  const tag = cipher.getAuthTag();

  return `${ENCRYPTED_PREFIX}${iv.toString('base64')}:${tag.toString('base64')}:${encrypted.toString('base64')}`;
};

export const decryptField = (value?: string | null): string | null => {
  if (!value) return null;
  if (!value.startsWith(ENCRYPTED_PREFIX)) return value;

  const key = getEncryptionKey();
  if (!key) return value;

  try {
    const encoded = value.slice(ENCRYPTED_PREFIX.length);
    const [ivB64, tagB64, dataB64] = encoded.split(':');
    if (!ivB64 || !tagB64 || !dataB64) return null;

    const iv = Buffer.from(ivB64, 'base64');
    const tag = Buffer.from(tagB64, 'base64');
    const encrypted = Buffer.from(dataB64, 'base64');

    const decipher = createDecipheriv('aes-256-gcm', key, iv);
    decipher.setAuthTag(tag);
    const decrypted = Buffer.concat([
      decipher.update(encrypted),
      decipher.final(),
    ]);

    return decrypted.toString('utf8');
  } catch {
    return null;
  }
};

import { Injectable, Logger, OnModuleInit, HttpException, HttpStatus } from '@nestjs/common';
import { S3Client, PutObjectCommand, DeleteObjectCommand, GetObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import { v4 as uuidv4 } from 'uuid';

@Injectable()
export class S3Service implements OnModuleInit {
  private readonly logger = new Logger(S3Service.name);
  private s3Client: S3Client;
  private readonly bucket = process.env.MINIO_BUCKET || 'pec-uploads';

  onModuleInit() {
    this.s3Client = new S3Client({
      region: 'us-east-1', // MinIO doesn't care about region but AWS SDK requires it
      endpoint: `http://${process.env.MINIO_ENDPOINT || 'localhost'}:${process.env.MINIO_PORT || '9000'}`,
      credentials: {
        accessKeyId: process.env.MINIO_ACCESS_KEY || 'admin',
        secretAccessKey: process.env.MINIO_SECRET_KEY || 'admin123',
      },
      forcePathStyle: true, // Crucial for MinIO
    });
    this.logger.log(`S3Service initialized connected to ${process.env.MINIO_ENDPOINT}`);
  }

  /**
   * Uploads a file buffer to S3/MinIO
   * @param buffer File buffer to upload
   * @param originalName Original file name to extract extension
   * @param mimetype File mime type
   * @returns The generated S3 object key
   */
  async uploadFile(buffer: Buffer, originalName: string, mimetype: string): Promise<string> {
    const ext = originalName.split('.').pop();
    const key = `${uuidv4()}.${ext}`;

    try {
      const command = new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: buffer,
        ContentType: mimetype,
      });

      await this.s3Client.send(command);
      return key;
    } catch (error) {
      this.logger.error(`Error uploading file to S3: ${error.message}`, error);
      throw new HttpException('Failed to upload file to storage', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }

  /**
   * Generates a pre-signed URL to download a file securely
   * @param key S3 Object key
   * @param expiresIn Expiration time in seconds (default: 3600)
   * @returns Pre-signed URL string
   */
  async getSignedDownloadUrl(key: string, expiresIn = 3600): Promise<string> {
    try {
      const command = new GetObjectCommand({
        Bucket: this.bucket,
        Key: key,
      });
      // Important: Use getSignedUrl from '@aws-sdk/s3-request-presigner'
      return await getSignedUrl(this.s3Client, command, { expiresIn });
    } catch (error) {
      this.logger.error(`Error generating pre-signed URL for key ${key}: ${error.message}`, error);
      throw new HttpException('Failed to generate download URL', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }

  /**
   * Deletes a file from S3/MinIO
   * @param key S3 Object key
   */
  async deleteFile(key: string): Promise<void> {
    try {
      const command = new DeleteObjectCommand({
        Bucket: this.bucket,
        Key: key,
      });
      await this.s3Client.send(command);
    } catch (error) {
      this.logger.error(`Error deleting file from S3 for key ${key}: ${error.message}`, error);
      // We don't necessarily want to fail a larger transaction just because S3 delete failed
    }
  }
}

export type ApiMeta = {
  limit?: number;
  offset?: number;
  total?: number;
};

export type ApiSuccess<T> = {
  success: true;
  data: T;
  meta?: ApiMeta;
};

export const ok = <T>(data: T, meta?: ApiMeta): ApiSuccess<T> => ({
  success: true,
  data,
  ...(meta ? { meta } : {}),
});

const LOCAL_DEV_ORIGINS = [
  'http://localhost:5173',
  'http://127.0.0.1:5173',
  'http://localhost:4173',
  'http://127.0.0.1:4173',
  'http://localhost:3000',
  'http://127.0.0.1:3000',
  'http://localhost:3001',
  'http://127.0.0.1:3001',
];

const parseBoolean = (
  value: string | undefined,
  fallback: boolean,
): boolean => {
  if (value == null || value.trim() === '') {
    return fallback;
  }

  return value.trim().toLowerCase() === 'true';
};

const parseNumber = (value: string | undefined, fallback: number): number => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback;
  }
  return parsed;
};

export const getAllowedCorsOrigins = (): string[] => {
  const configuredOrigins = (process.env.CORS_ORIGINS ?? '')
    .split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);

  if (configuredOrigins.length > 0) {
    return configuredOrigins;
  }

  if (process.env.NODE_ENV === 'production') {
    throw new Error(
      'CORS_ORIGINS must be explicitly configured in production. Refusing to enable permissive CORS.',
    );
  }

  return LOCAL_DEV_ORIGINS;
};

export const getCorsConfig = () => {
  const origins = getAllowedCorsOrigins();

  return {
    origins,
    allowCredentials: parseBoolean(process.env.CORS_ALLOW_CREDENTIALS, true),
    allowedMethods: [
      'GET',
      'HEAD',
      'POST',
      'PUT',
      'PATCH',
      'DELETE',
      'OPTIONS',
    ],
    allowedHeaders: [
      'Accept',
      'Authorization',
      'Content-Type',
      'Origin',
      'X-Captcha-Token',
      'X-Request-Id',
      'X-Requested-With',
    ],
    exposedHeaders: ['x-request-id'],
    maxAgeSeconds: parseNumber(process.env.CORS_MAX_AGE_SECONDS, 86_400),
  };
};

export const getBodySizeLimit = (): string =>
  process.env.REQUEST_BODY_LIMIT?.trim() || '1mb';

export const isProduction = (): boolean =>
  (process.env.NODE_ENV ?? '').toLowerCase() === 'production';

