@Injectable()
export class FeatureFlagsService {
  private readonly cache = new Map<string, CachedFlag>();
  private readonly ttlMs = Number(
    process.env.FEATURE_FLAG_CACHE_TTL_MS ?? '30000',
  );

  constructor(private readonly prisma: PrismaService) {}

  async listAll() {
    return this.prisma.featureFlag.findMany({ orderBy: [{ key: 'asc' }],
    });
  }

  async getByKey(key: string) {
    const cached = this.cache.get(key);
    const now = Date.now();

    if (cached && cached.expiresAt > now) {
      return cached.value;
    }

    const featureFlag = await this.prisma.featureFlag.findUnique({
      where: { key },
    });

    if (!featureFlag) {
      if (key === 'college-settings') {
        return this.upsert(key, {
          enabled: true,
          description: 'College settings',
          payload: JSON.stringify({ attendanceRequiredPercentage: 75 }),
        });
      }
      throw new NotFoundException('Feature flag not found');
    }

    this.cache.set(key, {
      value: featureFlag,
      expiresAt: now + this.ttlMs,
    });

    return featureFlag;
  }

  async isEnabled(key: string): Promise<boolean> {
    const flag = await this.getByKey(key);
    return flag.enabled;
  }

  async upsert(
    key: string,
    input: { enabled: boolean; description?: string; payload?: string },
  ) {
    const featureFlag = await this.prisma.featureFlag.upsert({
      where: { key },
      update: {
        enabled: input.enabled,
        description: input.description ?? null,
        payload: input.payload ?? null,
      },
      create: {
        key,
        enabled: input.enabled,
        description: input.description ?? null,
        payload: input.payload ?? null,
      },
    });

    this.cache.set(key, {
      value: featureFlag,
      expiresAt: Date.now() + this.ttlMs,
    });

    return featureFlag;
  }
}

import { ArgumentsHost, Catch, ExceptionFilter } from '@nestjs/common';
import { ZodValidationException } from 'nestjs-zod';

@Catch(ZodValidationException)
export class ZodValidationFilter implements ExceptionFilter {
  catch(exception: ZodValidationException, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<import('fastify').FastifyReply>();

    const errors = exception.getZodError().errors.map((err) => ({
      path: err.path.join('.'),
      message: err.message,
    }));

    response.status(400).send({
      statusCode: 400,
      error: 'Bad Request',
      message: 'Validation failed',
      errors,
    });
  }
}

