@UseGuards(AuthGuard, PoliciesGuard)
@Controller('night-canteen')
export class NightCanteenController {
  constructor(private readonly service: NightCanteenService) {}

  @CheckPolicies((ability) => ability.can('read', 'CanteenItem'))
  @Get('items')
  async listItems(@Query() query: NightCanteenItemQueryDto) {
    const result = await this.service.findItems(query);
    return ok(result.items, {
      total: result.total,
      limit: result.limit,
      offset: result.offset,
    });
  }

  @CheckPolicies((ability) => ability.can('read', 'CanteenItem'))
  @Get('items/:id')
  async getItem(@Param('id') id: string) {
    const data = await this.service.findItemById(id);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('create', 'CanteenItem'))
  @Post('items')
  async createItem(@Body() body: CreateCanteenItemDto) {
    const data = await this.service.createItem(body);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('create', 'CanteenItem'))
  @Post('items/:id')
  async upsertItem(
    @Param('id') id: string,
    @Body() body: CreateCanteenItemDto,
  ) {
    const data = await this.service.upsertItem(id, body);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('update', 'CanteenItem'))
  @Patch('items/:id')
  async updateItem(
    @Param('id') id: string,
    @Body() body: UpdateCanteenItemDto,
  ) {
    const data = await this.service.updateItem(id, body);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('delete', 'CanteenItem'))
  @Delete('items/:id')
  async deleteItem(@Param('id') id: string) {
    const data = await this.service.deleteItem(id);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('read', 'CanteenItem'))
  @Get('orders')
  async listOrders(
    @Req() req: FastifyRequest & { user?: { sub?: string; role?: string } },
    @Query() query: NightCanteenOrderQueryDto,
  ) {
    const role = req.user?.role;
    const currentUserId = req.user?.sub;

    const normalizedQuery: NightCanteenOrderQueryDto = {
      ...query,
      studentId: role === 'student' ? currentUserId : query.studentId,
    };

    const result = await this.service.findOrders(normalizedQuery);
    return ok(result.items, {
      total: result.total,
      limit: result.limit,
      offset: result.offset,
    });
  }

  @CheckPolicies((ability) => ability.can('read', 'CanteenItem'))
  @Get('orders/:id')
  async getOrder(@Param('id') id: string) {
    const data = await this.service.findOrderById(id);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('create', 'CanteenItem'))
  @Post('orders')
  async createOrder(
    @Req() req: FastifyRequest & { user?: { sub?: string; role?: string } },
    @Body() body: CreateCanteenOrderDto,
  ) {
    const role = req.user?.role;
    const currentUserId = req.user?.sub;
    const data = await this.service.createOrder({
      ...body,
      studentId: role === 'student' ? currentUserId : body.studentId,
    });
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('update', 'CanteenItem'))
  @Patch('orders/:id')
  async updateOrder(
    @Param('id') id: string,
    @Body() body: UpdateCanteenOrderDto,
  ) {
    const data = await this.service.updateOrder(id, body);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('delete', 'CanteenItem'))
  @Delete('orders/:id')
  async deleteOrder(@Param('id') id: string) {
    const data = await this.service.deleteOrder(id);
    return ok(data);
  }
}

import { Module } from '@nestjs/common';
import { NightCanteenController } from './night-canteen.controller';
import { NightCanteenService } from './night-canteen.service';
import { NightCanteenRepository } from './night-canteen.repository';

@Module({
  controllers: [NightCanteenController],
  providers: [NightCanteenService, NightCanteenRepository],
})
export class NightCanteenModule {}

import { Injectable } from '@nestjs/common';
import { Prisma } from '@pec/database';
import { PrismaService } from '../prisma/prisma.service';
import {
  NightCanteenItemQueryDto,
  NightCanteenOrderQueryDto,
} from './dto/night-canteen-query.dto';
import { CreateCanteenItemDto } from './dto/create-canteen-item.dto';
import { UpdateCanteenItemDto } from './dto/update-canteen-item.dto';
import { CreateCanteenOrderDto } from './dto/create-canteen-order.dto';
import { UpdateCanteenOrderDto } from './dto/update-canteen-order.dto';

@Injectable()
export class NightCanteenRepository {
  constructor(private readonly prisma: PrismaService) {}

  async findItems(query: NightCanteenItemQueryDto) {
    const where: Prisma.CanteenItemWhereInput = {
      ...(query.category ? { category: query.category } : {}),
      ...(query.isAvailable
        ? { isAvailable: query.isAvailable === 'true' }
        : {}),
    };

    const total = await this.prisma.canteenItem.count({ where });
    const items = await this.prisma.canteenItem.findMany({
      where,
      skip: query.offset,
      take: query.limit,
      orderBy: { [query.sortBy ?? 'updatedAt']: query.sortOrder ?? 'desc' },
    });

    return { items, total, limit: query.limit, offset: query.offset };
  }

  findItemById(id: string) {
    return this.prisma.canteenItem.findUnique({ where: { id } });
  }

  createItem(data: CreateCanteenItemDto) {
    return this.prisma.canteenItem.create({
      data: {
        name: data.name,
        price: data.price,
        category: data.category,
        description: data.description ?? '',
        image: data.image ?? '',
        isAvailable: data.isAvailable ?? true,
        stock: data.stock ?? 100,
      },
    });
  }

  upsertItem(id: string, data: CreateCanteenItemDto) {
    return this.prisma.canteenItem.upsert({
      where: { id },
      update: {
        name: data.name,
        price: data.price,
        category: data.category,
        description: data.description ?? '',
        image: data.image ?? '',
        isAvailable: data.isAvailable ?? true,
        stock: data.stock ?? 100,
      },
      create: {
        id,
        name: data.name,
        price: data.price,
        category: data.category,
        description: data.description ?? '',
        image: data.image ?? '',
        isAvailable: data.isAvailable ?? true,
        stock: data.stock ?? 100,
      },
    });
  }

  updateItem(id: string, data: UpdateCanteenItemDto) {
    return this.prisma.canteenItem.update({
      where: { id },
      data: data as any,
    });
  }

  deleteItem(id: string) {
    return this.prisma.canteenItem.delete({ where: { id } });
  }

  async findOrders(query: NightCanteenOrderQueryDto) {
    const where: Prisma.CanteenOrderWhereInput = {
      ...(query.studentId ? { studentId: query.studentId } : {}),
      ...(query.status ? { status: query.status } : {}),
    };

    const total = await this.prisma.canteenOrder.count({ where });
    const orders = await this.prisma.canteenOrder.findMany({
      where,
      skip: query.offset,
      take: query.limit,
      include: { items: true },
      orderBy: { [query.sortBy ?? 'timestamp']: query.sortOrder ?? 'desc' },
    });

    return { items: orders, total, limit: query.limit, offset: query.offset };
  }

  findOrderById(id: string) {
    return this.prisma.canteenOrder.findUnique({ 
      where: { id },
      include: { items: true }
    });
  }

  createOrder(data: CreateCanteenOrderDto) {
    if (!data.studentId) {
      throw new Error('studentId is required to create a canteen order');
    }
    if (!data.items?.length) {
      throw new Error('items are required to create a canteen order');
    }
    return (this.prisma.canteenOrder as any).create({
      data: {
        studentId: data.studentId,
        studentName: data.studentName ?? 'Student',
        hostelRoom: data.hostelRoom ?? 'Hostel',
        totalAmount: data.totalAmount,
        status: data.status ?? 'Pending',
        timestamp: data.timestamp ? new Date(data.timestamp) : new Date(),
        items: {
          create: (data.items ?? []).map((item: any) => ({
            itemId: item.itemId,
            name: item.name,
            quantity: item.quantity,
            price: item.price,
          })),
        },
      } as any,
      include: { items: true },
    });
  }

  updateOrder(id: string, data: UpdateCanteenOrderDto) {
    return (this.prisma.canteenOrder as any).update({
      where: { id },
      data: {
        ...(data.status ? { status: data.status } : {}),
        ...(data.hostelRoom ? { hostelRoom: data.hostelRoom } : {}),
        ...(typeof data.totalAmount === 'number'
          ? { totalAmount: data.totalAmount }
          : {}),
        ...(data.items
          ? {
              items: {
                deleteMany: {},
                create: data.items.map((item) => {
                  if (!item.itemId) {
                    throw new Error(
                      'itemId is required for each canteen order item',
                    );
                  }
                  return {
                    itemId: item.itemId,
                    name: item.name,
                    quantity: item.quantity,
                    price: item.price,
                  };
                }),
              },
            }
          : {}),
      } as any,
      include: { items: true },
    });
  }

  deleteOrder(id: string) {
    return this.prisma.canteenOrder.delete({ where: { id } });
  }
}

