import { CheckPolicies } from '../auth/decorators/check-policies.decorator';
import { RateLimit } from '../common/decorators/rate-limit-options.decorator';

@UseGuards(AuthGuard, PoliciesGuard)
@RateLimit({ limit: 2000, windowMs: 60_000, banAfterExceeded: 5 })
@Controller('timetable')
export class TimetableController {
  constructor(private readonly timetableService: TimetableService) {}

  @CheckPolicies((ability) => ability.can('read', 'Timetable'))
  @UseInterceptors(CacheInterceptor)
  @CacheTTL(300000) // 5 minutes
  @Get()
  async findAll(@Query() query: TimetableQueryDto) {
    const result = await this.timetableService.findAll(query);
    return ok(result.items, {
      total: result.total,
      limit: result.limit,
      offset: result.offset,
    });
  }

  @CheckPolicies((ability) => ability.can('create', 'Timetable'))
  @Post()
  async create(
    @Body(new ZodValidationPipe(timetableSchema))
    body: CreateTimetableDto,
  ) {
    const data = await this.timetableService.create(body);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('update', 'Timetable'))
  @Patch(':id')
  async update(
    @Param('id') id: string,
    @Body(new ZodValidationPipe(timetableSchema.partial()))
    body: UpdateTimetableDto,
  ) {
    const data = await this.timetableService.update(id, body);
    return ok(data);
  }

  @CheckPolicies((ability) => ability.can('delete', 'Timetable'))
  @Delete(':id')
  async remove(@Param('id') id: string) {
    const data = await this.timetableService.remove(id);
    return ok(data);
  }
}

import { Module } from '@nestjs/common';
import { PrismaModule } from '../prisma/prisma.module';
import { TimetableController } from './timetable.controller';
import { TimetableService } from './timetable.service';
import { TimetableRepository } from './timetable.repository';

@Module({
  imports: [PrismaModule],
  controllers: [TimetableController],
  providers: [TimetableService, TimetableRepository],
  exports: [TimetableService, TimetableRepository],
})
export class TimetableModule {}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { TimetableQueryDto } from './dto/timetable-query.dto';
import { CreateTimetableDto } from './dto/create-timetable.dto';
import { UpdateTimetableDto } from './dto/update-timetable.dto';
import { BaseRepository } from '../common/repositories/base.repository';

@Injectable()
export class TimetableRepository extends BaseRepository {
  constructor(private readonly prisma: PrismaService) {
    super();
  }

  async findMany(query: TimetableQueryDto) {
    const where = {
      ...(query.department ? { department: query.department } : {}),
      ...(query.semester ? { semester: query.semester } : {}),
      ...(query.facultyId ? { facultyId: query.facultyId } : {}),
      ...((query as any).courseId ? { courseId: (query as any).courseId } : {}),
    };

    return this.findManyWithCount(this.prisma.timetable, {
      query,
      defaultLimit: 500,
      where,
      orderBy: [{ day: 'asc' }, { startTime: 'asc' }],
    });
  }

  /**
   * Fetch timetable entries for multiple courses in a single IN query.
   * Use this instead of calling findMany() in a loop (N+1 anti-pattern).
   */
  async findManyByCourseIds(courseIds: string[]) {
    if (courseIds.length === 0) return [];
    return this.prisma.timetable.findMany({
      where: { courseId: { in: courseIds } },
      orderBy: [{ day: 'asc' }, { startTime: 'asc' }],
    });
  }

  async findConflicts(params: {
    room?: string | null;
    day: string;
    startTime: string;
    endTime: string;
    facultyId?: string | null;
    batch?: string | null;
    semester?: number | null;
    excludeId?: string;
  }) {
    const { room, day, startTime, endTime, facultyId, batch, semester, excludeId } = params;

    return this.prisma.timetable.findFirst({
      where: {
        day,
        id: excludeId ? { not: excludeId } : undefined,
        OR: [
          // Room conflict
          ...(room ? [{
            room,
            OR: [
              { startTime: { gte: startTime, lt: endTime } },
              { endTime: { gt: startTime, lte: endTime } },
              { startTime: { lte: startTime }, endTime: { gte: endTime } }
            ]
          }] : []),
          // Faculty busy conflict
          ...(facultyId ? [{
            facultyId,
            OR: [
              { startTime: { gte: startTime, lt: endTime } },
              { endTime: { gt: startTime, lte: endTime } },
              { startTime: { lte: startTime }, endTime: { gte: endTime } }
            ]
          }] : []),
          // Batch/Semester overlap conflict
          ...(batch && semester ? [{
            batch,
            semester,
            OR: [
              { startTime: { gte: startTime, lt: endTime } },
              { endTime: { gt: startTime, lte: endTime } },
              { startTime: { lte: startTime }, endTime: { gte: endTime } }
            ]
          }] : [])
        ]
      }
    });
  }

  create(data: CreateTimetableDto) {
    return this.prisma.timetable.create({
      data: {
        ...data,
        courseId: data.courseId ?? null,
        facultyId: data.facultyId ?? null,
        facultyName: data.facultyName ?? null,
        department: data.department ?? null,
        semester: data.semester ?? null,
        batch: data.batch ?? null,
      } as any,
    });
  }

  update(id: string, data: UpdateTimetableDto) {
    return this.prisma.timetable.update({
      where: { id },
      data: {
        ...data,
        ...(data.courseId !== undefined
          ? { courseId: data.courseId ?? null }
          : {}),
        ...(data.facultyId !== undefined
          ? { facultyId: data.facultyId ?? null }
          : {}),
        ...(data.facultyName !== undefined
          ? { facultyName: data.facultyName ?? null }
          : {}),
        ...(data.department !== undefined
          ? { department: data.department ?? null }
          : {}),
        ...(data.semester !== undefined
          ? { semester: data.semester ?? null }
          : {}),
        ...(data.batch !== undefined ? { batch: data.batch ?? null } : {}),
      },
    });
  }

  findById(id: string) {
    return this.prisma.timetable.findUnique({ where: { id } });
  }

  remove(id: string) {
    return this.prisma.timetable.delete({
      where: { id },
    });
  }
}

import { Injectable } from '@nestjs/common';
import { TimetableRepository } from './timetable.repository';
import { TimetableQueryDto } from './dto/timetable-query.dto';
import { CreateTimetableDto } from './dto/create-timetable.dto';
import { UpdateTimetableDto } from './dto/update-timetable.dto';

@Injectable()
export class TimetableService {
  constructor(private readonly repo: TimetableRepository) {}

  findAll(query: TimetableQueryDto) {
    return this.repo.findMany(query);
  }

  async create(data: CreateTimetableDto) {
    const conflict = await this.repo.findConflicts({
      room: data.room,
      day: data.day,
      startTime: data.startTime,
      endTime: data.endTime,
      facultyId: data.facultyId,
      batch: data.batch,
      semester: data.semester,
    });
    if (conflict) {
      throw new Error(`Schedule conflict detected with ${conflict.courseCode} affecting either Room, Faculty, or Batch.`);
    }
    return this.repo.create(data);
  }

  async update(id: string, data: UpdateTimetableDto) {
    const current = await this.repo.findById(id);
    if (!current) throw new Error('Timetable entry not found');

    if (data.room || data.day || data.startTime || data.endTime || data.facultyId || data.batch) {
       const conflict = await this.repo.findConflicts({
         room: data.room || current.room,
         day: data.day || current.day,
         startTime: data.startTime || current.startTime,
         endTime: data.endTime || current.endTime,
         facultyId: data.facultyId || current.facultyId,
         batch: data.batch || current.batch,
         semester: data.semester || current.semester,
         excludeId: id,
       });

       if (conflict) {
         throw new Error(`Conflict while updating schedule for ${conflict.courseCode}. Check Room/Faculty availability.`);
       }
    }
    return this.repo.update(id, data);
  }

  remove(id: string) {
    return this.repo.remove(id);
  }
}

