/**
 * Partition migrator
 * - Connects to the DB using DATABASE_URL
 * - For configured tables, creates partitioned parent (LIKE original)
 * - Creates year partitions for a given range
 * - Copies data in batches from original table into partitioned parent
 * - Verifies counts
 *
 * Usage: DATABASE_URL=... npx ts-node packages/database/scripts/partition_migrator.ts
 */
import { Client } from 'pg';

const BATCH_SIZE = 5000;

async function query(client: Client, sql: string, params: any[] = []) {
  return client.query(sql, params);
}

async function createParentAndPartitions(client: Client, table: string, dateCol: string) {
  console.log(`Creating partitioned parent for ${table}`);
  // create parent using LIKE
  await query(client, `CREATE TABLE IF NOT EXISTS ${table}_partitioned (LIKE ${table} INCLUDING ALL) PARTITION BY RANGE (${dateCol});`);

  // determine min and max year from table
  const res = await query(client, `SELECT EXTRACT(YEAR FROM MIN(${dateCol})) AS miny, EXTRACT(YEAR FROM MAX(${dateCol})) AS maxy FROM ${table};`);
  let minYear = res.rows[0].miny || new Date().getFullYear();
  let maxYear = res.rows[0].maxy || new Date().getFullYear();
  minYear = Math.max(2000, Math.floor(minYear));
  maxYear = Math.max(minYear, Math.floor(maxYear));

  const currentYear = new Date().getFullYear();
  if (maxYear < currentYear) maxYear = currentYear;

  for (let y = minYear; y <= maxYear; y++) {
    const partName = `${table}_y_${y}`;
    const from = `${y}-01-01`;
    const to = `${y + 1}-01-01`;
    await query(client, `CREATE TABLE IF NOT EXISTS ${partName} PARTITION OF ${table}_partitioned FOR VALUES FROM ('${from}') TO ('${to}');`);
    console.log(`  ensured partition ${partName}`);
  }
}

async function copyInBatches(client: Client, table: string) {
  console.log(`Copying data for ${table}`);
  // get total count
  const cntRes = await query(client, `SELECT COUNT(*) AS cnt FROM ${table};`);
  const total = parseInt(cntRes.rows[0].cnt, 10);
  console.log(`  total rows: ${total}`);

  let offset = 0;
  while (offset < total) {
    const idsRes = await query(client, `SELECT id FROM ${table} ORDER BY id LIMIT ${BATCH_SIZE} OFFSET ${offset};`);
    const ids = idsRes.rows.map((r: any) => `'${r.id}'`).join(',');
    if (!ids) break;
    const insertSql = `INSERT INTO ${table}_partitioned SELECT * FROM ${table} WHERE id IN (${ids}) ON CONFLICT DO NOTHING;`;
    await query(client, insertSql);
    offset += BATCH_SIZE;
    console.log(`  copied ${Math.min(offset, total)} / ${total}`);
  }
}

async function verifyCounts(client: Client, table: string) {
  const orig = (await query(client, `SELECT COUNT(*) AS cnt FROM ${table};`)).rows[0].cnt;
  const part = (await query(client, `SELECT COUNT(*) AS cnt FROM ${table}_partitioned;`)).rows[0].cnt;
  console.log(`  verify ${table}: original=${orig}, partitioned=${part}`);
}

async function main() {
  const url = process.env.DATABASE_URL;
  if (!url) {
    console.error('Please set DATABASE_URL');
    process.exit(1);
  }
  const client = new Client({ connectionString: url });
  await client.connect();

  const targets = [
    { table: 'attendance', dateCol: 'date' },
    { table: 'audit_log', dateCol: 'createdAt' },
    { table: 'background_job', dateCol: 'createdAt' },
    { table: 'finance_transaction', dateCol: 'createdAt' },
  ];

  for (const t of targets) {
    try {
      await createParentAndPartitions(client, t.table, t.dateCol);
      await copyInBatches(client, t.table);
      await verifyCounts(client, t.table);
      console.log(`Finished processing ${t.table}`);
    } catch (e) {
      console.error(`Failed processing ${t.table}:`, e?.message || e);
    }
  }

  await client.end();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

import { PrismaClient } from '@prisma/client';
import { faker } from '@faker-js/faker';

const prisma = new PrismaClient();

async function main() {
  console.log('Seeding database with mock data...');

  // Create Departments
  const departments = [];
  for (let i = 0; i < 5; i++) {
    departments.push(await prisma.department.upsert({
      where: { code: `DEPT-${i}` },
      update: {},
      create: {
        code: `DEPT-${i}`,
        name: faker.commerce.department() + ' ' + faker.string.alphanumeric(4),
        description: faker.lorem.sentence(),
      }
    }));
  }
  console.log(`Created ${departments.length} departments.`);

  // Create Courses
  const courses = [];
  for (let i = 0; i < 20; i++) {
    courses.push(await prisma.course.upsert({
      where: { code: `CS${100 + i}` },
      update: {},
      create: {
        code: `CS${100 + i}`,
        name: faker.company.catchPhrase(),
        credits: faker.number.int({ min: 1, max: 4 }),
        instructor: faker.person.fullName(),
        department: departments[i % departments.length].name,
        semester: faker.number.int({ min: 1, max: 8 }),
        status: 'active',
        capacity: faker.number.int({ min: 30, max: 100 })
      }
    }));
  }
  console.log(`Created ${courses.length} courses.`);

  // Create Students
  console.log('Creating 100 fake students (this might take a few seconds)...');
  for (let i = 0; i < 100; i++) {
    const student = await prisma.user.create({
      data: {
        email: faker.internet.email(),
        name: faker.person.fullName(),
        profileComplete: true,
        studentProfile: {
          create: {
            enrollmentNumber: `ENR-${faker.string.numeric(6)}`,
            department: departments[i % departments.length].name,
            semester: faker.number.int({ min: 1, max: 8 }),
            phone: faker.phone.number({ style: 'international' }),
          }
        }
      }
    });

    // Enroll in random courses
    for (let j = 0; j < 3; j++) {
      const course = courses[faker.number.int({ min: 0, max: courses.length - 1 })];

      // Prevent duplicate enrollments
      const existing = await prisma.enrollment.findUnique({
        where: { studentId_courseId: { studentId: student.id, courseId: course.id } }
      });

      if (!existing) {
        await prisma.enrollment.create({
          data: {
            studentId: student.id,
            courseId: course.id,
            courseName: course.name,
            courseCode: course.code,
            semester: course.semester
          }
        });
      }
    }
  }

  console.log('Seeding completed successfully!');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

async function main() {
  console.log('Seeding basic permissions...');
  const permissionsData = [
    { action: 'read', subject: 'Course', description: 'View courses' },
    { action: 'read', subject: 'Timetable', description: 'View schedule' },
    { action: 'read', subject: 'FeeRecord', description: 'View fees' },
    { action: 'read', subject: 'MarketplaceListing', description: 'View marketplace' },
    { action: 'read', subject: 'HostelIssue', description: 'View hostel issues' },
  ];

  for (const p of permissionsData) {
    await prisma.permission.upsert({
      where: { action_subject: { action: p.action, subject: p.subject } },
      update: {},
      create: p,
    });
  }

  const studentRole = await prisma.role.findUnique({ where: { name: 'student' } });
  if (studentRole) {
    const allPerms = await prisma.permission.findMany();
    for (const p of allPerms) {
      await prisma.rolePermission.upsert({
        where: {
          roleId_permissionId: {
            roleId: studentRole.id,
            permissionId: p.id,
          }
        },
        update: {},
        create: {
          roleId: studentRole.id,
          permissionId: p.id,
        }
      });
    }
    console.log('Granted all basic read permissions to student role.');
  } else {
    console.log('Student role not found!');
  }
}

main().catch(console.error).finally(() => prisma.$disconnect());

import { PrismaClient } from '@prisma/client';
import { PrismaPg } from '@prisma/adapter-pg';
import { Pool } from 'pg';

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const adapter = new PrismaPg(pool);
const prisma = new PrismaClient({ adapter });

async function main() {
  console.log('Seeding RBAC permissions...');
  
  // 1. Create Core Roles
  const roles = [
    { name: 'student', description: 'Standard student account', hierarchy: 1 },
    { name: 'faculty', description: 'Teaching staff', hierarchy: 2 },
    { name: 'admin', description: 'System Administrator', hierarchy: 3 },
  ];

  for (const r of roles) {
    await prisma.role.upsert({
      where: { name: r.name },
      update: { hierarchy: r.hierarchy, description: r.description, isSystem: true },
      create: { ...r, isSystem: true },
    });
  }

  // 2. Create Base Permissions
  const permissions = [
    // Auth & Identity
    { action: 'read', subject: 'User' },
    { action: 'update', subject: 'User', conditions: { id: '{{id}}' } },
    { action: 'manage', subject: 'User' },
    
    // Hostel
    { action: 'read', subject: 'HostelIssue' },
    { action: 'create', subject: 'HostelIssue' },
    { action: 'update', subject: 'HostelIssue', conditions: { studentId: '{{id}}' } },
    { action: 'delete', subject: 'HostelIssue', conditions: { studentId: '{{id}}' } },
    { action: 'manage', subject: 'HostelIssue' },
    
    // Marketplace
    { action: 'read', subject: 'MarketplaceListing' },
    { action: 'create', subject: 'MarketplaceListing' },
    { action: 'update', subject: 'MarketplaceListing', conditions: { sellerId: '{{id}}' } },
    { action: 'delete', subject: 'MarketplaceListing', conditions: { sellerId: '{{id}}' } },
    { action: 'manage', subject: 'MarketplaceListing' },
    
    // Finance
    { action: 'read', subject: 'FeeRecord', conditions: { studentId: '{{id}}' } },
    { action: 'manage', subject: 'FeeRecord' },
    
    // Timetable
    { action: 'read', subject: 'Timetable' },
    { action: 'manage', subject: 'Timetable' },
    
    // Courses
    { action: 'read', subject: 'Course' },
    { action: 'manage', subject: 'Course' },
    
    // Admin / System
    { action: 'manage', subject: 'Role' },
    { action: 'manage', subject: 'Permission' },
    { action: 'manage', subject: 'all' },
  ];

  for (const p of permissions) {
    await prisma.permission.upsert({
      where: { action_subject: { action: p.action, subject: p.subject } },
      update: { conditions: p.conditions || null },
      create: { 
        action: p.action, 
        subject: p.subject, 
        conditions: p.conditions || null,
        description: `Allows ${p.action} on ${p.subject}`
      },
    });
  }

  // 3. Map Basic Permissions to Roles
  console.log('Mapping permissions to roles...');
  const studentRole = await prisma.role.findUnique({ where: { name: 'student' } });
  const facultyRole = await prisma.role.findUnique({ where: { name: 'faculty' } });
  const adminRole = await prisma.role.findUnique({ where: { name: 'admin' } });

  const getPerms = async (actions: string[], subjects: string[]) => {
    return prisma.permission.findMany({
      where: { action: { in: actions }, subject: { in: subjects } }
    });
  };

  if (studentRole) {
    const studentPerms = await getPerms(
      ['read', 'create', 'update', 'delete'], 
      ['User', 'HostelIssue', 'MarketplaceListing', 'FeeRecord', 'Timetable', 'Course']
    );
    // filter down to non-manage 
    const filtered = studentPerms.filter(p => p.action !== 'manage');
    
    for (const p of filtered) {
      await prisma.rolePermission.upsert({
        where: { roleId_permissionId: { roleId: studentRole.id, permissionId: p.id } },
        update: {},
        create: { roleId: studentRole.id, permissionId: p.id }
      });
    }
  }

  if (facultyRole) {
    const facultyPerms = await getPerms(
      ['read', 'update', 'create'], 
      ['User', 'Timetable', 'Course']
    );
    for (const p of facultyPerms) {
      await prisma.rolePermission.upsert({
        where: { roleId_permissionId: { roleId: facultyRole.id, permissionId: p.id } },
        update: {},
        create: { roleId: facultyRole.id, permissionId: p.id }
      });
    }
  }

  if (adminRole) {
    const adminPerms = await prisma.permission.findMany();
    for (const p of adminPerms) {
      await prisma.rolePermission.upsert({
        where: { roleId_permissionId: { roleId: adminRole.id, permissionId: p.id } },
        update: {},
        create: { roleId: adminRole.id, permissionId: p.id }
      });
    }
  }

  console.log('RBAC Seeding completed.');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

import { PrismaClient } from '@prisma/client';
import { PrismaPg } from '@prisma/adapter-pg';
import { Pool } from 'pg';
import { readReplicas } from '@prisma/extension-read-replicas';
import { AsyncLocalStorage } from 'async_hooks';

export const dbContext = new AsyncLocalStorage<{ userId?: string; role?: string }>();

const createPrismaClient = () => {
  const pool = new Pool({ connectionString: process.env.DATABASE_URL });
  const adapter = new PrismaPg(pool);

  const baseClient = new PrismaClient({ adapter, log: [] });

  const replicaPool = new Pool({ connectionString: process.env.REPLICA_URL || process.env.DATABASE_URL });
  const replicaAdapter = new PrismaPg(replicaPool);
  const replicaClient = new PrismaClient({ adapter: replicaAdapter, log: [] });

  return baseClient
    .$extends(
      readReplicas({
        replicas: [replicaClient],
      })
    )
    .$extends({
      query: {
        $allModels: {
          async $allOperations({ model, operation, args, query }) {
            const context = dbContext.getStore();
            const userId = context?.userId;

            // Audit trails
            if (userId) {
              if (operation === 'create' || operation === 'createMany') {
                if (args.data) {
                  if (Array.isArray(args.data)) {
                    args.data = args.data.map(d => ({ ...d, createdBy: (d as any).createdBy || userId }));
                  } else {
                    (args.data as any).createdBy = (args.data as any).createdBy || userId;
                  }
                }
              }
              if (operation === 'update' || operation === 'updateMany') {
                if (args.data) {
                  (args.data as any).updatedBy = (args.data as any).updatedBy || userId;
                }
              }
            }

            const modelsWithSoftDelete = ['Course', 'FeeRecord', 'Notice', 'ExamSchedule', 'Job'];
            if (modelsWithSoftDelete.includes(model)) {
              if (operation === 'findUnique' || operation === 'findFirst' || operation === 'findMany') {
                args.where = { ...args.where, deletedAt: null };
              }
            }
            const criticalModels = ['FeeRecord', 'Course', 'User'];
            const writeOperations = ['create', 'createMany', 'update', 'updateMany', 'delete', 'deleteMany', 'upsert'];

            const result = await query(args);

            if (userId && criticalModels.includes(model as string) && writeOperations.includes(operation)) {
              const action = operation.toUpperCase();
              let entityId: string | null = null;

              if ('id' in (result as any)) {
                entityId = (result as any).id;
              } else if ((args as any).where && 'id' in (args as any).where) {
                entityId = ((args as any).where as any).id;
              }

              // Fire and forget audit log creation
              Promise.resolve().then(() => {
                const pool = new Pool({ connectionString: process.env.DATABASE_URL });
                pool.query(
                  'INSERT INTO "AuditLog" (id, "actorUserId", "actorRole", action, entity, "entityId", method, path, "createdAt") VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW())',
                  [
                    require('crypto').randomUUID(),
                    userId,
                    context?.role || 'system',
                    action,
                    model as string,
                    entityId,
                    'SYSTEM',
                    'PRISMA_EXTENSION'
                  ]
                ).catch(e => console.error('Failed to write audit log', e)).finally(() => pool.end());
              });
            }

            return result;
          },
        },
      },
    });
};

const globalForPrisma = globalThis as unknown as { prisma: ReturnType<typeof createPrismaClient> };

export const db = globalForPrisma.prisma || createPrismaClient();

if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = db;

